/* ============================================================
   1. CONSTANTS AND TABLE INSTALLATION
   ============================================================ */

function ktv_travel_install_tables() {
    global $wpdb;
    $charset = $wpdb->get_charset_collate();
    $prefix  = $wpdb->prefix;

    require_once ABSPATH . 'wp-admin/includes/upgrade.php';

    $tables = array(
        "{$prefix}ktv_tours" => "CREATE TABLE IF NOT EXISTS {$prefix}ktv_tours (
