            tour_price decimal(10,2) DEFAULT 0,
            tour_offer_price decimal(10,2) DEFAULT 0,
            tour_duration_days int(3) DEFAULT 1,
            tour_duration_nights int(3) DEFAULT 1,
            tour_location varchar(200),
            tour_city varchar(100),
            tour_region varchar(100),
            tour_country varchar(100) DEFAULT 'India',
            tour_image_id int(11) DEFAULT 0,
            tour_image text,
            tour_gallery text,
            tour_images_slides text,
            tour_type varchar(50),
            tour_rating decimal(3,2) DEFAULT 0,
            total_reviews int(11) DEFAULT 0,
            featured tinyint(1) DEFAULT 0,
            best_time varchar(200),
            inclusions text,
            exclusions text,
            itinerary text,
            amenities text,
            transport varchar(200),
            meals varchar(200),
            sightseeing text,
            activity_icons text,
            wishlist_count int(11) DEFAULT 0,
            badge_text varchar(100),
            badge_color varchar(20) DEFAULT '#ff5722',
            badge_icon varchar(50) DEFAULT 'fa-star',
