            deal_badge_text_color varchar(20) DEFAULT '#ffffff',
            deal_badge_position varchar(20) DEFAULT 'bottom-right',
            title_font_size varchar(20) DEFAULT '18px',
            title_color varchar(20) DEFAULT '#333333',
            title_font_family varchar(200) DEFAULT 'inherit',
            title_font_weight varchar(10) DEFAULT '700',
            price_font_size varchar(20) DEFAULT '24px',
            price_color varchar(20) DEFAULT '#28a745',
