    foreach ($tables as $sql) {
        dbDelta($sql);
    }

    ktv_migrate_tables();
    update_option('ktv_travel_db_version', KTV_TRAVEL_DB_VERSION);
}

/* ============================================================
   2. MIGRATIONS
   ============================================================ */

function ktv_migrate_tables() {
