function ktv_travel_maybe_upgrade_db() {
    $installed = get_option('ktv_travel_db_version', '');
    if ($installed === KTV_TRAVEL_DB_VERSION) {
        return;
    }

    $lock_key = 'ktv_db_upgrade_lock';
    if (get_transient($lock_key)) {
        return;
    }
    set_transient($lock_key, '1', 60);

    ktv_travel_install_tables();

    delete_transient($lock_key);
}

add_action('after_switch_theme', 'ktv_travel_install_tables');
add_action('admin_init', 'ktv_travel_maybe_upgrade_db', 5);

/* ============================================================
   3. OPTIONAL INC FILE LOADER
   ============================================================ */

function ktv_load_optional_inc() {
    $theme_dir = get_template_directory();

    $files = array(
        'schema-markup' => $theme_dir . '/inc/schema-markup.php',
        'account'       => $theme_dir . '/inc/account.php',
    );

    foreach ($files as $label => $path) {
        if (!file_exists($path)) {
            continue;
        }
        if (!function_exists('ktv_inc_loaded_' . str_replace('-', '_', $label))) {
            require_once $path;
        }
    }

    if (!isset($GLOBALS['ktv_inc_loaded'])) {
        $GLOBALS['ktv_inc_loaded'] = array();
    }
    foreach ($files as $label => $path) {
        if (file_exists($path)) {
            $GLOBALS['ktv_inc_loaded'][$label] = true;
        }
    }
}
add_action('after_setup_theme', 'ktv_load_optional_inc', 5);

function ktv_inc_available($label) {
    return !empty($GLOBALS['ktv_inc_loaded'][$label]);
}

/* ============================================================
   4. HEADING HIERARCHY HELPER
   ============================================================ */

function ktv_next_heading_level($requested = 'h4', $section = 'block') {
    $requested = strtolower((string) $requested);
    if (!in_array($requested, array('h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p'), true)) {
        $requested = 'h4';
    }

    if (!isset($GLOBALS['ktv_heading_depth']) || !is_array($GLOBALS['ktv_heading_depth'])) {
        $GLOBALS['ktv_heading_depth'] = array();
    }

    if ($requested === 'p') {
        return 'p';
    }

    $current = isset($GLOBALS['ktv_heading_depth'][$section]) ? (int) $GLOBALS['ktv_heading_depth'][$section] : 2;
    $requestedLevel = (int) substr($requested, 1);

    if ($requestedLevel > $current + 1) {
        $requestedLevel = $current + 1;
    }
    if ($requestedLevel < 1) {
        $requestedLevel = 1;
    }
    if ($requestedLevel > 6) {
        $requestedLevel = 6;
    }

    $GLOBALS['ktv_heading_depth'][$section] = $requestedLevel;

    return 'h' . $requestedLevel;
}

/* ============================================================
   5. SETTINGS HELPERS
   ============================================================ */

if (!isset($GLOBALS['ktv_setting_runtime_cache'])) {
    $GLOBALS['ktv_setting_runtime_cache'] = array();
}

function ktv_flush_setting_cache($key = '') {
    if (!isset($GLOBALS['ktv_setting_runtime_cache']) || !is_array($GLOBALS['ktv_setting_runtime_cache'])) {
        $GLOBALS['ktv_setting_runtime_cache'] = array();
    }
    if (!empty($key)) {
        unset($GLOBALS['ktv_setting_runtime_cache'][$key]);
    } else {
        $GLOBALS['ktv_setting_runtime_cache'] = array();
    }
}

function ktv_get_setting($key, $default = '') {
    global $wpdb;

    if (!isset($GLOBALS['ktv_setting_runtime_cache']) || !is_array($GLOBALS['ktv_setting_runtime_cache'])) {
        $GLOBALS['ktv_setting_runtime_cache'] = array();
    }

    if (array_key_exists($key, $GLOBALS['ktv_setting_runtime_cache'])) {
        return $GLOBALS['ktv_setting_runtime_cache'][$key];
    }

    $cache_key = 'ktv_setting_' . $key;
    $cached    = wp_cache_get($cache_key, 'ktv_settings');
    if ($cached !== false) {
        $GLOBALS['ktv_setting_runtime_cache'][$key] = $cached;
        return $cached;
    }

    $table_exists = $wpdb->get_var($wpdb->prepare(
        "SHOW TABLES LIKE %s",
        $wpdb->prefix . 'ktv_settings'
    ));

    if (!$table_exists) {
        $GLOBALS['ktv_setting_runtime_cache'][$key] = $default;
        return $default;
    }

    $val = $wpdb->get_var($wpdb->prepare(
        "SELECT setting_value FROM {$wpdb->prefix}ktv_settings WHERE setting_key = %s",
        $key
    ));

    $result = ($val === null || $val === '') ? $default : $val;
    wp_cache_set($cache_key, $result, 'ktv_settings', 3600);
    $GLOBALS['ktv_setting_runtime_cache'][$key] = $result;

    return $result;
}

function ktv_update_setting($key, $val) {
    global $wpdb;

    $exists = $wpdb->get_var($wpdb->prepare(
        "SELECT id FROM {$wpdb->prefix}ktv_settings WHERE setting_key = %s",
        $key
    ));

    if ($exists) {
        $wpdb->update(
            $wpdb->prefix . 'ktv_settings',
            array('setting_value' => $val),
            array('setting_key' => $key)
        );
    } else {
        $wpdb->insert(
            $wpdb->prefix . 'ktv_settings',
            array('setting_key' => $key, 'setting_value' => $val)
        );
    }

    wp_cache_delete('ktv_setting_' . $key, 'ktv_settings');
    ktv_flush_setting_cache($key);

    if (in_array($key, array('currency', 'currency_mode'), true)) {
        $transient_like = $wpdb->esc_like('_transient_ktv_currency_') . '%';
        $wpdb->query($wpdb->prepare(
            "DELETE FROM {$wpdb->options} WHERE option_name LIKE %s",
            $transient_like
        ));
        $transient_timeout_like = $wpdb->esc_like('_transient_timeout_ktv_currency_') . '%';
        $wpdb->query($wpdb->prepare(
            "DELETE FROM {$wpdb->options} WHERE option_name LIKE %s",
            $transient_timeout_like
        ));
    }
}

function ktv_ensure_runtime_settings() {
    $flag = 'ktv_runtime_settings_seeded';
    if (get_option($flag, '') === KTV_TRAVEL_DB_VERSION) {
        return;
    }

    $defaults = array(
        'extra_adult_percent'  => '50',
        'extra_child_percent'  => '40',
        'honeypot_enabled'     => '1',
        'spam_filter_enabled'  => '1',
        'rate_limit_enabled'   => '1',
        'voucher_onpage_show_company_name' => '0',
        'voucher_btn_icon_size'  => '14px',
        'voucher_btn_icon_color' => '#ffffff',
        'voucher_btn_gap'        => '12px',
        'voucher_email_logo_size' => '120',
        'currency_mode'          => 'auto'
    );

    foreach ($defaults as $key => $val) {
        $current = ktv_get_setting($key, '');
        if ($current === '' || $current === null) {
            ktv_update_setting($key, $val);
        }
    }

    update_option($flag, KTV_TRAVEL_DB_VERSION);
}
add_action('admin_init', 'ktv_ensure_runtime_settings', 15);
add_action('wp_loaded', 'ktv_ensure_runtime_settings', 5);

