function ktv_get_spam_keywords() {
    $raw = ktv_get_setting('spam_keywords', '');
    if (empty($raw)) {
        $raw = "viagra\ncasino\ncrypto\nloan\nporn\nxxx\nbitcoin\nforex\nweight loss\nseo services\nbacklink\nguest post\nfree money\nmake money online\nbinary options";
    }
    $lines = preg_split('/\r\n|\r|\n/', $raw);
    $out = array();
    foreach ($lines as $line) {
        $line = trim($line);
        if ($line !== '') {
            $out[] = strtolower($line);
        }
    }
    return $out;
}

function ktv_get_blocked_ips() {
    $raw = ktv_get_setting('blocked_ips', '');
    if (empty($raw)) {
        return array();
    }
    $lines = preg_split('/\r\n|\r|\n/', $raw);
    $out = array();
    foreach ($lines as $line) {
        $line = trim($line);
        if ($line !== '' && filter_var($line, FILTER_VALIDATE_IP)) {
            $out[] = $line;
        }
    }
    return $out;
}

