function ktv_get_currency_symbol($code = '') {
    $sym = array(
        'USD' => '$', 'EUR' => '€', 'GBP' => '£', 'INR' => '₹',
        'AUD' => 'A$', 'CAD' => 'C$', 'JPY' => '¥', 'AED' => 'د.إ',
        'SAR' => '﷼', 'SGD' => 'S$', 'MYR' => 'RM', 'KWD' => 'د.ك',
        'QAR' => 'ر.ق', 'OMR' => 'ر.ع.', 'BHD' => '.د.ب', 'TRY' => '₺',
        'RUB' => '₽', 'BRL' => 'R$', 'ZAR' => 'R', 'NZD' => 'NZ$',
        'CHF' => 'Fr', 'SEK' => 'kr', 'THB' => '฿', 'IDR' => 'Rp',
        'PHP' => '₱', 'KRW' => '₩', 'PKR' => '₨', 'BDT' => '৳',
        'NPR' => '₨', 'LKR' => '₨', 'CNY' => '¥'
    );
    $s = ktv_get_setting('currency_symbols_map', '');
    if (!empty($s)) {
        $d = json_decode($s, true);
        if (is_array($d)) {
            foreach ($d as $k => $v) if ($v !== '') $sym[$k] = $v;
        }
    }
    $cur = !empty($code) ? $code : ktv_get_currency_code();
    return isset($sym[$cur]) ? $sym[$cur] : '$';
}

function ktv_get_currency_code() {
    $mode = ktv_get_setting('currency_mode', 'auto');
    if ($mode === 'manual') {
        return ktv_get_setting('currency', 'USD');
    }
    $ip = ktv_get_client_ip();
    if (!empty($ip)) {
        $cache_key = 'ktv_currency_' . md5($ip);
        $cached = get_transient($cache_key);
        if ($cached !== false && !empty($cached)) {
            return $cached;
        }
        $country = ktv_get_user_country($ip);
        $detected = ktv_get_currency_for_country($country);
        if (!empty($detected)) {
            set_transient($cache_key, $detected, DAY_IN_SECONDS);
            return $detected;
        }
        set_transient($cache_key, ktv_get_setting('currency', 'USD'), HOUR_IN_SECONDS);
    }
    return ktv_get_setting('currency', 'USD');
}

function ktv_convert_price($amount, $force_currency_code = '') {
    $amount = floatval($amount);
    if ($amount <= 0) return 0.0;

    $target = !empty($force_currency_code) ? $force_currency_code : ktv_get_currency_code();
    if ($target === 'INR') return round($amount, 2);

    $rates = ktv_get_currency_rates_map();
    if (!isset($rates[$target])) return round($amount, 2);
    return round($amount * $rates[$target], 2);
}

