function ktv_time_ago($datetime) {
    if (empty($datetime)) {
        return '';
    }
    $time = strtotime($datetime);
    if ($time === false) {
        return '';
    }
    $diff = time() - $time;
    if ($diff < 0) {
        return __('Just now', 'ktv-travel');
    }
    if ($diff < 60) {
        return __('Just now', 'ktv-travel');
    }
    if ($diff < 3600) {
        return sprintf(__('%s minutes ago', 'ktv-travel'), floor($diff / 60));
    }
    if ($diff < 86400) {
        return sprintf(__('%s hours ago', 'ktv-travel'), floor($diff / 3600));
    }
    if ($diff < 604800) {
        return sprintf(__('%s days ago', 'ktv-travel'), floor($diff / 86400));
    }
    return date_i18n('M d, Y', $time);
}

function ktv_generate_upi_qr_code($upi_id, $amount = '', $name = '') {
    $upi_url = 'upi://pay?pa=' . rawurlencode($upi_id) . '&pn=' . rawurlencode($name ?: 'KTV Travel') . '&cu=INR';
    if ($amount) {
        $upi_url .= '&am=' . rawurlencode($amount);
    }
    return 'https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=' . rawurlencode($upi_url);
}

function ktv_get_client_ip() {
    static $ip = null;
    if ($ip !== null) {
        return $ip;
    }

    $raw = '';
    if (!empty($_SERVER['HTTP_CLIENT_IP'])) {
        $raw = $_SERVER['HTTP_CLIENT_IP'];
    } elseif (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
        $raw = $_SERVER['HTTP_X_FORWARDED_FOR'];
    } else {
        $raw = isset($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : '';
    }

    if (strpos($raw, ',') !== false) {
        $parts = array_map('trim', explode(',', $raw));
        foreach ($parts as $candidate) {
            if (filter_var($candidate, FILTER_VALIDATE_IP)) {
                $raw = $candidate;
                break;
            }
        }
    }

    $ip = filter_var($raw, FILTER_VALIDATE_IP) ? $raw : '';
    return $ip;
}

function ktv_get_user_geo($ip = '') {
    if (empty($ip)) {
        $ip = ktv_get_client_ip();
    }

    $fallback = array('country' => 'Local', 'city' => '', 'region' => '');

    if (empty($ip) || $ip === '127.0.0.1' || $ip === '::1') {
        return $fallback;
    }

    if (apply_filters('ktv_skip_geo', false, $ip)) {
        return $fallback;
    }

    $cache_key = 'ktv_ip_geo_' . md5($ip);
    $cached    = get_transient($cache_key);
    if ($cached !== false && is_array($cached)) {
        return $cached;
    }

    $geo = array('country' => 'Unknown', 'city' => '', 'region' => '');

    $response = wp_remote_get('https://ip-api.com/json/' . rawurlencode($ip) . '?fields=country,regionName,city,status', array('timeout' => 3, 'sslverify' => true));
    if (!is_wp_error($response) && wp_remote_retrieve_response_code($response) === 200) {
        $data = json_decode(wp_remote_retrieve_body($response), true);
        if (is_array($data) && isset($data['status']) && $data['status'] === 'success') {
            $geo = array(
                'country' => isset($data['country']) ? sanitize_text_field($data['country']) : 'Unknown',
                'city'    => isset($data['city']) ? sanitize_text_field($data['city']) : '',
                'region'  => isset($data['regionName']) ? sanitize_text_field($data['regionName']) : ''
            );
            set_transient($cache_key, $geo, DAY_IN_SECONDS);
            return $geo;
        }
    }

    if (is_wp_error($response)) {
        set_transient($cache_key, $geo, HOUR_IN_SECONDS);
        return $geo;
    }

    $response2 = wp_remote_get('https://ipapi.co/' . rawurlencode($ip) . '/json/', array('timeout' => 3, 'sslverify' => true));
    if (!is_wp_error($response2) && wp_remote_retrieve_response_code($response2) === 200) {
        $data2 = json_decode(wp_remote_retrieve_body($response2), true);
        if (is_array($data2) && !empty($data2['country_name'])) {
            $geo = array(
                'country' => sanitize_text_field($data2['country_name']),
                'city'    => isset($data2['city']) ? sanitize_text_field($data2['city']) : '',
                'region'  => isset($data2['region']) ? sanitize_text_field($data2['region']) : ''
            );
            set_transient($cache_key, $geo, DAY_IN_SECONDS);
            return $geo;
        }
    }

    set_transient($cache_key, $geo, HOUR_IN_SECONDS);
    return $geo;
}

function ktv_get_user_country($ip = '') {
    $geo = ktv_get_user_geo($ip);
    return isset($geo['country']) ? $geo['country'] : 'Unknown';
}

function ktv_get_user_device($user_agent = '') {
    if (empty($user_agent)) {
        $user_agent = isset($_SERVER['HTTP_USER_AGENT']) ? sanitize_text_field($_SERVER['HTTP_USER_AGENT']) : '';
    }
    if (empty($user_agent)) {
        return 'Unknown Device';
    }
    $ua = strtolower($user_agent);
    $device = 'Desktop';
    $os = 'Unknown OS';
    $browser = 'Unknown Browser';

    if (strpos($ua, 'iphone') !== false) {
        $device = 'iPhone';
        $os = 'iOS';
    } elseif (strpos($ua, 'ipad') !== false) {
        $device = 'iPad';
        $os = 'iPadOS';
    } elseif (strpos($ua, 'android') !== false) {
        $device = strpos($ua, 'mobile') !== false ? 'Android Phone' : 'Android Tablet';
        $os = 'Android';
    } elseif (strpos($ua, 'macintosh') !== false || strpos($ua, 'mac os') !== false) {
        $device = 'Mac';
        $os = 'macOS';
    } elseif (strpos($ua, 'windows') !== false) {
        $device = 'Windows PC';
        $os = 'Windows';
    } elseif (strpos($ua, 'linux') !== false) {
        $device = 'Linux';
        $os = 'Linux';
    }

    if (strpos($ua, 'edg/') !== false || strpos($ua, 'edge/') !== false) {
        $browser = 'Edge';
    } elseif (strpos($ua, 'opr/') !== false || strpos($ua, 'opera') !== false) {
        $browser = 'Opera';
    } elseif (strpos($ua, 'chrome/') !== false && strpos($ua, 'chromium') === false) {
        $browser = 'Chrome';
    } elseif (strpos($ua, 'safari/') !== false && strpos($ua, 'chrome') === false) {
        $browser = 'Safari';
    } elseif (strpos($ua, 'firefox/') !== false) {
        $browser = 'Firefox';
    }

    return $device . ' — ' . $os . ' — ' . $browser;
}

function ktv_get_booking_notice_count($force = false) {
    global $wpdb;
    static $cached = null;
    if (!$force && $cached !== null) {
        return $cached;
    }

    $transient_key = 'ktv_booking_notice_count';
    if (!$force) {
        $t = get_transient($transient_key);
        if ($t !== false) {
            $cached = (int) $t;
            return $cached;
        }
    }

    $table = $wpdb->prefix . 'ktv_bookings';
    $has_is_read = ktv_db_has_column($table, 'is_read');
    if (!$has_is_read) {
        $result = $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE booking_status = 'pending'");
    } else {
        $result = $wpdb->get_var("SELECT COUNT(*) FROM {$table} WHERE is_read = 0");
    }

    if ($result === null) {
        return 0;
    }

    $cached = (int) $result;
    set_transient($transient_key, $cached, MINUTE_IN_SECONDS);
    return $cached;
}

function ktv_mark_notices_read() {
    global $wpdb;
    $table = $wpdb->prefix . 'ktv_bookings';
    if (!ktv_db_has_column($table, 'is_read')) {
        return;
    }
    $wpdb->query("UPDATE {$table} SET is_read = 1 WHERE is_read = 0 AND booking_status IN ('pending', 'modified', 'confirmed', 'cancelled', 'cancel_requested', 'modify_requested')");
    delete_transient('ktv_booking_notice_count');
    ktv_get_booking_notice_count(true);
}

function ktv_get_ghost_tour_names() {
    return array(
        'tour card', 'tour grid', 'tour package',
        'product card', 'product grid', 'product package',
        'ktv tour card', 'ktv tour grid', 'ktv tour package',
        'ktv product card', 'ktv product grid', 'ktv product package',
        'tour_card', 'tour_grid', 'tour_package',
        'product_card', 'product_grid', 'product_package',
        'ktv_tour_card', 'ktv_tour_grid', 'ktv_tour_package'
    );
}

function ktv_is_ghost_tour_name($name) {
    if (empty($name)) {
        return true;
    }
    $ghost_names = ktv_get_ghost_tour_names();
    $lower       = strtolower(trim($name));
    return in_array($lower, $ghost_names, true);
}

function ktv_is_tour_excluded($tour_name) {
    return ktv_is_ghost_tour_name($tour_name);
}

function ktv_get_ghost_sql_exclusion() {
    global $wpdb;

    static $cached_sql = null;
    static $cached_ver = null;

    $reset = isset($GLOBALS['ktv_ghost_sql_reset']) ? $GLOBALS['ktv_ghost_sql_reset'] : 0;
    $ver   = KTV_TRAVEL_DB_VERSION . '|' . $reset;

    if ($cached_sql !== null && $cached_ver === $ver) {
        return $cached_sql;
    }

    $names = ktv_get_ghost_tour_names();
    if (empty($names)) {
        $cached_sql = '1=1';
        $cached_ver = $ver;
        return $cached_sql;
    }
    $parts = array();
    foreach ($names as $n) {
        $parts[] = $wpdb->prepare('%s', $n);
    }
    $cached_sql = 'LOWER(TRIM(tour_name)) NOT IN (' . implode(',', $parts) . ')';
    $cached_ver = $ver;
    return $cached_sql;
}

