function ktv_get_tour_default_icon_by_block($block_type) {
    switch ($block_type) {
        case 'card':
            return 'fa-id-card';
        case 'grid':
            return 'fa-th';
        case 'package':
            return 'fa-box';
        default:
            return 'fa-map-marker-alt';
    }
}

function ktv_resolve_tour_icon($icon_title, $block_type = 'grid') {
    $icon_title = trim((string) $icon_title);
    if (!empty($icon_title)) {
        return $icon_title;
    }
    return ktv_get_tour_default_icon_by_block($block_type);
}

function ktv_purge_hardcoded_tours() {
    global $wpdb;
    $table = $wpdb->prefix . 'ktv_tours';

    $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}");
    if (empty($columns) || !is_array($columns)) {
        return 0;
    }

    $deleted     = 0;
    $ghost_names = ktv_get_ghost_tour_names();

    foreach ($ghost_names as $name) {
        $result = $wpdb->query($wpdb->prepare(
            "DELETE FROM {$table} WHERE LOWER(TRIM(tour_name)) = %s",
            $name
        ));
        if ($result) {
            $deleted += (int) $result;
        }
    }

    if (in_array('is_hardcoded', $columns, true)) {
        $result = $wpdb->query("DELETE FROM {$table} WHERE is_hardcoded = 1");
        if ($result) {
            $deleted += (int) $result;
        }
    }

    if (in_array('is_ghost', $columns, true)) {
        $result = $wpdb->query("DELETE FROM {$table} WHERE is_ghost = 1");
        if ($result) {
            $deleted += (int) $result;
        }
    }

    ktv_clear_tour_caches();

    return $deleted;
}

function ktv_clear_tour_caches() {
    delete_transient('ktv_all_block_tours');
    delete_transient('ktv_booking_form_tours');
    delete_transient('ktv_booking_notice_count');
    delete_transient('ktv_tours_autosync_throttle');

    if (!isset($GLOBALS['ktv_ghost_sql_reset'])) {
        $GLOBALS['ktv_ghost_sql_reset'] = 1;
    } else {
        $GLOBALS['ktv_ghost_sql_reset'] = (int) $GLOBALS['ktv_ghost_sql_reset'] + 1;
    }
}

function ktv_strip_emoji_prefix($name) {
    if (empty($name)) {
        return '';
    }
    $name = trim((string) $name);
    $name = preg_replace('/^[^\p{L}\p{N}]+/u', '', $name);
    return trim($name);
}

/* ============================================================
   8. HONEYPOT AND SPAM PROTECTION
   ============================================================ */

function ktv_get_honeypot_field_name() {
    return 'ktv_hp_website';
}

function ktv_render_honeypot_field() {
    if (!ktv_is_honeypot_enabled()) {
        return '';
    }
    $field = ktv_get_honeypot_field_name();
    $html  = '<div class="ktv-honeypot-field" aria-hidden="true" data-ktv-protected="1" style="position:absolute !important;width:1px !important;height:1px !important;overflow:hidden !important;clip:rect(0,0,0,0) !important;clip-path:inset(50%) !important;white-space:nowrap !important;border:0 !important;padding:0 !important;margin:-1px !important;">';
    $html .= '<label for="' . esc_attr($field) . '">' . esc_html__('Website (leave blank)', 'ktv-travel') . '</label>';
    $html .= '<input type="text" name="' . esc_attr($field) . '" id="' . esc_attr($field) . '" value="" tabindex="-1" autocomplete="off" />';
    $html .= '</div>';
    return $html;
}

function ktv_honeypot_filled() {
    if (!ktv_is_honeypot_enabled()) {
        return false;
    }
    $field = ktv_get_honeypot_field_name();
    if (!isset($_POST[$field])) {
        return false;
    }
    $value = trim((string) wp_unslash($_POST[$field]));
    return $value !== '';
}

function ktv_check_blocked_ip($ip = '') {
    if (empty($ip)) {
        $ip = ktv_get_client_ip();
    }
    if (empty($ip)) {
        return false;
    }
    $blocked = ktv_get_blocked_ips();
    if (empty($blocked)) {
        return false;
    }
    return in_array($ip, $blocked, true);
}

function ktv_check_rate_limit($ip = '', $bucket = 'booking') {
    if (!ktv_is_rate_limit_enabled()) {
        return false;
    }
    if (empty($ip)) {
        $ip = ktv_get_client_ip();
    }
    if (empty($ip)) {
        return false;
    }
    $key   = 'ktv_rl_' . $bucket . '_' . md5($ip);
    $count = (int) get_transient($key);
    if ($count >= 5) {
        return true;
    }
    set_transient($key, $count + 1, 15 * MINUTE_IN_SECONDS);
    return false;
}

function ktv_check_spam_content($text, &$matched = array()) {
    $matched = array();
    if (!ktv_is_spam_filter_enabled()) {
        return false;
    }
    if (empty($text)) {
        return false;
    }
    $text_lower = strtolower($text);
    $keywords   = ktv_get_spam_keywords();
    $hits       = array();
    foreach ($keywords as $kw) {
        if ($kw === '') {
            continue;
        }
        if (strpos($text_lower, $kw) !== false) {
            $hits[] = $kw;
        }
    }
    if (!empty($hits)) {
        $matched = $hits;
        return true;
    }
    return false;
}

function ktv_check_url_spam($text) {
    if (!ktv_is_spam_filter_enabled()) {
        return false;
    }
    if (empty($text)) {
        return false;
    }
    if (preg_match('/https?:\/\/[^\s]+/i', $text)) {
        return true;
    }
    if (preg_match('/www\.[a-z0-9\-]+\.[a-z]{2,}/i', $text)) {
        return true;
    }
    return false;
}

function ktv_check_disposable_email($email) {
    if (!ktv_is_spam_filter_enabled()) {
        return false;
    }
    if (empty($email) || strpos($email, '@') === false) {
        return false;
    }
    $domain = strtolower(substr(strrchr($email, '@'), 1));
    $disposables = array(
        'mailinator.com', 'tempmail.com', 'guerrillamail.com', '10minutemail.com',
        'throwawaymail.com', 'yopmail.com', 'trashmail.com', 'sharklasers.com',
        'getnada.com', 'maildrop.cc', 'fakeinbox.com', 'dispostable.com',
        'tempr.email', 'discard.email', 'mailnesia.com', 'mytemp.email',
        'temp-mail.org', 'emailondeck.com', 'spam4.me', 'grr.la'
    );
    return in_array($domain, $disposables, true);
}

function ktv_log_blocked($form_type, $reason, $detail = '') {
    global $wpdb;
    $table = $wpdb->prefix . 'ktv_blocked_log';

    $ip    = ktv_get_client_ip();
    $email = isset($_POST['email']) ? sanitize_email(wp_unslash($_POST['email'])) : '';
    $name  = isset($_POST['name']) ? sanitize_text_field(wp_unslash($_POST['name'])) : '';
    $ua    = isset($_SERVER['HTTP_USER_AGENT']) ? sanitize_text_field($_SERVER['HTTP_USER_AGENT']) : '';

    ktv_db_insert_safe($table, array(
        'form_type'    => sanitize_key($form_type),
        'user_ip'      => $ip,
        'user_email'   => $email,
        'user_name'    => $name,
        'block_reason' => sanitize_text_field($reason),
        'block_detail' => sanitize_textarea_field($detail),
        'user_agent'   => $ua,
        'created_at'   => current_time('mysql')
    ));
}

function ktv_run_spam_checks($form_type, &$spam_score = 0) {
    $spam_score = 0;

    if (ktv_honeypot_filled()) {
        ktv_log_blocked($form_type, 'honeypot', 'Honeypot field was filled');
        return array('block' => true, 'silent' => true, 'reason' => 'honeypot');
    }

    $ip = ktv_get_client_ip();

    if (ktv_check_blocked_ip($ip)) {
        ktv_log_blocked($form_type, 'blocked_ip', 'IP: ' . $ip);
        return array('block' => true, 'silent' => false, 'reason' => 'blocked_ip');
    }

    if (ktv_check_rate_limit($ip, $form_type)) {
        ktv_log_blocked($form_type, 'rate_limit', 'IP: ' . $ip);
        return array('block' => true, 'silent' => false, 'reason' => 'rate_limit');
    }

    $name    = isset($_POST['name']) ? sanitize_text_field(wp_unslash($_POST['name'])) : '';
    $email   = isset($_POST['email']) ? sanitize_email(wp_unslash($_POST['email'])) : '';
    $message = '';

    if (isset($_POST['message'])) {
        $message = sanitize_textarea_field(wp_unslash($_POST['message']));
    }
    if (isset($_POST['special_requests'])) {
        $message .= ' ' . sanitize_textarea_field(wp_unslash($_POST['special_requests']));
    }

    if (ktv_check_disposable_email($email)) {
        ktv_log_blocked($form_type, 'disposable_email', 'Email: ' . $email);
        return array('block' => true, 'silent' => false, 'reason' => 'disposable_email');
    }

    if (ktv_check_url_spam($name)) {
        ktv_log_blocked($form_type, 'url_in_name', 'Name: ' . $name);
        return array('block' => true, 'silent' => false, 'reason' => 'url_in_name');
    }

    $matched = array();
    if (ktv_check_spam_content($name, $matched)) {
        ktv_log_blocked($form_type, 'spam_in_name', 'Matched: ' . implode(', ', $matched));
        return array('block' => true, 'silent' => false, 'reason' => 'spam_in_name');
    }

    if (ktv_check_spam_content($message, $matched)) {
        $spam_score = count($matched);
        ktv_log_blocked($form_type, 'spam_in_message', 'Matched: ' . implode(', ', $matched));
        return array('block' => true, 'silent' => false, 'reason' => 'spam_in_message');
    }

    return array('block' => false, 'silent' => false, 'reason' => '');
}

/* ============================================================
   9. CANCELLATION POLICY, GST AND PRICE CALCULATION
   ============================================================ */

function ktv_get_cancellation_policy_text($policy) {
    $policies = array(
        'fully_refundable'   => 'Fully Refundable - Cancel anytime for a full refund',
        'partial_refundable' => 'Partial Refundable - Cancellation fees may apply',
        'non_refundable'     => 'Non-Refundable - No refunds on cancellation'
    );
    return isset($policies[$policy]) ? $policies[$policy] : $policies['non_refundable'];
}

function ktv_calculate_smart_price($tour_price, $total_adults, $nights, $pax_data = array()) {
    $base_price = floatval($tour_price);
    $adults     = max(1, intval($total_adults));
    $nights     = max(1, intval($nights));
    $pax_data   = is_array($pax_data) ? $pax_data : array();

    $pax1   = isset($pax_data['pax_1_price'])  ? floatval($pax_data['pax_1_price'])  : 0;
    $pax2   = isset($pax_data['pax_2_price'])  ? floatval($pax_data['pax_2_price'])  : 0;
    $pax3   = isset($pax_data['pax_3_price'])  ? floatval($pax_data['pax_3_price'])  : 0;
    $group  = isset($pax_data['group_price'])  ? floatval($pax_data['group_price'])  : 0;
    $family = isset($pax_data['family_price']) ? floatval($pax_data['family_price']) : 0;

    $extra_adults_count   = isset($pax_data['extra_adults'])   ? max(0, intval($pax_data['extra_adults']))   : max(0, $adults - 1);
    $extra_children_count = isset($pax_data['extra_children']) ? max(0, intval($pax_data['extra_children'])) : (isset($pax_data['children']) ? max(0, intval($pax_data['children'])) : 0);

    $extra_adult_price = isset($pax_data['extra_adult_price']) ? floatval($pax_data['extra_adult_price']) : 0;
    $extra_child_price = isset($pax_data['extra_child_price']) ? floatval($pax_data['extra_child_price']) : 0;

    $extra_adult_percent = isset($pax_data['extra_adult_percent']) ? floatval($pax_data['extra_adult_percent']) : ktv_get_extra_adult_percent();
    $extra_child_percent = isset($pax_data['extra_child_percent']) ? floatval($pax_data['extra_child_percent']) : ktv_get_extra_child_percent();

    $base_per_person = $pax1 > 0 ? $pax1
        : ($pax2 > 0 ? $pax2
            : ($pax3 > 0 ? $pax3
                : ($group > 0 ? $group
                    : ($family > 0 ? $family : $base_price))));

    if ($base_per_person <= 0) {
        $base_per_person = $base_price;
    }

    if ($extra_adult_price > 0) {
        $extra_adult_increment = $extra_adult_price;
    } elseif ($extra_adult_percent > 0) {
        $extra_adult_increment = $base_per_person * ($extra_adult_percent / 100);
    } else {
        $extra_adult_increment = 0;
    }

    if ($extra_child_price > 0) {
        $extra_child_increment = $extra_child_price;
    } elseif ($extra_child_percent > 0) {
        $extra_child_increment = $base_per_person * ($extra_child_percent / 100);
    } else {
        $extra_child_increment = 0;
    }

    $total = $base_per_person;
    $total += $extra_adults_count * $extra_adult_increment;
    $total += $extra_children_count * $extra_child_increment;
    $total = $total * $nights;

    return round($total, 2);
}

function ktv_calculate_gst($amount, $percent = 5) {
    $percent = floatval($percent);
    if ($percent <= 0) {
        $percent = 0;
    }
    $gst_amount = $amount * ($percent / 100);
    return array(
        'gstAmount' => round($gst_amount, 2),
        'total'     => round($amount + $gst_amount, 2),
        'percent'   => $percent
    );
}

function ktv_get_base_per_person($tour_price, $pax_data = array()) {
    $pax_data = is_array($pax_data) ? $pax_data : array();
    $base = floatval($tour_price);
    $pax1   = isset($pax_data['pax_1_price'])  ? floatval($pax_data['pax_1_price'])  : 0;
    $pax2   = isset($pax_data['pax_2_price'])  ? floatval($pax_data['pax_2_price'])  : 0;
    $pax3   = isset($pax_data['pax_3_price'])  ? floatval($pax_data['pax_3_price'])  : 0;
    $group  = isset($pax_data['group_price'])  ? floatval($pax_data['group_price'])  : 0;
    $family = isset($pax_data['family_price']) ? floatval($pax_data['family_price']) : 0;

    $base_per_person = $pax1 > 0 ? $pax1
        : ($pax2 > 0 ? $pax2
            : ($pax3 > 0 ? $pax3
                : ($group > 0 ? $group
                    : ($family > 0 ? $family : $base))));

    if ($base_per_person <= 0) {
        $base_per_person = $base;
    }
    return $base_per_person;
}

function ktv_get_extra_unit_prices($tour_price, $pax_data = array()) {
    $pax_data = is_array($pax_data) ? $pax_data : array();
    $base_per_person = ktv_get_base_per_person($tour_price, $pax_data);

    $extra_adult_price = isset($pax_data['extra_adult_price']) ? floatval($pax_data['extra_adult_price']) : 0;
    $extra_child_price = isset($pax_data['extra_child_price']) ? floatval($pax_data['extra_child_price']) : 0;

    $extra_adult_percent = isset($pax_data['extra_adult_percent']) ? floatval($pax_data['extra_adult_percent']) : ktv_get_extra_adult_percent();
    $extra_child_percent = isset($pax_data['extra_child_percent']) ? floatval($pax_data['extra_child_percent']) : ktv_get_extra_child_percent();

    $extra_adult_increment = $extra_adult_price > 0 ? $extra_adult_price : ($extra_adult_percent > 0 ? $base_per_person * ($extra_adult_percent / 100) : 0);
    $extra_child_increment = $extra_child_price > 0 ? $extra_child_price : ($extra_child_percent > 0 ? $base_per_person * ($extra_child_percent / 100) : 0);

    return array(
        'base_per_person'       => round($base_per_person, 2),
        'extra_adult_increment' => round($extra_adult_increment, 2),
        'extra_child_increment' => round($extra_child_increment, 2)
    );
}

/* ============================================================
   10. TOUR DATA HELPERS
   ============================================================ */

function ktv_get_all_block_tours() {
    $cached = get_transient('ktv_all_block_tours');
    if ($cached !== false) {
        return $cached;
    }

    global $wpdb;
    $ghost_sql = ktv_get_ghost_sql_exclusion();

    $db_tours = $wpdb->get_results(
        "SELECT * FROM {$wpdb->prefix}ktv_tours
        WHERE status = 'published'
          AND is_hardcoded = 0
          AND (is_ghost = 0 OR is_ghost IS NULL)
          AND {$ghost_sql}
        ORDER BY featured DESC, id ASC
        LIMIT 500"
    );

    if (empty($db_tours)) {
        set_transient('ktv_all_block_tours', array(), 5 * MINUTE_IN_SECONDS);
        return array();
    }

    $all_tours = array();
    foreach ($db_tours as $tour) {
        if (ktv_is_tour_excluded($tour->tour_name)) {
            continue;
        }
        $all_tours[] = $tour;
    }

    set_transient('ktv_all_block_tours', $all_tours, 5 * MINUTE_IN_SECONDS);
    return $all_tours;
}

function ktv_get_tour_by_id($tour_id, $allow_draft = false) {
    global $wpdb;
    $tour_id = intval($tour_id);
    if ($tour_id < 1) {
        return null;
    }

    if ($allow_draft) {
        $tour = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_tours
             WHERE id = %d AND is_hardcoded = 0
               AND (is_ghost = 0 OR is_ghost IS NULL)",
            $tour_id
        ));
    } else {
        $tour = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_tours
             WHERE id = %d AND status = 'published' AND is_hardcoded = 0
               AND (is_ghost = 0 OR is_ghost IS NULL)",
            $tour_id
        ));
    }

    if ($tour && ktv_is_tour_excluded($tour->tour_name)) {
        return null;
    }

    return $tour;
}

function ktv_find_tour_row($tour_name = '', $tour_id = 0) {
    global $wpdb;

    $tour_id = intval($tour_id);

    if ($tour_id > 0) {
        $row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_tours
             WHERE id = %d AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)
             LIMIT 1",
            $tour_id
        ));
        if ($row && !ktv_is_tour_excluded($row->tour_name)) {
            return $row;
        }
    }

    if (empty($tour_name)) {
        return null;
    }

    $clean_name = ktv_strip_emoji_prefix($tour_name);

    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_tours
         WHERE tour_name = %s AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)
         LIMIT 1",
        $clean_name
    ));
    if ($row && !ktv_is_tour_excluded($row->tour_name)) {
        return $row;
    }

    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_tours
         WHERE tour_slug = %s AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)
         LIMIT 1",
        sanitize_title($clean_name)
    ));
    if ($row && !ktv_is_tour_excluded($row->tour_name)) {
        return $row;
    }

    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_tours
         WHERE tour_name LIKE %s AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)
         LIMIT 1",
        $wpdb->esc_like($clean_name) . '%'
    ));
    if ($row && !ktv_is_tour_excluded($row->tour_name)) {
        return $row;
    }

    return null;
}

function ktv_get_booking_form_tours() {
    $cached = get_transient('ktv_booking_form_tours');
    if ($cached !== false) {
        return $cached;
    }

    global $wpdb;
    $ghost_sql = ktv_get_ghost_sql_exclusion();

    $tours = $wpdb->get_results(
        "SELECT * FROM {$wpdb->prefix}ktv_tours
        WHERE status = 'published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)
          AND {$ghost_sql}
        ORDER BY featured DESC, tour_name ASC
        LIMIT 500"
    );

    if (empty($tours)) {
        set_transient('ktv_booking_form_tours', array(), 5 * MINUTE_IN_SECONDS);
        return array();
    }

    $result = array();
    $seen   = array();

    foreach ($tours as $tour) {
        $name = trim($tour->tour_name);
        if (ktv_is_tour_excluded($name)) {
            continue;
        }
        $lower = strtolower($name);
        if (in_array($lower, $seen, true)) {
            continue;
        }
        $seen[] = $lower;

        $price = ($tour->tour_offer_price && $tour->tour_offer_price > 0 && $tour->tour_offer_price < $tour->tour_price)
            ? $tour->tour_offer_price
            : $tour->tour_price;

        $block_type    = $tour->tour_block_type ?: 'grid';
        $resolved_icon = ktv_resolve_tour_icon(isset($tour->icon_title) ? $tour->icon_title : '', $block_type);

        $nights = intval($tour->tour_duration_nights);
        $days   = intval($tour->tour_duration_days);

        $visible_pax = isset($tour->visible_pax_columns) && !empty($tour->visible_pax_columns)
            ? $tour->visible_pax_columns
            : 'pax1';

        $result[] = array(
            'id'                    => $tour->id,
            'tour_name'             => $name,
            'tour_price'            => floatval($tour->tour_price),
            'original_price'        => floatval($tour->tour_price),
            'offer_price'           => floatval($tour->tour_offer_price),
            'tour_offer_price'      => floatval($tour->tour_offer_price),
            'display_price'         => floatval($price),
            'location'              => $tour->tour_location,
            'tour_city'             => isset($tour->tour_city) ? $tour->tour_city : '',
            'tour_region'           => isset($tour->tour_region) ? $tour->tour_region : '',
            'tour_country'          => isset($tour->tour_country) && !empty($tour->tour_country) ? $tour->tour_country : 'India',
            'nights'                => $nights,
            'days'                  => $days,
            'durationNights'        => $nights,
            'durationDays'          => $days,
            'block_type'            => $block_type,
            'tour_block_type'       => $block_type,
            'badge_text'            => $tour->badge_text,
            'badge_color'           => $tour->badge_color ?: '#ff5722',
            'badge_position'        => isset($tour->badge_position) ? $tour->badge_position : 'top-left',
            'icon_title'            => $resolved_icon,
            'icon_prefix'           => ktv_icon_to_prefix($resolved_icon),
            'pax_1_price'           => floatval($tour->pax_1_price),
            'pax_2_price'           => floatval($tour->pax_2_price),
            'pax_3_price'           => floatval($tour->pax_3_price),
            'group_price'           => floatval($tour->group_price),
            'family_price'          => floatval($tour->family_price),
            'extra_adult_price'     => floatval($tour->extra_adult_price),
            'extra_child_price'     => floatval($tour->extra_child_price),
            'extra_adult_label'     => $tour->extra_adult_label,
            'extra_child_label'     => $tour->extra_child_label,
            'pax_1_label'           => $tour->pax_1_label,
            'pax_2_label'           => $tour->pax_2_label,
            'pax_3_label'           => $tour->pax_3_label,
            'group_label'           => $tour->group_label,
            'family_label'          => $tour->family_label,
            'pax_1_icon'            => $tour->pax_1_icon,
            'pax_2_icon'            => $tour->pax_2_icon,
            'pax_3_icon'            => $tour->pax_3_icon,
            'group_icon'            => $tour->group_icon,
            'family_icon'           => $tour->family_icon,
            'group_max_persons'     => isset($tour->group_max_persons) ? intval($tour->group_max_persons) : 0,
            'family_max_persons'    => isset($tour->family_max_persons) ? intval($tour->family_max_persons) : 0,
            'visible_pax_columns'   => $visible_pax,
            'hotels_icon'           => $tour->hotels_icon,
            'hotels_label'          => $tour->hotels_label,
            'meals_icon'            => $tour->meals_icon,
            'meals_label'           => $tour->meals_label,
            'transport_icon'        => $tour->transport_icon,
            'transport_label'       => $tour->transport_label,
            'sightseeing_icon'      => $tour->sightseeing_icon,
            'sightseeing_label'     => $tour->sightseeing_label,
            'flight_icon'           => $tour->flight_icon,
            'flight_label'          => $tour->flight_label,
            'boat_icon'             => $tour->boat_icon,
            'boat_label'            => $tour->boat_label,
            'horse_riding_icon'     => $tour->horse_riding_icon,
            'horse_riding_label'    => $tour->horse_riding_label,
            'trekking_icon'         => $tour->trekking_icon,
