            'show_badge'            => intval($tour->show_badge),
            'show_icons'            => intval($tour->show_icons),
            'show_pax'              => intval($tour->show_pax),
            'show_icon_enabled'     => intval($tour->show_icon_enabled),
            'enable_icon_dropdown'  => isset($tour->enable_icon_dropdown) ? intval($tour->enable_icon_dropdown) : 1,
            'enable_ip_pricing'     => 1,
