            'review_star_color'     => $tour->review_star_color,
            'review_star_size'      => $tour->review_star_size,
            'is_hardcoded'          => 0
        );
    }

    set_transient('ktv_booking_form_tours', $result, 5 * MINUTE_IN_SECONDS);
    return $result;
}

function ktv_get_tours_by_date_range($location = '', $start_date = '', $end_date = '') {
    global $wpdb;

    $where  = "status='published' AND is_hardcoded=0 AND (is_ghost=0 OR is_ghost IS NULL)";
    $params = array();

    if (!empty($location)) {
        $where    .= " AND tour_location LIKE %s";
        $params[] = '%' . $wpdb->esc_like($location) . '%';
    }

    if (!empty($start_date) && !empty($end_date)) {
        $start    = date('Y-m-d', strtotime($start_date));
        $end      = date('Y-m-d', strtotime($end_date));
        $nights   = ceil((strtotime($end) - strtotime($start)) / 86400);
        $where   .= " AND tour_duration_nights <= %d";
        $params[] = $nights + 2;
    }

    $sql = "SELECT * FROM {$wpdb->prefix}ktv_tours WHERE $where ORDER BY featured DESC, id ASC LIMIT 100";
    if (!empty($params)) {
        $sql = $wpdb->prepare($sql, $params);
    }

    $results = $wpdb->get_results($sql);
    if (empty($results)) {
        return array();
    }

    $filtered = array();
    foreach ($results as $t) {
        if (ktv_is_tour_excluded($t->tour_name)) {
            continue;
        }
        $filtered[] = $t;
    }

    return $filtered;
}

