function ktv_get_tours_by_block_type($block_type = 'all', $limit = 100) {
    global $wpdb;
    $where  = "status='published' AND is_hardcoded=0 AND (is_ghost=0 OR is_ghost IS NULL)";
    $params = array();

    if ($block_type !== 'all' && !empty($block_type)) {
        $where    .= " AND tour_block_type = %s";
        $params[] = $block_type;
    }

    $params[] = intval($limit);

    $sql = "SELECT * FROM {$wpdb->prefix}ktv_tours WHERE $where ORDER BY featured DESC, id ASC LIMIT %d";

    $results = $wpdb->get_results($wpdb->prepare($sql, $params));
    if (empty($results)) {
        return array();
    }

    $filtered = array();
    foreach ($results as $t) {
        if (ktv_is_tour_excluded($t->tour_name)) {
            continue;
        }
        $filtered[] = $t;
    }

    return $filtered;
}

/* ============================================================
   11. UNIQUE META PER TOUR (BOOKING FORM SEO)
   ============================================================ */

function ktv_get_tour_meta_for_booking($tour_id, $fallback = array()) {
    $fallback = is_array($fallback) ? $fallback : array();
    $tour     = ktv_get_tour_by_id($tour_id, true);

    if (!$tour) {
        return array(
            'title'       => isset($fallback['title']) ? $fallback['title'] : '',
            'description' => isset($fallback['description']) ? $fallback['description'] : ''
        );
    }

    $site_name = wp_strip_all_tags(get_bloginfo('name'));

    $title = trim((string) $tour->tour_name);
    $title = $title !== '' ? $title : (isset($fallback['title']) ? $fallback['title'] : '');

    if (!empty($tour->tour_location)) {
        $title .= ' — ' . wp_strip_all_tags($tour->tour_location);
    }
    if (!empty($site_name)) {
        $title .= ' | ' . $site_name;
    }

    $description = '';
    if (!empty($tour->tour_brief_text)) {
        $description = wp_strip_all_tags($tour->tour_brief_text);
    } elseif (!empty($tour->tour_description)) {
        $description = wp_strip_all_tags($tour->tour_description);
    } elseif (!empty($fallback['description'])) {
        $description = wp_strip_all_tags($fallback['description']);
    }

    if (!empty($tour->tour_duration_nights) || !empty($tour->tour_duration_days)) {
        $duration_bits = array();
        if (!empty($tour->tour_duration_nights)) {
            $duration_bits[] = intval($tour->tour_duration_nights) . ' nights';
        }
        if (!empty($tour->tour_duration_days)) {
            $duration_bits[] = intval($tour->tour_duration_days) . ' days';
        }
        if (!empty($duration_bits)) {
            $description = trim($description . ' ' . implode(' / ', $duration_bits) . '.');
        }
    }

    if (function_exists('mb_substr')) {
        $description = mb_substr($description, 0, 160);
    } else {
        $description = substr($description, 0, 160);
    }

    return array(
        'title'       => $title,
        'description' => trim($description)
    );
}

/* ============================================================
   12. BOOKING HELPERS
   ============================================================ */

function ktv_get_admin_bookings_all($search = '', $status = '', $block_type = '', $limit = 20, $offset = 0) {
    global $wpdb;

    $where_params = ktv_build_admin_bookings_where($search, $status, $block_type);
    $where  = $where_params['where'];
    $params = $where_params['params'];

    $params[] = intval($limit);
    $params[] = intval($offset);

    $sql = "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE $where ORDER BY id DESC LIMIT %d OFFSET %d";
    $bookings = $wpdb->get_results($wpdb->prepare($sql, $params));

    if (empty($bookings)) {
        return array();
    }

    foreach ($bookings as $booking) {
        if (intval($booking->tour_id) === 0 && !empty($booking->tour_type)) {
            $found_tour = ktv_find_block_tour_by_title($booking->tour_type);
            if ($found_tour) {
                $booking->tour_id = $found_tour['id'];
                $booking->tour_block_type = $found_tour['block_type'];
                if (empty($booking->block_type) || $booking->block_type === 'grid') {
                    $booking->block_type = $found_tour['block_type'];
                }
            }
        }
    }

    return $bookings;
}

function ktv_build_admin_bookings_where($search = '', $status = '', $block_type = '') {
    global $wpdb;

    $where  = "1=1";
    $params = array();

    if (!empty($search)) {
        $like = '%' . $wpdb->esc_like($search) . '%';
        $fields = array(
            'booking_ref', 'name', 'email', 'phone', 'tour_type',
            'voucher_code', 'id_document', 'passport_id', 'visa_id',
            'card_last_four', 'flight_airline', 'flight_number',
            'country', 'block_type', 'tour_block_type'
        );
        $parts = array();
        foreach ($fields as $f) {
            $parts[] = "{$f} LIKE %s";
            $params[] = $like;
        }
        $parts[] = "CAST(id AS CHAR) LIKE %s";
        $params[] = $like;
        $where .= " AND (" . implode(' OR ', $parts) . ")";
    }

    if (!empty($status)) {
        $where    .= " AND booking_status = %s";
        $params[] = $status;
    }

    if (!empty($block_type)) {
        $where    .= " AND block_type = %s";
        $params[] = $block_type;
    }

    return array('where' => $where, 'params' => $params);
}

function ktv_find_block_tour_by_title($tour_name) {
    global $wpdb;

    if (empty($tour_name)) {
        return null;
    }

    $clean_name = ktv_strip_emoji_prefix($tour_name);

    $db_tour = $wpdb->get_row($wpdb->prepare(
        "SELECT id, tour_block_type FROM {$wpdb->prefix}ktv_tours WHERE tour_name = %s AND is_hardcoded = 0 LIMIT 1",
        $clean_name
    ));

    if ($db_tour) {
        return array(
            'id'         => intval($db_tour->id),
            'block_type' => $db_tour->tour_block_type ?: 'grid',
            'source_id'  => 0
        );
    }

    $posts = ktv_get_ktv_blocks_posts_scan();

    if (empty($posts)) {
        return null;
    }

    foreach ($posts as $post) {
        $blocks = ktv_parse_block_attributes($post->post_content);
        foreach ($blocks as $parsed) {
            $name = '';
            if (isset($parsed['attrs']['title'])) {
                $name = $parsed['attrs']['title'];
            } elseif (isset($parsed['attrs']['tourName'])) {
                $name = $parsed['attrs']['tourName'];
            }

            if (!empty($name) && strcasecmp(trim($name), trim($clean_name)) === 0) {
                $block_type = 'grid';
                if ($parsed['block'] === 'tour-card') {
                    $block_type = 'card';
                } elseif ($parsed['block'] === 'tour-package') {
                    $block_type = 'package';
                }
                if (isset($parsed['attrs']['tour_block_type']) && !empty($parsed['attrs']['tour_block_type'])) {
                    $block_type = $parsed['attrs']['tour_block_type'];
                }
                return array(
                    'id'         => 0,
                    'block_type' => $block_type,
                    'source_id'  => intval($post->ID)
                );
            }

            if (!empty($parsed['attrs']['customTours']) && is_array($parsed['attrs']['customTours'])) {
                foreach ($parsed['attrs']['customTours'] as $ct) {
                    if (!is_array($ct) || empty($ct['title'])) {
                        continue;
                    }
                    if (strcasecmp(trim($ct['title']), trim($clean_name)) === 0) {
                        $bt = isset($ct['tour_block_type']) ? $ct['tour_block_type'] : ($parsed['block'] === 'tour-card' ? 'card' : ($parsed['block'] === 'tour-package' ? 'package' : 'grid'));
                        return array(
                            'id'         => isset($ct['id']) ? intval($ct['id']) : 0,
                            'block_type' => $bt,
                            'source_id'  => intval($post->ID)
                        );
                    }
                }
            }
        }
    }

    return null;
}

function ktv_get_ktv_blocks_posts_scan() {
    static $posts_cache = null;
    if ($posts_cache !== null) {
        return $posts_cache;
    }
    global $wpdb;
    $posts_cache = $wpdb->get_results(
        "SELECT ID, post_content FROM {$wpdb->posts}
        WHERE post_status = 'publish'
          AND (post_content LIKE '%wp:ktv/tour-card%'
               OR post_content LIKE '%wp:ktv/tour-grid%'
               OR post_content LIKE '%wp:ktv/tour-package%')
        LIMIT 500"
    );
    if (!is_array($posts_cache)) {
        $posts_cache = array();
    }
    return $posts_cache;
}

function ktv_get_admin_bookings_count_all($search = '', $status = '', $block_type = '') {
    global $wpdb;

    $where_params = ktv_build_admin_bookings_where($search, $status, $block_type);
    $where  = $where_params['where'];
    $params = $where_params['params'];

    $sql = "SELECT COUNT(*) FROM {$wpdb->prefix}ktv_bookings WHERE $where";
    if (!empty($params)) {
        $sql = $wpdb->prepare($sql, $params);
    }

    return $wpdb->get_var($sql);
}

function ktv_get_booking_by_identifier($identifier) {
    global $wpdb;

    $booking = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_bookings
        WHERE id = %d
        OR booking_ref = %s
        OR voucher_code = %s
        OR CAST(id AS CHAR) = %s",
        $identifier, $identifier, $identifier, $identifier
    ));

    if ($booking) {
        $voucher = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_vouchers WHERE booking_id = %d",
            $booking->id
        ));
        if ($voucher) {
            $booking->voucher_data = $voucher;
        }
    }

    return $booking;
}

function ktv_update_booking_status($booking_id, $status, $reason = '') {
    global $wpdb;

    $allowed = array('pending', 'confirmed', 'cancelled', 'completed', 'modified', 'cancel_requested', 'modify_requested');
    if (!in_array($status, $allowed, true)) {
        return array('success' => false, 'message' => 'Invalid status');
    }

    $data = array('booking_status' => $status, 'is_read' => 1);
    if (!empty($reason)) {
        $data['decline_reason'] = $reason;
    }

    $result = $wpdb->update($wpdb->prefix . 'ktv_bookings', $data, array('id' => $booking_id));

    if ($result === false) {
        return array('success' => false, 'message' => 'Database error');
    }

    $booking = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d",
        $booking_id
    ));

    if (!$booking) {
        return array('success' => false, 'message' => 'Booking not found after update');
    }

    $booking->booking_status = $status;
    $fresh_voucher_code = $booking->voucher_code;

    if ($status === 'modified') {
        ktv_recalculate_booking_pricing($booking_id);
        $booking = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d",
            $booking_id
        ));
        if ($booking) {
            $booking->booking_status = $status;
            $fresh_voucher_code = $booking->voucher_code;
        }
    }

    $tour_name_display = !empty($booking->tour_name) ? $booking->tour_name : $booking->tour_type;

    if (in_array($status, array('confirmed', 'modified', 'completed', 'cancelled'), true)) {
        $voucher_code = $booking->voucher_code;
        if (empty($voucher_code)) {
            $voucher_code = ktv_generate_voucher_code();
        }
        $fresh_voucher_code = $voucher_code;

        $booking_array = (array) $booking;
        if (empty($booking_array['nights'])) {
            $arrival   = !empty($booking->arrival_date)   ? strtotime($booking->arrival_date)   : 0;
            $departure = !empty($booking->departure_date) ? strtotime($booking->departure_date) : 0;
            $booking_array['nights'] = ($arrival && $departure) ? max(1, (int) (($departure - $arrival) / DAY_IN_SECONDS)) : 1;
        }
        $booking_array['nights'] = max(1, intval($booking_array['nights']));
        $booking_array['days']   = intval($booking_array['nights']) + 1;
        $booking_array['voucher_code']   = $voucher_code;
        $booking_array['booking_status'] = $status;
        if (!empty($reason)) {
            $booking_array['decline_reason'] = $reason;
        }

        ktv_regenerate_voucher_for_status($booking_id, $booking_array, $status);

        $booking = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d",
            $booking_id
        ));
        if ($booking) {
            $booking->booking_status = $status;
            $fresh_voucher_code = !empty($booking->voucher_code) ? $booking->voucher_code : $voucher_code;
        }
    }

    if ($booking) {
        $booking->booking_status = $status;
        if (!empty($fresh_voucher_code)) {
            $booking->voucher_code = $fresh_voucher_code;
        }
    }

    $send_result = ktv_send_status_message($booking, $status, $reason, $tour_name_display);

    do_action('ktv_after_booking_status_change', $booking_id, $status, $booking);

    return array(
        'success' => true,
        'email_sent' => !empty($send_result['sent']),
        'email_error' => isset($send_result['error']) ? $send_result['error'] : ''
    );
}

function ktv_regenerate_voucher_for_status($booking_id, $booking_array, $status) {
    $voucher_code = isset($booking_array['voucher_code']) ? $booking_array['voucher_code'] : '';
    if (empty($voucher_code)) {
        $voucher_code = ktv_generate_voucher_code();
        $booking_array['voucher_code'] = $voucher_code;
    }
    $booking_array['booking_status'] = $status;
    return ktv_generate_and_store_voucher($booking_id, $booking_array, true, 'render');
}

function ktv_recalculate_booking_pricing($booking_id) {
    global $wpdb;

    $booking = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d",
        $booking_id
    ));

    if (!$booking) {
        return false;
    }

    $tour_row = ktv_find_tour_row($booking->tour_type ?: $booking->tour_name, intval($booking->tour_id));

    $tour_price = floatval($booking->tour_price);
    if ($tour_row) {
        $row_price = ($tour_row->tour_offer_price && $tour_row->tour_offer_price > 0 && $tour_row->tour_offer_price < $tour_row->tour_price)
            ? floatval($tour_row->tour_offer_price)
            : floatval($tour_row->tour_price);
        if ($row_price > 0) {
            $tour_price = $row_price;
        }
    }

    $pax_data = array(
        'extra_adult_price'   => 0,
        'extra_child_price'   => 0,
        'extra_adult_percent' => ktv_get_extra_adult_percent(),
        'extra_child_percent' => ktv_get_extra_child_percent(),
        'pax_1_price'         => floatval($booking->pax_1_price),
        'pax_2_price'         => floatval($booking->pax_2_price),
        'pax_3_price'         => floatval($booking->pax_3_price),
        'group_price'         => floatval($booking->group_price),
        'family_price'        => floatval($booking->family_price),
        'extra_adults'        => intval($booking->extra_adults),
        'extra_children'      => intval($booking->extra_children),
        'children'            => intval($booking->children)
    );

    $nights   = max(1, intval($booking->nights));
    $adults   = max(1, intval($booking->adults));

    $subtotal = ktv_calculate_smart_price($tour_price, $adults, $nights, $pax_data);
    $gst_pct  = floatval($booking->gst_percent);
    if ($gst_pct <= 0) {
        $gst_pct = floatval(ktv_get_setting('gst_percent', '5'));
    }
    $gst_calc = ktv_calculate_gst($subtotal, $gst_pct);

    $wpdb->update(
        $wpdb->prefix . 'ktv_bookings',
        array(
            'tour_price'       => $tour_price,
            'subtotal'         => $subtotal,
            'gst_amount'       => $gst_calc['gstAmount'],
            'total_amount'     => $gst_calc['total'],
            'gst_percent'      => $gst_pct,
            'base_price_per_person' => ktv_get_base_per_person($tour_price, $pax_data)
        ),
        array('id' => $booking_id)
    );

    return true;
}

function ktv_send_status_message($booking, $status, $reason = '', $tour_name_display = '') {
    global $wpdb;

    if (empty($tour_name_display)) {
        $tour_name_display = !empty($booking->tour_name) ? $booking->tour_name : $booking->tour_type;
    }

    $booking->booking_status = $status;

    $subject = '';
    $message = '';
    $sent = false;
    $error_msg = '';

    if ($status === 'confirmed') {
        $voucher_code = $booking->voucher_code;
        if (empty($voucher_code)) {
            $voucher_code = ktv_generate_voucher_code();
            $booking->voucher_code = $voucher_code;
        }

        $sent = ktv_send_voucher_email($booking, $voucher_code, '');
        if (!$sent) {
            $error_msg = 'wp_mail returned false for voucher email';
        }

        $subject = 'Booking Accepted - ' . $booking->booking_ref;
        $message = "Your booking has been accepted. Ref: {$booking->booking_ref}, Voucher: {$voucher_code}, Tour: {$tour_name_display}";

    } elseif ($status === 'cancelled') {
        $voucher_code = $booking->voucher_code;
        if (empty($voucher_code)) {
            $voucher_code = ktv_generate_voucher_code();
            $booking->voucher_code = $voucher_code;
        }

        $booking->booking_status = 'cancelled';

        $sent = ktv_send_voucher_email($booking, $voucher_code, '', $reason);
        if (!$sent) {
            $error_msg = 'wp_mail returned false for declined voucher email';
        }

        $subject = 'Booking Declined - ' . $booking->booking_ref;
        $message = "Your booking has been declined.";
        if (!empty($reason)) {
            $message .= " Reason: " . $reason;
        }
        $message .= " Ref: {$booking->booking_ref}, Voucher: {$voucher_code}, Tour: {$tour_name_display}";

    } elseif ($status === 'modified') {
        $voucher_code = $booking->voucher_code;
        if (empty($voucher_code)) {
            $voucher_code = ktv_generate_voucher_code();
            $booking->voucher_code = $voucher_code;
        }

        $booking->booking_status = 'modified';

        $sent = ktv_send_voucher_email($booking, $voucher_code, '');
        if (!$sent) {
            $error_msg = 'wp_mail returned false for modified voucher email';
        }

        $subject = "Booking Modified - " . $booking->booking_ref;
        $message = "Your booking has been modified. Ref: {$booking->booking_ref}, Voucher: {$voucher_code}, Tour: {$tour_name_display}";

    } elseif ($status === 'cancel_requested') {
        $subject = 'Cancellation Request Received - ' . $booking->booking_ref;
        $message = "Dear {$booking->name},\n\n";
        $message .= "We have received your cancellation request for booking (Ref: {$booking->booking_ref}).\n\n";
        $message .= "Your booking is NOT cancelled yet — our team will review your request and contact you shortly.\n\n";
        $message .= "Tour: {$tour_name_display}\n\n";
        $message .= "Team Kashmir Travelling Voyage";
        $sent = ktv_send_plain_email($booking->email, $subject, $message);
        if (!$sent) {
            $error_msg = 'wp_mail returned false for cancel_requested email';
        }
    } elseif ($status === 'modify_requested') {
        $subject = 'Modification Request Received - ' . $booking->booking_ref;
        $message = "Dear {$booking->name},\n\n";
        $message .= "We have received your modification request for booking (Ref: {$booking->booking_ref}).\n\n";
        $message .= "Our team will review your request and contact you shortly.\n\n";
        $message .= "Tour: {$tour_name_display}\n\n";
        $message .= "Team Kashmir Travelling Voyage";
        $sent = ktv_send_plain_email($booking->email, $subject, $message);
        if (!$sent) {
            $error_msg = 'wp_mail returned false for modify_requested email';
        }
    } elseif ($status === 'completed') {
        $subject  = "Booking Completed - " . $booking->booking_ref;
        $message  = "Dear {$booking->name},\n\n";
        $message .= "Thank you for travelling with Kashmir Travelling Voyage!\n\n";
        $message .= "Your booking (Ref: {$booking->booking_ref}) is now marked as completed.\n\n";
        $message .= "We'd love to hear about your experience. Please leave a review.\n\n";
        $message .= "Tour: {$tour_name_display}\n\n";
        $message .= "Team Kashmir Travelling Voyage";
        $sent = ktv_send_plain_email($booking->email, $subject, $message);
        if (!$sent) {
            $error_msg = 'wp_mail returned false for completed email';
        }
    }

    if (!empty($subject)) {
        $wpdb->insert($wpdb->prefix . 'ktv_auto_messages', array(
            'message_type'    => 'booking_' . $status,
            'recipient_email' => $booking->email,
            'recipient_name'  => $booking->name,
            'subject'         => $subject,
            'message_body'    => $message,
            'booking_ref'     => $booking->booking_ref,
            'tour_name'       => $tour_name_display,
            'tour_id'         => intval($booking->tour_id),
            'block_type'      => $booking->block_type,
            'send_status'     => $sent ? 'sent' : 'failed',
            'error_message'   => $error_msg,
            'sent_at'         => current_time('mysql')
        ));
    }

    return array('sent' => $sent, 'error' => $error_msg);
}

function ktv_get_tour_block_type_source($tour_id) {
    global $wpdb;
    $tour = $wpdb->get_row($wpdb->prepare(
        "SELECT tour_block_type FROM {$wpdb->prefix}ktv_tours WHERE id = %d AND is_hardcoded = 0",
        $tour_id
    ));

    if (!$tour) {
        return 'Unknown';
    }

    $sources = array(
        'grid'    => 'KTV Tour Grid',
        'package' => 'KTV Tour Package',
        'card'    => 'KTV Tour Card'
    );

    return isset($sources[$tour->tour_block_type]) ? $sources[$tour->tour_block_type] : 'KTV Tour Grid';
}

function ktv_get_available_dates($tour_id = 0, $days_ahead = 90) {
    $dates = array();
    $today = new DateTime();
    $end   = new DateTime("+$days_ahead days");

    global $wpdb;
    $booked_dates = array();
    if ($tour_id > 0) {
        $bookings = $wpdb->get_results($wpdb->prepare(
            "SELECT arrival_date, departure_date
            FROM {$wpdb->prefix}ktv_bookings
            WHERE tour_id = %d AND booking_status IN ('pending', 'confirmed')",
            $tour_id
        ));

        foreach ($bookings as $booking) {
            $start    = new DateTime($booking->arrival_date);
            $end_date = new DateTime($booking->departure_date);
            while ($start <= $end_date) {
                $booked_dates[$start->format('Y-m-d')] = true;
                $start->modify('+1 day');
            }
        }
    }

    while ($today <= $end) {
        $date_str     = $today->format('Y-m-d');
        $day_name     = $today->format('l');
        $is_weekend   = in_array($day_name, array('Saturday', 'Sunday'), true);
        $is_available = !isset($booked_dates[$date_str]);

        $dates[] = array(
            'date'         => $date_str,
            'day'          => $day_name,
            'is_weekend'   => $is_weekend,
            'is_available' => $is_available,
            'display'      => $today->format('M d, Y')
        );

        $today->modify('+1 day');
    }

    return $dates;
}

function ktv_get_booking_stats() {
    global $wpdb;
    $stats = array(
        'total'     => 0,
        'pending'   => 0,
        'confirmed' => 0,
        'cancelled' => 0,
        'completed' => 0,
        'modified'  => 0,
        'cancel_requested' => 0,
        'modify_requested' => 0
    );

    $results = $wpdb->get_results(
        "SELECT booking_status, COUNT(*) as count
        FROM {$wpdb->prefix}ktv_bookings
        GROUP BY booking_status"
    );

    if (!empty($results)) {
        foreach ($results as $row) {
            $stats[$row->booking_status] = intval($row->count);
            $stats['total'] += intval($row->count);
        }
    }

    return $stats;
}

function ktv_send_admin_notification($booking_data) {
    $admin_email = ktv_get_setting('admin_email', '');
    if (empty($admin_email)) {
        $admin_email = get_option('admin_email');
    }

    if (empty($admin_email) || !ktv_validate_email($admin_email)) {
        error_log('[KTV Admin Email] No valid admin_email configured.');
        return array('sent' => false, 'error' => 'No valid admin email configured');
    }

    $travelling_to = isset($booking_data['travel_location']) && $booking_data['travel_location'] !== ''
        ? $booking_data['travel_location']
        : 'Not specified';

    $booking_ref   = isset($booking_data['booking_ref']) ? $booking_data['booking_ref'] : '';
    $voucher_code  = isset($booking_data['voucher_code']) ? $booking_data['voucher_code'] : '';

    $admin_settings = ktv_get_admin_voucher_settings();
    $company_name   = ktv_get_setting('voucher_company_name', 'Kashmir Travelling Voyage');
    $company_phone  = ktv_get_setting('company_phone', '+917006838859');

    $currency     = isset($booking_data['currency']) && !empty($booking_data['currency']) ? $booking_data['currency'] : ktv_get_currency_code();
    $currency_sym = ktv_get_currency_symbol($currency);
    $total        = isset($booking_data['total']) ? floatval($booking_data['total']) : 0;;

    $token = '';
    if (!empty($voucher_code)) {
        $token = ktv_get_voucher_token($voucher_code);
        if (empty($token)) {
            global $wpdb;
            $row = $wpdb->get_row($wpdb->prepare(
                "SELECT id FROM {$wpdb->prefix}ktv_vouchers WHERE voucher_code = %s LIMIT 1",
                $voucher_code
            ));
            if ($row) {
                $token = ktv_generate_guest_voucher_token();
                ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
                    'voucher_token'         => $token,
                    'voucher_token_expires' => date('Y-m-d H:i:s', strtotime('+90 days'))
                ), array('id' => $row->id));
            }
        }
    }

    $voucher_url    = home_url('/voucher/' . $voucher_code);
    $token_voucher  = !empty($token) ? add_query_arg('token', $token, $voucher_url) : $voucher_url;
    $accept_url     = add_query_arg(array('admin_action' => 'accept', 'token' => $token), $voucher_url);
    $modify_url     = add_query_arg(array('admin_action' => 'modify', 'token' => $token), admin_url('admin.php?page=ktv-bookings&action=edit&id=' . intval(isset($booking_data['booking_id']) ? $booking_data['booking_id'] : 0)));
    $decline_url    = add_query_arg(array('admin_action' => 'decline', 'token' => $token), $voucher_url);

    $subject = 'New Booking - ' . $booking_ref;

    $voucher_html = '';
    if (!empty($voucher_code)) {
        global $wpdb;
        $booking_row = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE voucher_code = %s LIMIT 1",
            $voucher_code
        ));
        if ($booking_row) {
            $booking_array = (array) $booking_row;
            if (empty($booking_array['days']) && !empty($booking_array['nights'])) {
                $booking_array['days'] = intval($booking_array['nights']) + 1;
            }
            $voucher_html = ktv_generate_voucher_html_content($booking_array, $voucher_code, false, 'email', false);
        }
    }

    $action_buttons = '';
    if (!empty($token)) {
        $action_buttons .= '<div style="text-align:center;margin:20px 0;padding:20px;background:#e8f5e9;border-radius:12px;">';
        $action_buttons .= '<h3 style="margin:0 0 15px;color:#075e54;">Action Required — No Login Needed</h3>';
        $action_buttons .= '<a href="' . esc_url($accept_url) . '" style="display:inline-block;background:' . esc_attr($admin_settings['admin_action_btn_accept']) . ';color:#fff;padding:14px 28px;margin:6px;border-radius:8px;text-decoration:none;font-weight:700;"><i class="fas fa-check-circle"></i> ACCEPT BOOKING</a>';
        $action_buttons .= '<a href="' . esc_url($modify_url) . '" style="display:inline-block;background:' . esc_attr($admin_settings['admin_action_btn_modify']) . ';color:#fff;padding:14px 28px;margin:6px;border-radius:8px;text-decoration:none;font-weight:700;"><i class="fas fa-edit"></i> MODIFY BOOKING</a>';
        $action_buttons .= '<a href="' . esc_url($decline_url) . '" style="display:inline-block;background:' . esc_attr($admin_settings['admin_action_btn_decline']) . ';color:#fff;padding:14px 28px;margin:6px;border-radius:8px;text-decoration:none;font-weight:700;"><i class="fas fa-times-circle"></i> DECLINE BOOKING</a>';
        $action_buttons .= '<p style="margin:15px 0 0;font-size:12px;color:#555;">These buttons work directly from your email — no login required. You can also <a href="' . esc_url($token_voucher) . '" style="color:#075e54;">view the dynamic voucher</a>.</p>';
        $action_buttons .= '</div>';
    }

    $html  = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>' . esc_html($admin_settings['admin_heading_text']) . '</title></head><body style="margin:0;padding:20px;background:#f5f5f5;font-family:Tahoma,Arial,sans-serif;">';
    $html .= '<div style="max-width:800px;margin:0 auto 15px;padding:20px;background:#fff;border-radius:12px;">';
    $html .= '<h2 style="margin:0 0 10px;color:#075e54;">' . esc_html($admin_settings['admin_heading_text']) . '</h2>';
    $html .= '<p style="margin:0 0 15px;color:#555;">' . esc_html($admin_settings['admin_sub_heading_text']) . '</p>';
    $html .= '<p style="margin:0;font-size:14px;color:#333;">' . esc_html(str_replace(
        array('{name}', '{booking_ref}', '{tour_name}'),
        array(isset($booking_data['name']) ? $booking_data['name'] : '', $booking_ref, isset($booking_data['tour_name']) ? $booking_data['tour_name'] : ''),
        $admin_settings['admin_greeting_line']
    )) . '</p>';
    $html .= '<p style="margin:10px 0 0;font-size:14px;"><strong>Booking Ref:</strong> ' . esc_html($booking_ref) . ' &nbsp; | &nbsp; <strong>Voucher:</strong> ' . esc_html($voucher_code) . '</p>';
    $html .= '<p style="margin:5px 0 0;font-size:14px;"><strong>Guest:</strong> ' . esc_html(isset($booking_data['name']) ? $booking_data['name'] : '') . ' (' . esc_html(isset($booking_data['email']) ? $booking_data['email'] : '') . ')</p>';
    $html .= '<p style="margin:5px 0 0;font-size:14px;"><strong>Travelling To:</strong> ' . esc_html($travelling_to) . ' &nbsp; | &nbsp; <strong>Total:</strong> ' . esc_html($currency_sym . ' ' . number_format(ktv_convert_price($total, $currency), 2)) . '</p>';
    $html .= '</div>';

    $html .= $action_buttons;
    $html .= $voucher_html;

    $html .= '<div style="max-width:800px;margin:15px auto 0;padding:15px;background:#fff;border-radius:12px;text-align:center;font-size:12px;color:#666;">';
    $html .= esc_html($admin_settings['admin_footer_text']) . '<br>24/7 helpline: ' . esc_html($company_phone);
    $html .= '</div></body></html>';

    $attachments = array();

    $sent = ktv_send_email($admin_email, $subject, $html, isset($booking_data['email']) ? $booking_data['email'] : '', $attachments);

    $error = '';

    if (!$sent) {
        $error = 'wp_mail returned false for admin notification';
        error_log('[KTV Admin Email] ' . $error . ' — to: ' . $admin_email . ' ref: ' . $booking_ref);
    }

    global $wpdb;
    $wpdb->insert($wpdb->prefix . 'ktv_auto_messages', array(
        'message_type'    => 'admin_new_booking',
        'recipient_email' => $admin_email,
        'recipient_name'  => 'Admin',
        'subject'         => $subject,
        'message_body'    => 'Admin notification for booking ' . $booking_ref,
        'booking_ref'     => $booking_ref,
        'tour_name'       => isset($booking_data['tour_name']) ? $booking_data['tour_name'] : '',
        'tour_id'         => intval(isset($booking_data['booking_id']) ? $booking_data['booking_id'] : 0),
        'block_type'      => isset($booking_data['block_type']) ? $booking_data['block_type'] : 'grid',
        'send_status'     => $sent ? 'sent' : 'failed',
        'error_message'   => $error,
        'sent_at'         => current_time('mysql')
    ));

    do_action('ktv_after_email_sent', 'admin_notification', $admin_email, $sent, $error);

    return array('sent' => (bool) $sent, 'error' => $error);
}

function ktv_check_admin_permission() {
    if (!current_user_can('manage_options')) {
        wp_die('You do not have permission to access this page.');
    }
}

function ktv_check_booking_owner($booking_id) {
    global $wpdb;
    $booking = $wpdb->get_row($wpdb->prepare(
        "SELECT user_id, email FROM {$wpdb->prefix}ktv_bookings WHERE id = %d",
        $booking_id
    ));

    if (!$booking) {
        return false;
    }

    $current_user = wp_get_current_user();
    return $current_user->ID == $booking->user_id || $current_user->user_email == $booking->email;
}

function ktv_delete_tour_completely($tour_id) {
    global $wpdb;
    $tour_id = intval($tour_id);
    if ($tour_id < 1) {
        return false;
    }

    $vouchers_table = $wpdb->prefix . 'ktv_vouchers';
    if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $vouchers_table)) === $vouchers_table) {
        $wpdb->update($vouchers_table, array('tour_id' => 0), array('tour_id' => $tour_id));
    }

    $wpdb->delete($wpdb->prefix . 'ktv_reviews', array('tour_id' => $tour_id));
    $wpdb->delete($wpdb->prefix . 'ktv_wishlist', array('tour_id' => $tour_id));
    $wpdb->delete($wpdb->prefix . 'ktv_accordion_items', array('tour_id' => $tour_id));
    $wpdb->delete($wpdb->prefix . 'ktv_tab_items', array('tour_id' => $tour_id));
    $wpdb->delete($wpdb->prefix . 'ktv_auto_messages', array('tour_id' => $tour_id));
    $wpdb->delete($wpdb->prefix . 'ktv_contacts', array('tour_id' => $tour_id));

    $result = $wpdb->delete($wpdb->prefix . 'ktv_tours', array('id' => $tour_id));

    ktv_clear_tour_caches();

    return $result !== false;
}

function ktv_create_account_for_booking($booking_id, $booking_data) {
    global $wpdb;
    $email = isset($booking_data['email']) ? $booking_data['email'] : '';
    $name  = isset($booking_data['name']) ? $booking_data['name'] : '';
    $phone = isset($booking_data['phone']) ? $booking_data['phone'] : '';

    if (empty($email)) {
        return array('created' => false, 'error' => 'No email provided');
    }

    if (email_exists($email)) {
        $user = get_user_by('email', $email);
        if ($user) {
            $wpdb->update(
                $wpdb->prefix . 'ktv_bookings',
                array('user_id' => $user->ID),
                array('id' => $booking_id)
            );
            return array('created' => false, 'user_id' => $user->ID, 'existing' => true);
        }
        return array('created' => false, 'error' => 'Email exists but user not found');
    }

    $username      = sanitize_user(strtolower(explode('@', $email)[0]));
    $base_username = $username;
    $counter       = 1;
    while (username_exists($username)) {
        $username = $base_username . $counter;
        $counter++;
    }

    $password   = wp_generate_password(12, true, true);
    $name_parts = explode(' ', $name);
    $user_data  = array(
        'user_login'   => $username,
        'user_email'   => $email,
        'user_pass'    => $password,
        'display_name' => $name,
        'first_name'   => isset($name_parts[0]) ? $name_parts[0] : '',
        'last_name'    => isset($name_parts[1]) ? $name_parts[1] : '',
    );

    $user_id = wp_insert_user($user_data);
    if (is_wp_error($user_id)) {
        return array('created' => false, 'error' => $user_id->get_error_message());
    }

    update_user_meta($user_id, 'phone_number', $phone);
    update_user_meta($user_id, 'ktv_booking_refs', maybe_serialize(array($booking_data['booking_ref'])));
    $wpdb->update(
        $wpdb->prefix . 'ktv_bookings',
        array('user_id' => $user_id),
        array('id' => $booking_id)
    );

    $site_name = 'Kashmir Travelling Voyage';
    $login_url = home_url('/my-account');
    $subject   = 'Your ' . $site_name . ' Account has been Created';
    $message   = "Dear {$name},\n\nAn account has been created for you based on your booking.\n\nUsername: {$username}\nPassword: {$password}\nEmail: {$email}\n\nYou can login here: {$login_url}\n\nOnce logged in, you can view your bookings and download vouchers.\n\nThank you for choosing " . $site_name . "!\n";
    $account_sent = ktv_send_plain_email($email, $subject, $message);

    if (!$account_sent) {
        $error = 'wp_mail returned false for account creation email';
        error_log('[KTV Account Email] ' . $error . ' — to: ' . $email);
        $wpdb->insert($wpdb->prefix . 'ktv_auto_messages', array(
            'message_type'    => 'account_created',
            'recipient_email' => $email,
            'recipient_name'  => $name,
            'subject'         => $subject,
            'message_body'    => 'Account created email failed to send.',
            'booking_ref'     => isset($booking_data['booking_ref']) ? $booking_data['booking_ref'] : '',
            'send_status'     => 'failed',
            'error_message'   => $error,
            'sent_at'         => current_time('mysql')
        ));
    }

    return array('created' => true, 'user_id' => $user_id, 'username' => $username, 'password' => $password, 'email_sent' => $account_sent);
}
/* ============================================================
   13. VOUCHER ENGINE
   ============================================================ */

function ktv_generate_and_store_voucher($booking_id, $booking_data, $for_guest = true, $context = 'render') {
    global $wpdb;

    $voucher_code = isset($booking_data['voucher_code']) && !empty($booking_data['voucher_code'])
        ? $booking_data['voucher_code']
        : ktv_generate_voucher_code();

    $fresh_booking = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d",
        $booking_id
    ));

    if ($fresh_booking) {
        $booking_data = array_merge($booking_data, (array) $fresh_booking);
    }

    if (empty($booking_data['nights'])) {
        $arrival   = !empty($booking_data['arrival_date'])   ? strtotime($booking_data['arrival_date'])   : 0;
        $departure = !empty($booking_data['departure_date']) ? strtotime($booking_data['departure_date']) : 0;
        $booking_data['nights'] = ($arrival && $departure) ? max(1, (int) (($departure - $arrival) / DAY_IN_SECONDS)) : 1;
    }
    $booking_data['nights'] = max(1, intval($booking_data['nights']));
    if (empty($booking_data['days'])) {
        $booking_data['days'] = intval($booking_data['nights']) + 1;
    }

    $store_status = isset($booking_data['booking_status']) && !empty($booking_data['booking_status'])
        ? $booking_data['booking_status']
        : (($fresh_booking && !empty($fresh_booking->booking_status)) ? $fresh_booking->booking_status : 'pending');
    $booking_data['booking_status'] = $store_status;

    $store_for_guest = true;
    $store_context = 'render';
    $voucher_html  = ktv_generate_voucher_html_content($booking_data, $voucher_code, $store_for_guest, $store_context);
    $voucher_pdf_path = ktv_generate_voucher_pdf($booking_data, $voucher_code, $booking_id, $store_for_guest);

    $existing = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_vouchers WHERE voucher_code = %s",
        $voucher_code
    ));

    if ($existing) {
        $token = isset($existing->voucher_token) && !empty($existing->voucher_token)
            ? $existing->voucher_token
            : ktv_generate_guest_voucher_token();
        $token_expires = isset($existing->voucher_token_expires) && !empty($existing->voucher_token_expires)
            ? $existing->voucher_token_expires
            : date('Y-m-d H:i:s', strtotime('+90 days'));

        ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
            'voucher_html'      => $voucher_html,
            'voucher_pdf_path'  => $voucher_pdf_path,
            'booking_status'    => $store_status,
            'voucher_token'     => $token,
            'voucher_token_expires' => $token_expires
        ), array('id' => $existing->id));
    } else {
        ktv_db_insert_safe($wpdb->prefix . 'ktv_vouchers', array(
            'booking_id'        => $booking_id,
            'user_id'           => isset($booking_data['user_id']) ? $booking_data['user_id'] : 0,
            'tour_id'           => isset($booking_data['tour_id']) ? $booking_data['tour_id'] : 0,
            'voucher_code'      => $voucher_code,
            'voucher_html'      => $voucher_html,
            'voucher_pdf_path'  => $voucher_pdf_path,
            'booking_status'    => $store_status,
            'voucher_token'     => ktv_generate_guest_voucher_token(),
            'voucher_token_expires' => date('Y-m-d H:i:s', strtotime('+90 days')),
            'created_at'        => current_time('mysql')
        ));
    }

    ktv_db_update_safe($wpdb->prefix . 'ktv_bookings', array(
        'voucher_code'     => $voucher_code,
        'voucher_pdf_path' => $voucher_pdf_path,
        'nights'           => intval($booking_data['nights'])
    ), array('id' => $booking_id));

    do_action('ktv_after_voucher_generated', $booking_id, $voucher_code, $booking_data);

    return $voucher_code;
}

function ktv_get_voucher_token($voucher_code) {
    global $wpdb;
    if (empty($voucher_code)) {
        return '';
    }
    $row = $wpdb->get_row($wpdb->prepare(
        "SELECT id, voucher_token, voucher_token_expires FROM {$wpdb->prefix}ktv_vouchers WHERE voucher_code = %s LIMIT 1",
        $voucher_code
    ));
    if (!$row) {
        return '';
    }

    if (empty($row->voucher_token)) {
        $new_token = ktv_generate_guest_voucher_token();
        $expires   = date('Y-m-d H:i:s', strtotime('+90 days'));
        ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
            'voucher_token'         => $new_token,
            'voucher_token_expires' => $expires
        ), array('id' => $row->id));
        return $new_token;
    }

    if (!empty($row->voucher_token_expires) && strtotime($row->voucher_token_expires) < time()) {
        $new_token = ktv_generate_guest_voucher_token();
        $expires   = date('Y-m-d H:i:s', strtotime('+90 days'));
        ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
            'voucher_token'         => $new_token,
            'voucher_token_expires' => $expires
        ), array('id' => $row->id));
        return $new_token;
    }

    return $row->voucher_token;
}

function ktv_validate_voucher_token($voucher_code, $token) {
    if (empty($voucher_code) || empty($token)) {
        return false;
    }
    $stored = ktv_get_voucher_token($voucher_code);
    if (empty($stored)) {
        return false;
    }
    return hash_equals($stored, $token);
}

function ktv_generate_voucher_pdf($booking_data, $voucher_code, $booking_id, $for_guest = true) {
    $upload_dir  = wp_upload_dir();
    $voucher_dir = $upload_dir['basedir'] . '/ktv-vouchers/';
    if (!file_exists($voucher_dir)) {
        wp_mkdir_p($voucher_dir);
    }

    if (!is_writable($voucher_dir)) {
        error_log('[KTV Voucher PDF] Directory not writable: ' . $voucher_dir);
        return '';
    }

    $voucher_html = ktv_generate_voucher_html_content($booking_data, $voucher_code, $for_guest, 'download');
    $voucher_html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Voucher ' . esc_html($voucher_code) . '</title></head><body>' . $voucher_html . '</body></html>';

    $filename = 'voucher-' . $booking_id . '-' . $voucher_code . '.pdf';
    $filepath = $voucher_dir . $filename;
    $fileurl  = $upload_dir['baseurl'] . '/ktv-vouchers/' . $filename;

    if (class_exists('Dompdf\\Dompdf')) {
        try {
            $options = new \Dompdf\Options();
            $options->set('defaultFont', 'DejaVu Sans');
            $options->set('isRemoteEnabled', true);
            $options->set('isHtml5ParserEnabled', true);
            $options->set('isFontSubsettingEnabled', true);
            $options->set('chroot', $upload_dir['basedir']);
            $options->set('tempDir', sys_get_temp_dir());
            $dompdf = new \Dompdf\Dompdf($options);
            $dompdf->loadHtml($voucher_html);
            $dompdf->setPaper('A4', 'portrait');
            $dompdf->render();
            $pdf_content = $dompdf->output();
            file_put_contents($filepath, $pdf_content);
            return $fileurl;
        } catch (Exception $e) {
            error_log('[KTV Voucher PDF] Dompdf failed: ' . $e->getMessage());
        }
    }

    if (class_exists('Mpdf\\Mpdf')) {
        try {
            $mpdf = new \Mpdf\Mpdf(array('mode' => 'utf-8', 'format' => 'A4', 'tempDir' => sys_get_temp_dir()));
            $mpdf->WriteHTML($voucher_html);
            $mpdf->Output($filepath, 'F');
            if (file_exists($filepath)) {
                return $fileurl;
            }
        } catch (Exception $e) {
            error_log('[KTV Voucher PDF] Mpdf failed: ' . $e->getMessage());
        }
    }

    if (class_exists('TCPDF')) {
        try {
            $pdf = new TCPDF('P', 'mm', 'A4', true, 'UTF-8');
            $pdf->SetCreator('KTV Travel');
            $pdf->SetTitle('Voucher ' . $voucher_code);
            $pdf->AddPage();
            $pdf->writeHTML($voucher_html, true, false, true, false, '');
            $pdf->Output($filepath, 'F');
            if (file_exists($filepath)) {
                return $fileurl;
            }
        } catch (Exception $e) {
            error_log('[KTV Voucher PDF] TCPDF failed: ' . $e->getMessage());
        }
    }

    $debug_path = $voucher_dir . 'debug-' . $booking_id . '-' . $voucher_code . '.html';
    @file_put_contents($debug_path, $voucher_html);

    error_log('[KTV Voucher PDF] No PDF library available for voucher ' . $voucher_code);
    return '';
}

function ktv_generate_voucher_docx_html($booking_data, $voucher_code) {
    $voucher_html = ktv_generate_voucher_html_content($booking_data, $voucher_code, true, 'download');
    $doc = '<html xmlns:o="urn:schemas-microsoft-com:office:office" '
         . 'xmlns:w="urn:schemas-microsoft-com:office:word" '
         . 'xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="UTF-8">'
         . '<title>Voucher ' . esc_html($voucher_code) . '</title>'
         . '<style>body{font-family:Tahoma,Arial,sans-serif;font-size:14px;}</style>'
         . '</head><body>' . $voucher_html . '</body></html>';
    return $doc;
}

function ktv_build_voucher_text($booking_data, $voucher_code) {
    $booking_currency = !empty($booking_data['currency']) ? $booking_data['currency'] : ktv_get_currency_code();
    $currency_sym = ktv_get_currency_symbol($booking_currency);
    $company_name = ktv_get_setting('voucher_company_name', 'Kashmir Travelling Voyage');
    $onpage       = ktv_get_onpage_voucher_settings();

    $subtotal   = isset($booking_data['subtotal'])     ? floatval($booking_data['subtotal'])     : 0;
    $gst_amount = isset($booking_data['gst_amount'])   ? floatval($booking_data['gst_amount'])   : 0;
    $total      = isset($booking_data['total_amount']) ? floatval($booking_data['total_amount']) : 0;

    $adults   = isset($booking_data['adults'])   ? intval($booking_data['adults'])   : 1;
    $children = isset($booking_data['children']) ? intval($booking_data['children']) : 0;
    $nights   = isset($booking_data['nights'])   ? intval($booking_data['nights'])   : 1;
    $days     = $nights + 1;

    $tour_name = '';
    if (!empty($booking_data['tour_name'])) {
        $tour_name = $booking_data['tour_name'];
    } elseif (!empty($booking_data['tour_type'])) {
        $tour_name = $booking_data['tour_type'];
    }

    $country = isset($booking_data['country']) && $booking_data['country'] !== '' ? $booking_data['country'] : 'N/A';

    $travel_location = ktv_resolve_travelling_to($booking_data);

    $t  = '';
    $t .= str_repeat('=', 60) . "\n";
    $t .= "  " . strtoupper($company_name) . "\n";
    $t .= "  " . strtoupper($onpage['heading_text']) . "\n";
    $t .= str_repeat('=', 60) . "\n\n";
    $t .= $onpage['voucher_code_label'] . ": {$voucher_code}\n";
    $t .= $onpage['booking_ref_label'] . ": " . (isset($booking_data['booking_ref']) ? $booking_data['booking_ref'] : '') . "\n\n";
    $t .= "--- GUEST INFORMATION ---\n";
    $t .= "Name: " . (isset($booking_data['name']) ? $booking_data['name'] : '') . "\n";
    $t .= "Email: " . (isset($booking_data['email']) ? $booking_data['email'] : '') . "\n";
    $t .= "Phone: " . (isset($booking_data['phone_code']) ? $booking_data['phone_code'] : '') . ' ' . (isset($booking_data['phone']) ? $booking_data['phone'] : '') . "\n";
    $t .= "Country: {$country}\n\n";
    $t .= "--- TOUR DETAILS ---\n";
    $t .= "Tour: {$tour_name}\n";
    $t .= "Travelling To: {$travel_location}\n";
    $t .= "Duration: {$nights} Nights / {$days} Days\n";
    $t .= "Travel Dates: " . (isset($booking_data['arrival_date']) ? $booking_data['arrival_date'] : '') . " to " . (isset($booking_data['departure_date']) ? $booking_data['departure_date'] : '') . "\n";
    $t .= "Guests: {$adults} Adult(s)";
    if ($children > 0) {
        $t .= ", {$children} Child(ren)";
    }
    $t .= "\n\n";
    $t .= "--- PRICE BREAKDOWN ---\n";
    $t .= "Subtotal: " . $currency_sym . number_format(ktv_convert_price($subtotal, $booking_currency), 2) . "\n";
    $t .= "GST: " . $currency_sym . number_format(ktv_convert_price($gst_amount, $booking_currency), 2) . "\n";
    $t .= "TOTAL: " . $currency_sym . number_format(ktv_convert_price($total, $booking_currency), 2) . "\n\n";
    $t .= str_repeat('=', 60) . "\n";

    return $t;
}

/* ============================================================
   14. VOUCHER LOGO
   ============================================================ */

function ktv_get_voucher_logo_url() {
    $raw = ktv_get_setting('voucher_logo_url', '');

    if (!empty($raw)) {
        $raw = preg_replace('#^http://#i', 'https://', $raw);
        if (strpos($raw, 'http') !== 0 && strpos($raw, '//') !== 0) {
            $raw = home_url('/' . ltrim($raw, '/'));
        }
        return esc_url_raw($raw);
    }

    $custom_logo_id = get_theme_mod('custom_logo');
    if ($custom_logo_id) {
        $logo_url = wp_get_attachment_image_url($custom_logo_id, 'full');
        if ($logo_url) {
            return esc_url_raw(preg_replace('#^http://#i', 'https://', $logo_url));
        }
    }

    $site_icon_id = get_option('site_icon');
    if ($site_icon_id) {
        $icon_url = wp_get_attachment_image_url($site_icon_id, 'full');
        if ($icon_url) {
            return esc_url_raw(preg_replace('#^http://#i', 'https://', $icon_url));
        }
    }

    return '';
}

function ktv_get_voucher_logo_data_uri() {
    $logo_url = ktv_get_voucher_logo_url();
    if (empty($logo_url)) {
        return '';
    }

    $cache_key = 'ktv_logo_data_uri_' . md5($logo_url);
    $cached = get_transient($cache_key);
    if ($cached !== false) {
        return $cached;
    }

    $upload_dir = wp_upload_dir();
    $local_path = '';

    $norm_logo = preg_replace('#^https?:#i', '', $logo_url);
    $norm_base = preg_replace('#^https?:#i', '', $upload_dir['baseurl']);

    $norm_logo_nowww = str_replace('//www.', '//', $norm_logo);
    $norm_base_nowww = str_replace('//www.', '//', $norm_base);

    if (strpos($norm_logo_nowww, $norm_base_nowww) === 0) {
        $local_path = str_replace($norm_base_nowww, $upload_dir['basedir'], $norm_logo_nowww);
    }

    if (empty($local_path) || !file_exists($local_path)) {
        $attachment_id = attachment_url_to_postid($logo_url);
        if ($attachment_id) {
            $maybe = get_attached_file($attachment_id);
            if ($maybe && file_exists($maybe)) {
                $local_path = $maybe;
            }
        }
    }

    if (empty($local_path) || !file_exists($local_path)) {
        $uploads_relative = 'wp-content/uploads/';
        $pos = strpos($norm_logo_nowww, $uploads_relative);
        if ($pos !== false) {
            $rel = substr($norm_logo_nowww, $pos + strlen('wp-content/'));
            $candidate = WP_CONTENT_DIR . '/' . $rel;
            if (file_exists($candidate)) {
                $local_path = $candidate;
            }
        }
    }

    if (!empty($local_path) && file_exists($local_path)) {
        $file_type = wp_check_filetype($local_path);
        $mime = !empty($file_type['type']) ? $file_type['type'] : '';

        if (empty($mime) || strpos($mime, 'image/') !== 0) {
            if (preg_match('/\.webp$/i', $local_path)) {
                $mime = 'image/webp';
            } elseif (preg_match('/\.svg$/i', $local_path)) {
                $mime = 'image/svg+xml';
            } elseif (preg_match('/\.png$/i', $local_path)) {
                $mime = 'image/png';
            } elseif (preg_match('/\.gif$/i', $local_path)) {
                $mime = 'image/gif';
            } elseif (preg_match('/\.(jpe?g)$/i', $local_path)) {
                $mime = 'image/jpeg';
            } else {
                set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
                return '';
            }
        }

        $size = @filesize($local_path);
        if ($size === false || $size <= 0) {
            set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
            return '';
        }

        if (strpos($mime, 'svg') !== false) {
            $contents = @file_get_contents($local_path);
            if ($contents === false || strlen($contents) > 5242880) {
                set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
                return '';
            }
            $result = 'data:image/svg+xml;base64,' . base64_encode($contents);
            set_transient($cache_key, $result, HOUR_IN_SECONDS);
            return $result;
        }

        $needs_conversion = (strpos($mime, 'webp') !== false);

        if (!$needs_conversion && $size <= 5242880) {
            $contents = @file_get_contents($local_path);
            if ($contents === false) {
                set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
                return '';
            }
            $result = 'data:' . $mime . ';base64,' . base64_encode($contents);
            set_transient($cache_key, $result, HOUR_IN_SECONDS);
            return $result;
        }

        if (!function_exists('imagecreatefromstring') || !function_exists('imagejpeg')) {
            if ($size <= 5242880) {
                $contents = @file_get_contents($local_path);
                if ($contents !== false) {
                    $result = 'data:' . $mime . ';base64,' . base64_encode($contents);
                    set_transient($cache_key, $result, HOUR_IN_SECONDS);
                    return $result;
                }
            }
            set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
            return '';
        }

        $contents = @file_get_contents($local_path);
        if ($contents === false) {
            set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
            return '';
        }
        $img = @imagecreatefromstring($contents);
        if ($img === false) {
            set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
            return '';
        }
        ob_start();
        imagejpeg($img, null, 85);
        $jpeg_data = ob_get_clean();
        imagedestroy($img);
        if (empty($jpeg_data) || strlen($jpeg_data) > 5242880) {
            set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
            return '';
        }
        $result = 'data:image/jpeg;base64,' . base64_encode($jpeg_data);
        set_transient($cache_key, $result, HOUR_IN_SECONDS);
        return $result;
    }

    $response = wp_remote_get($logo_url, array(
        'timeout'     => 4,
        'sslverify'   => true,
        'redirection' => 2,
        'user-agent'  => 'WordPress/KTV-Voucher'
    ));
    if (!is_wp_error($response) && wp_remote_retrieve_response_code($response) === 200) {
        $body = wp_remote_retrieve_body($response);
        $mime = wp_remote_retrieve_header($response, 'content-type');
        if (empty($mime)) {
            $mime = 'image/png';
        }
        $mime = trim(preg_replace('/;.*$/', '', $mime));
        if (strpos($mime, 'image/') === 0 && strlen($body) > 0 && strlen($body) < 5242880) {
            $result = 'data:' . $mime . ';base64,' . base64_encode($body);
            set_transient($cache_key, $result, HOUR_IN_SECONDS);
            return $result;
        }
    }

    if (is_wp_error($response)) {
        error_log('[KTV Voucher Logo] wp_remote_get failed for ' . $logo_url . ' — ' . $response->get_error_message());
    }

    set_transient($cache_key, '', 5 * MINUTE_IN_SECONDS);
    return '';
}

function ktv_resolve_travelling_to($booking_data) {
    $parts = array();

    $location = '';
    if (!empty($booking_data['travel_location'])) {
        $location = $booking_data['travel_location'];
    } elseif (!empty($booking_data['tour_location'])) {
        $location = $booking_data['tour_location'];
    } elseif (!empty($booking_data['tour_name'])) {
        $location = $booking_data['tour_name'];
    } elseif (!empty($booking_data['tour_type'])) {
        $location = $booking_data['tour_type'];
    }

    $city = '';
    if (!empty($booking_data['tour_city'])) {
        $city = $booking_data['tour_city'];
    } elseif (!empty($booking_data['location_city'])) {
        $city = $booking_data['location_city'];
    }

    $region = '';
    if (!empty($booking_data['tour_region'])) {
        $region = $booking_data['tour_region'];
    } elseif (!empty($booking_data['location_region'])) {
        $region = $booking_data['location_region'];
    }

    $country = '';
    if (!empty($booking_data['tour_country'])) {
        $country = $booking_data['tour_country'];
    } elseif (!empty($booking_data['location_country'])) {
        $country = $booking_data['location_country'];
    }

    if (!empty($location)) {
        $parts[] = $location;
    }
    if (!empty($city) && stripos($location, $city) === false && stripos($city, $location) === false) {
        $parts[] = $city;
    }
    if (!empty($region) && stripos(implode(', ', $parts), $region) === false) {
        $parts[] = $region;
    }

    if (empty($country)) {
        $country = 'India';
    }
    if (stripos(implode(', ', $parts), $country) === false) {
        $parts[] = $country;
    }

    $parts = array_filter(array_map('trim', $parts));
    $parts = array_unique($parts);

    if (empty($parts)) {
        return 'N/A';
    }

    return implode(', ', $parts);
}

