function ktv_generate_voucher_html_content($booking_data, $voucher_code, $for_guest = true, $context = 'render', $for_admin_email = false) {
    $company_name    = ktv_get_setting('voucher_company_name', 'Kashmir Travelling Voyage');
    $company_address = ktv_get_setting('company_address', 'Boulevard Rd, Karapura, Rainawari, Srinagar, Jammu and Kashmir 190003');
    $company_phone   = ktv_get_setting('company_phone', '+917006838859');
    $company_email   = ktv_get_setting('company_email', 'info@kashmiritours.com');

    $onpage          = ktv_get_onpage_voucher_settings();
    $email_settings  = ktv_get_email_voucher_settings();
    $display         = ktv_get_voucher_display_settings();
    $logo_url        = ktv_get_voucher_logo_url();
    $header_bg       = ktv_get_setting('voucher_header_bg', '#075e54');
    $header_text     = ktv_get_setting('voucher_header_text', 'TRAVEL VOUCHER');
    $footer_text     = ktv_get_setting('voucher_footer_text', 'Thank you for choosing Kashmir Travelling Voyage');

    $is_email_context    = ($context === 'email');
    $is_download_context = ($context === 'download');
    $is_render_context   = ($context === 'render');

    if ($is_email_context) {
        $show_logo_flag = ktv_get_setting('voucher_email_show_logo', '1') === '1';
    } else {
        $show_logo_flag = ktv_get_setting('voucher_show_logo', '1') === '1';
    }
    $show_logo = ($show_logo_flag && !empty($logo_url));

    if ($is_email_context) {
        $show_company_name = ($email_settings['email_show_company_name'] === true);
    } elseif ($is_download_context) {
        $show_company_name = (ktv_get_setting('voucher_show_company_name', '1') === '1');
    } else {
        $show_company_name = ($onpage['show_company_name'] === true);
    }

    $logo_src_for_context = '';
    $logo_cid_for_email = '';
    if ($show_logo) {
        if ($is_email_context && !$for_admin_email) {
            $cid = ktv_get_email_logo_cid();
            if (!empty($cid)) {
                $logo_cid_for_email = $cid;
                $logo_src_for_context = 'cid:' . $cid;
            }
        }
        if (empty($logo_src_for_context)) {
            if ($is_email_context) {
                $data_uri = ktv_get_voucher_logo_data_uri();
                if (!empty($data_uri)) {
                    $logo_src_for_context = $data_uri;
                } else {
                    $logo_src_for_context = $logo_url;
                }
            } else {
                $logo_src_for_context = $logo_url;
            }
        }
    }

    $show_important  = ktv_get_setting('voucher_show_important_info', '1') === '1';
    $show_policy     = ktv_get_setting('voucher_show_cancellation_policy', '1') === '1';
    $show_card       = ktv_get_setting('voucher_show_card_details', '1') === '1';
    $show_gpay       = ktv_get_setting('voucher_show_gpay_details', '1') === '1';
    $show_promo      = ktv_get_setting('voucher_show_promo_details', '1') === '1';
    $show_flight     = ktv_get_setting('voucher_show_flight_details', '1') === '1';
    $show_kids       = ktv_get_setting('voucher_show_kids', '1') === '1';
    $show_booked_via = ktv_get_setting('voucher_show_booked_via', '0') === '1';

    $voucher_font_weight = $display['font_weight'];
    $voucher_font_size   = $display['font_size'];
    $voucher_font_family = $display['font_family'];
    $voucher_font_color  = $display['ticket_text_color'];
    $voucher_section_bg  = $display['section_bg_color'];
    $voucher_section_border = $display['section_border_color'];
    $voucher_row_border  = $display['row_border_color'];
    $voucher_row_label   = $display['row_label_color'];
    $voucher_row_value   = $display['row_value_color'];
    $voucher_total_color = $display['total_color'];
    $voucher_gst_color   = $display['gst_color'];
    $voucher_heading_size = $display['heading_font_size'];
    $voucher_label_size  = $display['label_font_size'];

    $email_logo_size = intval($onpage['email_logo_size']);
    if ($email_logo_size < 40 || $email_logo_size > 300) {
        $email_logo_size = 120;
    }

    $voucher_css_vars = '--ktv-voucher-header-bg:' . esc_attr($header_bg) . ';'
        . '--ktv-voucher-logo-max-h:' . esc_attr(intval($onpage['logo_size'])) . 'px;'
        . '--ktv-voucher-ticket-border-color:' . esc_attr($display['ticket_border_color']) . ';'
        . '--ktv-voucher-ticket-border-width:' . esc_attr($display['ticket_border_width']) . ';'
        . '--ktv-voucher-ticket-border-style:' . esc_attr($display['ticket_border_style']) . ';'
        . '--ktv-voucher-ticket-bg:' . esc_attr($display['ticket_bg_color']) . ';'
        . '--ktv-voucher-ticket-bg-2:' . esc_attr($display['ticket_bg_gradient']) . ';'
        . '--ktv-voucher-ticket-text:' . esc_attr($display['ticket_text_color']) . ';'
        . '--ktv-voucher-ticket-radius:' . esc_attr($display['ticket_radius']) . ';'
        . '--ktv-voucher-row-border:' . esc_attr($display['row_border_color']) . ';'
        . '--ktv-voucher-row-label:' . esc_attr($display['row_label_color']) . ';'
        . '--ktv-voucher-row-value:' . esc_attr($display['row_value_color']) . ';'
        . '--ktv-voucher-total-color:' . esc_attr($display['total_color']) . ';'
        . '--ktv-voucher-gst-color:' . esc_attr($display['gst_color']) . ';'
        . '--ktv-voucher-status-pending:' . esc_attr($display['status_pending_color']) . ';'
        . '--ktv-voucher-status-confirmed:' . esc_attr($display['status_confirmed_color']) . ';'
        . '--ktv-voucher-status-modified:' . esc_attr($display['status_modified_color']) . ';'
        . '--ktv-voucher-status-cancelled:' . esc_attr($display['status_cancelled_color']) . ';';

    $logo_max_height = $is_email_context ? $email_logo_size : intval($onpage['logo_size']);
    if ($logo_max_height < 40 || $logo_max_height > 300) {
        $logo_max_height = 120;
    }
    $logo_max_width = intval($onpage['logo_width']);
    if ($logo_max_width < 50 || $logo_max_width > 800) {
        $logo_max_width = 300;
    }
    $logo_align = isset($onpage['logo_align']) && in_array($onpage['logo_align'], array('left', 'center', 'right'), true)
        ? $onpage['logo_align']
        : 'center';
    $logo_margin_style = 'margin: 0 auto;';
    if ($logo_align === 'left') {
        $logo_margin_style = 'margin: 0 auto 0 0;';
    } elseif ($logo_align === 'right') {
        $logo_margin_style = 'margin: 0 0 0 auto;';
    }

    $policy_text = ktv_get_cancellation_policy_text(isset($booking_data['cancellation_policy']) ? $booking_data['cancellation_policy'] : 'non_refundable');
    if (!empty($booking_data['cancellation_text'])) {
        $policy_text = $booking_data['cancellation_text'];
    }

    $booking_currency = !empty($booking_data['currency']) ? $booking_data['currency'] : ktv_get_currency_code();
    $currency_sym = ktv_get_currency_symbol($booking_currency);

    $subtotal   = isset($booking_data['subtotal'])     ? floatval($booking_data['subtotal'])     : 0;
    $gst_amount = isset($booking_data['gst_amount'])   ? floatval($booking_data['gst_amount'])   : 0;
    $total      = isset($booking_data['total_amount']) ? floatval($booking_data['total_amount']) : 0;

    $adults         = isset($booking_data['adults'])         ? intval($booking_data['adults'])         : 1;
    $children       = isset($booking_data['children'])       ? intval($booking_data['children'])       : 0;
    $extra_adults   = isset($booking_data['extra_adults'])   ? intval($booking_data['extra_adults'])   : 0;
    $extra_children = isset($booking_data['extra_children']) ? intval($booking_data['extra_children']) : 0;
    $nights         = isset($booking_data['nights'])         ? intval($booking_data['nights'])         : 0;
    $days           = isset($booking_data['days']) && intval($booking_data['days']) > 0 ? intval($booking_data['days']) : ($nights + 1);
    $tour_price     = isset($booking_data['tour_price'])     ? floatval($booking_data['tour_price'])   : 0;

    if ($nights < 1 && !empty($booking_data['arrival_date']) && !empty($booking_data['departure_date'])) {
        $a = strtotime($booking_data['arrival_date']);
        $d = strtotime($booking_data['departure_date']);
        if ($a && $d) {
            $nights = max(1, (int) (($d - $a) / DAY_IN_SECONDS));
            $days   = $nights + 1;
        }
    }

    if ($nights < 1) {
        $nights = 1;
    }
    if ($days < 1) {
        $days = $nights + 1;
    }

    if ($extra_adults < 1) {
        $extra_adults = max(0, $adults - 1);
    }
    if ($extra_children < 1 && $children > 0) {
        $extra_children = max(0, $children);
    }

    $pax_data = array(
        'pax_1_price'  => isset($booking_data['pax_1_price'])  ? floatval($booking_data['pax_1_price'])  : 0,
        'pax_2_price'  => isset($booking_data['pax_2_price'])  ? floatval($booking_data['pax_2_price'])  : 0,
        'pax_3_price'  => isset($booking_data['pax_3_price'])  ? floatval($booking_data['pax_3_price'])  : 0,
        'group_price'  => isset($booking_data['group_price'])  ? floatval($booking_data['group_price'])  : 0,
        'family_price' => isset($booking_data['family_price']) ? floatval($booking_data['family_price']) : 0,
        'extra_adult_price' => isset($booking_data['extra_adult_price']) ? floatval($booking_data['extra_adult_price']) : 0,
        'extra_child_price' => isset($booking_data['extra_child_price']) ? floatval($booking_data['extra_child_price']) : 0,
        'extra_adult_percent' => ktv_get_extra_adult_percent(),
        'extra_child_percent' => ktv_get_extra_child_percent()
    );

    $unit_prices     = ktv_get_extra_unit_prices($tour_price, $pax_data);
    $base_per_person = $unit_prices['base_per_person'];

    if ($base_per_person <= 0 && isset($booking_data['base_price_per_person']) && floatval($booking_data['base_price_per_person']) > 0) {
        $base_per_person = floatval($booking_data['base_price_per_person']);
    }
    if ($base_per_person <= 0 && $tour_price > 0) {
        $base_per_person = $tour_price;
    }

    $extra_adult_increment = $unit_prices['extra_adult_increment'];
    $extra_child_increment = $unit_prices['extra_child_increment'];

    if ($subtotal <= 0 && $base_per_person > 0) {
        $subtotal = ($base_per_person + ($extra_adults * $extra_adult_increment) + ($extra_children * $extra_child_increment)) * $nights;
    }
    if ($subtotal <= 0 && $tour_price > 0) {
        $subtotal = $tour_price * $adults * $nights;
    }
    if ($total <= 0 && $subtotal > 0) {
        $gst_pct = floatval(ktv_get_setting('gst_percent', '5'));
