function ktv_block_category($categories) {
    $category_exists = false;
    foreach ($categories as $cat) {
        if (isset($cat['slug']) && $cat['slug'] === 'ktv-travel') {
            $category_exists = true;
            break;
        }
    }
    if (!$category_exists) {
        $categories = array_merge(
            array(
                array(
                    'slug'  => 'ktv-travel',
                    'title' => '🏔️ KTV Travel Blocks',
                    'icon'  => 'palmtree'
                )
            ),
            $categories
        );
    }
    return $categories;
}
add_filter('block_categories_all', 'ktv_block_category', 10, 1);

