/* ============================================================
   22. ICON VISIBILITY HELPERS
   ============================================================ */

function ktv_icon_visibility_class($attributes) {
    $classes = array();

    if (isset($attributes['enableIcon']) && ($attributes['enableIcon'] === false || $attributes['enableIcon'] === '0' || $attributes['enableIcon'] === 0)) {
        $classes[] = 'ktv-icon-disabled';
    }
    if (isset($attributes['enableIcon']) && !($attributes['enableIcon'] === false || $attributes['enableIcon'] === '0' || $attributes['enableIcon'] === 0)) {
        $classes[] = 'ktv-icon-enabled';
    }
    if (ktv_is_dark_mode_enabled()) {
        $classes[] = 'ktv-dark-mode-global';
        $classes[] = 'ktv-dark-mode';
    }
    if (!empty($attributes['darkMode']) && ($attributes['darkMode'] === true || $attributes['darkMode'] === '1')) {
        if (!in_array('ktv-dark-mode', $classes, true)) {
            $classes[] = 'ktv-dark-mode';
        }
    }
    if (!empty($classes)) {
        return ' ' . implode(' ', $classes);
    }
    return '';
}

function ktv_badge_position_style($position) {
    $position = $position ?: 'top-left';
    $styles = array(
        'top-left'      => 'top:12px;left:12px;right:auto;bottom:auto;',
        'top-right'     => 'top:12px;right:12px;left:auto;bottom:auto;',
        'bottom-left'   => 'bottom:12px;left:12px;top:auto;right:auto;',
        'bottom-right'  => 'bottom:12px;right:12px;top:auto;left:auto;'
    );
    $classes = array(
        'top-left'     => 'ktv-badge-left',
        'top-right'    => 'ktv-badge-right',
        'bottom-left'  => 'ktv-badge-bottom-left',
        'bottom-right' => 'ktv-badge-bottom-right'
    );
    return array(
        'class' => isset($classes[$position]) ? $classes[$position] : 'ktv-badge-left',
        'style' => isset($styles[$position]) ? $styles[$position] : $styles['top-left']
    );
}

function ktv_get_visible_pax_keys($attributes) {
    $default = array('pax1');
    if (!isset($attributes['visiblePaxColumns'])) {
        return $default;
    }
    $val = $attributes['visiblePaxColumns'];
    if (is_array($val)) {
        $keys = array_filter(array_map('sanitize_key', $val));
        return empty($keys) ? $default : array_values($keys);
    }
    if (is_string($val) && $val !== '') {
        $keys = array_filter(array_map('sanitize_key', explode(',', $val)));
        return empty($keys) ? $default : array_values($keys);
    }
    return $default;
}

/* ============================================================
   23. IMAGE HELPERS
   ============================================================ */

function ktv_render_image_tag($image_id, $size = 'medium', $alt = '', $class = '', $extra_attrs = array(), $fallback_url = '', $lazy = true) {
    $image_id = intval($image_id);
    $size     = is_string($size) && $size !== '' ? $size : 'medium';
    $alt      = trim((string) $alt);
    $class    = trim((string) $class);

    $attrs = is_array($extra_attrs) ? $extra_attrs : array();

    $url = '';
    $width = 0;
    $height = 0;
    $srcset = '';
    $sizes = '';

    if ($image_id > 0) {
        $src_arr = wp_get_attachment_image_src($image_id, $size);
        if (is_array($src_arr)) {
            $url    = $src_arr[0];
            $width  = intval($src_arr[1]);
            $height = intval($src_arr[2]);
        }
        $srcset = wp_get_attachment_image_srcset($image_id, $size);
        $sizes  = wp_get_attachment_image_sizes($image_id, $size);
    }

    if (empty($url) && !empty($fallback_url)) {
        $url = $fallback_url;
    }

    if (empty($url)) {
        return '';
    }

    $parts = array();
    $parts[] = 'src="' . esc_url($url) . '"';
    $parts[] = 'alt="' . esc_attr($alt) . '"';

    if ($width > 0 && $height > 0) {
        $parts[] = 'width="' . intval($width) . '"';
        $parts[] = 'height="' . intval($height) . '"';
    }
    if (!empty($srcset)) {
        $parts[] = 'srcset="' . esc_attr($srcset) . '"';
    }
    if (!empty($sizes)) {
        $parts[] = 'sizes="' . esc_attr($sizes) . '"';
    }
    if (!empty($class)) {
        $parts[] = 'class="' . esc_attr($class) . '"';
    }
    $parts[] = 'loading="' . ($lazy ? 'lazy' : 'eager') . '"';
    $parts[] = 'decoding="async"';

    foreach ($attrs as $k => $v) {
        if ($k === 'src' || $k === 'alt' || $k === 'width' || $k === 'height' || $k === 'srcset' || $k === 'sizes' || $k === 'class' || $k === 'loading' || $k === 'decoding') {
            continue;
        }
        $parts[] = esc_attr($k) . '="' . esc_attr($v) . '"';
    }

    return '<img ' . implode(' ', $parts) . '>';
}

/* ============================================================
   24. STARS RENDERER
   ============================================================ */

function ktv_render_stars_html($rating, $star_size = '14px', $star_color = '#FFD700') {
    $html   = '';
    $rating = floatval($rating);
    for ($i = 1; $i <= 5; $i++) {
        if ($i <= floor($rating)) {
            $html .= '<i class="fas fa-star" style="font-size:' . esc_attr($star_size) . ';color:' . esc_attr($star_color) . ';"></i>';
        } elseif ($i - 0.5 <= $rating) {
            $html .= '<i class="fas fa-star-half-alt" style="font-size:' . esc_attr($star_size) . ';color:' . esc_attr($star_color) . ';"></i>';
        } else {
            $html .= '<i class="far fa-star" style="font-size:' . esc_attr($star_size) . ';color:' . esc_attr($star_color) . ';"></i>';
        }
    }
    return $html;
}

/* ============================================================
   25. BLOCK ATTRIBUTE PARSER
   ============================================================ */

function ktv_parse_block_attributes($content) {
    if (!is_string($content) || empty($content)) {
        return array();
    }

    $matches = array();
    $found   = array();

    if (!preg_match_all('/<!--\s*wp:ktv\/(tour-card|tour-package|tour-grid|tour-icons|booking-form|review-form|reviews-display|accordion|tabs|contact-form|image-badge|pixel-carousel|booking-button)(?:\s+(\{.*?\}))?\s*(?:\/)?-->/s', $content, $matches, PREG_OFFSET_CAPTURE)) {
        return array();
    }

    if (!isset($matches[1])) {
        return array();
    }

    foreach ($matches[1] as $index => $block_match) {
        $block_name = $block_match[0];
        $json_str   = isset($matches[2][$index][0]) ? trim($matches[2][$index][0]) : '';

        if (empty($json_str)) {
            $attrs = array();
        } else {
            $attrs = json_decode($json_str, true);
            if (!is_array($attrs)) {
                $attrs = ktv_parse_json_like_array($json_str);
            }
        }
        if (is_array($attrs)) {
            $found[] = array(
                'block' => $block_name,
                'attrs' => $attrs
            );
        }
    }

    return $found;
}

function ktv_parse_json_like_array($json_str) {
    $json_str = trim($json_str);
    if (empty($json_str)) {
        return array();
    }

    $decoded = json_decode($json_str, true);
    if (is_array($decoded)) {
        return $decoded;
    }

    $json_str_fixed = preg_replace('/([{,]\s*)([a-zA-Z_][a-zA-Z0-9_]*)\s*:/', '$1"$2":', $json_str);
    $decoded = json_decode($json_str_fixed, true);
    if (is_array($decoded)) {
        return $decoded;
    }

    return array();
}

/* ============================================================
   26. TOUR DETECTION FROM BLOCKS
   ============================================================ */

function ktv_detect_tours_from_blocks($page_content) {
    global $wpdb;

    $tour_data  = array();
    $tour_names = array();
    $tour_ids   = array();

    if (!is_string($page_content) || empty($page_content)) {
        return array('names' => array(), 'ids' => array(), 'data' => array());
    }

    $non_tour_blocks = array(
        'booking-form', 'booking-button', 'review-form', 'reviews-display',
        'accordion', 'tabs', 'contact-form', 'image-badge', 'pixel-carousel',
        'tour-icons'
    );

    $parsed_blocks = ktv_parse_block_attributes($page_content);

    foreach ($parsed_blocks as $parsed) {
        $block_name = $parsed['block'];

        if (in_array($block_name, $non_tour_blocks, true)) {
            continue;
        }

        $attrs = $parsed['attrs'];

        $block_type_default = 'grid';
        if ($block_name === 'tour-card') {
            $block_type_default = 'card';
        } elseif ($block_name === 'tour-package') {
            $block_type_default = 'package';
        }

        $name = '';
        if (!empty($attrs['title'])) {
            $name = $attrs['title'];
        } elseif (!empty($attrs['tourName'])) {
            $name = $attrs['tourName'];
        }

        if (!empty($name) && !ktv_is_tour_excluded($name) && !in_array($name, $tour_names, true)) {
            $id = isset($attrs['tourId']) ? intval($attrs['tourId']) : (isset($attrs['id']) ? intval($attrs['id']) : 0);
            $block_type = isset($attrs['tour_block_type']) && !empty($attrs['tour_block_type']) ? $attrs['tour_block_type'] : $block_type_default;

            $icon = isset($attrs['iconTitle']) ? $attrs['iconTitle'] : '';
            $resolved_icon = ktv_resolve_tour_icon($icon, $block_type);

            $tour_names[] = $name;
            $tour_data[]  = array(
                'name'         => $name,
                'id'           => $id,
                'price'        => isset($attrs['price']) ? floatval($attrs['price']) : 0,
                'offer_price'  => isset($attrs['offerPrice']) ? floatval($attrs['offerPrice']) : 0,
                'nights'       => isset($attrs['durationNights']) ? intval($attrs['durationNights']) : (isset($attrs['nights']) ? intval($attrs['nights']) : 0),
                'days'         => isset($attrs['durationDays']) ? intval($attrs['durationDays']) : (isset($attrs['days']) ? intval($attrs['days']) : 0),
                'location'     => isset($attrs['location']) ? $attrs['location'] : '',
                'block_type'   => $block_type,
                'icon_title'   => $resolved_icon,
                'icon_prefix'  => ktv_icon_to_prefix($resolved_icon),
                'badge_text'   => isset($attrs['badgeText']) ? $attrs['badgeText'] : '',
                'pax_1_price'  => isset($attrs['pax1Price']) ? floatval($attrs['pax1Price']) : 0,
                'pax_2_price'  => isset($attrs['pax2Price']) ? floatval($attrs['pax2Price']) : 0,
                'pax_3_price'  => isset($attrs['pax3Price']) ? floatval($attrs['pax3Price']) : 0,
                'group_price'  => isset($attrs['groupPrice']) ? floatval($attrs['groupPrice']) : 0,
                'family_price' => isset($attrs['familyPrice']) ? floatval($attrs['familyPrice']) : 0,
                'is_hardcoded' => 0
            );
        }

        if (!empty($attrs['customTours']) && is_array($attrs['customTours'])) {
            foreach ($attrs['customTours'] as $ct) {
                if (!is_array($ct)) {
                    continue;
                }
                $ct_name = isset($ct['title']) ? $ct['title'] : '';
                if (empty($ct_name) || ktv_is_tour_excluded($ct_name) || in_array($ct_name, $tour_names, true)) {
                    continue;
                }
                $ct_block_type = isset($ct['tour_block_type']) && !empty($ct['tour_block_type']) ? $ct['tour_block_type'] : $block_type_default;
                $ct_icon       = isset($ct['iconTitle']) ? $ct['iconTitle'] : '';
                $ct_icon       = ktv_resolve_tour_icon($ct_icon, $ct_block_type);

                $tour_names[] = $ct_name;
                $tour_data[]  = array(
                    'name'         => $ct_name,
                    'id'           => isset($ct['id']) ? intval($ct['id']) : 0,
                    'price'        => isset($ct['price']) ? floatval($ct['price']) : 0,
                    'offer_price'  => isset($ct['offerPrice']) ? floatval($ct['offerPrice']) : 0,
                    'nights'       => isset($ct['durationNights']) ? intval($ct['durationNights']) : 0,
                    'days'         => isset($ct['durationDays']) ? intval($ct['durationDays']) : 0,
                    'location'     => isset($ct['location']) ? $ct['location'] : '',
                    'block_type'   => $ct_block_type,
                    'icon_title'   => $ct_icon,
                    'icon_prefix'  => ktv_icon_to_prefix($ct_icon),
                    'badge_text'   => isset($ct['badgeText']) ? $ct['badgeText'] : '',
                    'pax_1_price'  => isset($ct['pax1Price']) ? floatval($ct['pax1Price']) : 0,
                    'pax_2_price'  => isset($ct['pax2Price']) ? floatval($ct['pax2Price']) : 0,
                    'pax_3_price'  => isset($ct['pax3Price']) ? floatval($ct['pax3Price']) : 0,
                    'group_price'  => isset($ct['groupPrice']) ? floatval($ct['groupPrice']) : 0,
                    'family_price' => isset($ct['familyPrice']) ? floatval($ct['familyPrice']) : 0,
                    'is_hardcoded' => 0
                );
            }
        }
    }

    if (!empty($tour_names)) {
        if (count($tour_names) > 100) {
            $tour_names = array_slice($tour_names, 0, 100);
        }

        $tour_names = array_values(array_unique(array_filter(array_map('trim', $tour_names))));

        if (!empty($tour_names)) {
            $placeholders = implode(',', array_fill(0, count($tour_names), '%s'));
            $sql = "SELECT * FROM {$wpdb->prefix}ktv_tours
                    WHERE tour_name IN ($placeholders) AND status='published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)";
            $db_tours = $wpdb->get_results($wpdb->prepare($sql, $tour_names));
        } else {
            $db_tours = array();
        }

        if (!empty($db_tours)) {
            foreach ($db_tours as $tour) {
                if (ktv_is_tour_excluded($tour->tour_name)) {
                    continue;
                }

                $price = ($tour->tour_offer_price && $tour->tour_offer_price > 0 && $tour->tour_offer_price < $tour->tour_price)
                    ? $tour->tour_offer_price
                    : $tour->tour_price;

                $found = false;
                foreach ($tour_data as &$td) {
                    if ($td['name'] === $tour->tour_name) {
                        $td['id']           = $tour->id;
                        $td['price']        = $price;
                        $td['offer_price']  = $tour->tour_offer_price;
                        $td['nights']       = $tour->tour_duration_nights;
                        $td['days']         = $tour->tour_duration_days;
                        $td['location']     = $tour->tour_location;
                        $td['block_type']   = $tour->tour_block_type ?: 'grid';
                        $td['pax_1_price']  = $tour->pax_1_price;
                        $td['pax_2_price']  = $tour->pax_2_price;
                        $td['pax_3_price']  = $tour->pax_3_price;
                        $td['group_price']  = $tour->group_price;
                        $td['family_price'] = $tour->family_price;
                        $td['badge_text']   = $tour->badge_text;
                        $td['badge_color']  = $tour->badge_color;

                        $db_icon = isset($tour->icon_title) ? $tour->icon_title : '';
                        $resolved_icon = ktv_resolve_tour_icon($db_icon, $td['block_type']);
                        $td['icon_title']  = $resolved_icon;
                        $td['icon_prefix'] = ktv_icon_to_prefix($resolved_icon);

                        $td['is_hardcoded'] = 0;
                        $found = true;
                        break;
                    }
                }
                unset($td);

                if (!$found) {
                    $block_type    = $tour->tour_block_type ?: 'grid';
                    $resolved_icon = ktv_resolve_tour_icon(isset($tour->icon_title) ? $tour->icon_title : '', $block_type);

                    $tour_data[] = array(
                        'name'         => $tour->tour_name,
                        'id'           => $tour->id,
                        'price'        => $price,
                        'offer_price'  => $tour->tour_offer_price,
                        'nights'       => $tour->tour_duration_nights,
                        'days'         => $tour->tour_duration_days,
                        'location'     => $tour->tour_location,
                        'block_type'   => $block_type,
                        'icon_title'   => $resolved_icon,
                        'icon_prefix'  => ktv_icon_to_prefix($resolved_icon),
                        'pax_1_price'  => $tour->pax_1_price,
                        'pax_2_price'  => $tour->pax_2_price,
                        'pax_3_price'  => $tour->pax_3_price,
                        'group_price'  => $tour->group_price,
                        'family_price' => $tour->family_price,
                        'badge_text'   => $tour->badge_text,
                        'badge_color'  => $tour->badge_color,
                        'is_hardcoded' => 0
                    );
                }
            }
        }
    }

    $filtered_data = array();
    $seen_names    = array();

    foreach ($tour_data as $td) {
        if (ktv_is_tour_excluded($td['name'])) {
            continue;
        }
        if (isset($td['is_hardcoded']) && $td['is_hardcoded'] == 1) {
            continue;
        }
        $lower = strtolower($td['name']);
        if (!empty($td['name']) && !in_array($lower, $seen_names, true)) {
            $seen_names[]    = $lower;
            $filtered_data[] = $td;
        }
    }

    $final_names = array();
    $final_ids   = array();
    $final_data  = array();
    $seen_final  = array();

    foreach ($filtered_data as $td) {
        $lower = strtolower($td['name']);
        if (!in_array($lower, $seen_final, true)) {
            $seen_final[]  = $lower;
            $final_names[] = $td['name'];
            $final_ids[]   = $td['id'];
            $final_data[]  = $td;
        }
    }

    return array('names' => $final_names, 'ids' => $final_ids, 'data' => $final_data);
}

/* ============================================================
   27. SHARED FIELD ICON HELPERS
   ============================================================ */

function ktv_render_field_icon_html($resolved, $extra_style = '') {
    if (!is_array($resolved) || empty($resolved['icon'])) {
        return '';
    }
    $icon_class = esc_attr($resolved['icon']);
    $size  = esc_attr($resolved['size']);
    $color = esc_attr($resolved['color']);

    $prefix = 'fas';
    if (strpos($icon_class, 'fab ') === 0 || $icon_class === 'fa-google-pay') {
        $prefix = 'fab';
        $icon_class = str_replace('fab ', '', $icon_class);
    }

    return '<i class="' . $prefix . ' ' . $icon_class . '" style="font-size:' . $size . '; color:' . $color . ';' . $extra_style . '"></i>';
}

