            <a href="<?php echo esc_url($buttonUrl); ?>" class="ktv-tour-book-btn" data-tour-id="<?php echo esc_attr($tour_id); ?>" data-tour-name="<?php echo esc_attr($title); ?>" data-tour-price="<?php echo esc_attr($per_person_base); ?>" data-tour-location="<?php echo esc_attr($location); ?>" title="<?php echo esc_attr($buttonText . ' — ' . $title); ?>" data-block-type="card"<?php echo $pax_data_attrs; ?> style="<?php echo $btn_style; ?>width:100%;padding:<?php echo esc_attr($buttonPadding); ?>;border:none;border-radius:<?php echo esc_attr($buttonBorderRadius); ?>;font-weight:<?php echo esc_attr($buttonFontWeight); ?>;font-size:<?php echo esc_attr($buttonFontSize); ?>;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);position:relative;overflow:hidden;text-decoration:none;text-align:center;">
                <i class="fas fa-calendar-check"></i> <?php echo esc_html($buttonText); ?>
            </a>
            <?php else: ?>
            <button class="ktv-tour-book-btn" data-tour-id="<?php echo esc_attr($tour_id); ?>" data-tour-name="<?php echo esc_attr($title); ?>" data-tour-price="<?php echo esc_attr($per_person_base); ?>" data-tour-location="<?php echo esc_attr($location); ?>" title="<?php echo esc_attr($buttonText . ' — ' . $title); ?>" data-block-type="card"<?php echo $pax_data_attrs; ?> style="<?php echo $btn_style; ?>width:100%;padding:<?php echo esc_attr($buttonPadding); ?>;border:none;border-radius:<?php echo esc_attr($buttonBorderRadius); ?>;font-weight:<?php echo esc_attr($buttonFontWeight); ?>;font-size:<?php echo esc_attr($buttonFontSize); ?>;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);position:relative;overflow:hidden;">
                <i class="fas fa-calendar-check"></i> <?php echo esc_html($buttonText); ?>
            </button>
            <?php endif; ?>
        </div>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   30. RENDER — TOUR GRID
   ============================================================ */

function ktv_render_block_product_grid($attributes) {
    global $wpdb;

    $attributes = is_array($attributes) ? $attributes : array();

    $custom_tours = isset($attributes['customTours']) && is_array($attributes['customTours'])
        ? $attributes['customTours']
        : array();

    $block_enable_icon_dropdown = isset($attributes['enableIconInDropdown'])
        ? (bool) $attributes['enableIconInDropdown']
        : (isset($attributes['enable_icon_dropdown']) ? (bool) $attributes['enable_icon_dropdown'] : true);

    $tours = array();

    if (!empty($custom_tours)) {
        foreach ($custom_tours as $tour) {
            if (isset($tour['is_hardcoded']) && $tour['is_hardcoded'] == 1) {
                continue;
            }
            if (isset($tour['title']) && ktv_is_tour_excluded($tour['title'])) {
                continue;
            }

            $price        = isset($tour['price']) ? floatval($tour['price']) : 0;
            $offerPrice   = isset($tour['offerPrice']) ? floatval($tour['offerPrice']) : 0;
            $displayPrice = ($offerPrice > 0 && $offerPrice < $price) ? $offerPrice : $price;
            $oldPrice     = ($offerPrice > 0 && $offerPrice < $price) ? $price : 0;

            $tours[] = array(
                'id'                => isset($tour['id']) ? intval($tour['id']) : 0,
                'title'             => isset($tour['title']) ? $tour['title'] : 'Tour',
                'price'             => $displayPrice,
                'oldPrice'          => $oldPrice,
                'imageId'           => isset($tour['imageId']) ? intval($tour['imageId']) : 0,
                'imageLink'         => isset($tour['imageLink']) ? $tour['imageLink'] : '',
                'imageDisplaySize'  => isset($tour['imageDisplaySize']) ? $tour['imageDisplaySize'] : 'medium',
                'location'          => isset($tour['location']) ? $tour['location'] : '',
                'briefText'         => isset($tour['briefText']) ? $tour['briefText'] : '',
                'badgeText'         => isset($tour['badgeText']) ? $tour['badgeText'] : '',
                'badgeColor'        => isset($tour['badgeColor']) ? $tour['badgeColor'] : '#ff5722',
                'badgeIcon'         => isset($tour['badgeIcon']) ? $tour['badgeIcon'] : 'fa-star',
                'badgePosition'     => isset($tour['badgePosition']) ? $tour['badgePosition'] : 'top-left',
                'durationNights'    => isset($tour['durationNights']) ? intval($tour['durationNights']) : (isset($tour['nights']) ? intval($tour['nights']) : 0),
                'durationDays'      => isset($tour['durationDays']) ? intval($tour['durationDays']) : (isset($tour['days']) ? intval($tour['days']) : 0),
                'rating'            => isset($tour['rating']) ? floatval($tour['rating']) : 0,
                'totalReviews'      => isset($tour['reviews']) ? intval($tour['reviews']) : 0,
                'afterTitleText'    => isset($tour['afterTitleText']) ? $tour['afterTitleText'] : '',
                'lastBookingName'   => isset($tour['lastBookingName']) ? $tour['lastBookingName'] : '',
                'lastBookingCountry' => isset($tour['lastBookingCountry']) ? $tour['lastBookingCountry'] : 'India',
                'lastBookingTime'   => isset($tour['lastBookingTime']) ? $tour['lastBookingTime'] : '',
                'lastBookingCount'  => isset($tour['lastBookingCount']) ? intval($tour['lastBookingCount']) : 0,
                'promoCode'         => isset($tour['promoCode']) ? $tour['promoCode'] : '',
                'promoDiscount'     => isset($tour['promoDiscount']) ? intval($tour['promoDiscount']) : 0,
                'promoCodeValidUntil' => isset($tour['promoCodeValidUntil']) ? $tour['promoCodeValidUntil'] : '',
                'pax1Price'         => isset($tour['pax1Price']) ? floatval($tour['pax1Price']) : 0,
                'pax2Price'         => isset($tour['pax2Price']) ? floatval($tour['pax2Price']) : 0,
                'pax3Price'         => isset($tour['pax3Price']) ? floatval($tour['pax3Price']) : 0,
                'groupPrice'        => isset($tour['groupPrice']) ? floatval($tour['groupPrice']) : 0,
                'familyPrice'       => isset($tour['familyPrice']) ? floatval($tour['familyPrice']) : 0,
                'extraAdultPrice'   => isset($tour['extraAdultPrice']) ? floatval($tour['extraAdultPrice']) : 0,
                'extraChildPrice'   => isset($tour['extraChildPrice']) ? floatval($tour['extraChildPrice']) : 0,
                'pax1Label'         => isset($tour['pax1Label']) ? $tour['pax1Label'] : '1 Pax',
                'pax2Label'         => isset($tour['pax2Label']) ? $tour['pax2Label'] : '2 Pax',
                'pax3Label'         => isset($tour['pax3Label']) ? $tour['pax3Label'] : '3 Pax',
                'groupLabel'        => isset($tour['groupLabel']) ? $tour['groupLabel'] : 'Group',
                'familyLabel'       => isset($tour['familyLabel']) ? $tour['familyLabel'] : 'Family',
                'pax1Icon'          => isset($tour['pax1Icon']) ? $tour['pax1Icon'] : 'fa-user',
                'pax2Icon'          => isset($tour['pax2Icon']) ? $tour['pax2Icon'] : 'fa-user-friends',
                'pax3Icon'          => isset($tour['pax3Icon']) ? $tour['pax3Icon'] : 'fa-users',
                'groupIcon'         => isset($tour['groupIcon']) ? $tour['groupIcon'] : 'fa-user-plus',
                'familyIcon'        => isset($tour['familyIcon']) ? $tour['familyIcon'] : 'fa-home',
                'groupMaxPersons'   => isset($tour['groupMaxPersons']) ? intval($tour['groupMaxPersons']) : 0,
                'familyMaxPersons'  => isset($tour['familyMaxPersons']) ? intval($tour['familyMaxPersons']) : 0,
                'hotelsIcon'        => isset($tour['hotelsIcon']) ? $tour['hotelsIcon'] : 'fa-hotel',
                'hotelsLabel'       => isset($tour['hotelsLabel']) ? $tour['hotelsLabel'] : 'Hotels',
                'mealsIcon'         => isset($tour['mealsIcon']) ? $tour['mealsIcon'] : 'fa-utensils',
                'mealsLabel'        => isset($tour['mealsLabel']) ? $tour['mealsLabel'] : 'Meals',
                'transportIcon'     => isset($tour['transportIcon']) ? $tour['transportIcon'] : 'fa-car',
                'transportLabel'    => isset($tour['transportLabel']) ? $tour['transportLabel'] : 'Transport',
                'sightseeingIcon'   => isset($tour['sightseeingIcon']) ? $tour['sightseeingIcon'] : 'fa-eye',
                'sightseeingLabel'  => isset($tour['sightseeingLabel']) ? $tour['sightseeingLabel'] : 'Sightseeing',
                'flightIcon'        => isset($tour['flightIcon']) ? $tour['flightIcon'] : 'fa-plane',
                'flightLabel'       => isset($tour['flightLabel']) ? $tour['flightLabel'] : 'Flight',
                'boatIcon'          => isset($tour['boatIcon']) ? $tour['boatIcon'] : 'fa-ship',
                'boatLabel'         => isset($tour['boatLabel']) ? $tour['boatLabel'] : 'Boat',
                'horseRidingIcon'   => isset($tour['horseRidingIcon']) ? $tour['horseRidingIcon'] : 'fa-horse',
                'horseRidingLabel'  => isset($tour['horseRidingLabel']) ? $tour['horseRidingLabel'] : 'Horse Riding',
                'trekkingIcon'      => isset($tour['trekkingIcon']) ? $tour['trekkingIcon'] : 'fa-hiking',
                'trekkingLabel'     => isset($tour['trekkingLabel']) ? $tour['trekkingLabel'] : 'Trekking',
                'hikingIcon'        => isset($tour['hikingIcon']) ? $tour['hikingIcon'] : 'fa-mountain',
                'hikingLabel'       => isset($tour['hikingLabel']) ? $tour['hikingLabel'] : 'Hiking',
                'galleryImages'     => isset($tour['galleryImages']) ? $tour['galleryImages'] : '',
                'galleryAutoSlide'  => isset($tour['galleryAutoSlide']) ? $tour['galleryAutoSlide'] : false,
                'gallerySlideInterval' => isset($tour['gallerySlideInterval']) ? intval($tour['gallerySlideInterval']) : 3000,
                'cancellationPolicy' => isset($tour['cancellationPolicy']) ? $tour['cancellationPolicy'] : 'non_refundable',
                'cancellationText'  => isset($tour['cancellationText']) ? $tour['cancellationText'] : '',
                'gstPercent'        => isset($tour['gstPercent']) ? $tour['gstPercent'] : '5',
                'gstLabel'          => isset($tour['gstLabel']) ? $tour['gstLabel'] : 'GST',
                'tour_block_type'   => isset($tour['tour_block_type']) ? $tour['tour_block_type'] : 'grid',
                'enable_icon_dropdown' => isset($tour['enable_icon_dropdown']) ? intval($tour['enable_icon_dropdown']) : 1,
                'nightIcon'         => isset($tour['nightIcon']) ? $tour['nightIcon'] : 'fa-moon',
                'dayIcon'           => isset($tour['dayIcon']) ? $tour['dayIcon'] : 'fa-sun',
                'nightIconSize'     => isset($tour['nightIconSize']) ? $tour['nightIconSize'] : '14px',
                'dayIconSize'       => isset($tour['dayIconSize']) ? $tour['dayIconSize'] : '14px',
                'nightIconColor'    => isset($tour['nightIconColor']) ? $tour['nightIconColor'] : '#FFD700',
                'dayIconColor'      => isset($tour['dayIconColor']) ? $tour['dayIconColor'] : '#FFA500',
                'showNightDayIcons' => isset($tour['showNightDayIcons']) ? $tour['showNightDayIcons'] : true,
                'showWishlist'      => isset($tour['showWishlist']) ? $tour['showWishlist'] : true,
                'showBadge'         => isset($tour['showBadge']) ? $tour['showBadge'] : true,
                'showIcons'         => isset($tour['showIcons']) ? $tour['showIcons'] : true,
                'showPax'           => isset($tour['showPax']) ? $tour['showPax'] : true,
                'visiblePaxColumns' => isset($tour['visiblePaxColumns']) ? $tour['visiblePaxColumns'] : 'pax1',
                'showPerDayPrice'   => isset($tour['showPerDayPrice']) ? intval($tour['showPerDayPrice']) : 1,
                'showCompletePrice' => isset($tour['showCompletePrice']) ? intval($tour['showCompletePrice']) : 0,
                'enableIpPricing'   => isset($tour['enableIpPricing']) ? intval($tour['enableIpPricing']) : 1,
                'defaultAdults'     => isset($tour['defaultAdults']) ? max(1, intval($tour['defaultAdults'])) : 2,
                'defaultChildren'   => isset($tour['defaultChildren']) ? max(0, intval($tour['defaultChildren'])) : 0,
                'iconTitle'         => isset($tour['iconTitle']) ? $tour['iconTitle'] : 'fa-map-marker-alt',
                'is_hardcoded'      => 0
            );
        }
    } else {
        $limit          = isset($attributes['limit']) ? intval($attributes['limit']) : 6;
        $sortBy         = isset($attributes['sortBy']) ? $attributes['sortBy'] : 'newest';
        $filterLocation = isset($attributes['filterLocation']) ? $attributes['filterLocation'] : '';

        $order_map = array(
            'featured'   => 'featured DESC, id DESC',
            'price_low'  => 'tour_offer_price ASC, tour_price ASC',
            'price_high' => 'tour_offer_price DESC, tour_price DESC',
            'name_asc'   => 'tour_name ASC',
            'name_desc'  => 'tour_name DESC',
            'newest'     => 'id DESC',
            'rating'     => 'tour_rating DESC, total_reviews DESC'
        );
        $order_clause = isset($order_map[$sortBy]) ? $order_map[$sortBy] : $order_map['newest'];

        $where_clause = "status='published' AND is_hardcoded=0 AND (is_ghost=0 OR is_ghost IS NULL)";
        $params       = array();

        if (!empty($filterLocation)) {
            $where_clause .= " AND tour_location LIKE %s";
            $params[]      = '%' . $wpdb->esc_like($filterLocation) . '%';
        }

        $params[] = intval($limit);

        $db_tours = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_tours WHERE $where_clause ORDER BY $order_clause LIMIT %d",
            $params
        ));

        if (empty($db_tours)) {
            return '<div class="ktv-no-tours"><i class="fas fa-info-circle"></i> No tours found. Add tours in WP Admin → KTV Travel → Tours or add them in the block editor.</div>';
        }

        foreach ($db_tours as $tour) {
            if (ktv_is_tour_excluded($tour->tour_name)) {
                continue;
            }

            $tours[] = array(
                'id'                => $tour->id,
                'title'             => $tour->tour_name,
                'price'             => ($tour->tour_offer_price && $tour->tour_offer_price > 0 && $tour->tour_offer_price < $tour->tour_price) ? $tour->tour_offer_price : $tour->tour_price,
