                'briefText'         => $tour->tour_brief_text,
                'badgeText'         => $tour->badge_text,
                'badgeColor'        => $tour->badge_color ?: '#ff5722',
                'badgeIcon'         => isset($tour->badge_icon) ? $tour->badge_icon : 'fa-star',
                'badgePosition'     => isset($tour->badge_position) ? $tour->badge_position : 'top-left',
                'durationNights'    => $tour->tour_duration_nights,
                'durationDays'      => $tour->tour_duration_days,
                'rating'            => $tour->tour_rating,
                'reviews'           => intval($tour->total_reviews),
                'totalReviews'      => $tour->total_reviews,
                'afterTitleText'    => $tour->tour_after_title_text,
                'lastBookingName'   => $tour->last_booking_name,
                'lastBookingCountry' => $tour->last_booking_country,
                'lastBookingTime'   => $tour->last_booking_time,
                'lastBookingCount'  => $tour->last_booking_count,
                'promoCode'         => $tour->promo_code,
                'promoDiscount'     => $tour->promo_discount,
                'promoCodeValidUntil' => $tour->promo_code_valid_until,
                'pax1Price'         => $tour->pax_1_price,
                'pax2Price'         => $tour->pax_2_price,
                'pax3Price'         => $tour->pax_3_price,
                'groupPrice'        => $tour->group_price,
                'familyPrice'       => $tour->family_price,
                'extraAdultPrice'   => floatval($tour->extra_adult_price),
                'extraChildPrice'   => floatval($tour->extra_child_price),
                'pax1Label'         => $tour->pax_1_label,
                'pax2Label'         => $tour->pax_2_label,
                'pax3Label'         => $tour->pax_3_label,
                'groupLabel'        => $tour->group_label,
                'familyLabel'       => $tour->family_label,
                'pax1Icon'          => $tour->pax_1_icon,
                'pax2Icon'          => $tour->pax_2_icon,
                'pax3Icon'          => $tour->pax_3_icon,
                'groupIcon'         => $tour->group_icon,
                'familyIcon'        => $tour->family_icon,
                'groupMaxPersons'   => isset($tour->group_max_persons) ? intval($tour->group_max_persons) : 0,
                'familyMaxPersons'  => isset($tour->family_max_persons) ? intval($tour->family_max_persons) : 0,
                'hotelsIcon'        => $tour->hotels_icon,
                'hotelsLabel'       => $tour->hotels_label,
                'mealsIcon'         => $tour->meals_icon,
                'mealsLabel'        => $tour->meals_label,
                'transportIcon'     => $tour->transport_icon,
                'transportLabel'    => $tour->transport_label,
                'sightseeingIcon'   => $tour->sightseeing_icon,
                'sightseeingLabel'  => $tour->sightseeing_label,
                'flightIcon'        => $tour->flight_icon,
                'flightLabel'       => $tour->flight_label,
                'boatIcon'          => $tour->boat_icon,
                'boatLabel'         => $tour->boat_label,
                'horseRidingIcon'   => $tour->horse_riding_icon,
                'horseRidingLabel'  => $tour->horse_riding_label,
                'trekkingIcon'      => $tour->trekking_icon,
                'trekkingLabel'     => $tour->trekking_label,
                'hikingIcon'        => $tour->hiking_icon,
                'hikingLabel'       => $tour->hiking_label,
                'galleryImages'     => $tour->tour_gallery,
                'galleryAutoSlide'  => $tour->gallery_auto_slide,
                'gallerySlideInterval' => $tour->gallery_slide_interval,
                'cancellationPolicy' => $tour->cancellation_policy,
                'cancellationText'  => $tour->cancellation_text,
                'gstPercent'        => $tour->gst_percent,
                'gstLabel'          => $tour->gst_label,
                'tour_block_type'   => $tour->tour_block_type ?: 'grid',
                'enable_icon_dropdown' => isset($tour->enable_icon_dropdown) ? intval($tour->enable_icon_dropdown) : 1,
                'nightIcon'         => $tour->night_icon ?: 'fa-moon',
                'dayIcon'           => $tour->day_icon ?: 'fa-sun',
                'nightIconSize'     => $tour->night_icon_size ?: '14px',
                'dayIconSize'       => $tour->day_icon_size ?: '14px',
                'nightIconColor'    => $tour->night_icon_color ?: '#FFD700',
                'dayIconColor'      => $tour->day_icon_color ?: '#FFA500',
                'showNightDayIcons' => isset($tour->show_night_day_icons) ? $tour->show_night_day_icons : true,
                'showWishlist'      => isset($tour->show_wishlist) ? $tour->show_wishlist : true,
                'showBadge'         => isset($tour->show_badge) ? $tour->show_badge : true,
                'showIcons'         => isset($tour->show_icons) ? $tour->show_icons : true,
                'showPax'           => isset($tour->show_pax) ? $tour->show_pax : true,
                'visiblePaxColumns' => isset($tour->visible_pax_columns) && !empty($tour->visible_pax_columns) ? $tour->visible_pax_columns : 'pax1',
                'showPerDayPrice'   => 1,
                'showCompletePrice' => 0,
                'enableIpPricing'   => 1,
                'defaultAdults'     => 2,
                'defaultChildren'   => 0,
                'iconTitle'         => isset($tour->icon_title) ? $tour->icon_title : '',
                'is_hardcoded'      => 0
            );
        }
    }

    $columns             = isset($attributes['columns']) ? intval($attributes['columns']) : 3;
    $showWishlistGrid    = isset($attributes['showWishlist']) ? $attributes['showWishlist'] : true;
    $showBadge           = isset($attributes['showBadge']) ? $attributes['showBadge'] : true;
