    $headingTypeRaw      = isset($attributes['headingType']) ? $attributes['headingType'] : 'h4';
    $headingType         = ktv_next_heading_level($headingTypeRaw, 'grid');
    $showReviews         = isset($attributes['showReviews']) ? $attributes['showReviews'] : true;
    $reviewStarColor     = isset($attributes['reviewStarColor']) ? $attributes['reviewStarColor'] : '#FFD700';
    $reviewStarSize      = isset($attributes['reviewStarSize']) ? $attributes['reviewStarSize'] : '14px';
    $locationIcon        = isset($attributes['locationIcon']) ? $attributes['locationIcon'] : 'fa-map-marker-alt';
    $locationIconSize    = isset($attributes['locationIconSize']) ? $attributes['locationIconSize'] : '12px';
    $locationIconColor   = isset($attributes['locationIconColor']) ? $attributes['locationIconColor'] : '#075e54';
    $locationTextSize    = isset($attributes['locationTextSize']) ? $attributes['locationTextSize'] : '13px';
    $locationTextColor   = isset($attributes['locationTextColor']) ? $attributes['locationTextColor'] : '#666666';
    $iconSize            = isset($attributes['iconSize']) ? $attributes['iconSize'] : '14px';
    $iconColor           = isset($attributes['iconColor']) ? $attributes['iconColor'] : '#075e54';
    $showPaxColumns      = isset($attributes['showPaxColumns']) ? $attributes['showPaxColumns'] : true;
    $showActivityIcons   = isset($attributes['showActivityIcons']) ? $attributes['showActivityIcons'] : true;
    $gridTitle           = isset($attributes['gridTitle']) ? $attributes['gridTitle'] : '';
    $gridTitleHeading    = isset($attributes['gridTitleHeading']) ? $attributes['gridTitleHeading'] : 'h2';
    $buttonText          = isset($attributes['buttonText']) && !empty($attributes['buttonText']) ? $attributes['buttonText'] : 'Book Now';
    $buttonUrl           = isset($attributes['buttonUrl']) ? $attributes['buttonUrl'] : '#';
    $buttonColor         = isset($attributes['buttonColor']) ? $attributes['buttonColor'] : '#ff5722';
    $buttonTextColor     = isset($attributes['buttonTextColor']) ? $attributes['buttonTextColor'] : '#ffffff';
    $filterLocation      = isset($attributes['filterLocation']) ? $attributes['filterLocation'] : '';
    $briefFontSize       = isset($attributes['briefFontSize']) ? $attributes['briefFontSize'] : '14px';
    $briefColor          = isset($attributes['briefColor']) ? $attributes['briefColor'] : '#555555';
    $afterTitleFontSize  = isset($attributes['afterTitleFontSize']) ? $attributes['afterTitleFontSize'] : '12px';
    $afterTitleColor     = isset($attributes['afterTitleColor']) ? $attributes['afterTitleColor'] : '#075e54';
    $showLastBooking     = isset($attributes['showLastBooking']) ? $attributes['showLastBooking'] : true;
    $image_display_size  = isset($attributes['imageDisplaySize']) ? $attributes['imageDisplaySize'] : 'medium';

    $nightIcon          = isset($attributes['nightIcon']) ? $attributes['nightIcon'] : 'fa-moon';
    $dayIcon            = isset($attributes['dayIcon']) ? $attributes['dayIcon'] : 'fa-sun';
    $nightIconSize      = isset($attributes['nightIconSize']) ? $attributes['nightIconSize'] : '14px';
    $dayIconSize        = isset($attributes['dayIconSize']) ? $attributes['dayIconSize'] : '14px';
    $nightIconColor     = isset($attributes['nightIconColor']) ? $attributes['nightIconColor'] : '#FFD700';
    $dayIconColor       = isset($attributes['dayIconColor']) ? $attributes['dayIconColor'] : '#FFA500';
    $showNightDayIcons  = isset($attributes['showNightDayIcons']) ? $attributes['showNightDayIcons'] : true;

    $cancellation_policy = isset($attributes['cancellationPolicy']) ? $attributes['cancellationPolicy'] : 'non_refundable';
    $cancellation_text   = isset($attributes['cancellationText']) ? $attributes['cancellationText'] : '';
    $policy_display      = ktv_get_cancellation_policy_text($cancellation_policy);
    if (!empty($cancellation_text)) {
        $policy_display = $cancellation_text;
    }

    $gst_percent = isset($attributes['gstPercent']) ? $attributes['gstPercent'] : ktv_get_setting('gst_percent', '5');
