        $wishlist_table = $wpdb->prefix . 'ktv_wishlist';

        $count_rows = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT tour_id, COUNT(*) AS cnt FROM {$wishlist_table} WHERE tour_id IN ({$ids_placeholders}) GROUP BY tour_id",
