            )
        );
        if (!empty($count_rows)) {
            foreach ($count_rows as $row) {
                $wishlist_counts_map[(string) $row->tour_id] = (int) $row->cnt;
            }
        }

        if (!empty($user_ip)) {
            $in_rows = $wpdb->get_results(
                $wpdb->prepare(
                    "SELECT DISTINCT tour_id FROM {$wishlist_table} WHERE tour_id IN ({$ids_placeholders}) AND user_ip = %s",
                    array_merge($tour_ids_for_wishlist, array($user_ip))
                )
            );
            if (!empty($in_rows)) {
                foreach ($in_rows as $row) {
                    $wishlist_in_map[(string) $row->tour_id] = 1;
                }
            }
        }
