                                array(),
                                $gimg,
                                true
                            );
                            ?>
                        </div>
                        <?php endforeach; ?>
                    </div>
                    <?php endif; ?>

                    <?php if (!empty($tour['badgeText']) && $tourShowBadge): ?>
                    <div class="ktv-tour-badge <?php echo esc_attr($tourBadgePos['class']); ?>" data-position="<?php echo esc_attr(isset($tour['badgePosition']) ? $tour['badgePosition'] : 'top-left'); ?>" style="position:absolute;<?php echo esc_attr($tourBadgePos['style']); ?>padding:6px 14px;border-radius:25px;font-size:12px;font-weight:600;color:#fff;z-index:10;display:flex;align-items:center;gap:5px;background:<?php echo esc_attr(isset($tour['badgeColor']) ? $tour['badgeColor'] : '#ff5722'); ?>;"><i class="fas <?php echo esc_attr(isset($tour['badgeIcon']) ? $tour['badgeIcon'] : 'fa-star'); ?>"></i> <?php echo esc_html($tour['badgeText']); ?></div>
                    <?php endif; ?>
                    <?php if ($discount > 0): ?>
                    <div class="ktv-tour-badge ktv-badge-deal" style="position:absolute;bottom:12px;right:12px;top:auto;padding:6px 14px;border-radius:25px;font-size:12px;font-weight:700;color:#fff;z-index:10;background:#ff5722;">-<?php echo esc_html($discount); ?>% OFF</div>
                    <?php endif; ?>

                    <?php if ($tourShowNightDayIcons && ($tour['durationNights'] > 0 || $tour['durationDays'] > 0)): ?>
                    <div class="ktv-night-day-icon" style="position:absolute;bottom:12px;left:12px;display:flex;align-items:center;gap:6px;background:rgba(0,0,0,0.7);padding:4px 12px;border-radius:15px;z-index:10;">
                        <i class="fas <?php echo esc_attr($tourNightIcon); ?>" style="font-size:<?php echo esc_attr($tourNightIconSize); ?>;color:<?php echo esc_attr($tourNightIconColor); ?> !important;"></i>
                        <span style="font-size:11px;color:#fff;font-weight:600;"><?php echo esc_html($tour['durationNights']); ?>N</span>
                        <i class="fas <?php echo esc_attr($tourDayIcon); ?>" style="font-size:<?php echo esc_attr($tourDayIconSize); ?>;color:<?php echo esc_attr($tourDayIconColor); ?> !important;"></i>
                        <span style="font-size:11px;color:#fff;font-weight:600;"><?php echo esc_html($tour['durationDays']); ?>D</span>
                    </div>
                    <?php elseif ($tour['durationNights'] > 0 || $tour['durationDays'] > 0): ?>
                    <div class="ktv-tour-duration-badge" style="position:absolute;bottom:12px;left:12px;background:rgba(0,0,0,0.7);color:#fff;padding:5px 12px;border-radius:20px;font-size:12px;display:flex;gap:8px;z-index:10;"><i class="fas fa-moon" style="color:<?php echo esc_attr($tourNightIconColor); ?> !important;"></i> <?php echo esc_html($tour['durationNights']); ?>N <i class="fas fa-sun" style="color:<?php echo esc_attr($tourDayIconColor); ?> !important;"></i> <?php echo esc_html($tour['durationDays']); ?>D</div>
                    <?php endif; ?>

                    <?php if ($tourShowWishlist && $showWishlistGrid): ?>
                    <button class="ktv-wishlist-btn<?php echo $in_wishlist > 0 ? ' active' : ''; ?>" data-tour-id="<?php echo esc_attr($tourId); ?>" data-tour-name="<?php echo esc_attr($tour['title']); ?>" data-in-wishlist="<?php echo esc_attr($in_wishlist > 0 ? 1 : 0); ?>" title="Add to Wishlist" style="position:absolute;top:12px;right:12px;background:rgba(255,255,255,0.9);border:none;width:auto;min-width:36px;height:36px;border-radius:25px;cursor:pointer;z-index:20;color:#ff4757;display:flex;align-items:center;justify-content:center;gap:5px;transition:all 0.3s ease;font-size:14px;padding:0 12px;"><i class="<?php echo $in_wishlist > 0 ? 'fas' : 'far'; ?> fa-heart"></i> <span class="ktv-wishlist-count" style="display:inline;font-size:11px;font-weight:700;color:#ff4757;background:rgba(255,71,87,0.1);padding:2px 6px;border-radius:10px;min-width:18px;text-align:center;"><?php echo esc_html($wishlist_count); ?></span></button>
                    <?php endif; ?>
                </div>
                <div class="ktv-tour-details" style="padding:18px;">
                    <?php if (!empty($tour['afterTitleText'])): ?>
                    <div class="ktv-tour-after-title" style="font-size:<?php echo esc_attr($afterTitleFontSize); ?>; color:<?php echo esc_attr($afterTitleColor); ?>; font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;"><?php echo esc_html($tour['afterTitleText']); ?></div>
                    <?php endif; ?>
                    <<?php echo esc_attr($headingType); ?> class="ktv-tour-title" style="font-size:<?php echo esc_attr($titleFontSize); ?>; color:<?php echo esc_attr($titleColor); ?>; margin:0 0 5px;line-height:1.3;">
                        <?php echo esc_html($tour['title']); ?>
                    </<?php echo esc_attr($headingType); ?>>
                    <?php if (!empty($tour['briefText'])): ?>
                    <p class="ktv-tour-brief" style="font-size:<?php echo esc_attr($briefFontSize); ?>; color:<?php echo esc_attr($briefColor); ?>; margin-bottom:8px;line-height:1.5;"><?php echo esc_html($tour['briefText']); ?></p>
                    <?php endif; ?>
                    <?php if (!empty($tour['location'])): ?>
                    <div class="ktv-tour-location" style="font-size:<?php echo esc_attr($locationTextSize); ?>; color:<?php echo esc_attr($locationTextColor); ?>; margin-bottom:12px;">
                        <i class="fas <?php echo esc_attr($locationIcon); ?>" style="font-size:<?php echo esc_attr($locationIconSize); ?>; color:<?php echo esc_attr($locationIconColor); ?>;"></i> <?php echo esc_html($tour['location']); ?>
                    </div>
                    <?php endif; ?>

                    <?php if ($showActivityIcons && $tourShowIcons): ?>
                    <div class="ktv-tour-icons" style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px;">
                        <?php foreach ($activityIcons as $iconData): ?>
                            <?php if (!empty($iconData['label']) && !empty($iconData['icon'])): ?>
                            <span class="ktv-tour-icon-item" style="font-size:<?php echo esc_attr($iconSize); ?>; color:<?php echo esc_attr($iconColor); ?>; background:#e8f5e9;padding:3px 10px;border-radius:15px;display:inline-flex;align-items:center;gap:4px;">
                                <i class="fas <?php echo esc_attr($iconData['icon']); ?>"></i> <?php echo esc_html($iconData['label']); ?>
                            </span>
                            <?php endif; ?>
                        <?php endforeach; ?>
                    </div>
                    <?php endif; ?>

                    <?php
                    echo ktv_render_pax_columns_html($pax_attributes_for_render, $cur_symbol, array(
                        'show_pax'      => $showPaxColumns && $tourShowPax,
                        'icon_size'     => $iconSize,
                        'icon_color'    => $iconColor,
                        'grid_class'    => 'ktv-tour-pax-grid'
                    ));
                    ?>

                    <?php if ($showReviews): ?>
                    <div class="ktv-tour-reviews-mini ktv-review-clickable" data-tour-id="<?php echo esc_attr($tourId); ?>" data-tour-name="<?php echo esc_attr($tour['title']); ?>" data-page-id="<?php echo esc_attr(get_the_ID()); ?>" style="cursor:pointer;display:flex;align-items:center;gap:6px;margin:4px 0 8px;">
                        <?php if ($tour['totalReviews'] > 0): ?>
                            <span class="ktv-rating-number" style="font-weight:700;font-size:16px;color:#333;"><?php echo number_format($tour['rating'], 1); ?></span>
                            <?php echo ktv_render_stars_html($tour['rating'], $reviewStarSize, $reviewStarColor); ?>
                            <span class="ktv-review-count-mini" style="font-size:12px;color:#666;">(<?php echo esc_html($tour['totalReviews']); ?> reviews)</span>
                        <?php else: ?>
                            <button type="button" class="ktv-zero-reviews-link" data-tour-id="<?php echo esc_attr($tourId); ?>" data-tour-name="<?php echo esc_attr($tour['title']); ?>" data-page-id="<?php echo esc_attr(get_the_ID()); ?>" title="Write the first review" aria-label="Write the first review for <?php echo esc_attr($tour['title']); ?>"><i class="far fa-star" style="color:<?php echo esc_attr($reviewStarColor); ?>;"></i> 0 Reviews</button>
                        <?php endif; ?>
                    </div>
                    <?php endif; ?>

                    <?php if ($showLastBooking && !empty($tour['lastBookingName']) && !empty($tour['lastBookingTime'])): ?>
                    <div class="ktv-last-booking" data-time="<?php echo esc_attr($tour['lastBookingTime']); ?>" style="display:flex;align-items:center;gap:6px;background:#e8f5e9;padding:8px 12px;border-radius:8px;font-size:12px;color:#075e54;margin-bottom:12px;line-height:1.4;">
                        <i class="fas fa-clock" style="color:#28a745;font-size:11px;"></i>
                        <?php echo isset($tour['lastBookingCount']) && $tour['lastBookingCount'] > 0 ? 'Booked ' . esc_html($tour['lastBookingCount']) . ' times' : 'Last booking'; ?>
                        <strong style="color:#075e54;"><?php echo esc_html($tour['lastBookingName']); ?></strong> from <?php echo esc_html($tour['lastBookingCountry']); ?> - <span class="ktv-time-ago" style="font-weight:600;color:#28a745;"><?php echo esc_html(ktv_time_ago($tour['lastBookingTime'])); ?></span>
                    </div>
                    <?php endif; ?>

                    <?php if (!empty($tour['promoCode'])): ?>
                    <div class="ktv-promo-code" style="margin:8px 0;padding:8px 12px;background:linear-gradient(135deg,#fff3e0,#ffe0b2);border-radius:8px;border:1px dashed #ff5722;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:5px;">
                        <span style="font-size:12px;color:#e65100;"><i class="fas fa-ticket-alt"></i> Promo: <strong style="text-transform:uppercase;"><?php echo esc_html($tour['promoCode']); ?></strong></span>
                        <?php if (isset($tour['promoDiscount']) && $tour['promoDiscount'] > 0): ?>
                        <span style="font-size:11px;color:#ff5722;font-weight:600;">-<?php echo esc_html($tour['promoDiscount']); ?>% OFF</span>
                        <?php endif; ?>
                        <?php if (!empty($tour['promoCodeValidUntil'])): ?>
                        <span style="font-size:10px;color:#999;">Valid until <?php echo esc_html(date_i18n('M d, Y', strtotime($tour['promoCodeValidUntil']))); ?></span>
                        <?php endif; ?>
                    </div>
                    <?php endif; ?>

                    <?php if (!empty($policy_display)): ?>
                    <div class="ktv-cancellation-policy" style="margin:8px 0;padding:6px 12px;background:#f8f9fa;border-radius:6px;font-size:11px;color:#666;border-left:3px solid <?php echo $cancellation_policy === 'fully_refundable' ? '#28a745' : ($cancellation_policy === 'partial_refundable' ? '#ffc107' : '#dc3545'); ?>;display:flex;align-items:center;gap:6px;">
                        <i class="fas fa-info-circle" style="margin-right:6px;font-size:12px;"></i> <?php echo esc_html($policy_display); ?>
                    </div>
                    <?php endif; ?>

                    <div class="ktv-tour-price" style="margin-bottom:15px;display:flex;align-items:baseline;gap:5px;flex-wrap:wrap;">
                        <?php if ($oldPrice > 0): ?>
                        <span class="ktv-old-price" style="text-decoration:line-through;color:#999;font-size:14px;margin-right:8px;"><?php echo esc_html($cur_symbol . number_format(ktv_convert_price($oldPrice), 2)); ?></span>
                        <?php endif; ?>
                         <span class="ktv-new-price" style="font-size:<?php echo esc_attr($priceFontSize); ?>; color:<?php echo esc_attr($priceColor); ?>;"><?php echo esc_html($cur_symbol . number_format(ktv_convert_price($displayPrice), 2)); ?></span>
                        <span class="ktv-price-unit <?php echo $tourShowComplete ? 'ktv-price-unit--complete' : 'ktv-price-unit--per-day'; ?>" style="font-size:12px;color:#767676;"><?php echo $tourShowComplete ? '/ total' : '/ person'; ?></span>
                        <?php if ($showGst): ?>
                        <span class="ktv-gst-badge" style="display:inline-block;background:<?php echo esc_attr($gst_badge_bg); ?>;color:<?php echo esc_attr($gst_badge_text); ?>;padding:2px 8px;border-radius:4px;font-size:10px;font-weight:600;margin-left:5px;"><i class="fas fa-receipt"></i> <?php echo esc_html($gst_label); ?> <?php echo esc_html($gst_percent); ?>%</span>
                        <?php endif; ?>
                    </div>
                    <?php if (!empty($buttonUrl) && $buttonUrl !== '#'): ?>
                    <a href="<?php echo esc_url($buttonUrl); ?>" class="ktv-tour-book-btn" data-tour-id="<?php echo esc_attr($tourId); ?>" data-tour-name="<?php echo esc_attr($tour['title']); ?>" data-tour-price="<?php echo esc_attr($grid_per_person_base); ?>" data-tour-location="<?php echo esc_attr($tour['location']); ?>" title="<?php echo esc_attr($buttonText . ' — ' . $tour['title']); ?>" data-block-type="grid"<?php echo $grid_pax_data_attrs; ?> style="--ktv-btn-bg:<?php echo esc_attr($buttonColor); ?>;--ktv-btn-text:<?php echo esc_attr($buttonTextColor); ?>;width:100%;padding:12px;background:var(--ktv-btn-bg);color:var(--ktv-btn-text);border:none;border-radius:30px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);font-size:14px;position:relative;overflow:hidden;text-decoration:none;text-align:center;">
                        <i class="fas fa-calendar-check"></i> <?php echo esc_html($buttonText); ?>
                    </a>
                    <?php else: ?>
                    <button class="ktv-tour-book-btn" data-tour-id="<?php echo esc_attr($tourId); ?>" data-tour-name="<?php echo esc_attr($tour['title']); ?>" data-tour-price="<?php echo esc_attr($grid_per_person_base); ?>" data-tour-location="<?php echo esc_attr($tour['location']); ?>" title="<?php echo esc_attr($buttonText . ' — ' . $tour['title']); ?>" data-block-type="grid"<?php echo $grid_pax_data_attrs; ?> style="--ktv-btn-bg:<?php echo esc_attr($buttonColor); ?>;--ktv-btn-text:<?php echo esc_attr($buttonTextColor); ?>;width:100%;padding:12px;background:var(--ktv-btn-bg);color:var(--ktv-btn-text);border:none;border-radius:30px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);font-size:14px;position:relative;overflow:hidden;">
                        <i class="fas fa-calendar-check"></i> <?php echo esc_html($buttonText); ?>
                    </button>
                    <?php endif; ?>
                </div>
            </div>
            <?php endforeach; ?>
        </div>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   31. RENDER — TOUR PACKAGE
   ============================================================ */

function ktv_render_block_tour_package($attributes) {
    global $wpdb;

    $attributes = is_array($attributes) ? $attributes : array();

    $tour_id = isset($attributes['tourId']) ? intval($attributes['tourId']) : 0;
    $db_tour = null;

    if ($tour_id > 0) {
        $db_tour = ktv_get_tour_by_id($tour_id);
    }

    $block_icon_title = isset($attributes['iconTitle']) ? $attributes['iconTitle'] : '';
    $block_enable_icon_dropdown = isset($attributes['enableIconInDropdown'])
        ? (bool) $attributes['enableIconInDropdown']
        : (isset($attributes['enable_icon_dropdown']) ? (bool) $attributes['enable_icon_dropdown'] : true);

    if ($db_tour) {
        $attribute_map = array(
            'title'              => 'tour_name',
            'location'           => 'tour_location',
            'briefText'          => 'tour_brief_text',
            'afterTitleText'     => 'tour_after_title_text',
            'badgeText'          => 'badge_text',
            'badgeColor'         => 'badge_color',
            'badgePosition'      => 'badge_position',
            'dealBadgeColor'     => 'deal_badge_color',
            'dealBadgeTextColor' => 'deal_badge_text_color',
            'dealBadgePosition'  => 'deal_badge_position',
            'buttonText'         => 'button_text',
            'buttonUrl'          => 'button_url',
            'buttonColor'        => 'button_color',
            'buttonTextColor'    => 'button_text_color',
            'imageLink'          => 'image_link_url',
            'imageDisplaySize'   => 'image_display_size',
            'galleryImages'      => 'tour_gallery',
            'gstLabel'           => 'gst_label',
            'cancellationPolicy' => 'cancellation_policy',
            'cancellationText'   => 'cancellation_text',
            'lastBookingName'    => 'last_booking_name',
            'lastBookingCountry' => 'last_booking_country',
            'lastBookingTime'    => 'last_booking_time',
            'promoCode'          => 'promo_code',
            'promoCodeValidUntil' => 'promo_code_valid_until',
            'titleColor'         => 'title_color',
            'priceColor'         => 'price_color',
            'iconColor'          => 'icon_color',
            'iconSize'           => 'icon_size',
            'headingType'        => 'heading_type',
            'reviewStarColor'    => 'review_star_color',
            'hotelsLabel'        => 'hotels_label',
            'hotelsIcon'         => 'hotels_icon',
            'mealsLabel'         => 'meals_label',
            'mealsIcon'          => 'meals_icon',
            'transportLabel'     => 'transport_label',
            'transportIcon'      => 'transport_icon',
            'sightseeingLabel'   => 'sightseeing_label',
            'sightseeingIcon'    => 'sightseeing_icon',
            'flightLabel'        => 'flight_label',
            'flightIcon'         => 'flight_icon',
            'boatLabel'          => 'boat_label',
            'boatIcon'           => 'boat_icon',
            'horseRidingLabel'   => 'horse_riding_label',
            'horseRidingIcon'    => 'horse_riding_icon',
            'trekkingLabel'      => 'trekking_label',
            'trekkingIcon'       => 'trekking_icon',
            'hikingLabel'        => 'hiking_label',
            'hikingIcon'         => 'hiking_icon',
            'nightIcon'          => 'night_icon',
            'nightIconSize'      => 'night_icon_size',
            'nightIconColor'     => 'night_icon_color',
            'dayIcon'            => 'day_icon',
            'dayIconSize'        => 'day_icon_size',
            'dayIconColor'       => 'day_icon_color',
            'pax1Label'          => 'pax_1_label',
            'pax2Label'          => 'pax_2_label',
            'pax3Label'          => 'pax_3_label',
            'groupLabel'         => 'group_label',
            'familyLabel'        => 'family_label',
            'pax1Icon'           => 'pax_1_icon',
            'pax2Icon'           => 'pax_2_icon',
            'pax3Icon'           => 'pax_3_icon',
            'groupIcon'          => 'group_icon',
            'familyIcon'         => 'family_icon',
            'visiblePaxColumns'  => 'visible_pax_columns'
        );

        foreach ($attribute_map as $attr_key => $db_key) {
            if (isset($db_tour->$db_key) && $db_tour->$db_key !== '' && $db_tour->$db_key !== null) {
                $attributes[$attr_key] = $db_tour->$db_key;
            }
        }

        $attributes['nights']            = intval($db_tour->tour_duration_nights) ?: (isset($attributes['nights']) ? intval($attributes['nights']) : 2);
        $attributes['days']              = intval($db_tour->tour_duration_days) ?: (isset($attributes['days']) ? intval($attributes['days']) : 3);
        $attributes['durationNights']    = $attributes['nights'];
        $attributes['durationDays']      = $attributes['days'];
        $attributes['price']             = floatval($db_tour->tour_price) ?: (isset($attributes['price']) ? floatval($attributes['price']) : 0);
        $attributes['offerPrice']        = floatval($db_tour->tour_offer_price) ?: (isset($attributes['offerPrice']) ? floatval($attributes['offerPrice']) : 0);
        $attributes['imageId']           = intval($db_tour->tour_image_id) ?: (isset($attributes['imageId']) ? intval($attributes['imageId']) : 0);
        $attributes['galleryAutoSlide']  = boolval($db_tour->gallery_auto_slide);
        $attributes['gallerySlideInterval'] = intval($db_tour->gallery_slide_interval) ?: 3000;
        $attributes['gstPercent']        = floatval($db_tour->gst_percent) ?: 5;
        $attributes['lastBookingCount']  = intval($db_tour->last_booking_count) ?: 0;
        $attributes['promoDiscount']     = intval($db_tour->promo_discount) ?: 0;
        $attributes['showReviews']       = boolval($db_tour->show_reviews);
        $attributes['totalReviews']      = intval($db_tour->total_reviews) ?: 0;
        $attributes['avgRating']         = floatval($db_tour->tour_rating) ?: 0;
        $attributes['tour_block_type']   = $db_tour->tour_block_type ?: 'package';
        $attributes['showNightDayIcons'] = boolval($db_tour->show_night_day_icons);
        $attributes['showWishlist']      = boolval($db_tour->show_wishlist);
        $attributes['showBadge']         = isset($db_tour->show_badge) ? boolval($db_tour->show_badge) : true;
        $attributes['showIcons']         = isset($db_tour->show_icons) ? boolval($db_tour->show_icons) : true;
        $attributes['showPax']           = isset($db_tour->show_pax) ? boolval($db_tour->show_pax) : true;
        $attributes['enableIcon']        = isset($db_tour->show_icon_enabled) ? boolval($db_tour->show_icon_enabled) : true;
        $attributes['darkMode']          = isset($db_tour->enable_dark_mode) ? boolval($db_tour->enable_dark_mode) : false;
        $attributes['pax1Price']         = floatval($db_tour->pax_1_price);
        $attributes['pax2Price']         = floatval($db_tour->pax_2_price);
        $attributes['pax3Price']         = floatval($db_tour->pax_3_price);
        $attributes['groupPrice']        = floatval($db_tour->group_price);
        $attributes['familyPrice']       = floatval($db_tour->family_price);
        $attributes['extraAdultPrice']   = floatval($db_tour->extra_adult_price);
        $attributes['extraChildPrice']   = floatval($db_tour->extra_child_price);
        $attributes['groupMaxPersons']   = isset($db_tour->group_max_persons) ? intval($db_tour->group_max_persons) : 0;
        $attributes['familyMaxPersons']  = isset($db_tour->family_max_persons) ? intval($db_tour->family_max_persons) : 0;

        if (!isset($attributes['visiblePaxColumns']) || empty($attributes['visiblePaxColumns'])) {
            $attributes['visiblePaxColumns'] = isset($db_tour->visible_pax_columns) && !empty($db_tour->visible_pax_columns) ? $db_tour->visible_pax_columns : 'pax1';
        }

        if (!empty($block_icon_title)) {
            $attributes['iconTitle'] = $block_icon_title;
        } elseif (!isset($attributes['iconTitle']) || empty($attributes['iconTitle'])) {
            $attributes['iconTitle'] = isset($db_tour->icon_title) ? $db_tour->icon_title : 'fa-map-marker-alt';
        }

        if (isset($db_tour->enable_icon_dropdown) && !isset($attributes['enableIconInDropdown'])) {
            $block_enable_icon_dropdown = intval($db_tour->enable_icon_dropdown) === 1;
        }
    }

    $title         = isset($attributes['title']) && $attributes['title'] !== '' ? $attributes['title'] : 'Kashmir Delight Package';
    $location      = isset($attributes['location']) ? $attributes['location'] : '';
    $briefText     = isset($attributes['briefText']) ? $attributes['briefText'] : '';
    $afterTitleText = isset($attributes['afterTitleText']) ? $attributes['afterTitleText'] : '';
    $nights        = isset($attributes['nights']) ? intval($attributes['nights']) : 2;
    $days          = isset($attributes['days']) ? intval($attributes['days']) : 3;
    $imageId       = isset($attributes['imageId']) ? intval($attributes['imageId']) : 0;
    $imageDisplaySize = isset($attributes['imageDisplaySize']) ? $attributes['imageDisplaySize'] : 'medium';
    $imageUrl      = $imageId ? wp_get_attachment_image_url($imageId, $imageDisplaySize) : '';
    if (!$imageUrl && $imageId) {
        $imageUrl = wp_get_attachment_url($imageId);
    }
    $imageLink   = isset($attributes['imageLink']) ? $attributes['imageLink'] : '';
    $price       = isset($attributes['price']) ? floatval($attributes['price']) : 0;
    $offerPrice  = isset($attributes['offerPrice']) ? floatval($attributes['offerPrice']) : 0;
    $badgeText   = isset($attributes['badgeText']) ? $attributes['badgeText'] : 'Popular';
    $badgeColor  = isset($attributes['badgeColor']) ? $attributes['badgeColor'] : '#ff5722';
    $badgePosition = isset($attributes['badgePosition']) ? $attributes['badgePosition'] : 'top-left';
    $buttonText  = isset($attributes['buttonText']) ? $attributes['buttonText'] : 'Book Package';
    $buttonColor = isset($attributes['buttonColor']) && !empty($attributes['buttonColor']) ? $attributes['buttonColor'] : '#075e54';
    $buttonTextColor = isset($attributes['buttonTextColor']) && !empty($attributes['buttonTextColor']) ? $attributes['buttonTextColor'] : '#ffffff';
    $titleColor  = isset($attributes['titleColor']) ? $attributes['titleColor'] : '#333333';
