                <span style="font-size:11px;color:#fff;font-weight:600;"><?php echo esc_html($days); ?>D</span>
            </div>
            <?php elseif ($nights > 0 || $days > 0): ?>
            <div class="ktv-tour-package-duration" style="position:absolute;bottom:12px;left:12px;background:rgba(0,0,0,0.7);color:#fff;padding:5px 12px;border-radius:20px;font-size:12px;z-index:10;display:flex;gap:8px;"><span><i class="fas fa-moon" style="color:<?php echo esc_attr($nightIconColor); ?> !important;"></i> <?php echo esc_html($nights); ?>N</span><span><i class="fas fa-sun" style="color:<?php echo esc_attr($dayIconColor); ?> !important;"></i> <?php echo esc_html($days); ?>D</span></div>
            <?php endif; ?>

            <?php if ($showWishlist): ?>
            <button class="ktv-wishlist-btn<?php echo $in_wishlist > 0 ? ' active' : ''; ?>" data-tour-id="<?php echo esc_attr($tour_id); ?>" data-tour-name="<?php echo esc_attr($title); ?>" data-in-wishlist="<?php echo esc_attr($in_wishlist > 0 ? 1 : 0); ?>" title="Add to Wishlist" style="position:absolute;top:12px;right:12px;background:rgba(255,255,255,0.9);border:none;width:auto;min-width:36px;height:36px;border-radius:25px;cursor:pointer;z-index:20;color:#ff4757;display:flex;align-items:center;justify-content:center;gap:5px;transition:all 0.3s ease;font-size:14px;padding:0 12px;"><i class="<?php echo $in_wishlist > 0 ? 'fas' : 'far'; ?> fa-heart"></i> <span class="ktv-wishlist-count" style="display:inline;font-size:11px;font-weight:700;color:#ff4757;background:rgba(255,71,87,0.1);padding:2px 6px;border-radius:10px;min-width:18px;text-align:center;"><?php echo esc_html($wishlist_count); ?></span></button>
            <?php endif; ?>
        </div>
        <div class="ktv-tour-package-content" style="padding:18px;">
            <?php if ($afterTitleText): ?>
            <div class="ktv-tour-package-after-title" style="font-size:12px;color:#075e54;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;"><?php echo esc_html($afterTitleText); ?></div>
            <?php endif; ?>
            <<?php echo esc_attr($headingType); ?> class="ktv-tour-package-title" style="font-size:18px;font-weight:700;margin:0 0 5px;color:<?php echo esc_attr($titleColor); ?>;line-height:1.3;">
                <?php echo esc_html($title); ?>
            </<?php echo esc_attr($headingType); ?>>
            <?php if ($briefText): ?>
            <p class="ktv-tour-package-brief" style="font-size:13px;color:#555;margin-bottom:10px;line-height:1.5;"><?php echo esc_html($briefText); ?></p>
            <?php endif; ?>
            <?php if ($location): ?>
            <div class="ktv-tour-package-location" style="font-size:13px;color:#666;margin-bottom:12px;"><i class="fas fa-map-marker-alt" style="color:<?php echo esc_attr($iconColor); ?>;"></i> <?php echo esc_html($location); ?></div>
            <?php endif; ?>

            <?php if ($showIcons): ?>
            <div class="ktv-tour-package-icons" style="display:flex;justify-content:space-around;padding:12px 0;border-top:1px solid #eee;border-bottom:1px solid #eee;margin-bottom:15px;gap:5px;flex-wrap:wrap;">
                <?php foreach ($icons as $ico): ?>
                <?php if (!empty($ico['label']) && !empty($ico['icon'])): ?>
                <div class="ktv-tour-package-icon-item" style="text-align:center;font-size:11px;color:<?php echo esc_attr($iconColor); ?>;flex:1;min-width:50px;">
                    <span class="ktv-icon" style="display:block;font-size:<?php echo esc_attr($iconSize); ?>;margin-bottom:4px;"><i class="fas <?php echo esc_attr($ico['icon']); ?>" style="color:<?php echo esc_attr($iconColor); ?>;"></i></span>
                    <span class="ktv-tour-package-icon-label" style="font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:0.3px;color:<?php echo esc_attr($iconColor); ?>;"><?php echo esc_html($ico['label']); ?></span>
                </div>
                <?php endif; ?>
                <?php endforeach; ?>
            </div>
            <?php endif; ?>

            <?php
            echo ktv_render_pax_columns_html($pax_attributes_for_render, $currency, array(
                'show_pax'      => $showPax,
                'icon_size'     => $iconSize,
                'icon_color'    => $iconColor,
                'grid_class'    => 'ktv-tour-pax-grid'
            ));
            ?>

            <?php if ($showReviews): ?>
            <div class="ktv-tour-package-reviews-mini ktv-review-clickable" data-tour-id="<?php echo esc_attr($tour_id); ?>" data-tour-name="<?php echo esc_attr($title); ?>" data-page-id="<?php echo esc_attr(get_the_ID()); ?>" style="cursor:pointer;display:flex;align-items:center;gap:6px;margin:4px 0 8px;">
                <?php if ($totalReviews > 0): ?>
                    <span class="ktv-rating-number" style="font-weight:700;font-size:16px;color:#333;"><?php echo number_format($avgRating, 1); ?></span>
                    <?php echo ktv_render_stars_html($avgRating, '14px', $reviewStarColor); ?>
                    <span class="ktv-review-count-mini" style="font-size:12px;color:#666;">(<?php echo esc_html($totalReviews); ?> reviews)</span>
                <?php else: ?>
                    <button type="button" class="ktv-zero-reviews-link" data-tour-id="<?php echo esc_attr($tour_id); ?>" data-tour-name="<?php echo esc_attr($title); ?>" data-page-id="<?php echo esc_attr(get_the_ID()); ?>" title="Write the first review" aria-label="Write the first review for <?php echo esc_attr($title); ?>"><i class="far fa-star" style="color:<?php echo esc_attr($reviewStarColor); ?>;"></i> 0 Reviews</button>
                <?php endif; ?>
            </div>
            <?php endif; ?>

            <?php if ($showLastBooking && !empty($lastBookingName) && !empty($lastBookingTime)): ?>
            <div class="ktv-last-booking" data-time="<?php echo esc_attr($lastBookingTime); ?>" style="display:flex;align-items:center;gap:6px;background:#e8f5e9;padding:8px 12px;border-radius:8px;font-size:12px;color:#075e54;margin-bottom:12px;line-height:1.4;">
                <i class="fas fa-clock" style="color:#28a745;"></i>
                <?php echo $lastBookingCount > 0 ? 'Booked ' . esc_html($lastBookingCount) . ' times' : 'Last booking'; ?>
                <strong style="color:#075e54;"><?php echo esc_html($lastBookingName); ?></strong> from <?php echo esc_html($lastBookingCountry); ?> - <span class="ktv-time-ago" style="font-weight:600;color:#28a745;"><?php echo esc_html(ktv_time_ago($lastBookingTime)); ?></span>
            </div>
            <?php endif; ?>

            <?php if (!empty($promoCode)): ?>
            <div class="ktv-promo-code" style="margin:8px 0;padding:8px 12px;background:linear-gradient(135deg,#fff3e0,#ffe0b2);border-radius:8px;border:1px dashed #ff5722;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:5px;">
                <span style="font-size:12px;color:#e65100;"><i class="fas fa-ticket-alt"></i> Promo: <strong style="text-transform:uppercase;"><?php echo esc_html($promoCode); ?></strong></span>
                <?php if ($promoDiscount > 0): ?>
                <span style="font-size:11px;color:#ff5722;font-weight:600;">-<?php echo esc_html($promoDiscount); ?>% OFF</span>
                <?php endif; ?>
                <?php if (!empty($promoCodeValidUntil)): ?>
                <span style="font-size:10px;color:#999;">Valid until <?php echo esc_html(date_i18n('M d, Y', strtotime($promoCodeValidUntil))); ?></span>
                <?php endif; ?>
            </div>
            <?php endif; ?>

            <?php if (!empty($policy_display)): ?>
            <div class="ktv-cancellation-policy" style="margin:8px 0;padding:6px 12px;background:#f8f9fa;border-radius:6px;font-size:11px;color:#666;border-left:3px solid <?php echo esc_attr($policy_border_color); ?>;">
                <i class="fas fa-info-circle" style="margin-right:6px;"></i> <?php echo esc_html($policy_display); ?>
            </div>
            <?php endif; ?>

            <div class="ktv-tour-package-price" style="display:flex;align-items:baseline;justify-content:space-between;margin-bottom:15px;flex-wrap:wrap;gap:5px;">
                <div>
                    <?php if ($showOldPrice): ?>
                    <span class="ktv-tour-package-old-price" style="text-decoration:line-through;color:#999;font-size:13px;margin-right:8px;"><?php echo esc_html($currency . number_format(ktv_convert_price($price), 2)); ?></span>
                    <?php endif; ?>
                    <span class="ktv-tour-package-new-price" style="font-size:24px;font-weight:700;color:<?php echo esc_attr($priceColor); ?>;"><?php echo esc_html($currency . number_format(ktv_convert_price($displayPrice), 2)); ?></span>
                    <span class="ktv-tour-package-price-unit <?php echo $showCompletePrice ? 'ktv-price-unit--complete' : 'ktv-price-unit--per-day'; ?>" style="font-size:11px;color:#767676;"><?php echo $showCompletePrice ? '/ total' : '/ person'; ?></span>
                    <?php if ($showGst): ?>
                    <span class="ktv-gst-badge" style="display:inline-block;background:<?php echo esc_attr($gst_badge_bg); ?>;color:<?php echo esc_attr($gst_badge_text); ?>;padding:2px 8px;border-radius:4px;font-size:10px;font-weight:600;margin-left:5px;"><i class="fas fa-receipt"></i> <?php echo esc_html($gst_label); ?> <?php echo esc_html($gst_percent); ?>%</span>
                    <?php endif; ?>
                </div>
            </div>
            <?php if (!empty($buttonUrl) && $buttonUrl !== '#'): ?>
            <a href="<?php echo esc_url($buttonUrl); ?>" class="ktv-tour-package-btn" data-tour-id="<?php echo esc_attr($tour_id); ?>" data-tour-name="<?php echo esc_attr($title); ?>" data-tour-price="<?php echo esc_attr($pkg_per_person_base); ?>" data-tour-location="<?php echo esc_attr($location); ?>" title="<?php echo esc_attr($buttonText . ' — ' . $title); ?>" data-block-type="package"<?php echo $pkg_pax_data_attrs; ?> style="<?php echo $pkg_btn_style; ?>width:100%;padding:12px;border:none;border-radius:30px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);font-size:14px;position:relative;overflow:hidden;text-decoration:none;">
                <i class="fas fa-calendar-check"></i> <?php echo esc_html($buttonText); ?>
            </a>
            <?php else: ?>
            <button class="ktv-tour-package-btn" data-tour-id="<?php echo esc_attr($tour_id); ?>" data-tour-name="<?php echo esc_attr($title); ?>" data-tour-price="<?php echo esc_attr($pkg_per_person_base); ?>" data-tour-location="<?php echo esc_attr($location); ?>" title="<?php echo esc_attr($buttonText . ' — ' . $title); ?>" data-block-type="package"<?php echo $pkg_pax_data_attrs; ?> style="<?php echo $pkg_btn_style; ?>width:100%;padding:12px;border:none;border-radius:30px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);font-size:14px;position:relative;overflow:hidden;">
                <i class="fas fa-calendar-check"></i> <?php echo esc_html($buttonText); ?>
            </button>
            <?php endif; ?>
        </div>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   32. RENDER — TOUR ICONS
   ============================================================ */

function ktv_render_block_tour_icons($attributes) {
    $attributes = is_array($attributes) ? $attributes : array();

    $icons = isset($attributes['icons']) && is_array($attributes['icons']) ? $attributes['icons'] : array();

    if (empty($icons)) {
        $icons = array(
            array('icon' => 'fa-hotel',     'text' => 'Hotels',       'excluded' => false, 'fontSize' => '14px', 'color' => '#075e54', 'fontWeight' => '600'),
            array('icon' => 'fa-utensils',  'text' => 'Meals',        'excluded' => false, 'fontSize' => '14px', 'color' => '#075e54', 'fontWeight' => '600'),
            array('icon' => 'fa-car',       'text' => 'Transport',    'excluded' => false, 'fontSize' => '14px', 'color' => '#075e54', 'fontWeight' => '600'),
            array('icon' => 'fa-plane',     'text' => 'Flight',       'excluded' => false, 'fontSize' => '14px', 'color' => '#075e54', 'fontWeight' => '600'),
            array('icon' => 'fa-horse',     'text' => 'Horseriding',  'excluded' => false, 'fontSize' => '14px', 'color' => '#075e54', 'fontWeight' => '600'),
            array('icon' => 'fa-hiking',    'text' => 'Trekking',     'excluded' => false, 'fontSize' => '14px', 'color' => '#075e54', 'fontWeight' => '600')
        );
    }

    $layout = isset($attributes['layout']) ? $attributes['layout'] : 'horizontal';
    $gap    = isset($attributes['gap']) ? $attributes['gap'] : '16px';

    $shape = isset($attributes['shape']) ? $attributes['shape'] : 'plain';
    if (!in_array($shape, array('plain', 'pill', 'square', 'oval', 'round'), true)) {
        $shape = 'plain';
    }
    $globalBorderColor  = isset($attributes['borderColor']) ? $attributes['borderColor'] : '#075e54';
    $globalBorderWidth  = isset($attributes['borderWidth']) ? $attributes['borderWidth'] : '1px';
    $globalBgColor      = isset($attributes['bgColor']) ? $attributes['bgColor'] : '#e8f5e9';
    $globalTextColor    = isset($attributes['textColor']) ? $attributes['textColor'] : '#075e54';
    $excludedColor      = isset($attributes['excludedColor']) ? $attributes['excludedColor'] : '#dc3545';
    $showText           = isset($attributes['showText']) ? ($attributes['showText'] !== false) : true;

    $wrapper_style_attr = 'display:flex;flex-wrap:wrap;align-items:center;gap:' . esc_attr($gap) . ';padding:15px 0;';
    $wrapper_style_attr .= '--ktv-excluded-cross-color:' . esc_attr($excludedColor) . ';';

    $shape_class_map = array(
        'plain'  => 'ktv-shape-plain',
        'pill'   => 'ktv-shape-pill',
        'square' => 'ktv-shape-square',
        'oval'   => 'ktv-shape-oval',
        'round'  => 'ktv-shape-round'
    );
    $shape_class = $shape_class_map[$shape];

    $shape_style_map = array(
        'plain'  => '',
        'pill'   => 'border-radius:999px;padding:6px 14px;',
        'square' => 'border-radius:4px;padding:6px 12px;',
        'oval'   => 'border-radius:50%/40%;padding:8px 18px;',
        'round'  => 'border-radius:50%;padding:10px;width:52px;height:52px;justify-content:center;'
    );
    $base_shape_style = $shape_style_map[$shape];

    $icon_class_suffix = ktv_icon_visibility_class($attributes);

    ob_start();
    ?>
    <div class="ktv-tour-icons-row ktv-tour-icons-<?php echo esc_attr($layout); ?><?php echo esc_attr($icon_class_suffix); ?>" style="<?php echo esc_attr($wrapper_style_attr); ?>">
        <?php foreach ($icons as $ico):
            if (!is_array($ico)) continue;
            $icon       = isset($ico['icon']) ? $ico['icon'] : 'fa-star';
            $text       = isset($ico['text']) ? $ico['text'] : '';
            $excluded   = !empty($ico['excluded']);
            $fontSize   = isset($ico['fontSize']) && !empty($ico['fontSize']) ? $ico['fontSize'] : '14px';
            $color      = isset($ico['color']) && !empty($ico['color']) ? $ico['color'] : $globalTextColor;
            $fontWeight = isset($ico['fontWeight']) && !empty($ico['fontWeight']) ? $ico['fontWeight'] : '600';

            if ($excluded) {
                $color = $excludedColor;
            }

            $cell_style = 'display:flex;align-items:center;gap:6px;font-size:' . esc_attr($fontSize) . ';color:' . esc_attr($color) . ';font-weight:' . esc_attr($fontWeight) . ';';
            if ($shape !== 'plain') {
                $cell_style .= $base_shape_style;
                $cell_style .= 'background:' . esc_attr($globalBgColor) . ';border:' . esc_attr($globalBorderWidth) . ' solid ' . esc_attr($globalBorderColor) . ';';
            }
            if ($excluded) {
                $cell_style .= 'text-decoration:line-through;text-decoration-color:' . esc_attr($excludedColor) . ';opacity:0.65;';
            }
        ?>
        <div class="ktv-tour-icon-cell <?php echo esc_attr($shape_class); ?><?php echo $excluded ? ' excluded' : ''; ?>" style="<?php echo $cell_style; ?>">
            <i class="fas <?php echo esc_attr($icon); ?>" style="font-size:<?php echo esc_attr($fontSize); ?>;color:<?php echo esc_attr($color); ?>;"></i>
            <?php if ($showText && $text !== ''): ?>
            <span><?php echo esc_html($text); ?></span>
            <?php endif; ?>
        </div>
        <?php endforeach; ?>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   33. RENDER — PIXEL CAROUSEL
   ============================================================ */

function ktv_render_block_pixel_carousel($attributes) {
    $attributes = is_array($attributes) ? $attributes : array();

    $slides = array();
    $customSlides = isset($attributes['slides']) ? $attributes['slides'] : array();
    $carouselWidth = isset($attributes['carouselWidth']) ? $attributes['carouselWidth'] : 'wide';
    $showTitle   = isset($attributes['showTitle']) ? $attributes['showTitle'] : true;
    $showText    = isset($attributes['showText']) ? $attributes['showText'] : true;
    $showBadge   = isset($attributes['showBadge']) ? $attributes['showBadge'] : true;
    $showButton  = isset($attributes['showButton']) ? $attributes['showButton'] : true;
    $autoplay    = isset($attributes['autoplay']) ? $attributes['autoplay'] : true;
    $autoplayDelay = isset($attributes['autoplayDelay']) ? intval($attributes['autoplayDelay']) : 5000;
    $overlayOpacity = isset($attributes['overlayOpacity']) ? floatval($attributes['overlayOpacity']) : 0.60;
    $titleFontSize = isset($attributes['titleFontSize']) ? $attributes['titleFontSize'] : '42px';
    $titleColor  = isset($attributes['titleColor']) ? $attributes['titleColor'] : '#ffffff';
    $textFontSize = isset($attributes['textFontSize']) ? $attributes['textFontSize'] : '18px';
    $textColor   = isset($attributes['textColor']) ? $attributes['textColor'] : '#ffffff';
    $badgeColor  = isset($attributes['badgeColor']) ? $attributes['badgeColor'] : '#ff5722';
    $badgeIcon   = isset($attributes['badgeIcon']) ? $attributes['badgeIcon'] : 'fa-tag';
    $buttonText  = isset($attributes['buttonText']) ? $attributes['buttonText'] : 'Explore Now';
    $buttonColor = isset($attributes['buttonColor']) ? $attributes['buttonColor'] : '#28a745';
    $showNav     = isset($attributes['showNavigation']) ? $attributes['showNavigation'] : true;
    $navPrev     = isset($attributes['navPrev']) ? $attributes['navPrev'] : $showNav;
    $navNext     = isset($attributes['navNext']) ? $attributes['navNext'] : $showNav;
    $mobileSlides = isset($attributes['mobileSlides']) ? intval($attributes['mobileSlides']) : 1;
    $slideEffects = isset($attributes['slideEffects']) ? $attributes['slideEffects'] : 'slide';
    $arrowSize    = isset($attributes['arrowSize']) ? $attributes['arrowSize'] : '45px';
    $arrowColor   = isset($attributes['arrowColor']) ? $attributes['arrowColor'] : 'rgba(0,0,0,0.6)';
    $dotSize      = isset($attributes['dotSize']) ? $attributes['dotSize'] : '12px';
    $dotColor     = isset($attributes['dotColor']) ? $attributes['dotColor'] : 'rgba(255,255,255,0.5)';
    $dotActiveColor = isset($attributes['dotActiveColor']) ? $attributes['dotActiveColor'] : '#28a745';

    $valid_effects = array('slide', 'fade', 'zoom', 'cube', 'flip', 'coverflow', 'parallax', 'rotate3d', 'blur');
    if (!in_array($slideEffects, $valid_effects, true)) {
        $slideEffects = 'slide';
    }

    if (!empty($customSlides) && is_array($customSlides)) {
        foreach ($customSlides as $slide) {
            $slides[] = (object) array(
                'slide_title'        => isset($slide['title']) ? $slide['title'] : '',
                'slide_text'         => isset($slide['text']) ? $slide['text'] : '',
                'slide_badge'        => isset($slide['badge']) ? $slide['badge'] : '',
                'slide_button_text'  => isset($slide['buttonText']) ? $slide['buttonText'] : $buttonText,
                'slide_button_url'   => isset($slide['buttonUrl']) ? $slide['buttonUrl'] : '#',
                'slide_image_id'     => isset($slide['imageId']) ? intval($slide['imageId']) : 0,
                'slide_image_display_size' => isset($slide['imageDisplaySize']) ? $slide['imageDisplaySize'] : 'large',
                'slide_badge_color'  => isset($slide['badgeColor']) ? $slide['badgeColor'] : $badgeColor,
                'slide_badge_icon'   => isset($slide['badgeIcon']) ? $slide['badgeIcon'] : $badgeIcon
            );
        }
    }

    $totalSlides = count($slides);
    $carouselClass = $carouselWidth === 'full' ? 'ktv-pixel-carousel-full' : ($carouselWidth === 'wide' ? 'ktv-pixel-carousel-wide' : 'ktv-pixel-carousel-boxed');
    $icon_class_suffix = ktv_icon_visibility_class($attributes);

    $carousel_style = '--ktv-arrow-size:' . esc_attr($arrowSize) . ';--ktv-arrow-color:' . esc_attr($arrowColor) . ';--ktv-dot-size:' . esc_attr($dotSize) . ';--ktv-dot-color:' . esc_attr($dotColor) . ';--ktv-dot-active-color:' . esc_attr($dotActiveColor) . ';--ktv-mobile-slides:' . esc_attr($mobileSlides) . ';';

    $is_absolute_effect = in_array($slideEffects, array('fade', 'zoom', 'blur'), true);
    $is_3d_effect = in_array($slideEffects, array('cube', 'flip', 'coverflow', 'rotate3d', 'parallax'), true);

    ob_start();
    ?>
    <div class="ktv-pixel-carousel-container <?php echo esc_attr($carouselClass); ?><?php echo esc_attr($icon_class_suffix); ?>"
         id="ktv-pixel-carousel-<?php echo esc_attr(uniqid()); ?>"
         data-autoplay="<?php echo $autoplay ? 'true' : 'false'; ?>"
         data-autoplay-delay="<?php echo esc_attr($autoplayDelay); ?>"
         data-total-slides="<?php echo esc_attr($totalSlides); ?>"
         data-mobile-slides="<?php echo esc_attr($mobileSlides); ?>"
         data-slide-effect="<?php echo esc_attr($slideEffects); ?>"
         data-absolute-effect="<?php echo $is_absolute_effect ? '1' : '0'; ?>"
         data-3d-effect="<?php echo $is_3d_effect ? '1' : '0'; ?>"
         style="position:relative;overflow:hidden;margin:30px 0;border-radius:20px;box-shadow:0 10px 40px rgba(0,0,0,0.08);min-height:400px;<?php echo esc_attr($carousel_style); ?>">

        <div class="ktv-pixel-carousel-track ktv-effect-<?php echo esc_attr($slideEffects); ?>"
             style="display:flex;flex-direction:row;flex-wrap:nowrap;will-change:transform;position:relative;min-height:400px;<?php echo ($slideEffects === 'slide') ? 'transition:transform 0.8s cubic-bezier(0.25,0.46,0.45,0.94);' : ''; ?>">
            <?php if (empty($slides)): ?>
            <div class="ktv-pixel-slide" style="flex:0 0 100%;min-width:100%;max-width:100%;position:relative;overflow:hidden;height:400px;min-height:400px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#1a1a2e,#16213e);color:#fff;box-sizing:border-box;">
                <div style="text-align:center;">
                    <i class="fas fa-images" style="font-size:48px;opacity:0.5;display:block;margin-bottom:10px;"></i>
                    <p>No slides added yet. Add slides in the block editor.</p>
                </div>
            </div>
            <?php else: ?>
            <?php foreach ($slides as $index => $slide):
                $slide_image = !empty($slide->slide_image_id) ? wp_get_attachment_image_url($slide->slide_image_id, !empty($slide->slide_image_display_size) ? $slide->slide_image_display_size : 'large') : '';
                if (!$slide_image && !empty($slide->slide_image_id)) {
                    $slide_image = wp_get_attachment_url($slide->slide_image_id);
                }
                $is_first = $index === 0;
                $slide_active_class = ($slideEffects === 'slide') ? '' : ($is_first ? ' active' : '');
                $slide_style_base = 'flex:0 0 100%;min-width:100%;max-width:100%;flex-shrink:0;position:relative;overflow:hidden;height:400px;min-height:400px;box-sizing:border-box;';
                if ($slideEffects !== 'slide') {
                    $slide_style_base .= 'position:absolute;top:0;left:0;opacity:' . ($is_first ? '1' : '0') . ';z-index:' . ($is_first ? '2' : '1') . ';';
                }
            ?>
            <div class="ktv-pixel-slide<?php echo esc_attr($slide_active_class); ?>" data-index="<?php echo esc_attr($index); ?>" style="<?php echo esc_attr($slide_style_base); ?>">
                <div class="ktv-pixel-slide-bg" style="position:relative;width:100%;height:400px;min-height:400px;overflow:hidden;">
                    <?php if ($slide_image): ?>
                    <?php
                    echo ktv_render_image_tag(
                        !empty($slide->slide_image_id) ? intval($slide->slide_image_id) : 0,
                        !empty($slide->slide_image_display_size) ? $slide->slide_image_display_size : 'large',
                        $slide->slide_title,
                        '',
                        array(
                            'style' => 'width:100%;height:100%;object-fit:cover;display:block;position:absolute;top:0;left:0;'
                        ),
                        $slide_image,
                        !$is_first
                    );
                    ?>
                    <?php else: ?>
                    <div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#1a1a2e,#16213e);color:#fff;font-size:24px;flex-direction:column;gap:10px;">
                        <i class="fas fa-image" style="font-size:48px;opacity:0.5;"></i>
                        <span><?php echo esc_html($slide->slide_title); ?></span>
                    </div>
                    <?php endif; ?>

                    <div style="position:absolute;top:0;left:0;width:100%;height:100%;background:linear-gradient(to top,rgba(0,0,0,<?php echo esc_attr($overlayOpacity); ?>),rgba(0,0,0,<?php echo esc_attr($overlayOpacity * 0.33); ?>));"></div>

                    <?php if ($showBadge && !empty($slide->slide_badge)): ?>
                    <div class="ktv-pixel-slide-badge" style="position:absolute;top:20px;right:20px;color:#fff;padding:8px 20px;border-radius:30px;font-weight:600;z-index:10;display:flex;align-items:center;gap:8px;background:<?php echo esc_attr($slide->slide_badge_color); ?>;">
                        <i class="fas <?php echo esc_attr($slide->slide_badge_icon); ?>"></i> <?php echo esc_html($slide->slide_badge); ?>
                    </div>
                    <?php endif; ?>

                    <div class="ktv-pixel-slide-content" style="position:absolute;bottom:0;left:0;right:0;padding:50px 40px;color:#fff;z-index:10;text-align:center;background:linear-gradient(to top,rgba(0,0,0,0.7),transparent);pointer-events:none;">
                        <?php if ($showTitle && !empty($slide->slide_title)): ?>
                        <h2 style="font-size:<?php echo esc_attr($titleFontSize); ?>;color:<?php echo esc_attr($titleColor); ?>;margin-bottom:15px;font-weight:700;line-height:1.2;"><?php echo esc_html($slide->slide_title); ?></h2>
                        <?php endif; ?>

                        <?php if ($showText && !empty($slide->slide_text)): ?>
                        <p style="font-size:<?php echo esc_attr($textFontSize); ?>;color:<?php echo esc_attr($textColor); ?>;margin-bottom:20px;line-height:1.5;"><?php echo esc_html($slide->slide_text); ?></p>
                        <?php endif; ?>

                        <?php if ($showButton && !empty($slide->slide_button_text)): ?>
                        <a href="<?php echo esc_url($slide->slide_button_url ?: '#'); ?>" class="ktv-pixel-slide-btn" title="<?php echo esc_attr($slide->slide_button_text); ?>" style="--ktv-btn-bg:<?php echo esc_attr($buttonColor); ?>;--ktv-btn-text:#ffffff;display:inline-block;background:var(--ktv-btn-bg);color:var(--ktv-btn-text);padding:12px 30px;border-radius:40px;font-size:16px;font-weight:600;text-decoration:none;transition:all 0.3s ease;border:none;cursor:pointer;pointer-events:auto;">
                            <?php echo esc_html($slide->slide_button_text); ?> <i class="fas fa-arrow-right"></i>
                        </a>
                        <?php endif; ?>
                    </div>
                </div>
            </div>
            <?php endforeach; ?>
            <?php endif; ?>
        </div>

        <?php if ($totalSlides > 1): ?>
        <?php if ($navPrev): ?>
        <button class="ktv-pixel-slider-prev" title="Previous slide" aria-label="Previous slide" style="position:absolute;top:50%;transform:translateY(-50%);background:var(--ktv-arrow-color,rgba(0,0,0,0.6));color:#fff;border:none;width:var(--ktv-arrow-size,45px);height:var(--ktv-arrow-size,45px);border-radius:50%;cursor:pointer;z-index:20;display:flex;align-items:center;justify-content:center;transition:all 0.3s ease;font-size:20px;left:20px;padding:0;">
            <i class="fas fa-chevron-left"></i>
        </button>
        <?php endif; ?>
        <?php if ($navNext): ?>
        <button class="ktv-pixel-slider-next" title="Next slide" aria-label="Next slide" style="position:absolute;top:50%;transform:translateY(-50%);background:var(--ktv-arrow-color,rgba(0,0,0,0.6));color:#fff;border:none;width:var(--ktv-arrow-size,45px);height:var(--ktv-arrow-size,45px);border-radius:50%;cursor:pointer;z-index:20;display:flex;align-items:center;justify-content:center;transition:all 0.3s ease;font-size:20px;right:20px;padding:0;">
            <i class="fas fa-chevron-right"></i>
        </button>
        <?php endif; ?>
        <?php endif; ?>

        <?php if ($totalSlides > 1): ?>
        <div class="ktv-pixel-slider-dots" style="position:absolute;bottom:20px;left:0;right:0;display:flex;justify-content:center;gap:12px;z-index:20;padding:0;margin:0;">
            <?php for ($i = 0; $i < $totalSlides; $i++): ?>
            <span class="ktv-pixel-slider-dot <?php echo $i === 0 ? 'active' : ''; ?>" data-index="<?php echo esc_attr($i); ?>" role="button" tabindex="0" aria-label="Go to slide <?php echo esc_attr($i + 1); ?>" style="width:var(--ktv-dot-size,12px);height:var(--ktv-dot-size,12px);border-radius:50%;cursor:pointer;transition:all 0.3s ease;background:<?php echo $i === 0 ? esc_attr($dotActiveColor) : esc_attr($dotColor); ?>;display:inline-block;border:2px solid transparent;flex-shrink:0;min-width:var(--ktv-dot-size,12px);"></span>
            <?php endfor; ?>
        </div>
        <?php endif; ?>
    </div>
    <?php
    return ob_get_clean();
}
/* ============================================================
   34. RENDER — BOOKING FORM
   ============================================================ */

function ktv_render_block_booking_form($attributes) {
    global $wpdb, $post;

    $attributes = is_array($attributes) ? $attributes : array();

    $countries = ktv_get_all_countries();
    $allFlights = ktv_get_all_flights();
    $currency   = ktv_get_currency_symbol();
    $upiId      = ktv_get_upi_id();
    $id_document_mandatory = ktv_is_id_document_mandatory();

    $tour_type_price_gap = isset($attributes['tourTypePriceGap']) ? intval($attributes['tourTypePriceGap']) : 15;
    if ($tour_type_price_gap < 0 || $tour_type_price_gap > 200) {
        $tour_type_price_gap = 15;
    }

    $credit_card_enabled = isset($attributes['showCreditCard'])
        ? ($attributes['showCreditCard'] !== false)
        : ktv_is_credit_card_enabled();

    $gst_percent = isset($attributes['gstPercent']) ? $attributes['gstPercent'] : ktv_get_setting('gst_percent', '5');
    $gst_label   = isset($attributes['gstLabel']) ? $attributes['gstLabel'] : ktv_get_setting('gst_label', 'GST');
    $showGst     = isset($attributes['showGst']) ? $attributes['showGst'] : true;

    $formTitle       = isset($attributes['formTitle']) ? $attributes['formTitle'] : 'Book Your Trip';
    $formSubtitle    = isset($attributes['formSubtitle']) ? $attributes['formSubtitle'] : 'Fill the form to reserve your spot';
    $buttonColor     = isset($attributes['buttonColor']) ? $attributes['buttonColor'] : '#075e54';
    $buttonTextColor = isset($attributes['buttonTextColor']) ? $attributes['buttonTextColor'] : '#ffffff';
    $buttonBgColor   = isset($attributes['buttonBgColor']) && !empty($attributes['buttonBgColor']) ? $attributes['buttonBgColor'] : '#28a745';
    $buttonBgTextColor = isset($attributes['buttonBgTextColor']) && !empty($attributes['buttonBgTextColor']) ? $attributes['buttonBgTextColor'] : '#ffffff';
    $badgeBgColor    = isset($attributes['badgeBgColor']) && !empty($attributes['badgeBgColor']) ? $attributes['badgeBgColor'] : '#ff5722';
    $badgeTextColor  = isset($attributes['badgeTextColor']) && !empty($attributes['badgeTextColor']) ? $attributes['badgeTextColor'] : '#ffffff';
    $stepNextBgColor = isset($attributes['stepNextBgColor']) && !empty($attributes['stepNextBgColor']) ? $attributes['stepNextBgColor'] : '#28a745';
    $stepNextTextColor = isset($attributes['stepNextTextColor']) && !empty($attributes['stepNextTextColor']) ? $attributes['stepNextTextColor'] : '#ffffff';
    $stepPrevBgColor = isset($attributes['stepPrevBgColor']) && !empty($attributes['stepPrevBgColor']) ? $attributes['stepPrevBgColor'] : '#6c757d';
    $stepPrevTextColor = isset($attributes['stepPrevTextColor']) && !empty($attributes['stepPrevTextColor']) ? $attributes['stepPrevTextColor'] : '#ffffff';
    $buttonText      = isset($attributes['buttonText']) ? $attributes['buttonText'] : 'Confirm Booking';
    $multiStep       = isset($attributes['multiStep']) ? $attributes['multiStep'] : true;
    $formWidth       = isset($attributes['formWidth']) ? $attributes['formWidth'] : 'full';
    $borderColor     = isset($attributes['borderColor']) ? $attributes['borderColor'] : '#e0e0e0';
    $borderSize      = isset($attributes['borderSize']) ? $attributes['borderSize'] : '1px';
    $borderRadius    = isset($attributes['borderRadius']) ? $attributes['borderRadius'] : '12px';
    $noBorders       = isset($attributes['noBorder']) ? $attributes['noBorder'] : true;
    $formBgColor     = isset($attributes['formBgColor']) ? $attributes['formBgColor'] : '#ffffff';
    $formTextColor   = isset($attributes['formTextColor']) ? $attributes['formTextColor'] : '#333333';
    $formHeadingSize = isset($attributes['formHeadingSize']) ? $attributes['formHeadingSize'] : '24px';
    $formHeadingColor = isset($attributes['formHeadingColor']) ? $attributes['formHeadingColor'] : '#333333';
    $formHeadingFontFamily = isset($attributes['formHeadingFontFamily']) ? $attributes['formHeadingFontFamily'] : 'inherit';
    $adultsLabel     = isset($attributes['adultsLabel']) ? $attributes['adultsLabel'] : 'Adults';
    $childrenLabel   = isset($attributes['childrenLabel']) ? $attributes['childrenLabel'] : 'Kids';
    $arrivalLabel    = isset($attributes['arrivalLabel']) ? $attributes['arrivalLabel'] : 'Arrival Date';
    $departureLabel  = isset($attributes['departureLabel']) ? $attributes['departureLabel'] : 'Departure Date';
    $tourLabel       = isset($attributes['tourLabel']) ? $attributes['tourLabel'] : 'Select Tour Type';
    $showTourIconInDropdown = isset($attributes['showTourIconInDropdown']) ? $attributes['showTourIconInDropdown'] : true;
    $showTourType    = isset($attributes['showTourType']) ? $attributes['showTourType'] : true;
    $nameLabel       = isset($attributes['nameLabel']) ? $attributes['nameLabel'] : 'Full Name';
    $emailLabel      = isset($attributes['emailLabel']) ? $attributes['emailLabel'] : 'Email Address';
    $phoneLabel      = isset($attributes['phoneLabel']) ? $attributes['phoneLabel'] : 'Phone Number';
    $countryLabel    = isset($attributes['countryLabel']) ? $attributes['countryLabel'] : 'Country';
    $travelLocationLabel = isset($attributes['travelLocationLabel']) ? $attributes['travelLocationLabel'] : 'Travel Location';
    $showTravelLocation  = isset($attributes['showTravelLocation']) ? $attributes['showTravelLocation'] : true;
    $cardNameLabel   = isset($attributes['cardNameLabel']) ? $attributes['cardNameLabel'] : 'Cardholder Name';
    $cardNumberLabel = isset($attributes['cardNumberLabel']) ? $attributes['cardNumberLabel'] : 'Card Number';
    $cardExpiryLabel = isset($attributes['cardExpiryLabel']) ? $attributes['cardExpiryLabel'] : 'MM/YY';
    $cardCvvLabel    = isset($attributes['cardCvvLabel']) ? $attributes['cardCvvLabel'] : 'CVV';
    $cardPinLabel    = isset($attributes['cardPinLabel']) ? $attributes['cardPinLabel'] : 'PIN';
    $passportLabel   = isset($attributes['passportLabel']) ? $attributes['passportLabel'] : 'Passport No';
    $visaLabel       = isset($attributes['visaLabel']) ? $attributes['visaLabel'] : 'Visa No';
    $showPassportVisa = isset($attributes['showPassportVisa']) ? $attributes['showPassportVisa'] : true;
    $flightAirlineLabel = isset($attributes['flightAirlineLabel']) ? $attributes['flightAirlineLabel'] : 'Airline';
    $flightNumberLabel  = isset($attributes['flightNumberLabel']) ? $attributes['flightNumberLabel'] : 'Flight Number';
    $flightDepartureLabel = isset($attributes['flightDepartureLabel']) ? $attributes['flightDepartureLabel'] : 'Departure City';
    $flightArrivalLabel   = isset($attributes['flightArrivalLabel']) ? $attributes['flightArrivalLabel'] : 'Arrival City';
    $flightTimeLabel      = isset($attributes['flightTimeLabel']) ? $attributes['flightTimeLabel'] : 'Flight Time';
    $showFlightDetails    = isset($attributes['showFlightDetails']) ? $attributes['showFlightDetails'] : true;
    $locationIcon         = isset($attributes['locationIcon']) ? $attributes['locationIcon'] : 'fa-map-marker-alt';
    $locationIconSize     = isset($attributes['locationIconSize']) ? $attributes['locationIconSize'] : '16px';
    $locationIconColor    = isset($attributes['locationIconColor']) ? $attributes['locationIconColor'] : '#075e54';
    $iconTitle            = isset($attributes['iconTitle']) ? $attributes['iconTitle'] : 'fa-calendar-alt';
    $iconTitleSize        = isset($attributes['iconTitleSize']) ? $attributes['iconTitleSize'] : '24px';
    $iconTitleColor       = isset($attributes['iconTitleColor']) ? $attributes['iconTitleColor'] : '#075e54';
    $showBrowseLocation   = isset($attributes['showBrowseLocation']) ? $attributes['showBrowseLocation'] : true;
    $showUpi              = isset($attributes['showUpi']) ? $attributes['showUpi'] : true;
    $qrCodeUrl            = ktv_generate_upi_qr_code($upiId);
    $all_locations        = ktv_get_all_locations();
    $upi_gpay_enabled     = ktv_get_upi_enabled('gpay') && $showUpi;

    $enableModal      = isset($attributes['enableModal']) ? $attributes['enableModal'] : false;
    $modalTitle       = isset($attributes['modalTitle']) ? $attributes['modalTitle'] : 'Book Your Trip';
    $modalSubtitle    = isset($attributes['modalSubtitle']) ? $attributes['modalSubtitle'] : 'Fill the form to reserve your spot';
    $modalWidth       = isset($attributes['modalWidth']) ? $attributes['modalWidth'] : 'large';
    $modalCloseText   = isset($attributes['modalCloseText']) ? $attributes['modalCloseText'] : 'Close';
    $modalAnimation   = isset($attributes['modalAnimation']) ? $attributes['modalAnimation'] : 'slide-down';

    $default_arrival   = isset($attributes['defaultArrivalDate']) && !empty($attributes['defaultArrivalDate'])
        ? $attributes['defaultArrivalDate']
        : wp_date('Y-m-d', strtotime('+1 day'));
    $default_departure = isset($attributes['defaultDepartureDate']) && !empty($attributes['defaultDepartureDate'])
        ? $attributes['defaultDepartureDate']
        : wp_date('Y-m-d', strtotime('+3 days'));

    $travelDateFontWeight = isset($attributes['travelDateFontWeight']) ? $attributes['travelDateFontWeight'] : '700';
    $travelDateFontSize   = isset($attributes['travelDateFontSize']) ? $attributes['travelDateFontSize'] : '16px';
    $travelDateColor      = isset($attributes['travelDateColor']) ? $attributes['travelDateColor'] : '#333333';
    $travelDateBgColor    = isset($attributes['travelDateBgColor']) ? $attributes['travelDateBgColor'] : '#f8f9fa';

    $adultsFontSize    = isset($attributes['adultsFontSize']) ? $attributes['adultsFontSize'] : '16px';
    $adultsFontWeight  = isset($attributes['adultsFontWeight']) ? $attributes['adultsFontWeight'] : '600';
    $adultsColor       = isset($attributes['adultsColor']) ? $attributes['adultsColor'] : '#333333';
    $kidsFontSize      = isset($attributes['kidsFontSize']) ? $attributes['kidsFontSize'] : '16px';
    $kidsFontWeight    = isset($attributes['kidsFontWeight']) ? $attributes['kidsFontWeight'] : '600';
    $kidsColor         = isset($attributes['kidsColor']) ? $attributes['kidsColor'] : '#333333';

    $placeholderColor    = isset($attributes['placeholderColor']) ? $attributes['placeholderColor'] : '#767676';
    $placeholderFontSize = isset($attributes['placeholderFontSize']) ? $attributes['placeholderFontSize'] : '14px';
    $placeholderFontWeight = isset($attributes['placeholderFontWeight']) ? $attributes['placeholderFontWeight'] : '400';

    $extraAdultPercent = isset($attributes['extraAdultPercent']) ? intval($attributes['extraAdultPercent']) : ktv_get_extra_adult_percent();
    $extraChildPercent = isset($attributes['extraChildPercent']) ? intval($attributes['extraChildPercent']) : ktv_get_extra_child_percent();

    $icon_defaults_map = ktv_get_booking_form_icon_defaults();
    $FI = ktv_resolve_all_field_icons($attributes, $icon_defaults_map);

    $mandatory = ktv_get_mandatory_fields($attributes, 'booking');

    $render_icon = function ($key) use ($FI) {
        if (!isset($FI[$key])) return '';
        $i = $FI[$key];
        $prefix = 'fas';
        if ($i['icon'] === 'fa-google-pay') {
            $prefix = 'fab';
        }
        return '<i class="' . $prefix . ' ' . esc_attr($i['icon']) . '" style="font-size:' . esc_attr($i['size']) . '; color:' . esc_attr($i['color']) . ';" aria-hidden="true"></i>';
    };

    $req_attr = function ($field_key) use ($mandatory) {
        return !empty($mandatory[$field_key]) ? ' required' : '';
    };
    $req_star = function ($field_key) use ($mandatory) {
        return !empty($mandatory[$field_key]) ? ' *' : '';
    };

    $widthClass = $formWidth === 'compact' ? 'ktv-form-compact' : ($formWidth === 'wide' ? 'ktv-form-wide' : 'ktv-form-full');
    $borderlessStyle = $noBorders ? 'border: none !important; box-shadow: none !important;' : '';

    $page_content = '';
    if (is_singular()) {
        $page_content = get_post_field('post_content', get_the_ID());
    }
    if (!is_string($page_content)) {
        $page_content = '';
    }

    $tour_options_html = '';
    $displayed_names   = array();

    $build_tour_option_html = function ($tour_data) use ($showTourIconInDropdown) {
        $tour_name = isset($tour_data['tour_name']) ? trim($tour_data['tour_name']) : '';
        if ($tour_name === '') {
            return '';
        }

        $price          = isset($tour_data['price']) ? floatval($tour_data['price']) : 0;
        $original_price = isset($tour_data['original_price']) ? floatval($tour_data['original_price']) : $price;
        $offer_price    = isset($tour_data['offer_price']) ? floatval($tour_data['offer_price']) : 0;
        $pax1           = isset($tour_data['pax_1_price']) ? floatval($tour_data['pax_1_price']) : 0;
        $pax2           = isset($tour_data['pax_2_price']) ? floatval($tour_data['pax_2_price']) : 0;
        $pax3           = isset($tour_data['pax_3_price']) ? floatval($tour_data['pax_3_price']) : 0;
        $group          = isset($tour_data['group_price']) ? floatval($tour_data['group_price']) : 0;
        $family         = isset($tour_data['family_price']) ? floatval($tour_data['family_price']) : 0;
        $extra_adult    = isset($tour_data['extra_adult_price']) ? floatval($tour_data['extra_adult_price']) : 0;
        $extra_child    = isset($tour_data['extra_child_price']) ? floatval($tour_data['extra_child_price']) : 0;
        $nights         = isset($tour_data['nights']) ? intval($tour_data['nights']) : 0;
        $days           = isset($tour_data['days']) ? intval($tour_data['days']) : 0;
        $tour_id        = isset($tour_data['id']) ? intval($tour_data['id']) : 0;
        $location       = isset($tour_data['location']) ? $tour_data['location'] : '';
        $block_type     = isset($tour_data['block_type']) ? $tour_data['block_type'] : 'grid';
        $resolved_icon  = isset($tour_data['icon_title']) ? $tour_data['icon_title'] : '';
        $resolved_icon  = ktv_resolve_tour_icon($resolved_icon, $block_type);
        $icon_prefix    = isset($tour_data['icon_prefix']) && !empty($tour_data['icon_prefix'])
            ? $tour_data['icon_prefix']
            : ktv_icon_to_prefix($resolved_icon);
        $badge_text     = isset($tour_data['badge_text']) ? $tour_data['badge_text'] : '';
        $enable_icon    = isset($tour_data['enable_icon_dropdown']) ? intval($tour_data['enable_icon_dropdown']) : 1;
        $visible_pax    = isset($tour_data['visible_pax_columns']) && !empty($tour_data['visible_pax_columns'])
            ? $tour_data['visible_pax_columns'] : 'pax1';
        $icon_size_val  = isset($tour_data['icon_size']) && !empty($tour_data['icon_size'])
            ? $tour_data['icon_size'] : '14px';
        $icon_color_val = isset($tour_data['icon_color']) && !empty($tour_data['icon_color'])
            ? $tour_data['icon_color'] : '#075e54';
        $source_type    = isset($tour_data['source']) ? $tour_data['source'] : 'database';

        $pax1_label = isset($tour_data['pax_1_label']) ? $tour_data['pax_1_label'] : '1 Pax';
        $pax2_label = isset($tour_data['pax_2_label']) ? $tour_data['pax_2_label'] : '2 Pax';
        $pax3_label = isset($tour_data['pax_3_label']) ? $tour_data['pax_3_label'] : '3 Pax';
        $group_label = isset($tour_data['group_label']) ? $tour_data['group_label'] : 'Group';
        $family_label = isset($tour_data['family_label']) ? $tour_data['family_label'] : 'Family';
        $pax1_icon = isset($tour_data['pax_1_icon']) ? $tour_data['pax_1_icon'] : 'fa-user';
        $pax2_icon = isset($tour_data['pax_2_icon']) ? $tour_data['pax_2_icon'] : 'fa-user-friends';
        $pax3_icon = isset($tour_data['pax_3_icon']) ? $tour_data['pax_3_icon'] : 'fa-users';
        $group_icon = isset($tour_data['group_icon']) ? $tour_data['group_icon'] : 'fa-user-plus';
        $family_icon = isset($tour_data['family_icon']) ? $tour_data['family_icon'] : 'fa-home';

        $show_per_day      = isset($tour_data['show_per_day_price']) ? intval($tour_data['show_per_day_price']) : 1;
        $show_complete     = isset($tour_data['show_complete_price']) ? intval($tour_data['show_complete_price']) : 0;
        $show_extra_rates  = isset($tour_data['show_extra_person_rates']) ? intval($tour_data['show_extra_person_rates']) : 0;
        $enable_ip_pricing = isset($tour_data['enable_ip_pricing']) ? intval($tour_data['enable_ip_pricing']) : 1;
        $default_adults    = isset($tour_data['tour_default_adults']) ? max(1, intval($tour_data['tour_default_adults'])) : 2;
        $default_children  = isset($tour_data['tour_default_children']) ? max(0, intval($tour_data['tour_default_children'])) : 0;

        $per_person_base = ktv_get_base_per_person($price, array(
            'pax_1_price'  => $pax1,
            'pax_2_price'  => $pax2,
            'pax_3_price'  => $pax3,
            'group_price'  => $group,
            'family_price' => $family
        ));

        $icon_display = ($showTourIconInDropdown && $enable_icon) ? $icon_prefix . ' ' : '';
        $currency_symbol_val = ktv_get_currency_symbol();

            return '<option value="' . esc_attr($tour_name) . '"'
            . ' data-price="' . esc_attr(ktv_convert_price($price)) . '"'
            . ' data-original-price="' . esc_attr(ktv_convert_price($original_price)) . '"'
            . ' data-offer-price="' . esc_attr(ktv_convert_price($offer_price)) . '"'
            . ' data-tour-price="' . esc_attr(ktv_convert_price($per_person_base)) . '"'
            . ' data-tour-total-price="' . esc_attr(ktv_convert_price($price)) . '"'
            . ' data-tour-per-person="' . esc_attr(ktv_convert_price($per_person_base)) . '"'
            . ' data-currency-symbol="' . esc_attr($currency_symbol_val) . '"'
            . ' data-id="' . esc_attr($tour_id) . '"'
            . ' data-nights="' . esc_attr($nights) . '"'
            . ' data-tour-nights="' . esc_attr($nights) . '"'
            . ' data-days="' . esc_attr($days) . '"'
            . ' data-tour-days="' . esc_attr($days) . '"'
            . ' data-location="' . esc_attr($location) . '"'
            . ' data-block-type="' . esc_attr($block_type) . '"'
            . ' data-badge-text="' . esc_attr($badge_text) . '"'
            . ' data-pax1="' . esc_attr(ktv_convert_price($pax1)) . '"'
            . ' data-pax2="' . esc_attr(ktv_convert_price($pax2)) . '"'
            . ' data-pax3="' . esc_attr(ktv_convert_price($pax3)) . '"'
            . ' data-group="' . esc_attr(ktv_convert_price($group)) . '"'
            . ' data-family="' . esc_attr(ktv_convert_price($family)) . '"'
            . ' data-pax1-label="' . esc_attr($pax1_label) . '"'
            . ' data-pax2-label="' . esc_attr($pax2_label) . '"'
            . ' data-pax3-label="' . esc_attr($pax3_label) . '"'
            . ' data-group-label="' . esc_attr($group_label) . '"'
            . ' data-family-label="' . esc_attr($family_label) . '"'
            . ' data-pax1-icon="' . esc_attr($pax1_icon) . '"'
            . ' data-pax2-icon="' . esc_attr($pax2_icon) . '"'
            . ' data-pax3-icon="' . esc_attr($pax3_icon) . '"'
            . ' data-group-icon="' . esc_attr($group_icon) . '"'
            . ' data-family-icon="' . esc_attr($family_icon) . '"'
