            . ' data-tour-icon-color="' . esc_attr($icon_color_val) . '"'
            . ' data-icon="' . esc_attr($resolved_icon) . '"'
            . ' data-enable-icon="' . esc_attr($enable_icon ? '1' : '0') . '"'
            . ' data-source="' . esc_attr($source_type) . '"'
            . ' data-is-hardcoded="0">' . esc_html($icon_display . $tour_name) . '</option>';
    };

    $db_tours = $wpdb->get_results(
        "SELECT * FROM {$wpdb->prefix}ktv_tours
        WHERE status = 'published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)
        ORDER BY featured DESC, tour_name ASC
        LIMIT 500"
    );

    if (!empty($db_tours)) {
        foreach ($db_tours as $tour) {
            $tour_name = trim($tour->tour_name);
            if (ktv_is_tour_excluded($tour_name)) {
                continue;
            }
            $lower_name = strtolower($tour_name);
            if (in_array($lower_name, $displayed_names, true)) {
                continue;
            }
            $displayed_names[] = $lower_name;

            $price = ($tour->tour_offer_price && $tour->tour_offer_price > 0 && $tour->tour_offer_price < $tour->tour_price)
                ? floatval($tour->tour_offer_price)
                : floatval($tour->tour_price);

            $block_type    = $tour->tour_block_type ?: 'grid';
            $resolved_icon = ktv_resolve_tour_icon(isset($tour->icon_title) ? $tour->icon_title : '', $block_type);

            $tour_options_html .= $build_tour_option_html(array(
                'tour_name'          => $tour_name,
                'price'              => $price,
                'original_price'     => floatval($tour->tour_price),
                'offer_price'        => floatval($tour->tour_offer_price),
                'pax_1_price'        => floatval($tour->pax_1_price),
                'pax_2_price'        => floatval($tour->pax_2_price),
                'pax_3_price'        => floatval($tour->pax_3_price),
                'group_price'        => floatval($tour->group_price),
                'family_price'       => floatval($tour->family_price),
                'extra_adult_price'  => floatval($tour->extra_adult_price),
                'extra_child_price'  => floatval($tour->extra_child_price),
                'nights'             => intval($tour->tour_duration_nights),
                'days'               => intval($tour->tour_duration_days),
                'id'                 => intval($tour->id),
                'location'           => $tour->tour_location,
                'block_type'         => $block_type,
                'icon_title'         => $resolved_icon,
                'badge_text'         => $tour->badge_text,
                'enable_icon_dropdown' => isset($tour->enable_icon_dropdown) ? intval($tour->enable_icon_dropdown) : 1,
                'visible_pax_columns'=> isset($tour->visible_pax_columns) && !empty($tour->visible_pax_columns) ? $tour->visible_pax_columns : 'pax1',
                'pax_1_label'        => $tour->pax_1_label,
                'pax_2_label'        => $tour->pax_2_label,
                'pax_3_label'        => $tour->pax_3_label,
                'group_label'        => $tour->group_label,
                'family_label'       => $tour->family_label,
                'pax_1_icon'         => $tour->pax_1_icon,
                'pax_2_icon'         => $tour->pax_2_icon,
                'pax_3_icon'         => $tour->pax_3_icon,
                'group_icon'         => $tour->group_icon,
                'family_icon'        => $tour->family_icon,
                'icon_size'          => isset($tour->icon_size) ? $tour->icon_size : '14px',
                'icon_color'         => isset($tour->icon_color) ? $tour->icon_color : '#075e54',
                'source'             => 'database'
            ));
        }
    }

    $detected = ktv_detect_tours_from_blocks($page_content);
    if (!empty($detected['data'])) {
        foreach ($detected['data'] as $tour) {
            $tour_name = isset($tour['name']) ? trim($tour['name']) : '';
            if (empty($tour_name) || ktv_is_tour_excluded($tour_name)) {
                continue;
            }
            $lower_name = strtolower($tour_name);
            if (in_array($lower_name, $displayed_names, true)) {
                continue;
            }
            $displayed_names[] = $lower_name;

            $price = isset($tour['price']) ? floatval($tour['price']) : 0;
            if ($price <= 0 && isset($tour['offer_price'])) {
                $price = floatval($tour['offer_price']);
            }

            $block_type  = isset($tour['block_type']) ? $tour['block_type'] : 'grid';
            $source_type = isset($tour['is_page_tour']) && $tour['is_page_tour'] ? 'page' : 'block';
            $resolved_icon = isset($tour['icon_title']) ? ktv_resolve_tour_icon($tour['icon_title'], $block_type) : 'fa-map-marker-alt';
            $icon_prefix   = isset($tour['icon_prefix']) && !empty($tour['icon_prefix'])
                ? $tour['icon_prefix']
                : ktv_icon_to_prefix($resolved_icon);

            $tour_options_html .= $build_tour_option_html(array(
                'tour_name'          => $tour_name,
                'price'              => $price,
                'original_price'     => isset($tour['price']) ? floatval($tour['price']) : 0,
                'offer_price'        => isset($tour['offer_price']) ? floatval($tour['offer_price']) : 0,
                'pax_1_price'        => isset($tour['pax_1_price']) ? floatval($tour['pax_1_price']) : 0,
                'pax_2_price'        => isset($tour['pax_2_price']) ? floatval($tour['pax_2_price']) : 0,
                'pax_3_price'        => isset($tour['pax_3_price']) ? floatval($tour['pax_3_price']) : 0,
                'group_price'        => isset($tour['group_price']) ? floatval($tour['group_price']) : 0,
                'family_price'       => isset($tour['family_price']) ? floatval($tour['family_price']) : 0,
                'extra_adult_price'  => 0,
                'extra_child_price'  => 0,
                'nights'             => isset($tour['nights']) ? intval($tour['nights']) : 0,
                'days'               => isset($tour['days']) ? intval($tour['days']) : 0,
