                    $sec_icon_color = isset($section['iconColor']) ? $section['iconColor'] : '#075e54';
                    $sec_icon_size = isset($section['iconSize']) ? $section['iconSize'] : '16px';
                    $sec_placeholder = isset($section['placeholder']) ? $section['placeholder'] : $sec_label;
                    $sec_required = isset($section['required']) ? $section['required'] : false;
                    $sec_type = isset($section['fieldType']) ? $section['fieldType'] : 'text';
                    if (empty($sec_key) || empty($sec_label)) {
                        continue;
                    }
                    $sec_field_id = 'ktv-custom-' . $sec_key;
                    ?>
