/* ============================================================
   35. RENDER — BOOKING BUTTON
   ============================================================ */

function ktv_render_block_booking_button($attributes) {
    $attributes = is_array($attributes) ? $attributes : array();

    $buttonText      = isset($attributes['buttonText']) ? $attributes['buttonText'] : 'Book Now';
    $buttonUrl       = isset($attributes['buttonUrl']) ? $attributes['buttonUrl'] : '#';
    $buttonIcon      = isset($attributes['buttonIcon']) ? $attributes['buttonIcon'] : 'fa-calendar-check';
    $buttonColor     = isset($attributes['buttonColor']) ? $attributes['buttonColor'] : '#ff5722';
    $buttonTextColor = isset($attributes['buttonTextColor']) ? $attributes['buttonTextColor'] : '#ffffff';
    $buttonSize      = isset($attributes['buttonSize']) ? $attributes['buttonSize'] : 'medium';
    $fullWidth       = isset($attributes['fullWidth']) ? $attributes['fullWidth'] : false;
    $tourId          = isset($attributes['tourId']) ? intval($attributes['tourId']) : 0;
    $tourName        = isset($attributes['tourName']) ? $attributes['tourName'] : '';
    $tourPrice       = isset($attributes['tourPrice']) ? floatval($attributes['tourPrice']) : 0;
    $tourLocation    = isset($attributes['tourLocation']) ? $attributes['tourLocation'] : '';
    $blockType       = isset($attributes['blockType']) ? $attributes['blockType'] : 'grid';
    $buttonBorderRadius = isset($attributes['buttonBorderRadius']) ? $attributes['buttonBorderRadius'] : '30px';

    $iconTitle      = isset($attributes['iconTitle']) && !empty($attributes['iconTitle']) ? $attributes['iconTitle'] : $buttonIcon;
    $iconTitleSize  = isset($attributes['iconTitleSize']) ? $attributes['iconTitleSize'] : '16px';
    $iconTitleColor = isset($attributes['iconTitleColor']) ? $attributes['iconTitleColor'] : '#ffffff';

    $sizeClass = 'ktv-btn-' . $buttonSize;
    $sizeStyles = array(
        'small'  => 'padding:8px 20px;font-size:13px;',
        'medium' => 'padding:12px 30px;font-size:15px;',
        'large'  => 'padding:16px 40px;font-size:18px;',
        'xlarge' => 'padding:20px 50px;font-size:20px;'
    );
    $sizeStyle = isset($sizeStyles[$buttonSize]) ? $sizeStyles[$buttonSize] : $sizeStyles['medium'];

    $showIcon = !isset($attributes['enableIcon']) || $attributes['enableIcon'] !== false;
    $icon_class_suffix = ktv_icon_visibility_class($attributes);
    $currency_sym = ktv_get_currency_symbol();

    $btn_pax_data_attrs = ' data-pax1="' . esc_attr(isset($attributes['pax1Price']) ? floatval($attributes['pax1Price']) : 0) . '"'
        . ' data-pax2="' . esc_attr(isset($attributes['pax2Price']) ? floatval($attributes['pax2Price']) : 0) . '"'
        . ' data-pax3="' . esc_attr(isset($attributes['pax3Price']) ? floatval($attributes['pax3Price']) : 0) . '"'
        . ' data-group="' . esc_attr(isset($attributes['groupPrice']) ? floatval($attributes['groupPrice']) : 0) . '"'
