                        <input type="text" name="name" id="review-name" placeholder="<?php echo esc_attr($nameLabel); ?> *" required aria-label="<?php echo esc_attr($nameLabel); ?>" style="border:none !important;box-shadow:none !important;background:#f8f9fa;border-radius:10px;padding:12px 16px;width:100%;">
                    </div>
                    <div class="ktv-input-group" style="border:none !important;box-shadow:none !important;">
                        <i class="fas fa-envelope" aria-hidden="true"></i>
                        <label for="review-email" class="ktv-sr-only"><?php echo esc_html($emailLabel); ?></label>
                        <input type="email" name="email" id="review-email" placeholder="<?php echo esc_attr($emailLabel); ?> *" required aria-label="<?php echo esc_attr($emailLabel); ?>" style="border:none !important;box-shadow:none !important;background:#f8f9fa;border-radius:10px;padding:12px 16px;width:100%;">
                    </div>
