                <div class="ktv-input-group" style="border:none !important;box-shadow:none !important; margin-bottom:15px;">
                    <i class="fas fa-heading" aria-hidden="true"></i>
                    <label for="review-title" class="ktv-sr-only"><?php echo esc_html($reviewTitleLabel); ?></label>
                    <input type="text" name="review_title" id="review-title" placeholder="<?php echo esc_attr($reviewTitleLabel); ?>" aria-label="<?php echo esc_attr($reviewTitleLabel); ?>" style="border:none !important;box-shadow:none !important;background:#f8f9fa;border-radius:10px;padding:12px 16px;width:100%;">
                </div>

                <div class="ktv-form-row">
                    <div class="ktv-input-group" style="border:none !important;box-shadow:none !important;flex:1;">
                        <i class="fas fa-globe" aria-hidden="true"></i>
                        <label for="review_language" class="ktv-sr-only">Review Language</label>
                        <select name="review_language" id="review_language" aria-label="Review Language" style="border:none !important;box-shadow:none !important;background:#f8f9fa;border-radius:10px;padding:12px 16px;width:100%;">
                            <option value="en">English</option>
                            <?php foreach ($languages as $code => $label): ?>
                            <option value="<?php echo esc_attr($code); ?>"><?php echo esc_html($label); ?></option>
