                        </select>
                    </div>
                    <div class="ktv-input-group" style="border:none !important;box-shadow:none !important;">
                        <i class="fas fa-image" aria-hidden="true"></i>
                        <label for="review_image" class="ktv-sr-only">Review Image</label>
                        <input type="file" name="review_image" id="review_image" accept="image/*" aria-label="Review Image" style="border:none !important;box-shadow:none !important;background:#f8f9fa;border-radius:10px;padding:8px 12px;width:100%;">
                    </div>
                </div>

                <?php if ($showReviewerProfilePic): ?>
                <div class="ktv-input-group" style="border:none !important;box-shadow:none !important; margin-bottom:15px;">
                    <i class="fas fa-user-circle" aria-hidden="true"></i>
                    <label for="reviewer_profile_pic" class="ktv-sr-only">Reviewer Profile Picture</label>
                    <input type="file" name="reviewer_profile_pic" id="reviewer_profile_pic" accept="image/*" aria-label="Reviewer Profile Picture" style="border:none !important;box-shadow:none !important;background:#f8f9fa;border-radius:10px;padding:8px 12px;width:100%;">
                </div>
                <?php endif; ?>

                <?php if (!empty($custom_sections)): ?>
                <?php foreach ($custom_sections as $section): ?>
                    <?php
                    if (isset($section['enabled']) && $section['enabled'] === false) {
                        continue;
                    }
                    $sec_key = isset($section['key']) ? sanitize_key($section['key']) : '';
                    $sec_label = isset($section['label']) ? $section['label'] : '';
                    $sec_icon = isset($section['icon']) ? $section['icon'] : 'fa-star';
                    $sec_icon_color = isset($section['iconColor']) ? $section['iconColor'] : '#075e54';
                    $sec_icon_size = isset($section['iconSize']) ? $section['iconSize'] : '16px';
                    if (empty($sec_key) || empty($sec_label)) {
                        continue;
                    }
                    $sec_field_id = 'review-custom-' . $sec_key;
                    ?>
                <div class="ktv-input-group" style="border:none !important;box-shadow:none !important; margin-bottom:15px;">
                    <i class="fas <?php echo esc_attr($sec_icon); ?>" style="color:<?php echo esc_attr($sec_icon_color); ?>; font-size:<?php echo esc_attr($sec_icon_size); ?>;" aria-hidden="true"></i>
                    <label for="<?php echo esc_attr($sec_field_id); ?>" class="ktv-sr-only"><?php echo esc_html($sec_label); ?></label>
                    <input type="text" id="<?php echo esc_attr($sec_field_id); ?>" name="custom_<?php echo esc_attr($sec_key); ?>" placeholder="<?php echo esc_attr($sec_label); ?>" aria-label="<?php echo esc_attr($sec_label); ?>" style="border:none !important;box-shadow:none !important;background:#f8f9fa;border-radius:10px;padding:12px 16px;width:100%;">
                </div>
