                    <label for="review-content" class="ktv-sr-only"><?php echo esc_html($reviewLabel); ?></label>
                    <textarea name="content" id="review-content" rows="4" placeholder="<?php echo esc_attr($reviewLabel); ?> *" required aria-label="<?php echo esc_attr($reviewLabel); ?>" style="border:none !important;box-shadow:none !important;background:#f8f9fa;border-radius:10px;padding:12px 16px;width:100%;resize:vertical;"></textarea>
