                <div class="ktv-message"></div>
            </form>
        </div>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   37. RENDER — REVIEWS DISPLAY
   ============================================================ */

function ktv_render_block_reviews_display($attributes) {
    global $wpdb;

    $attributes = is_array($attributes) ? $attributes : array();

    $pageId  = isset($attributes['pageId']) && $attributes['pageId'] > 0 ? intval($attributes['pageId']) : get_the_ID();
    $tourId  = isset($attributes['tourId']) ? intval($attributes['tourId']) : 0;
    $limit   = isset($attributes['limit']) ? intval($attributes['limit']) : 10;
    $starColor = isset($attributes['starColor']) ? $attributes['starColor'] : '#FFD700';
    $starSize  = isset($attributes['starSize']) ? $attributes['starSize'] : '16px';
    $headingType = isset($attributes['headingType']) ? $attributes['headingType'] : 'h3';
    $headingFontSize = isset($attributes['headingFontSize']) ? $attributes['headingFontSize'] : '20px';
    $headingColor    = isset($attributes['headingColor']) ? $attributes['headingColor'] : '#333333';
    $headingFontFamily = isset($attributes['headingFontFamily']) ? $attributes['headingFontFamily'] : 'inherit';
    $headingFontWeight = isset($attributes['headingFontWeight']) ? $attributes['headingFontWeight'] : '700';
    $sortReviews     = isset($attributes['sortReviews']) ? $attributes['sortReviews'] : 'newest';
    $languageFilter  = isset($attributes['languageFilter']) ? $attributes['languageFilter'] : '';

    $iconTitle      = isset($attributes['iconTitle']) ? $attributes['iconTitle'] : 'fa-star';
    $iconTitleSize  = isset($attributes['iconTitleSize']) ? $attributes['iconTitleSize'] : '24px';
    $iconTitleColor = isset($attributes['iconTitleColor']) ? $attributes['iconTitleColor'] : '#FFD700';

    $reviewTitleIconEnabled = isset($attributes['reviewTitleIconEnabled']) ? $attributes['reviewTitleIconEnabled'] : true;
    $reviewTitleIconSize    = isset($attributes['reviewTitleIconSize']) ? $attributes['reviewTitleIconSize'] : $iconTitleSize;
    $reviewTitleIconColor   = isset($attributes['reviewTitleIconColor']) ? $attributes['reviewTitleIconColor'] : $iconTitleColor;

    $reviewFormTitleSize = isset($attributes['reviewFormTitleSize'])
        ? $attributes['reviewFormTitleSize']
        : (isset($attributes['headingFontSize']) ? $attributes['headingFontSize'] : '20px');

    $reviewFormTitleColor = isset($attributes['reviewFormTitleColor'])
        ? $attributes['reviewFormTitleColor']
        : (isset($attributes['headingColor']) ? $attributes['headingColor'] : '#333333');

    $reviewFormTitleFontWeight = isset($attributes['reviewFormTitleFontWeight'])
        ? $attributes['reviewFormTitleFontWeight']
        : (isset($attributes['headingFontWeight']) ? $attributes['headingFontWeight'] : '700');

    $reviewFormTitleFontFamily = isset($attributes['reviewFormTitleFontFamily'])
        ? $attributes['reviewFormTitleFontFamily']
        : (isset($attributes['headingFontFamily']) ? $attributes['headingFontFamily'] : 'inherit');

    $displayTitleColor = isset($attributes['displayTitleColor']) && $attributes['displayTitleColor'] !== ''
        ? $attributes['displayTitleColor']
        : $reviewFormTitleColor;

    $showTitle = isset($attributes['showTitle']) ? $attributes['showTitle'] : true;
    $titleText = isset($attributes['titleText']) ? $attributes['titleText'] : 'Customer Reviews';
    $showIcon  = !isset($attributes['enableIcon']) || $attributes['enableIcon'] !== false;

    $reviewModalTitle = isset($attributes['reviewModalTitle']) && $attributes['reviewModalTitle'] !== ''
        ? $attributes['reviewModalTitle']
        : ktv_get_setting('review_modal_title', 'Write a Review');
    $reviewModalIcon  = isset($attributes['reviewModalIcon']) && $attributes['reviewModalIcon'] !== ''
        ? $attributes['reviewModalIcon']
        : ktv_get_setting('review_modal_icon', 'fa-star');

    $reviewModalLogo            = isset($attributes['reviewModalLogo']) && $attributes['reviewModalLogo'] !== ''
        ? $attributes['reviewModalLogo']
        : ktv_get_setting('review_modal_logo', '');
    $reviewModalBgColor         = isset($attributes['reviewModalBgColor']) && $attributes['reviewModalBgColor'] !== ''
        ? $attributes['reviewModalBgColor']
        : ktv_get_setting('review_modal_bg_color', '');
    $reviewModalBgImage         = isset($attributes['reviewModalBgImage']) && $attributes['reviewModalBgImage'] !== ''
        ? $attributes['reviewModalBgImage']
        : ktv_get_setting('review_modal_bg_image', '');
    $reviewModalTitleBgColor    = isset($attributes['reviewModalTitleBgColor']) && $attributes['reviewModalTitleBgColor'] !== ''
        ? $attributes['reviewModalTitleBgColor']
        : ktv_get_setting('review_modal_title_bg_color', '');
    $reviewModalTitleBgImage    = isset($attributes['reviewModalTitleBgImage']) && $attributes['reviewModalTitleBgImage'] !== ''
        ? $attributes['reviewModalTitleBgImage']
        : ktv_get_setting('review_modal_title_bg_image', '');
    $reviewModalTitleTextColor  = isset($attributes['reviewModalTitleTextColor']) && $attributes['reviewModalTitleTextColor'] !== ''
        ? $attributes['reviewModalTitleTextColor']
        : ktv_get_setting('review_modal_title_text_color', '#ffffff');
    $reviewModalTitleIconColor  = isset($attributes['reviewModalTitleIconColor']) && $attributes['reviewModalTitleIconColor'] !== ''
        ? $attributes['reviewModalTitleIconColor']
        : ktv_get_setting('review_modal_title_icon_color', '#FFD700');

    if ($tourId > 0) {
        $reviews = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_reviews WHERE tour_id = %d AND status = 'approved' ORDER BY created_at DESC LIMIT %d",
            $tourId, $limit
        ));
        $tour_name = $wpdb->get_var($wpdb->prepare(
            "SELECT tour_name FROM {$wpdb->prefix}ktv_tours WHERE id = %d AND is_hardcoded = 0",
            $tourId
        ));
    } else {
        $reviews = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_reviews WHERE page_id = %d AND status = 'approved' ORDER BY created_at DESC LIMIT %d",
            $pageId, $limit
        ));
        $tour_name = get_the_title($pageId);
    }

    $heading_tag = in_array($headingType, array('h1', 'h2', 'h3', 'h4', 'h5', 'h6'), true) ? $headingType : 'h3';

    $modal_data_attrs = ' data-review-modal-title="' . esc_attr($reviewModalTitle) . '"'
        . ' data-review-modal-icon="' . esc_attr($reviewModalIcon) . '"'
        . ' data-review-modal-logo="' . esc_attr($reviewModalLogo) . '"'
        . ' data-review-modal-bg-color="' . esc_attr($reviewModalBgColor) . '"'
        . ' data-review-modal-bg-image="' . esc_attr($reviewModalBgImage) . '"'
        . ' data-review-modal-title-bg-color="' . esc_attr($reviewModalTitleBgColor) . '"'
        . ' data-review-modal-title-bg-image="' . esc_attr($reviewModalTitleBgImage) . '"'
        . ' data-review-modal-title-text-color="' . esc_attr($reviewModalTitleTextColor) . '"'
        . ' data-review-modal-title-icon-color="' . esc_attr($reviewModalTitleIconColor) . '"';

    if (empty($reviews)) {
        $display_name = $tour_name ? $tour_name : 'this tour';
        return '<div class="ktv-no-reviews" data-tour-id="' . esc_attr($tourId) . '" data-page-id="' . esc_attr($pageId) . '"' . $modal_data_attrs . ' style="text-align:center;padding:20px;">
            <i class="far fa-star" style="font-size:48px;color:' . esc_attr($starColor) . ';"></i>
            <p>No reviews yet for ' . esc_html($display_name) . '.</p>
            <button type="button" class="ktv-be-first-review" data-tour-id="' . esc_attr($tourId) . '" data-page-id="' . esc_attr($pageId) . '" style="background:none;border:none;padding:0;color:' . esc_attr($starColor) . ';text-decoration:underline;cursor:pointer;">Be the first to write a review</button>
        </div>';
    }

    $total = count($reviews);
    $avg   = 0;
    foreach ($reviews as $r) {
        $avg += $r->rating;
    }
    $avg = round($avg / $total, 1);

    $display_name = $tour_name ? $tour_name : get_the_title($pageId);
    $icon_class_suffix = ktv_icon_visibility_class($attributes);

    ob_start();
    ?>
    <div class="ktv-reviews-google<?php echo esc_attr($icon_class_suffix); ?>"<?php echo $modal_data_attrs; ?>
         style="--ktv-star-color:<?php echo esc_attr($starColor); ?>; --ktv-star-size:<?php echo esc_attr($starSize); ?>;">
        <?php if ($showTitle): ?>
        <<?php echo esc_attr($heading_tag); ?> class="ktv-reviews-title" style="font-size:<?php echo esc_attr($reviewFormTitleSize); ?>; color:<?php echo esc_attr($displayTitleColor); ?>; font-family:<?php echo esc_attr($reviewFormTitleFontFamily); ?>; font-weight:<?php echo esc_attr($reviewFormTitleFontWeight); ?>; text-align:center;margin:0 0 20px;">
            <?php if ($showIcon && $reviewTitleIconEnabled): ?><i class="fas <?php echo esc_attr($iconTitle); ?>" style="font-size:<?php echo esc_attr($reviewTitleIconSize); ?>; color:<?php echo esc_attr($reviewTitleIconColor); ?>; margin-right:10px;" aria-hidden="true"></i><?php endif; ?>
            <?php echo esc_html($titleText); ?>
        </<?php echo esc_attr($heading_tag); ?>>
        <?php endif; ?>

        <div class="ktv-reviews-header" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:15px;background:#fff;padding:25px;border-radius:16px;margin-bottom:20px;box-shadow:0 10px 40px rgba(0,0,0,0.08);">
            <div class="ktv-overall-rating" style="display:flex;align-items:center;gap:15px;flex-wrap:wrap;">
                <span class="ktv-rating-number" style="font-size:36px;font-weight:700;color:#333;"><?php echo esc_html($avg); ?></span>
                <div>
                    <div class="ktv-stars"><?php echo ktv_render_stars_html($avg, $starSize, $starColor); ?></div>
                    <span class="ktv-review-count" style="font-size:12px;color:#666;"><?php echo esc_html($total); ?> reviews for <?php echo esc_html($display_name); ?></span>
                </div>
            </div>
            <div class="ktv-review-sort" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
                <label style="font-size:12px;color:#666;"><i class="fas fa-sort"></i> Sort:</label>
                <select class="ktv-review-sort-select" aria-label="Sort reviews" data-tour-id="<?php echo esc_attr($tourId); ?>" data-page-id="<?php echo esc_attr($pageId); ?>" style="padding:6px 12px;border-radius:6px;border:1px solid #ddd;font-size:12px;">
                    <option value="newest" <?php echo $sortReviews === 'newest' ? 'selected' : ''; ?>>Newest First</option>
                    <option value="highest" <?php echo $sortReviews === 'highest' ? 'selected' : ''; ?>>Highest Rated</option>
                    <option value="lowest" <?php echo $sortReviews === 'lowest' ? 'selected' : ''; ?>>Lowest Rated</option>
                    <option value="most_helpful" <?php echo $sortReviews === 'most_helpful' ? 'selected' : ''; ?>>Most Helpful</option>
                </select>
                <select class="ktv-review-language-filter" aria-label="Filter reviews by language" data-tour-id="<?php echo esc_attr($tourId); ?>" data-page-id="<?php echo esc_attr($pageId); ?>" style="padding:6px 12px;border-radius:6px;border:1px solid #ddd;font-size:12px;">
                    <option value="">All Languages</option>
                    <option value="en" <?php echo $languageFilter === 'en' ? 'selected' : ''; ?>>English</option>
                    <option value="hi" <?php echo $languageFilter === 'hi' ? 'selected' : ''; ?>>Hindi</option>
                    <option value="ur" <?php echo $languageFilter === 'ur' ? 'selected' : ''; ?>>Urdu</option>
                    <option value="ar" <?php echo $languageFilter === 'ar' ? 'selected' : ''; ?>>Arabic</option>
                    <option value="fr" <?php echo $languageFilter === 'fr' ? 'selected' : ''; ?>>French</option>
                    <option value="es" <?php echo $languageFilter === 'es' ? 'selected' : ''; ?>>Spanish</option>
                    <option value="de" <?php echo $languageFilter === 'de' ? 'selected' : ''; ?>>German</option>
                </select>
            </div>
        </div>
        <div class="ktv-reviews-list" style="margin-top:20px;">
            <?php foreach ($reviews as $review):
                $avatar_url = '';
                if (!empty($review->reviewer_profile_pic)) {
                    $avatar_url = $review->reviewer_profile_pic;
                } elseif (!empty($review->reviewer_avatar)) {
                    $avatar_url = $review->reviewer_avatar;
                } else {
                    $avatar_url = 'https://ui-avatars.com/api/?name=' . urlencode($review->reviewer_name) . '&background=28a745&color=fff&size=50';
                }
            ?>
            <div class="ktv-review-card" data-rating="<?php echo esc_attr($review->rating); ?>" data-date="<?php echo esc_attr($review->created_at); ?>" data-language="<?php echo esc_attr($review->review_language); ?>" style="background:#fff;padding:20px;border-radius:12px;border:1px solid #e0e0e0;box-shadow:0 2px 8px rgba(0,0,0,0.04);margin-bottom:15px;">
                <div class="ktv-reviewer-info" style="display:flex;align-items:center;gap:12px;margin-bottom:10px;">
                    <img src="<?php echo esc_url($avatar_url); ?>" class="ktv-reviewer-avatar" alt="" width="50" height="50" loading="lazy" decoding="async" style="width:50px;height:50px;border-radius:50%;object-fit:cover;">
                    <div>
                        <strong><?php echo esc_html($review->reviewer_name); ?></strong>
                        <?php if ($review->verified): ?><span class="ktv-verified-badge" style="color:#28a745;font-size:12px;margin-left:8px;"><i class="fas fa-check-circle"></i> Verified</span><?php endif; ?>
                        <div class="ktv-review-date" style="font-size:12px;color:#999;"><?php echo esc_html(ktv_time_ago($review->created_at)); ?></div>
                    </div>
                </div>
                <div style="font-size:12px;color:#075e54;font-weight:600;margin-bottom:6px;">
                    📍 Review for: <strong><?php echo esc_html($review->tour_name); ?></strong>
                    <?php if ($review->tour_id > 0): ?>
                    (ID: <?php echo esc_html($review->tour_id); ?>)
                    <?php endif; ?>
                    <?php if ($review->page_id > 0): ?>
                    | Page ID: <?php echo esc_html($review->page_id); ?>
                    <?php endif; ?>
                </div>
                <div class="ktv-stars" style="margin-bottom:8px;"><?php echo ktv_render_stars_html($review->rating, $starSize, $starColor); ?></div>
                <?php if (!empty($review->review_title)): ?>
                <h4 style="font-size:16px;margin:5px 0;color:#333;"><?php echo esc_html($review->review_title); ?></h4>
                <?php endif; ?>
                <div class="ktv-review-content" style="font-size:14px;color:#555;line-height:1.6;"><?php echo wp_kses_post(wpautop($review->review_content)); ?></div>

                <?php if (!empty($review->review_image)): ?>
                <div style="margin:10px 0;">
                    <img src="<?php echo esc_url($review->review_image); ?>" alt="Review Image" width="200" height="200" loading="lazy" decoding="async" style="max-width:200px;border-radius:8px;border:1px solid #e0e0e0;cursor:pointer;" class="ktv-review-image-thumb" data-full="<?php echo esc_url($review->review_image); ?>">
                </div>
                <?php endif; ?>

                <div class="ktv-review-helpful" style="margin-top:10px;display:flex;gap:15px;font-size:12px;color:#999;">
                    <button class="ktv-helpful-btn" data-review-id="<?php echo esc_attr($review->id); ?>" aria-label="Mark review as helpful" style="background:none;border:none;cursor:pointer;color:#666;font-size:12px;">
                        <i class="far fa-thumbs-up"></i> Helpful (<span class="ktv-helpful-count"><?php echo esc_html($review->helpful_count ?: 0); ?></span>)
                    </button>
                </div>

                <?php if (!empty($review->reply_content)): ?>
                <div style="margin-top:12px;padding:12px 16px;background:#f0f8f0;border-radius:8px;border-left:3px solid #28a745;">
                    <strong style="color:#075e54;font-size:13px;">Reply from Kashmir Travelling Voyage:</strong>
                    <p style="margin:5px 0 0;font-size:13px;color:#555;"><?php echo esc_html($review->reply_content); ?></p>
                    <span style="font-size:11px;color:#999;"><?php echo !empty($review->reply_date) ? esc_html(ktv_time_ago($review->reply_date)) : ''; ?></span>
                </div>
                <?php endif; ?>
            </div>
            <?php endforeach; ?>
        </div>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   38. RENDER — ACCORDION
   ============================================================ */

function ktv_render_block_accordion($attributes) {
    global $wpdb;

    $attributes = is_array($attributes) ? $attributes : array();

    $title      = isset($attributes['sectionTitle']) && !empty($attributes['sectionTitle'])
        ? $attributes['sectionTitle']
        : (isset($attributes['titleText']) ? $attributes['titleText'] : 'Tour Itinerary');
    $titleColor = isset($attributes['titleColor']) ? $attributes['titleColor'] : '#333333';
    $titleFontSize = isset($attributes['titleFontSize']) ? $attributes['titleFontSize'] : '20px';
    $titleFontFamily = isset($attributes['titleFontFamily']) ? $attributes['titleFontFamily'] : 'inherit';
    $titleFontWeight = isset($attributes['titleFontWeight']) ? $attributes['titleFontWeight'] : '700';
    $iconColor  = isset($attributes['iconColor']) ? $attributes['iconColor'] : '#075e54';
    $pageId     = isset($attributes['pageId']) ? intval($attributes['pageId']) : get_the_ID();
    $tourId     = isset($attributes['tourId']) ? intval($attributes['tourId']) : 0;
    $showShare  = isset($attributes['showShare']) ? $attributes['showShare'] : true;
    $showDownload = isset($attributes['showDownload']) ? $attributes['showDownload'] : true;
    $downloadLabel = isset($attributes['downloadLabel']) ? $attributes['downloadLabel'] : 'Download Itinerary';
    $firstOpen  = isset($attributes['firstOpen']) ? $attributes['firstOpen'] : false;
    $allClosed  = isset($attributes['allClosed']) ? $attributes['allClosed'] : false;
    $showTitle  = isset($attributes['showTitle']) ? $attributes['showTitle'] : true;
    $shareDownloadSameLine = isset($attributes['shareDownloadSameLine']) ? $attributes['shareDownloadSameLine'] : true;

    $shareButtonSize      = isset($attributes['shareButtonSize']) ? $attributes['shareButtonSize'] : '40px';
    $shareButtonBgColor   = isset($attributes['shareButtonBgColor']) ? $attributes['shareButtonBgColor'] : 'transparent';
    $shareButtonIconColor = isset($attributes['shareButtonIconColor']) ? $attributes['shareButtonIconColor'] : '#666666';
    $shareButtonIconSize  = isset($attributes['shareButtonIconSize']) ? $attributes['shareButtonIconSize'] : '14px';

    $downloadButtonBgColor   = isset($attributes['downloadButtonBgColor']) ? $attributes['downloadButtonBgColor'] : '#075e54';
    $downloadButtonTextColor = isset($attributes['downloadButtonTextColor']) ? $attributes['downloadButtonTextColor'] : '#ffffff';
    $downloadButtonFontSize  = isset($attributes['downloadButtonFontSize']) ? $attributes['downloadButtonFontSize'] : '14px';
    $downloadButtonFontWeight = isset($attributes['downloadButtonFontWeight']) ? $attributes['downloadButtonFontWeight'] : '600';

    $showDocx = isset($attributes['showDocx']) ? $attributes['showDocx'] : true;
    $showTxt  = isset($attributes['showTxt'])  ? $attributes['showTxt']  : true;

    $showPrintButton  = isset($attributes['showPrintButton']) ? ($attributes['showPrintButton'] !== false) : true;
    $printButtonLabel = isset($attributes['printButtonLabel']) && !empty($attributes['printButtonLabel'])
        ? $attributes['printButtonLabel']
        : 'Print Itinerary';

    $showViewDocx = isset($attributes['showViewDocx']) ? (bool) $attributes['showViewDocx'] : false;
    $showViewTxt  = isset($attributes['showViewTxt'])  ? (bool) $attributes['showViewTxt']  : false;

    $any_view_enabled = ($showViewDocx || $showViewTxt);

    $iconTitle      = isset($attributes['iconTitle']) ? $attributes['iconTitle'] : 'fa-calendar-alt';
    $iconTitleSize  = isset($attributes['iconTitleSize']) ? $attributes['iconTitleSize'] : '20px';
    $iconTitleColor = isset($attributes['iconTitleColor']) ? $attributes['iconTitleColor'] : '#075e54';
    $showIcon       = !isset($attributes['enableIcon']) || $attributes['enableIcon'] !== false;

    $sectionHeadingType = isset($attributes['sectionHeadingType']) ? $attributes['sectionHeadingType'] : 'h3';
    if (!in_array($sectionHeadingType, array('h2', 'h3', 'h4', 'h5', 'h6'), true)) {
        $sectionHeadingType = 'h3';
    }
    $sectionBriefText     = isset($attributes['sectionBriefText']) ? $attributes['sectionBriefText'] : '';
    $sectionBriefSize     = isset($attributes['sectionBriefSize']) ? $attributes['sectionBriefSize'] : '14px';
    $sectionBriefColor    = isset($attributes['sectionBriefColor']) ? $attributes['sectionBriefColor'] : '#666666';

    $customItems = isset($attributes['customAccordionItems']) ? $attributes['customAccordionItems'] : array();
    $items       = array();

    if (!empty($customItems) && is_array($customItems)) {
        foreach ($customItems as $item) {
            $items[] = (object) array(
                'item_title'   => isset($item['title']) ? $item['title'] : '',
                'item_after_title_text' => isset($item['after_title_text']) ? $item['after_title_text'] : '',
                'item_content' => isset($item['content']) ? $item['content'] : '',
                'item_icon'    => isset($item['icon']) ? $item['icon'] : 'fa-map-pin',
                'item_icon_size'  => isset($item['icon_size']) ? $item['icon_size'] : '16px',
                'item_icon_color' => isset($item['icon_color']) ? $item['icon_color'] : '',
                'item_icon_font_family' => isset($item['icon_font_family']) ? $item['icon_font_family'] : 'inherit',
                'item_title_size' => isset($item['title_size']) ? $item['title_size'] : '16px',
                'item_title_color'=> isset($item['title_color']) ? $item['title_color'] : '',
                'item_title_weight'=> isset($item['title_weight']) ? $item['title_weight'] : '600',
                'item_title_font_family' => isset($item['title_font_family']) ? $item['title_font_family'] : 'inherit',
                'after_title_font_size' => isset($item['after_title_font_size']) ? $item['after_title_font_size'] : '12px',
                'after_title_color' => isset($item['after_title_color']) ? $item['after_title_color'] : '#666666',
                'icon_position'   => isset($item['icon_position']) ? $item['icon_position'] : 'left',
                'first_open'   => isset($item['first_open']) ? $item['first_open'] : false
            );
        }
    }

    if (empty($items)) {
        if ($tourId > 0) {
            $items = $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$wpdb->prefix}ktv_accordion_items WHERE status = 'active' AND tour_id = %d ORDER BY item_order ASC",
                $tourId
            ));
        }
        if (empty($items) && $pageId > 0) {
            $items = $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$wpdb->prefix}ktv_accordion_items WHERE status = 'active' AND page_id = %d ORDER BY item_order ASC",
                $pageId
            ));
        }
        if (empty($items)) {
            $items = $wpdb->get_results(
                "SELECT * FROM {$wpdb->prefix}ktv_accordion_items WHERE status = 'active' AND (page_id = 0 OR page_id IS NULL) AND (tour_id = 0 OR tour_id IS NULL) ORDER BY item_order ASC"
            );
        }
    }

    if (!empty($items) && !isset($items[0]->first_open)) {
        $items[0]->first_open = $firstOpen;
    }

    $id = 'accordion-' . uniqid();
    $icon_class_suffix = ktv_icon_visibility_class($attributes);

    $effectiveFirstOpen = $allClosed ? false : $firstOpen;

    ob_start();
    ?>
    <div class="ktv-accordion-wrapper<?php echo esc_attr($icon_class_suffix); ?>" id="<?php echo esc_attr($id); ?>" data-title="<?php echo esc_attr($title); ?>" data-first-open="<?php echo $effectiveFirstOpen ? 'true' : 'false'; ?>" data-all-closed="<?php echo $allClosed ? 'true' : 'false'; ?>">
        <?php if ($showTitle): ?>
        <div class="ktv-accordion-header" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:20px;">
            <div style="flex:1;min-width:0;">
                <<?php echo esc_attr($sectionHeadingType); ?> class="ktv-accordion-section-title" style="color:<?php echo esc_attr($titleColor); ?>; font-size:<?php echo esc_attr($titleFontSize); ?>; font-family:<?php echo esc_attr($titleFontFamily); ?>; font-weight:<?php echo esc_attr($titleFontWeight); ?>; margin:0;">
                    <?php if ($showIcon): ?><i class="fas <?php echo esc_attr($iconTitle); ?>" style="font-size:<?php echo esc_attr($iconTitleSize); ?>; color:<?php echo esc_attr($iconTitleColor); ?>; margin-right:10px;" aria-hidden="true"></i><?php endif; ?>
                    <?php echo esc_html($title); ?>
                </<?php echo esc_attr($sectionHeadingType); ?>>
                <?php if (!empty($sectionBriefText)): ?>
                <p class="ktv-accordion-section-brief" style="font-size:<?php echo esc_attr($sectionBriefSize); ?>; color:<?php echo esc_attr($sectionBriefColor); ?>; margin:6px 0 0; line-height:1.5;"><?php echo esc_html($sectionBriefText); ?></p>
                <?php endif; ?>
            </div>
            <div class="ktv-accordion-actions" style="display:flex;align-items:center;gap:10px;position:relative;<?php echo $shareDownloadSameLine ? 'flex-wrap:nowrap;' : 'flex-wrap:wrap;'; ?>">
                <?php if ($showShare): ?>
                <button class="ktv-accordion-share-btn" title="Share Itinerary" aria-label="Share Itinerary" style="--ktv-share-bg:<?php echo esc_attr($shareButtonBgColor); ?>;background:var(--ktv-share-bg);border:1px solid #e0e0e0;width:<?php echo esc_attr($shareButtonSize); ?>;height:<?php echo esc_attr($shareButtonSize); ?>;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all 0.3s ease;">
                    <i class="fas fa-share-alt" style="color:<?php echo esc_attr($shareButtonIconColor); ?>;font-size:<?php echo esc_attr($shareButtonIconSize); ?>;" aria-hidden="true"></i>
                </button>
                <?php endif; ?>
                <?php if ($showDownload): ?>
                <button class="ktv-accordion-download-btn" style="--ktv-dl-bg:<?php echo esc_attr($downloadButtonBgColor); ?>;--ktv-dl-text:<?php echo esc_attr($downloadButtonTextColor); ?>;padding:10px 20px;background:var(--ktv-dl-bg);color:var(--ktv-dl-text);border:none;border-radius:30px;cursor:pointer;font-size:<?php echo esc_attr($downloadButtonFontSize); ?>;font-weight:<?php echo esc_attr($downloadButtonFontWeight); ?>;transition:all 0.3s ease;display:inline-flex;align-items:center;gap:8px;"><i class="fas fa-download" aria-hidden="true"></i> <?php echo esc_html($downloadLabel); ?></button>
                <div class="ktv-download-options<?php echo $any_view_enabled ? ' ktv-view-enabled' : ''; ?>" style="display:none;position:absolute;right:0;top:100%;background:#fff;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,0.15);z-index:9999;overflow:hidden;min-width:220px;margin-top:5px;">
                    <?php if ($showDocx): ?>
                    <button class="ktv-download-docx" style="display:block;width:100%;padding:12px 20px;border:none;background:none;cursor:pointer;text-align:left;font-size:14px;color:#333;transition:all 0.2s ease;"><i class="fas fa-file-word"></i> Download as DOCX</button>
                    <?php endif; ?>
                    <?php if ($showTxt): ?>
                    <button class="ktv-download-txt" style="display:block;width:100%;padding:12px 20px;border:none;background:none;cursor:pointer;text-align:left;font-size:14px;color:#333;transition:all 0.2s ease;"><i class="fas fa-file-alt"></i> Download as TXT</button>
                    <?php endif; ?>
                    <?php if ($showPrintButton): ?>
                    <button class="ktv-accordion-print-btn" style="display:block;width:100%;padding:12px 20px;border:none;border-top:1px solid #eee;background:none;cursor:pointer;text-align:left;font-size:14px;color:#333;transition:all 0.2s ease;"><i class="fas fa-print"></i> <?php echo esc_html($printButtonLabel); ?></button>
                    <?php endif; ?>
                    <?php if ($any_view_enabled): ?>
                    <div style="border-top:1px solid #eee;margin:4px 0;"></div>
                    <?php if ($showViewDocx): ?>
                    <button class="ktv-view-docx" style="display:block;width:100%;padding:12px 20px;border:none;background:none;cursor:pointer;text-align:left;font-size:14px;color:#333;transition:all 0.2s ease;"><i class="fas fa-external-link-alt"></i> View as DOCX</button>
                    <?php endif; ?>
                    <?php if ($showViewTxt): ?>
                    <button class="ktv-view-txt" style="display:block;width:100%;padding:12px 20px;border:none;background:none;cursor:pointer;text-align:left;font-size:14px;color:#333;transition:all 0.2s ease;"><i class="fas fa-external-link-alt"></i> View as TXT</button>
                    <?php endif; ?>
                    <?php endif; ?>
                </div>
                <?php endif; ?>
            </div>
        </div>
        <?php endif; ?>

        <?php if (empty($items)): ?>
        <div class="ktv-no-accordion-items" style="text-align:center;padding:30px;background:#f8f9fa;border-radius:12px;color:#666;">
            <i class="fas fa-info-circle" style="font-size:32px;display:block;margin-bottom:10px;"></i>
            No itinerary items available. Add them in the block editor or WP Admin → KTV Travel → Accordion.
        </div>
        <?php else: ?>
        <?php foreach ($items as $index => $item): ?>
        <?php
            $isOpen = ($effectiveFirstOpen && $index === 0) || (isset($item->first_open) && $item->first_open && !$allClosed);
            $item_icon_size = isset($item->item_icon_size) && !empty($item->item_icon_size) ? $item->item_icon_size : '16px';
            $item_icon_color = isset($item->item_icon_color) && !empty($item->item_icon_color) ? $item->item_icon_color : $iconColor;
            $item_title_size = isset($item->item_title_size) && !empty($item->item_title_size) ? $item->item_title_size : '16px';
            $item_title_color = isset($item->item_title_color) && !empty($item->item_title_color) ? $item->item_title_color : '#333333';
            $item_title_weight = isset($item->item_title_weight) && !empty($item->item_title_weight) ? $item->item_title_weight : '600';
            $item_title_font_family = isset($item->item_title_font_family) && !empty($item->item_title_font_family) ? $item->item_title_font_family : 'inherit';
            $item_after_title_text = isset($item->item_after_title_text) ? $item->item_after_title_text : '';
            $after_title_font_size = isset($item->after_title_font_size) && !empty($item->after_title_font_size) ? $item->after_title_font_size : '12px';
            $after_title_color = isset($item->after_title_color) && !empty($item->after_title_color) ? $item->after_title_color : '#666666';
            $icon_position = isset($item->icon_position) && $item->icon_position === 'right' ? 'right' : 'left';
        ?>
        <div class="ktv-accordion-item" style="margin-bottom:12px;border:1px solid #e0e0e0;border-radius:12px;overflow:hidden;background:#fff;">
            <div class="ktv-accordion-head" role="button" tabindex="0" data-icon-position="<?php echo esc_attr($icon_position); ?>" style="padding:16px 20px;background:#f8f9fa;cursor:pointer;display:flex;justify-content:space-between;align-items:center;font-weight:600;transition:all 0.3s ease;user-select:none;gap:15px;">
                <span class="ktv-accordion-head-left" style="display:flex;align-items:center;gap:10px;flex:1;flex-direction:<?php echo $icon_position === 'right' ? 'row-reverse' : 'row'; ?>;justify-content:<?php echo $icon_position === 'right' ? 'flex-end' : 'flex-start'; ?>;">
                    <i class="fas <?php echo esc_attr($item->item_icon ?: 'fa-map-pin'); ?>" style="color:<?php echo esc_attr($item_icon_color); ?>;font-size:<?php echo esc_attr($item_icon_size); ?>;width:20px;text-align:center;flex-shrink:0;" aria-hidden="true"></i>
                    <span style="display:flex;flex-direction:column;gap:2px;">
                        <span style="font-size:<?php echo esc_attr($item_title_size); ?>;color:<?php echo esc_attr($item_title_color); ?>;font-weight:<?php echo esc_attr($item_title_weight); ?>;font-family:<?php echo esc_attr($item_title_font_family); ?>;"><?php echo esc_html($item->item_title); ?></span>
                        <?php if (!empty($item_after_title_text)): ?>
                        <span class="ktv-accordion-after-title" style="font-size:<?php echo esc_attr($after_title_font_size); ?>;color:<?php echo esc_attr($after_title_color); ?>;font-weight:400;line-height:1.3;"><?php echo esc_html($item_after_title_text); ?></span>
                        <?php endif; ?>
                    </span>
                </span>
                <span class="ktv-accordion-icon" style="font-size:20px;font-weight:700;transition:all 0.3s ease;flex-shrink:0;"><?php echo $isOpen ? '−' : '+'; ?></span>
            </div>
            <div class="ktv-accordion-body" data-ktv-protected="1" style="<?php echo $isOpen ? 'display:block;' : 'display:none;'; ?>padding:20px;border-top:1px solid #e0e0e0;background:#fff;line-height:1.7;">
                <div class="ktv-accordion-content" data-ktv-protected="1">
                    <?php echo wp_kses_post($item->item_content); ?>
                </div>
            </div>
        </div>
        <?php endforeach; ?>
        <?php endif; ?>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   39. RENDER — TABS
   ============================================================ */

function ktv_render_block_tabs($attributes) {
    global $wpdb;

    $attributes = is_array($attributes) ? $attributes : array();

    $tabBgColor         = isset($attributes['tabBgColor']) ? $attributes['tabBgColor'] : '#f0f4f8';
    $tabActiveColor     = isset($attributes['tabActiveColor']) ? $attributes['tabActiveColor'] : '#075e54';
    $tabTextColor       = isset($attributes['tabTextColor']) ? $attributes['tabTextColor'] : '#333333';
    $tabActiveTextColor = isset($attributes['tabActiveTextColor']) ? $attributes['tabActiveTextColor'] : '#ffffff';
    $enableActiveTabColor = isset($attributes['enableActiveTabColor']) ? $attributes['enableActiveTabColor'] : true;

    $tabStyle = 'horizontal';
    if (isset($attributes['tabStyle']) && in_array($attributes['tabStyle'], array('horizontal', 'vertical'), true)) {
        $tabStyle = $attributes['tabStyle'];
    }

    $firstOpen          = isset($attributes['firstOpen']) ? $attributes['firstOpen'] : true;
    $autoScroll         = isset($attributes['autoScroll']) ? $attributes['autoScroll'] : true;
    $showTitle          = isset($attributes['showTitle']) ? $attributes['showTitle'] : false;
    $titleText          = isset($attributes['titleText']) ? $attributes['titleText'] : 'Tour Information';
    $titleColor         = isset($attributes['titleColor']) ? $attributes['titleColor'] : '#333333';
    $titleFontSize      = isset($attributes['titleFontSize']) ? $attributes['titleFontSize'] : '24px';
    $titleFontFamily    = isset($attributes['titleFontFamily']) ? $attributes['titleFontFamily'] : 'inherit';
    $titleFontWeight    = isset($attributes['titleFontWeight']) ? $attributes['titleFontWeight'] : '700';
    $pageId             = isset($attributes['pageId']) ? intval($attributes['pageId']) : get_the_ID();
    $tourId             = isset($attributes['tourId']) ? intval($attributes['tourId']) : 0;

    $iconTitle      = isset($attributes['iconTitle']) ? $attributes['iconTitle'] : 'fa-info-circle';
    $iconTitleSize  = isset($attributes['iconTitleSize']) ? $attributes['iconTitleSize'] : '20px';
    $iconTitleColor = isset($attributes['iconTitleColor']) ? $attributes['iconTitleColor'] : '#075e54';
    $showIcon       = !isset($attributes['enableIcon']) || $attributes['enableIcon'] !== false;

    $tabBorderRadius = isset($attributes['tabBorderRadius']) ? $attributes['tabBorderRadius'] : '8px';
    $tabContentBg    = isset($attributes['tabContentBgColor']) ? $attributes['tabContentBgColor'] : '#ffffff';

    $tabsSectionHeadingType = isset($attributes['tabsSectionHeadingType']) ? $attributes['tabsSectionHeadingType'] : 'h2';
    if (!in_array($tabsSectionHeadingType, array('h2', 'h3', 'h4', 'h5', 'h6'), true)) {
        $tabsSectionHeadingType = 'h2';
    }
    $tabsSectionBriefText  = isset($attributes['tabsSectionBriefText']) ? $attributes['tabsSectionBriefText'] : '';
    $tabsSectionBriefSize  = isset($attributes['tabsSectionBriefSize']) ? $attributes['tabsSectionBriefSize'] : '14px';
    $tabsSectionBriefColor = isset($attributes['tabsSectionBriefColor']) ? $attributes['tabsSectionBriefColor'] : '#666666';

    $showDownloadTab = isset($attributes['showDownloadTab']) ? $attributes['showDownloadTab'] : true;
    $showDocxTab     = isset($attributes['showDocxTab']) ? $attributes['showDocxTab'] : true;
    $showTxtTab      = isset($attributes['showTxtTab']) ? $attributes['showTxtTab'] : true;
    $showPrintTab    = isset($attributes['showPrintTab']) ? ($attributes['showPrintTab'] !== false) : true;
    $showViewDocxTab = isset($attributes['showViewDocxTab']) ? (bool) $attributes['showViewDocxTab'] : false;
    $showViewTxtTab  = isset($attributes['showViewTxtTab']) ? (bool) $attributes['showViewTxtTab'] : false;
    $downloadTabLabel = isset($attributes['downloadTabLabel']) && !empty($attributes['downloadTabLabel'])
        ? $attributes['downloadTabLabel']
        : 'Download Tabs';
    $printTabLabel = isset($attributes['printTabLabel']) && !empty($attributes['printTabLabel'])
        ? $attributes['printTabLabel']
        : 'Print';

    $customTabs = isset($attributes['customTabs']) ? $attributes['customTabs'] : array();
    $tabs       = array();

    if (!empty($customTabs) && is_array($customTabs)) {
        foreach ($customTabs as $tab) {
            $tabs[] = (object) array(
                'tab_title'   => isset($tab['title']) ? $tab['title'] : '',
                'tab_after_title_text' => isset($tab['after_title_text']) ? $tab['after_title_text'] : '',
                'tab_content' => isset($tab['content']) ? $tab['content'] : '',
                'tab_icon'    => isset($tab['icon']) ? $tab['icon'] : 'fa-info-circle',
                'tab_icon_size'  => isset($tab['icon_size']) ? $tab['icon_size'] : '16px',
                'tab_icon_color' => isset($tab['icon_color']) ? $tab['icon_color'] : '',
                'tab_icon_font_family' => isset($tab['icon_font_family']) ? $tab['icon_font_family'] : 'inherit',
                'tab_icon_position' => isset($tab['icon_position']) ? $tab['icon_position'] : 'left',
                'tab_title_size'  => isset($tab['title_size']) ? $tab['title_size'] : '14px',
                'tab_title_color' => isset($tab['title_color']) ? $tab['title_color'] : '',
                'tab_title_weight'=> isset($tab['title_weight']) ? $tab['title_weight'] : '600',
                'tab_title_font_family' => isset($tab['title_font_family']) ? $tab['title_font_family'] : 'inherit',
                'tab_after_title_font_size' => isset($tab['after_title_font_size']) ? $tab['after_title_font_size'] : '11px',
                'tab_after_title_color' => isset($tab['after_title_color']) ? $tab['after_title_color'] : '#666666',
                'first_open'  => isset($tab['first_open']) ? $tab['first_open'] : false
            );
        }
    }

    if (empty($tabs)) {
        if ($tourId > 0) {
            $tabs = $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$wpdb->prefix}ktv_tab_items WHERE status = 'active' AND tour_id = %d ORDER BY tab_order ASC",
                $tourId
            ));
        }
        if (empty($tabs) && $pageId > 0) {
            $tabs = $wpdb->get_results($wpdb->prepare(
                "SELECT * FROM {$wpdb->prefix}ktv_tab_items WHERE status = 'active' AND page_id = %d ORDER BY tab_order ASC",
                $pageId
            ));
        }
        if (empty($tabs)) {
            $tabs = $wpdb->get_results(
                "SELECT * FROM {$wpdb->prefix}ktv_tab_items WHERE status = 'active' AND (page_id = 0 OR page_id IS NULL) AND (tour_id = 0 OR tour_id IS NULL) ORDER BY tab_order ASC"
            );
        }
    }

    $wrapperClass = $tabStyle === 'vertical'
        ? 'ktv-tabs-wrapper ktv-tabs-vertical ktv-tabs-style-vertical'
        : 'ktv-tabs-wrapper ktv-tabs-style-horizontal';

    $icon_class_suffix = ktv_icon_visibility_class($attributes);

    $active_color_disabled_attr = $enableActiveTabColor ? 'false' : 'true';

    ob_start();
    ?>
    <?php if ($showTitle): ?>
    <div class="ktv-tabs-section-header" style="text-align:center;margin-bottom:20px;">
        <<?php echo esc_attr($tabsSectionHeadingType); ?> class="ktv-tabs-section-title" style="font-size:<?php echo esc_attr($titleFontSize); ?>;color:<?php echo esc_attr($titleColor); ?>;font-family:<?php echo esc_attr($titleFontFamily); ?>;font-weight:<?php echo esc_attr($titleFontWeight); ?>;margin:0;">
            <?php if ($showIcon): ?><i class="fas <?php echo esc_attr($iconTitle); ?>" style="font-size:<?php echo esc_attr($iconTitleSize); ?>; color:<?php echo esc_attr($iconTitleColor); ?>; margin-right:10px;" aria-hidden="true"></i><?php endif; ?>
            <?php echo esc_html($titleText); ?>
        </<?php echo esc_attr($tabsSectionHeadingType); ?>>
        <?php if (!empty($tabsSectionBriefText)): ?>
        <p class="ktv-tabs-section-brief" style="font-size:<?php echo esc_attr($tabsSectionBriefSize); ?>; color:<?php echo esc_attr($tabsSectionBriefColor); ?>; margin:8px 0 0; line-height:1.5;"><?php echo esc_html($tabsSectionBriefText); ?></p>
        <?php endif; ?>
    </div>
    <?php endif; ?>
    <div class="<?php echo esc_attr($wrapperClass); ?><?php echo esc_attr($icon_class_suffix); ?>" style="margin:30px 0;width:100%;" data-first-open="<?php echo $firstOpen ? 'true' : 'false'; ?>" data-auto-scroll="<?php echo $autoScroll ? 'true' : 'false'; ?>" data-style="<?php echo esc_attr($tabStyle); ?>" data-border-radius="<?php echo esc_attr($tabBorderRadius); ?>" data-content-bg="<?php echo esc_attr($tabContentBg); ?>" data-active-color-disabled="<?php echo esc_attr($active_color_disabled_attr); ?>">
        <?php if (empty($tabs)): ?>
        <div class="ktv-no-tabs" style="text-align:center;padding:30px;background:#f8f9fa;border-radius:12px;color:#666;">
            <i class="fas fa-info-circle" style="font-size:32px;display:block;margin-bottom:10px;"></i>
            No tabs available. Add them in the block editor or WP Admin → KTV Travel → Tabs.
        </div>
        <?php else: ?>
        <div class="ktv-tabs-nav" role="tablist" style="display:flex;gap:8px;flex-wrap:nowrap;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;-ms-overflow-style:none;">
            <?php foreach ($tabs as $index => $tab): ?>
            <?php
                $isActive = ($firstOpen && $index === 0) || (isset($tab->first_open) && $tab->first_open);
                $tab_icon_size = isset($tab->tab_icon_size) && !empty($tab->tab_icon_size) ? $tab->tab_icon_size : '16px';
                $tab_icon_color = isset($tab->tab_icon_color) && !empty($tab->tab_icon_color) ? $tab->tab_icon_color : $iconTitleColor;
                $tab_icon_position = isset($tab->tab_icon_position) && $tab->tab_icon_position === 'right' ? 'right' : 'left';
                $tab_title_size = isset($tab->tab_title_size) && !empty($tab->tab_title_size) ? $tab->tab_title_size : '14px';
                $tab_title_color = isset($tab->tab_title_color) && !empty($tab->tab_title_color) ? $tab->tab_title_color : $tabTextColor;
                $tab_title_weight = isset($tab->tab_title_weight) && !empty($tab->tab_title_weight) ? $tab->tab_title_weight : '600';
                $tab_title_font_family = isset($tab->tab_title_font_family) && !empty($tab->tab_title_font_family) ? $tab->tab_title_font_family : 'inherit';
                $tab_after_title_text = isset($tab->tab_after_title_text) ? $tab->tab_after_title_text : '';
                $tab_after_title_font_size = isset($tab->tab_after_title_font_size) && !empty($tab->tab_after_title_font_size) ? $tab->tab_after_title_font_size : '11px';
                $tab_after_title_color = isset($tab->tab_after_title_color) && !empty($tab->tab_after_title_color) ? $tab->tab_after_title_color : '#666666';
                $active_bg = $enableActiveTabColor ? $tabActiveColor : $tabBgColor;
                $active_text = $enableActiveTabColor ? $tabActiveTextColor : $tab_title_color;
            ?>
            <button class="ktv-tab-btn <?php echo $isActive ? 'active' : ''; ?>" data-tab="<?php echo esc_attr($index); ?>" data-icon-position="<?php echo esc_attr($tab_icon_position); ?>" role="tab" aria-selected="<?php echo $isActive ? 'true' : 'false'; ?>"
                style="background:<?php echo $isActive ? esc_attr($active_bg) : esc_attr($tabBgColor); ?>; color:<?php echo $isActive ? esc_attr($active_text) : esc_attr($tab_title_color); ?>; border:none; padding:12px 28px; border-radius:<?php echo esc_attr($tabBorderRadius); ?> <?php echo esc_attr($tabBorderRadius); ?> 0 0; cursor:pointer; display:flex; align-items:center; gap:8px; flex-direction:<?php echo $tab_icon_position === 'right' ? 'row-reverse' : 'row'; ?>; font-weight:<?php echo esc_attr($tab_title_weight); ?>; font-size:<?php echo esc_attr($tab_title_size); ?>; transition:all 0.3s ease; white-space:nowrap; flex-shrink:0;">
                <i class="fas <?php echo esc_attr($tab->tab_icon); ?>" style="font-size:<?php echo esc_attr($tab_icon_size); ?>;color:<?php echo esc_attr($tab_icon_color); ?>;width:20px;text-align:center;" aria-hidden="true"></i>
                <span style="display:flex;flex-direction:column;gap:2px;font-family:<?php echo esc_attr($tab_title_font_family); ?>;text-align:left;">
                    <span><?php echo esc_html($tab->tab_title); ?></span>
                    <?php if (!empty($tab_after_title_text)): ?>
                    <span class="ktv-tab-after-title" style="font-size:<?php echo esc_attr($tab_after_title_font_size); ?>;color:<?php echo esc_attr($tab_after_title_color); ?>;font-weight:400;line-height:1.2;"><?php echo esc_html($tab_after_title_text); ?></span>
                    <?php endif; ?>
                </span>
            </button>
            <?php endforeach; ?>
        </div>
        <div class="ktv-tabs-content" style="background:<?php echo esc_attr($tabContentBg); ?>;border-radius:0 <?php echo esc_attr($tabBorderRadius); ?> <?php echo esc_attr($tabBorderRadius); ?> <?php echo esc_attr($tabBorderRadius); ?>;overflow:hidden;">
            <?php foreach ($tabs as $index => $tab): ?>
            <?php $isActive = ($firstOpen && $index === 0) || (isset($tab->first_open) && $tab->first_open); ?>
            <div class="ktv-tab-pane <?php echo $isActive ? 'active' : ''; ?>" data-tab="<?php echo esc_attr($index); ?>" role="tabpanel" style="<?php echo $isActive ? 'display:block;' : 'display:none;'; ?>padding:25px;line-height:1.8;">
                <div class="ktv-tab-inner-content" style="line-height:1.8;">
                    <?php echo wp_kses_post($tab->tab_content); ?>
                </div>
                <?php if ($showDownloadTab): ?>
                <div class="ktv-tab-download-bar" style="margin-top:20px;padding-top:15px;border-top:1px solid #eee;display:flex;flex-wrap:wrap;gap:8px;align-items:center;">
                    <?php if ($showDocxTab): ?>
                    <button type="button" class="ktv-tab-download-btn ktv-tab-download-docx" data-tab-index="<?php echo esc_attr($index); ?>" style="display:inline-flex;align-items:center;gap:6px;padding:8px 16px;background:#0073aa;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:13px;font-weight:600;"><i class="fas fa-file-word"></i> DOCX</button>
                    <?php endif; ?>
                    <?php if ($showTxtTab): ?>
                    <button type="button" class="ktv-tab-download-btn ktv-tab-download-txt" data-tab-index="<?php echo esc_attr($index); ?>" style="display:inline-flex;align-items:center;gap:6px;padding:8px 16px;background:#6c757d;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:13px;font-weight:600;"><i class="fas fa-file-alt"></i> TXT</button>
                    <?php endif; ?>
                    <?php if ($showPrintTab): ?>
                    <button type="button" class="ktv-tab-download-btn ktv-tab-print-btn" data-tab-index="<?php echo esc_attr($index); ?>" style="display:inline-flex;align-items:center;gap:6px;padding:8px 16px;background:#075e54;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:13px;font-weight:600;"><i class="fas fa-print"></i> <?php echo esc_html($printTabLabel); ?></button>
                    <?php endif; ?>
                </div>
                <?php endif; ?>
            </div>
            <?php endforeach; ?>
        </div>
        <?php endif; ?>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   40. RENDER — CONTACT FORM
   ============================================================ */

function ktv_render_block_contact_form($attributes) {
    $attributes = is_array($attributes) ? $attributes : array();

    $countries = ktv_get_all_countries();

    $title       = isset($attributes['formTitle']) ? $attributes['formTitle'] : 'Send us a Message';
    $subtitle    = isset($attributes['formSubtitle']) ? $attributes['formSubtitle'] : 'We will reply within 24 hours';
    $btnText     = isset($attributes['btnText']) ? $attributes['btnText'] : 'Send Message';
    $buttonColor = isset($attributes['buttonColor']) ? $attributes['buttonColor'] : '#075e54';
    $buttonTextColor = isset($attributes['buttonTextColor']) ? $attributes['buttonTextColor'] : '#ffffff';
    $arrivalLabel = isset($attributes['arrivalLabel']) ? $attributes['arrivalLabel'] : 'Arrival Date';
    $departureLabel = isset($attributes['departureLabel']) ? $attributes['departureLabel'] : 'Departure Date';
    $nameLabel   = isset($attributes['nameLabel']) ? $attributes['nameLabel'] : 'Full Name';
    $emailLabel  = isset($attributes['emailLabel']) ? $attributes['emailLabel'] : 'Email Address';
    $phoneLabel  = isset($attributes['phoneLabel']) ? $attributes['phoneLabel'] : 'Phone Number';
    $countryLabel = isset($attributes['countryLabel']) ? $attributes['countryLabel'] : 'Country';
    $messageLabel = isset($attributes['messageLabel']) ? $attributes['messageLabel'] : 'Your Message';

    $formWidth    = isset($attributes['formWidth']) ? $attributes['formWidth'] : 'full';
    $formBgColor  = isset($attributes['formBgColor']) ? $attributes['formBgColor'] : '#ffffff';
    $formTextColor = isset($attributes['formTextColor']) ? $attributes['formTextColor'] : '#333333';
    $formHeadingSize = isset($attributes['formHeadingSize']) ? $attributes['formHeadingSize'] : '24px';
    $formHeadingColor = isset($attributes['formHeadingColor']) ? $attributes['formHeadingColor'] : '#333333';
    $borderColor  = isset($attributes['borderColor']) ? $attributes['borderColor'] : '#e0e0e0';
    $borderSize   = isset($attributes['borderSize']) ? $attributes['borderSize'] : '1px';
    $borderRadius = isset($attributes['borderRadius']) ? $attributes['borderRadius'] : '12px';

    $iconTitle      = isset($attributes['iconTitle']) ? $attributes['iconTitle'] : 'fa-envelope-open-text';
    $iconTitleSize  = isset($attributes['iconTitleSize']) ? $attributes['iconTitleSize'] : '24px';
    $iconTitleColor = isset($attributes['iconTitleColor']) ? $attributes['iconTitleColor'] : '#075e54';
    $showIcon       = !isset($attributes['enableIcon']) || $attributes['enableIcon'] !== false;

    $default_arrival   = isset($attributes['defaultArrivalDate']) && !empty($attributes['defaultArrivalDate'])
        ? $attributes['defaultArrivalDate']
        : wp_date('Y-m-d', strtotime('+1 day'));
    $default_departure = isset($attributes['defaultDepartureDate']) && !empty($attributes['defaultDepartureDate'])
        ? $attributes['defaultDepartureDate']
        : wp_date('Y-m-d', strtotime('+3 days'));

    $travelDateColor      = isset($attributes['travelDateColor']) ? $attributes['travelDateColor'] : '#333333';
    $travelDateFontSize   = isset($attributes['travelDateFontSize']) ? $attributes['travelDateFontSize'] : '16px';
    $travelDateFontWeight = isset($attributes['travelDateFontWeight']) ? $attributes['travelDateFontWeight'] : '600';
    $travelDateBgColor    = isset($attributes['travelDateBgColor']) ? $attributes['travelDateBgColor'] : '#f8f9fa';

    $placeholderColor    = isset($attributes['placeholderColor']) ? $attributes['placeholderColor'] : '#767676';
    $placeholderFontSize = isset($attributes['placeholderFontSize']) ? $attributes['placeholderFontSize'] : '14px';
    $placeholderFontWeight = isset($attributes['placeholderFontWeight']) ? $attributes['placeholderFontWeight'] : '400';

    $widthClass = $formWidth === 'compact' ? 'ktv-form-compact' : ($formWidth === 'wide' ? 'ktv-form-wide' : 'ktv-form-full');
    $custom_sections = isset($attributes['customSections']) && is_array($attributes['customSections']) ? $attributes['customSections'] : array();
    $icon_class_suffix = ktv_icon_visibility_class($attributes);

    $icon_defaults_map = ktv_get_contact_form_icon_defaults();
    $FI = ktv_resolve_all_field_icons($attributes, $icon_defaults_map);

    $mandatory = ktv_get_mandatory_fields($attributes, 'contact');

    $render_icon = function ($key) use ($FI) {
        if (!isset($FI[$key])) return '';
        $i = $FI[$key];
        $prefix = 'fas';
        if ($i['icon'] === 'fa-google-pay') {
            $prefix = 'fab';
        }
        return '<i class="' . $prefix . ' ' . esc_attr($i['icon']) . '" style="font-size:' . esc_attr($i['size']) . '; color:' . esc_attr($i['color']) . ';" aria-hidden="true"></i>';
    };

    $req_attr = function ($field_key) use ($mandatory) {
        return !empty($mandatory[$field_key]) ? ' required' : '';
    };
    $req_star = function ($field_key) use ($mandatory) {
        return !empty($mandatory[$field_key]) ? ' *' : '';
    };

    $placeholder_style = '--ktv-placeholder-color:' . esc_attr($placeholderColor) . ';--ktv-placeholder-size:' . esc_attr($placeholderFontSize) . ';--ktv-placeholder-weight:' . esc_attr($placeholderFontWeight) . ';';
    $theme_style = $placeholder_style
        . '--ktv-cf-submit-bg:' . esc_attr($buttonColor) . ';'
        . '--ktv-cf-submit-text:' . esc_attr($buttonTextColor) . ';';

    ob_start();
    ?>
    <div class="ktv-contact-modern <?php echo esc_attr($widthClass); ?><?php echo esc_attr($icon_class_suffix); ?>" style="<?php echo esc_attr($theme_style); ?>background:<?php echo esc_attr($formBgColor); ?>; border:<?php echo esc_attr($borderSize); ?> solid <?php echo esc_attr($borderColor); ?>; border-radius:<?php echo esc_attr($borderRadius); ?>;">
        <div class="ktv-contact-header" style="text-align:center;margin-bottom:30px;">
            <h3 style="font-size:<?php echo esc_attr($formHeadingSize); ?>; color:<?php echo esc_attr($formHeadingColor); ?>;">
                <?php if ($showIcon): ?><i class="fas <?php echo esc_attr($iconTitle); ?>" style="font-size:<?php echo esc_attr($iconTitleSize); ?>; color:<?php echo esc_attr($iconTitleColor); ?>; margin-right:10px;" aria-hidden="true"></i><?php endif; ?>
                <?php echo esc_html($title); ?>
            </h3>
            <p style="color:<?php echo esc_attr($formTextColor); ?>;"><?php echo esc_html($subtitle); ?></p>
        </div>
        <form id="ktv-contact-form" method="post">
            <input type="hidden" name="action" value="ktv_send_contact">
            <input type="hidden" name="nonce" value="<?php echo wp_create_nonce('ktv_travel_nonce'); ?>">
            <?php echo ktv_render_honeypot_field(); ?>

            <div class="ktv-form-row ktv-dates-row" style="display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-bottom:15px;">
                <div class="ktv-input-group" style="display:flex;align-items:center;gap:12px;background:<?php echo esc_attr($travelDateBgColor); ?>;border-radius:12px;padding:0 15px;border:2px solid transparent;transition:all 0.3s ease;">
                    <?php echo $render_icon('arrivalIcon'); ?>
                    <label for="ktv-contact-arrival" class="ktv-sr-only"><?php echo esc_html($arrivalLabel); ?></label>
                    <input type="text" id="ktv-contact-arrival" name="arrival_date" class="ktv-datepicker" value="<?php echo esc_attr($default_arrival); ?>" placeholder="<?php echo esc_attr($arrivalLabel); ?><?php echo $req_star('arrival_date'); ?>"<?php echo $req_attr('arrival_date'); ?> autocomplete="off" aria-label="<?php echo esc_attr($arrivalLabel); ?>" style="width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:<?php echo esc_attr($travelDateFontSize); ?>;color:<?php echo esc_attr($travelDateColor); ?>;font-weight:<?php echo esc_attr($travelDateFontWeight); ?>;">
                </div>
                <div class="ktv-input-group" style="display:flex;align-items:center;gap:12px;background:<?php echo esc_attr($travelDateBgColor); ?>;border-radius:12px;padding:0 15px;border:2px solid transparent;transition:all 0.3s ease;">
                    <?php echo $render_icon('departureIcon'); ?>
                    <label for="ktv-contact-departure" class="ktv-sr-only"><?php echo esc_html($departureLabel); ?></label>
                    <input type="text" id="ktv-contact-departure" name="departure_date" class="ktv-datepicker" value="<?php echo esc_attr($default_departure); ?>" placeholder="<?php echo esc_attr($departureLabel); ?><?php echo $req_star('departure_date'); ?>"<?php echo $req_attr('departure_date'); ?> autocomplete="off" aria-label="<?php echo esc_attr($departureLabel); ?>" style="width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:<?php echo esc_attr($travelDateFontSize); ?>;color:<?php echo esc_attr($travelDateColor); ?>;font-weight:<?php echo esc_attr($travelDateFontWeight); ?>;">
                </div>
            </div>

            <div class="ktv-form-row" style="display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-bottom:15px;">
                <div class="ktv-input-group" style="display:flex;align-items:center;gap:12px;background:#f8f9fa;border-radius:12px;padding:0 15px;border:2px solid transparent;transition:all 0.3s ease;">
                    <?php echo $render_icon('nameIcon'); ?>
                    <label for="ktv-contact-name" class="ktv-sr-only"><?php echo esc_html($nameLabel); ?></label>
                    <input type="text" id="ktv-contact-name" name="name" placeholder="<?php echo esc_attr($nameLabel); ?><?php echo $req_star('name'); ?>"<?php echo $req_attr('name'); ?> aria-label="<?php echo esc_attr($nameLabel); ?>" style="width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:16px;color:<?php echo esc_attr($formTextColor); ?>;font-weight:600;">
                </div>
                <div class="ktv-input-group" style="display:flex;align-items:center;gap:12px;background:#f8f9fa;border-radius:12px;padding:0 15px;border:2px solid transparent;transition:all 0.3s ease;">
                    <?php echo $render_icon('emailIcon'); ?>
                    <label for="ktv-contact-email" class="ktv-sr-only"><?php echo esc_html($emailLabel); ?></label>
                    <input type="email" id="ktv-contact-email" name="email" placeholder="<?php echo esc_attr($emailLabel); ?><?php echo $req_star('email'); ?>"<?php echo $req_attr('email'); ?> aria-label="<?php echo esc_attr($emailLabel); ?>" style="width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:16px;color:<?php echo esc_attr($formTextColor); ?>;font-weight:600;">
                </div>
            </div>

            <div class="ktv-phone-group" style="display:flex;align-items:center;gap:6px;background:#f8f9fa;border-radius:12px;padding:0 12px;border:2px solid transparent;transition:all 0.3s ease;direction:ltr;text-align:left;width:100%;margin-bottom:15px;">
                <?php
                $phone_icon_data = $FI['phoneIcon'];
                $phone_prefix = ($phone_icon_data['icon'] === 'fa-google-pay') ? 'fab' : 'fas';
                ?>
                <i class="<?php echo $phone_prefix; ?> <?php echo esc_attr($phone_icon_data['icon']); ?>" style="font-size:<?php echo esc_attr($phone_icon_data['size']); ?>;color:<?php echo esc_attr($phone_icon_data['color']); ?>;flex-shrink:0;pointer-events:none;transform:scaleX(-1);display:inline-block;" aria-hidden="true"></i>
                <label for="ktv-contact-phone-code" class="ktv-sr-only">Phone country code</label>
                <select id="ktv-contact-phone-code" name="phone_code" aria-label="Phone country code" style="width:auto;min-width:85px;max-width:110px;padding:14px 4px;border:none;background:transparent;outline:none;flex-shrink:0;font-size:13px;cursor:pointer;appearance:none;font-weight:600;color:#333;">
                    <?php foreach ($countries as $c): ?>
                    <option value="<?php echo esc_attr($c['code']); ?>" <?php echo $c['code'] == '+91' ? 'selected' : ''; ?>><?php echo esc_html($c['flag'] . ' ' . $c['code']); ?></option>
                    <?php endforeach; ?>
                </select>
                <label for="ktv-contact-phone" class="ktv-sr-only"><?php echo esc_html($phoneLabel); ?></label>
                <input type="tel" id="ktv-contact-phone" name="phone" placeholder="<?php echo esc_attr($phoneLabel); ?><?php echo $req_star('phone'); ?>"<?php echo $req_attr('phone'); ?> aria-label="<?php echo esc_attr($phoneLabel); ?>" style="flex:1;min-width:200px;width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:16px;direction:ltr;text-align:left;cursor:text;font-weight:600;color:#333;">
            </div>

            <div class="ktv-input-group" style="display:flex;align-items:center;gap:12px;background:#f8f9fa;border-radius:12px;padding:0 15px;border:2px solid transparent;transition:all 0.3s ease;width:100%;margin-bottom:15px;">
                <?php echo $render_icon('countryIcon'); ?>
                <label for="ktv-contact-country" class="ktv-sr-only"><?php echo esc_html($countryLabel); ?></label>
                <select name="country" id="ktv-contact-country" aria-label="<?php echo esc_attr($countryLabel); ?>" style="width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:16px;cursor:pointer;appearance:none;font-weight:600;color:#333;">
                    <option value=""><?php echo esc_html($countryLabel); ?></option>
                    <?php foreach ($countries as $c): ?>
                    <option value="<?php echo esc_attr($c['name']); ?>"><?php echo esc_html($c['flag'] . ' ' . $c['name']); ?></option>
                    <?php endforeach; ?>
                </select>
            </div>

            <?php if (!empty($custom_sections)): ?>
            <?php foreach ($custom_sections as $section): ?>
                <?php
                if (isset($section['enabled']) && $section['enabled'] === false) {
                    continue;
                }
                $sec_key = isset($section['key']) ? sanitize_key($section['key']) : '';
                $sec_label = isset($section['label']) ? $section['label'] : '';
                $sec_icon = isset($section['icon']) ? $section['icon'] : 'fa-star';
                $sec_icon_color = isset($section['iconColor']) ? $section['iconColor'] : '#075e54';
                $sec_icon_size = isset($section['iconSize']) ? $section['iconSize'] : '16px';
                $sec_placeholder = isset($section['placeholder']) ? $section['placeholder'] : $sec_label;
                $sec_required = isset($section['required']) ? $section['required'] : false;
                $sec_type = isset($section['fieldType']) ? $section['fieldType'] : 'text';
                if (empty($sec_key) || empty($sec_label)) {
                    continue;
                }
                $sec_field_id = 'ktv-contact-custom-' . $sec_key;
                ?>
            <div class="ktv-input-group" style="display:flex;align-items:center;gap:12px;background:#f8f9fa;border-radius:12px;padding:0 15px;border:2px solid transparent;transition:all 0.3s ease;width:100%;margin-bottom:15px;">
                <i class="fas <?php echo esc_attr($sec_icon); ?>" style="color:<?php echo esc_attr($sec_icon_color); ?>;flex-shrink:0;font-size:<?php echo esc_attr($sec_icon_size); ?>;pointer-events:none;" aria-hidden="true"></i>
                <label for="<?php echo esc_attr($sec_field_id); ?>" class="ktv-sr-only"><?php echo esc_html($sec_label); ?></label>
                <?php if ($sec_type === 'textarea'): ?>
                <textarea id="<?php echo esc_attr($sec_field_id); ?>" name="custom_<?php echo esc_attr($sec_key); ?>" rows="3" placeholder="<?php echo esc_attr($sec_placeholder); ?><?php echo $sec_required ? ' *' : ''; ?>" aria-label="<?php echo esc_attr($sec_label); ?>" <?php echo $sec_required ? 'required data-required="1"' : ''; ?> style="width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:16px;color:<?php echo esc_attr($formTextColor); ?>;font-weight:600;resize:vertical;"></textarea>
                <?php else: ?>
                <input type="<?php echo esc_attr($sec_type); ?>" id="<?php echo esc_attr($sec_field_id); ?>" name="custom_<?php echo esc_attr($sec_key); ?>" placeholder="<?php echo esc_attr($sec_placeholder); ?><?php echo $sec_required ? ' *' : ''; ?>" aria-label="<?php echo esc_attr($sec_label); ?>" <?php echo $sec_required ? 'required data-required="1"' : ''; ?> style="width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:16px;color:<?php echo esc_attr($formTextColor); ?>;font-weight:600;">
                <?php endif; ?>
            </div>
            <?php endforeach; ?>
            <?php endif; ?>

            <div class="ktv-input-group" style="display:flex;align-items:flex-start;gap:12px;background:#f8f9fa;border-radius:12px;padding:0 15px;border:2px solid transparent;transition:all 0.3s ease;margin-bottom:15px;">
                <span style="margin-top:14px;">
                    <?php echo $render_icon('messageIcon'); ?>
                </span>
                <label for="ktv-contact-message" class="ktv-sr-only"><?php echo esc_html($messageLabel); ?></label>
                <textarea id="ktv-contact-message" name="message" rows="4" placeholder="<?php echo esc_attr($messageLabel); ?><?php echo $req_star('message'); ?>"<?php echo $req_attr('message'); ?> aria-label="<?php echo esc_attr($messageLabel); ?>" style="width:100%;padding:14px 0;border:none;background:transparent;outline:none;font-size:16px;resize:vertical;min-height:80px;color:<?php echo esc_attr($formTextColor); ?>;font-weight:600;"></textarea>
            </div>

            <button type="submit" class="ktv-submit-btn" style="width:100%; padding:14px; border:none; border-radius:30px; cursor:pointer; font-size:16px; font-weight:600; transition:all 0.3s ease; display:flex; align-items:center; justify-content:center; gap:8px;">
                <?php echo esc_html($btnText); ?> <?php echo $render_icon('submitIcon'); ?>
            </button>

            <div class="ktv-message" style="margin-top:15px;padding:0;border-radius:8px;text-align:center;font-size:14px;display:none;"></div>
        </form>
    </div>
    <?php
    return ob_get_clean();
}

/* ============================================================
   41. RENDER — IMAGE BADGE
   ============================================================ */

function ktv_render_block_image_badge($attributes) {
    $attributes = is_array($attributes) ? $attributes : array();

    $imageId          = isset($attributes['imageId']) ? intval($attributes['imageId']) : 0;
    $imageDisplaySize = isset($attributes['imageDisplaySize']) ? $attributes['imageDisplaySize'] : 'large';
    $imageUrl         = $imageId ? wp_get_attachment_image_url($imageId, $imageDisplaySize) : '';
    if (!$imageUrl && $imageId) {
        $imageUrl = wp_get_attachment_url($imageId);
    }
    $imageLink   = isset($attributes['imageLink']) ? $attributes['imageLink'] : '';

    $leftBadge   = isset($attributes['leftBadge']) ? $attributes['leftBadge'] : '';
    $leftBg      = isset($attributes['leftBg']) ? $attributes['leftBg'] : '#075e54';
    $leftIcon    = isset($attributes['leftIcon']) ? $attributes['leftIcon'] : 'fa-star';
    $rightBadge  = isset($attributes['rightBadge']) ? $attributes['rightBadge'] : '';
    $rightBg     = isset($attributes['rightBg']) ? $attributes['rightBg'] : '#ff5722';
    $rightIcon   = isset($attributes['rightIcon']) ? $attributes['rightIcon'] : 'fa-clock';

    $badgeText       = isset($attributes['badgeText']) ? $attributes['badgeText'] : '';
    $badgeColor      = isset($attributes['badgeColor']) ? $attributes['badgeColor'] : '#ff5722';
    $badgeTextColor  = isset($attributes['badgeTextColor']) ? $attributes['badgeTextColor'] : '#ffffff';
    $badgeStyle      = isset($attributes['badgeStyle']) ? $attributes['badgeStyle'] : 'pill';
    $badgePosition   = isset($attributes['badgePosition']) ? $attributes['badgePosition'] : 'top-left';

    $nights      = isset($attributes['nights']) ? $attributes['nights'] : '';
    $days        = isset($attributes['days']) ? $attributes['days'] : '';
    $nightsDaysIcon      = isset($attributes['nightsDaysIcon']) ? $attributes['nightsDaysIcon'] : 'fa-moon';
    $nightsDaysIconColor = isset($attributes['nightsDaysIconColor']) ? $attributes['nightsDaysIconColor'] : '#FFD700';
    $nightsDaysIconSize  = isset($attributes['nightsDaysIconSize']) ? $attributes['nightsDaysIconSize'] : '14px';
    $nightsDaysPosition  = isset($attributes['nightsDaysPosition']) ? $attributes['nightsDaysPosition'] : 'bottom-left';

    $buttonText  = isset($attributes['buttonText']) ? $attributes['buttonText'] : 'Book Now';
    $buttonUrl   = isset($attributes['buttonUrl']) ? $attributes['buttonUrl'] : '#';
    $buttonColor = isset($attributes['buttonColor']) ? $attributes['buttonColor'] : '#ff5722';
    $bookNowTextColor = isset($attributes['bookNowTextColor']) ? $attributes['bookNowTextColor'] : '#ffffff';
    $enableBookNow    = isset($attributes['enableBookNow']) ? $attributes['enableBookNow'] : true;
    $bookNowPosition  = isset($attributes['bookNowPosition']) ? $attributes['bookNowPosition'] : 'bottom-center';

    $showBadge   = isset($attributes['showBadge']) ? $attributes['showBadge'] : true;
    $showWishlist = isset($attributes['showWishlist']) ? $attributes['showWishlist'] : false;
    $wishlistPosition = isset($attributes['wishlistPosition']) ? $attributes['wishlistPosition'] : 'top-right';

    $tourId   = isset($attributes['tourId']) ? intval($attributes['tourId']) : 0;
    $tourName = isset($attributes['tourName']) ? $attributes['tourName'] : $leftBadge;

    $icon_class_suffix = ktv_icon_visibility_class($attributes);

    $badge_shape_style = '';
    if ($badgeStyle === 'pill') {
        $badge_shape_style = 'border-radius:25px;';
    } elseif ($badgeStyle === 'square') {
        $badge_shape_style = 'border-radius:4px;';
    } elseif ($badgeStyle === 'oval') {
        $badge_shape_style = 'border-radius:50%/40%;';
    } elseif ($badgeStyle === 'round') {
        $badge_shape_style = 'border-radius:50%;padding:14px;';
    } else {
        $badge_shape_style = 'border-radius:25px;';
    }

    $badge_pos_map = array(
        'top-left'     => 'top:12px;left:12px;right:auto;bottom:auto;',
        'top-right'    => 'top:12px;right:12px;left:auto;bottom:auto;',
        'bottom-left'  => 'bottom:12px;left:12px;top:auto;right:auto;',
        'bottom-right' => 'bottom:12px;right:12px;top:auto;left:auto;'
    );
    $badge_pos_style = isset($badge_pos_map[$badgePosition]) ? $badge_pos_map[$badgePosition] : $badge_pos_map['top-left'];

    $nightsdays_pos_map = array(
        'top-left'     => 'top:12px;left:12px;right:auto;bottom:auto;',
        'top-right'    => 'top:12px;right:12px;left:auto;bottom:auto;',
        'bottom-left'  => 'bottom:12px;left:12px;top:auto;right:auto;',
        'bottom-right' => 'bottom:12px;right:12px;top:auto;left:auto;'
    );
    $nightsdays_pos_style = isset($nightsdays_pos_map[$nightsDaysPosition]) ? $nightsdays_pos_map[$nightsDaysPosition] : $nightsdays_pos_map['bottom-left'];

    $booknow_pos_map = array(
        'top-left'      => 'top:20px;left:20px;transform:none;',
        'top-right'     => 'top:20px;right:20px;left:auto;transform:none;',
        'bottom-left'   => 'bottom:20px;left:20px;transform:none;',
        'bottom-right'  => 'bottom:20px;right:20px;left:auto;transform:none;',
        'center'        => 'top:50%;left:50%;transform:translate(-50%,-50%);',
        'bottom-center' => 'bottom:20px;left:50%;transform:translateX(-50%);'
    );
    $booknow_pos_style = isset($booknow_pos_map[$bookNowPosition]) ? $booknow_pos_map[$bookNowPosition] : $booknow_pos_map['bottom-center'];

    $wishlist_pos_map = array(
        'top-left'     => 'top:12px;left:12px;right:auto;bottom:auto;',
        'top-right'    => 'top:12px;right:12px;left:auto;bottom:auto;',
        'bottom-left'  => 'bottom:12px;left:12px;top:auto;right:auto;',
        'bottom-right' => 'bottom:12px;right:12px;top:auto;left:auto;'
    );
    $wishlist_pos_style = isset($wishlist_pos_map[$wishlistPosition]) ? $wishlist_pos_map[$wishlistPosition] : $wishlist_pos_map['top-right'];

    $wishlist_count = 0;
    $in_wishlist = 0;
    if ($showWishlist && $tourId > 0) {
        global $wpdb;
        $user_ip = ktv_get_client_ip();
        $wishlist_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$wpdb->prefix}ktv_wishlist WHERE tour_id = %d",
            $tourId
        ));
        if (!empty($user_ip)) {
            $in_wishlist = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$wpdb->prefix}ktv_wishlist WHERE tour_id = %d AND user_ip = %s",
                $tourId, $user_ip
            ));
        }
    }

    $currency_sym = ktv_get_currency_symbol();

    $badge_pax_data_attrs = ' data-pax1="' . esc_attr(isset($attributes['pax1Price']) ? floatval($attributes['pax1Price']) : 0) . '"'
        . ' data-pax2="' . esc_attr(isset($attributes['pax2Price']) ? floatval($attributes['pax2Price']) : 0) . '"'
        . ' data-pax3="' . esc_attr(isset($attributes['pax3Price']) ? floatval($attributes['pax3Price']) : 0) . '"'
        . ' data-group="' . esc_attr(isset($attributes['groupPrice']) ? floatval($attributes['groupPrice']) : 0) . '"'
        . ' data-family="' . esc_attr(isset($attributes['familyPrice']) ? floatval($attributes['familyPrice']) : 0) . '"'
        . ' data-extra-adult="' . esc_attr(isset($attributes['extraAdultPrice']) ? floatval($attributes['extraAdultPrice']) : 0) . '"'
        . ' data-extra-child="' . esc_attr(isset($attributes['extraChildPrice']) ? floatval($attributes['extraChildPrice']) : 0) . '"'
        . ' data-visible-pax-columns="' . esc_attr(isset($attributes['visiblePaxColumns']) ? $attributes['visiblePaxColumns'] : 'pax1') . '"'
        . ' data-tour-nights="' . esc_attr($nights) . '"'
        . ' data-tour-days="' . esc_attr($days) . '"'
        . ' data-tour-icon="fa-map-marker-alt"'
        . ' data-tour-icon-size="14px"'
        . ' data-tour-icon-color="#075e54"'
        . ' data-currency-symbol="' . esc_attr($currency_sym) . '"'
        . ' data-enable-icon-dropdown="1"';

    ob_start();
    ?>
    <div class="ktv-image-badge-wrapper<?php echo esc_attr($icon_class_suffix); ?>" style="position:relative;border-radius:20px;overflow:hidden;margin:30px 0;box-shadow:0 10px 40px rgba(0,0,0,0.08);width:100%;">
        <?php if ($imageUrl): ?>
            <?php if (!empty($imageLink) && $imageLink !== '#'): ?>
            <a href="<?php echo esc_url($imageLink); ?>" target="_blank" class="ktv-tour-image-link" title="<?php echo esc_attr($leftBadge); ?>" style="display:block;text-decoration:none;position:relative;">
                <?php
                echo ktv_render_image_tag(
                    $imageId,
                    $imageDisplaySize,
                    $leftBadge,
                    '',
                    array('style' => 'width:100%;display:block;'),
                    $imageUrl,
                    true
                );
                ?>
            </a>
            <?php else: ?>
            <?php
            echo ktv_render_image_tag(
                $imageId,
                $imageDisplaySize,
                $leftBadge,
                '',
                array('style' => 'width:100%;display:block;'),
                $imageUrl,
                true
            );
            ?>
            <?php endif; ?>
        <?php else: ?>
        <div class="ktv-image-placeholder" style="display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:250px;background:#f0f0f0;color:#999;gap:10px;border-radius:20px;width:100%;"><i class="fas fa-image fa-3x"></i><span>Select Image</span></div>
        <?php endif; ?>

        <?php if ($showBadge && $leftBadge): ?>
        <div class="ktv-tour-badge ktv-badge-left" style="position:absolute;<?php echo esc_attr($badge_pos_style); ?>padding:6px 14px;<?php echo esc_attr($badge_shape_style); ?>font-size:12px;font-weight:600;color:#fff;z-index:10;display:flex;align-items:center;gap:5px;background:<?php echo esc_attr($leftBg); ?>;"><i class="fas <?php echo esc_attr($leftIcon); ?>" style="font-size:11px;" aria-hidden="true"></i> <?php echo esc_html($leftBadge); ?></div>
        <?php endif; ?>
        <?php if ($showBadge && $rightBadge): ?>
        <div class="ktv-tour-badge ktv-badge-right" style="position:absolute;top:12px;right:12px;left:auto;bottom:auto;padding:6px 14px;border-radius:25px;font-size:12px;font-weight:600;color:#fff;z-index:10;display:flex;align-items:center;gap:5px;background:<?php echo esc_attr($rightBg); ?>;"><i class="fas <?php echo esc_attr($rightIcon); ?>" style="font-size:11px;" aria-hidden="true"></i> <?php echo esc_html($rightBadge); ?></div>
        <?php endif; ?>

        <?php if ($showBadge && !empty($badgeText)): ?>
        <div class="ktv-image-badge-text" data-position="<?php echo esc_attr($badgePosition); ?>" style="position:absolute;<?php echo esc_attr($badge_pos_style); ?>padding:6px 16px;<?php echo esc_attr($badge_shape_style); ?>font-size:12px;font-weight:700;background:<?php echo esc_attr($badgeColor); ?>;color:<?php echo esc_attr($badgeTextColor); ?>;z-index:15;letter-spacing:0.5px;"><?php echo esc_html($badgeText); ?></div>
        <?php endif; ?>

        <?php if ($nights || $days): ?>
        <div class="ktv-image-badge-nightsdays" data-position="<?php echo esc_attr($nightsDaysPosition); ?>" style="position:absolute;<?php echo esc_attr($nightsdays_pos_style); ?>background:rgba(0,0,0,0.7);color:#fff;padding:6px 14px;border-radius:25px;font-size:13px;display:flex;gap:8px;align-items:center;z-index:10;">
            <?php if ($nights): ?><i class="fas <?php echo esc_attr($nightsDaysIcon); ?>" style="font-size:<?php echo esc_attr($nightsDaysIconSize); ?>;color:<?php echo esc_attr($nightsDaysIconColor); ?> !important;" aria-hidden="true"></i> <?php echo esc_html($nights); ?>N<?php endif; ?>
            <?php if ($days): ?><i class="fas fa-sun" style="color:<?php echo esc_attr(isset($attributes['dayIconColor']) && !empty($attributes['dayIconColor']) ? $attributes['dayIconColor'] : '#FFA500'); ?> !important;" aria-hidden="true"></i> <?php echo esc_html($days); ?>D<?php endif; ?>
        </div>
        <?php endif; ?>

        <?php if ($showWishlist): ?>
        <button class="ktv-wishlist-btn ktv-image-badge-wishlist<?php echo $in_wishlist > 0 ? ' active' : ''; ?>" data-tour-id="<?php echo esc_attr($tourId); ?>" data-tour-name="<?php echo esc_attr($tourName); ?>" data-in-wishlist="<?php echo esc_attr($in_wishlist > 0 ? 1 : 0); ?>" title="Add to Wishlist" style="position:absolute;<?php echo esc_attr($wishlist_pos_style); ?>background:rgba(255,255,255,0.9);border:none;width:auto;min-width:36px;height:36px;border-radius:25px;cursor:pointer;z-index:20;color:#ff4757;display:flex;align-items:center;justify-content:center;gap:5px;transition:all 0.3s ease;font-size:14px;padding:0 12px;"><i class="<?php echo $in_wishlist > 0 ? 'fas' : 'far'; ?> fa-heart"></i> <span class="ktv-wishlist-count" style="display:inline;font-size:11px;font-weight:700;color:#ff4757;background:rgba(255,71,87,0.1);padding:2px 6px;border-radius:10px;min-width:18px;text-align:center;"><?php echo esc_html($wishlist_count); ?></span></button>
        <?php endif; ?>

        <?php if ($enableBookNow && $buttonText): ?>
        <?php if (!empty($buttonUrl) && $buttonUrl !== '#'): ?>
        <a href="<?php echo esc_url($buttonUrl); ?>" class="ktv-book-now-btn" title="<?php echo esc_attr($buttonText); ?>" style="--ktv-btn-bg:<?php echo esc_attr($buttonColor); ?>;--ktv-btn-text:<?php echo esc_attr($bookNowTextColor); ?>;position:absolute;<?php echo esc_attr($booknow_pos_style); ?>background:var(--ktv-btn-bg);color:var(--ktv-btn-text);border:none;padding:12px 30px;border-radius:30px;font-size:16px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:10px;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);text-decoration:none;z-index:10;overflow:hidden;"<?php echo $badge_pax_data_attrs; ?>><?php echo esc_html($buttonText); ?> <i class="fas fa-arrow-right"></i></a>
        <?php else: ?>
        <button class="ktv-book-now-btn" title="<?php echo esc_attr($buttonText); ?>" style="--ktv-btn-bg:<?php echo esc_attr($buttonColor); ?>;--ktv-btn-text:<?php echo esc_attr($bookNowTextColor); ?>;position:absolute;<?php echo esc_attr($booknow_pos_style); ?>background:var(--ktv-btn-bg);color:var(--ktv-btn-text);border:none;padding:12px 30px;border-radius:30px;font-size:16px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:10px;transition:all 0.3s cubic-bezier(0.4,0,0.2,1);text-decoration:none;z-index:10;overflow:hidden;" data-tour-id="<?php echo esc_attr($tourId); ?>" data-tour-name="<?php echo esc_attr($tourName); ?>" data-tour-location=""<?php echo $badge_pax_data_attrs; ?>><?php echo esc_html($buttonText); ?> <i class="fas fa-arrow-right"></i></button>
        <?php endif; ?>
        <?php endif; ?>
    </div>
    <?php
    return ob_get_clean();
}
/* ============================================================
   42. DATABASE SAFE HELPERS
   ============================================================ */

function ktv_db_get_columns($table) {
    global $wpdb;
    static $cache = array();
    if (isset($cache[$table])) {
        return $cache[$table];
    }
    $cols = $wpdb->get_col("SHOW COLUMNS FROM {$table}");
    $cache[$table] = is_array($cols) ? $cols : array();
    return $cache[$table];
}

function ktv_db_has_column($table, $column) {
    $cols = ktv_db_get_columns($table);
    return in_array($column, $cols, true);
}

function ktv_db_insert_safe($table, $data) {
    global $wpdb;

    if (empty($table) || !is_array($data) || empty($data)) {
        return false;
    }

    $existing = ktv_db_get_columns($table);
    if (empty($existing)) {
        return false;
    }

    $safe = array();
    foreach ($data as $col => $val) {
        if (in_array($col, $existing, true)) {
            $safe[$col] = $val;
        }
    }

    if (empty($safe)) {
        return false;
    }

    return $wpdb->insert($table, $safe);
}

function ktv_db_update_safe($table, $data, $where) {
    global $wpdb;

    if (empty($table) || !is_array($data) || empty($data) || !is_array($where) || empty($where)) {
        return false;
    }

    $existing = ktv_db_get_columns($table);
    if (empty($existing)) {
        return false;
    }

    $safe = array();
    foreach ($data as $col => $val) {
        if (in_array($col, $existing, true)) {
            $safe[$col] = $val;
        }
    }

    if (empty($safe)) {
        return false;
    }

    return $wpdb->update($table, $safe, $where);
}

function ktv_db_filter_columns($table, $data) {
    if (!is_array($data) || empty($data)) {
        return array();
    }
    $existing = ktv_db_get_columns($table);
    if (empty($existing)) {
        return array();
    }
    $safe = array();
    foreach ($data as $col => $val) {
        if (in_array($col, $existing, true)) {
            $safe[$col] = $val;
        }
    }
    return $safe;
}

/* ============================================================
   43. AJAX — SUBMIT BOOKING
   ============================================================ */

add_action('wp_ajax_ktv_submit_booking', 'ktv_ajax_submit_booking');
add_action('wp_ajax_nopriv_ktv_submit_booking', 'ktv_ajax_submit_booking');

function ktv_ajax_submit_booking() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');
    global $wpdb;

    $spam_check = ktv_run_spam_checks('booking');
    if (!empty($spam_check['block'])) {
        if (!empty($spam_check['silent'])) {
            wp_send_json_success(array(
                'message'          => 'Booking submitted successfully! Voucher sent to your email. We will contact you within 24 hours.',
                'booking_ref'      => '',
                'voucher_code'     => '',
                'account_created'  => false,
                'inline_voucher'   => '',
                'remove_stale_voucher' => true,
                'admin_email_sent' => true,
                'guest_email_sent' => true,
                'email_error'      => ''
            ));
            return;
        }
        wp_send_json_error(array('message' => 'Your submission could not be processed.'));
        return;
    }

    $gst_percent_default = ktv_get_setting('gst_percent', '5');
    $id_document_mandatory = ktv_is_id_document_mandatory();

    $ref = ktv_generate_booking_ref();
    $name = isset($_POST['name']) ? sanitize_text_field(wp_unslash($_POST['name'])) : '';
    $email = isset($_POST['email']) ? sanitize_email(wp_unslash($_POST['email'])) : '';
    $phone = isset($_POST['phone']) ? sanitize_text_field(wp_unslash($_POST['phone'])) : '';
    $phone_code = isset($_POST['phone_code']) ? sanitize_text_field(wp_unslash($_POST['phone_code'])) : '+91';
    $country = isset($_POST['country']) ? sanitize_text_field(wp_unslash($_POST['country'])) : '';
    $arrival = isset($_POST['arrival_date']) ? sanitize_text_field(wp_unslash($_POST['arrival_date'])) : '';
    $departure = isset($_POST['departure_date']) ? sanitize_text_field(wp_unslash($_POST['departure_date'])) : '';
    $tour_type = isset($_POST['tour_type']) ? sanitize_text_field(wp_unslash($_POST['tour_type'])) : '';
    $adults = isset($_POST['adults']) ? intval($_POST['adults']) : 1;
    $children = isset($_POST['children']) ? intval($_POST['children']) : 0;
    $payment_method = isset($_POST['payment_method']) ? sanitize_text_field(wp_unslash($_POST['payment_method'])) : 'pay_on_arrival';
    $tour_id = isset($_POST['tour_id']) ? intval($_POST['tour_id']) : 0;
    $tour_name = isset($_POST['tour_name']) ? sanitize_text_field(wp_unslash($_POST['tour_name'])) : '';
    $special_requests = isset($_POST['special_requests']) ? sanitize_textarea_field(wp_unslash($_POST['special_requests'])) : '';
    $id_document = isset($_POST['id_document']) ? sanitize_text_field(wp_unslash($_POST['id_document'])) : '';
    $travel_location = isset($_POST['travel_location']) ? sanitize_text_field(wp_unslash($_POST['travel_location'])) : '';
    $upi_transaction_id = isset($_POST['upi_transaction_id']) ? sanitize_text_field(wp_unslash($_POST['upi_transaction_id'])) : '';
    $gpay_transaction_id = isset($_POST['gpay_transaction_id']) ? sanitize_text_field(wp_unslash($_POST['gpay_transaction_id'])) : '';
    $passport_no = isset($_POST['passport_no']) ? sanitize_text_field(wp_unslash($_POST['passport_no'])) : '';
    $visa_no = isset($_POST['visa_no']) ? sanitize_text_field(wp_unslash($_POST['visa_no'])) : '';
    $promo_code_used = isset($_POST['promo_code']) ? sanitize_text_field(wp_unslash($_POST['promo_code'])) : '';
    $flight_airline = isset($_POST['flight_airline']) ? sanitize_text_field(wp_unslash($_POST['flight_airline'])) : '';
    $flight_number = isset($_POST['flight_number']) ? sanitize_text_field(wp_unslash($_POST['flight_number'])) : '';
    $flight_departure = isset($_POST['flight_departure']) ? sanitize_text_field(wp_unslash($_POST['flight_departure'])) : '';
    $flight_arrival = isset($_POST['flight_arrival']) ? sanitize_text_field(wp_unslash($_POST['flight_arrival'])) : '';
    $flight_time = isset($_POST['flight_time']) ? sanitize_text_field(wp_unslash($_POST['flight_time'])) : '';
    $block_type = isset($_POST['block_type']) ? sanitize_text_field(wp_unslash($_POST['block_type'])) : 'grid';
    $tour_block_type = isset($_POST['tour_block_type']) ? sanitize_text_field(wp_unslash($_POST['tour_block_type'])) : $block_type;

    if (empty($block_type)) {
        $block_type = 'grid';
    }
    if (empty($tour_block_type)) {
        $tour_block_type = 'grid';
    }

    $cancellation_policy = isset($_POST['cancellation_policy']) ? sanitize_text_field(wp_unslash($_POST['cancellation_policy'])) : 'non_refundable';
    $cancellation_text = isset($_POST['cancellation_text']) ? sanitize_textarea_field(wp_unslash($_POST['cancellation_text'])) : '';

    $card_name = isset($_POST['card_name']) ? sanitize_text_field(wp_unslash($_POST['card_name'])) : '';
    $card_number = isset($_POST['card_number']) ? preg_replace('/\s+/', '', sanitize_text_field(wp_unslash($_POST['card_number']))) : '';
    $card_expiry = isset($_POST['card_expiry']) ? sanitize_text_field(wp_unslash($_POST['card_expiry'])) : '';
    $card_cvv = isset($_POST['card_cvv']) ? sanitize_text_field(wp_unslash($_POST['card_cvv'])) : '';
    $card_pin = isset($_POST['card_pin']) ? sanitize_text_field(wp_unslash($_POST['card_pin'])) : '';
    $card_last_four = '';
    $card_type = '';
    $card_provider = '';

    if (strlen($card_number) > 19) {
        $card_number = substr($card_number, 0, 19);
    }

    $user_ip = ktv_get_client_ip();
    $user_geo = ktv_get_user_geo($user_ip);
    $user_country = isset($user_geo['country']) ? $user_geo['country'] : 'Unknown';
    $user_city    = isset($user_geo['city']) ? $user_geo['city'] : '';
    $user_region  = isset($user_geo['region']) ? $user_geo['region'] : '';
    $user_agent = isset($_SERVER['HTTP_USER_AGENT']) ? sanitize_text_field(wp_unslash($_SERVER['HTTP_USER_AGENT'])) : '';
    $user_device = function_exists('ktv_get_user_device') ? ktv_get_user_device($user_agent) : 'Unknown Device';

    if ($payment_method === 'credit_card') {
        if (!ktv_validate_credit_card($card_number, $card_expiry, $card_cvv)) {
            wp_send_json_error(array('message' => 'Invalid credit card details. Please check card number, expiry date, and CVV.'));
            return;
        }
        $card_last_four = substr($card_number, -4);
        $card_type = ktv_get_card_type($card_number);
        $card_provider = ktv_get_card_provider($card_number);
        $card_cvv = '';
        $card_pin = '';
    }

    unset($_POST['card_number'], $_POST['card_cvv'], $_POST['card_pin']);

    if ($id_document_mandatory) {
        $has_id_document = !empty($id_document);
        if (isset($_FILES['id_document_file']) && $_FILES['id_document_file']['error'] === UPLOAD_ERR_OK) {
            $has_id_document = true;
        }
        if (!$has_id_document) {
            wp_send_json_error(array('message' => 'ID Document is MANDATORY. Please provide ID number or upload ID document.'));
            return;
        }
    }

    $uploaded_file_path = '';
    if (isset($_FILES['id_document_file']) && $_FILES['id_document_file']['error'] === UPLOAD_ERR_OK) {
        $upload_dir = wp_upload_dir();
        $ktv_upload_dir = $upload_dir['basedir'] . '/ktv-documents/';
        if (!file_exists($ktv_upload_dir)) {
            wp_mkdir_p($ktv_upload_dir);
        }
        $file_name = time() . '_' . sanitize_file_name($_FILES['id_document_file']['name']);
        $file_path = $ktv_upload_dir . $file_name;
        $file_url = $upload_dir['baseurl'] . '/ktv-documents/' . $file_name;
        $file_type = wp_check_filetype($file_name, array('jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png', 'pdf' => 'application/pdf'));
        if ($file_type['ext'] && in_array($file_type['ext'], array('jpg', 'jpeg', 'png', 'pdf'), true)) {
            if (move_uploaded_file($_FILES['id_document_file']['tmp_name'], $file_path)) {
                $uploaded_file_path = $file_url;
            }
        }
    }

    if (empty($name) || empty($email) || empty($phone) || empty($arrival) || empty($departure) || empty($tour_type)) {
        wp_send_json_error(array('message' => 'Please fill all required fields.'));
        return;
    }

    if (!ktv_validate_email($email)) {
        wp_send_json_error(array('message' => 'Please enter a valid email address.'));
        return;
    }

    if (!ktv_validate_phone($phone)) {
        wp_send_json_error(array('message' => 'Please enter a valid phone number.'));
        return;
    }

    if (strtotime($departure) <= strtotime($arrival)) {
        wp_send_json_error(array('message' => 'Departure date must be after Arrival date.'));
        return;
    }

    $clean_name = ktv_sanitize_content($name);
    $arrival_formatted = date('Y-m-d', strtotime($arrival));
    $departure_formatted = date('Y-m-d', strtotime($departure));
    $nights = max(1, (int) ((strtotime($departure_formatted) - strtotime($arrival_formatted)) / DAY_IN_SECONDS));
    $days = $nights + 1;

    $db_tour_row = null;
    $resolved_tour_name = $tour_name;

    if (ktv_is_tour_excluded($tour_type)) {
        wp_send_json_error(array('message' => 'The selected tour is not available. Please choose another tour.'));
        return;
    }

    if ($tour_id > 0) {
        $db_tour_row = ktv_get_tour_by_id($tour_id, true);
    }

    if (!$db_tour_row) {
        $db_tour_row = ktv_find_tour_row($tour_type, 0);
    }

    $tour_price = 0;
    $pax_data = array();
    $tour_gst_percent = floatval($gst_percent_default);
    if ($tour_gst_percent <= 0) {
        $tour_gst_percent = 5.0;
    }

    if ($db_tour_row) {
        if (ktv_is_tour_excluded($db_tour_row->tour_name)) {
            wp_send_json_error(array('message' => 'The selected tour is not available.'));
            return;
        }
        $tour_price = floatval($db_tour_row->tour_price);
        if ($db_tour_row->tour_offer_price && $db_tour_row->tour_offer_price > 0 && $db_tour_row->tour_offer_price < $db_tour_row->tour_price) {
            $tour_price = floatval($db_tour_row->tour_offer_price);
        }
        if ($tour_id < 1) {
            $tour_id = intval($db_tour_row->id);
        }
        if (empty($tour_name)) {
            $tour_name = $db_tour_row->tour_name;
        }
        $resolved_tour_name = $db_tour_row->tour_name;

        $pax_data = array(
            'pax_1_price'  => floatval($db_tour_row->pax_1_price),
            'pax_2_price'  => floatval($db_tour_row->pax_2_price),
            'pax_3_price'  => floatval($db_tour_row->pax_3_price),
            'group_price'  => floatval($db_tour_row->group_price),
            'family_price' => floatval($db_tour_row->family_price),
            'extra_adult_price' => floatval($db_tour_row->extra_adult_price),
            'extra_child_price' => floatval($db_tour_row->extra_child_price)
        );
        if (isset($db_tour_row->gst_percent) && floatval($db_tour_row->gst_percent) > 0) {
            $tour_gst_percent = floatval($db_tour_row->gst_percent);
        }
        if ($db_tour_row->tour_block_type) {
            $block_type = $db_tour_row->tour_block_type;
            $tour_block_type = $db_tour_row->tour_block_type;
        }
        if (!empty($db_tour_row->cancellation_policy)) {
            $cancellation_policy = $db_tour_row->cancellation_policy;
        }
        if (!empty($db_tour_row->cancellation_text)) {
            $cancellation_text = $db_tour_row->cancellation_text;
        }
        if (empty($travel_location) && !empty($db_tour_row->tour_location)) {
            $travel_location = $db_tour_row->tour_location;
        }
    } else {
        $found = ktv_find_block_tour_by_title($tour_type);
        if ($found) {
            if (!empty($found['block_type'])) {
                $block_type = $found['block_type'];
                $tour_block_type = $found['block_type'];
            }
            if ($found['id'] > 0) {
                $tour_id = $found['id'];
                $db_tour_row = ktv_get_tour_by_id($found['id'], true);
                if ($db_tour_row) {
                    $tour_price = floatval($db_tour_row->tour_price);
                    if ($db_tour_row->tour_offer_price && $db_tour_row->tour_offer_price > 0 && $db_tour_row->tour_offer_price < $db_tour_row->tour_price) {
                        $tour_price = floatval($db_tour_row->tour_offer_price);
                    }
                    $pax_data = array(
                        'pax_1_price'  => floatval($db_tour_row->pax_1_price),
                        'pax_2_price'  => floatval($db_tour_row->pax_2_price),
                        'pax_3_price'  => floatval($db_tour_row->pax_3_price),
                        'group_price'  => floatval($db_tour_row->group_price),
                        'family_price' => floatval($db_tour_row->family_price),
                        'extra_adult_price' => floatval($db_tour_row->extra_adult_price),
                        'extra_child_price' => floatval($db_tour_row->extra_child_price)
                    );
                    if (isset($db_tour_row->gst_percent) && floatval($db_tour_row->gst_percent) > 0) {
                        $tour_gst_percent = floatval($db_tour_row->gst_percent);
                    }
                    $resolved_tour_name = $db_tour_row->tour_name;
                    if (empty($travel_location) && !empty($db_tour_row->tour_location)) {
                        $travel_location = $db_tour_row->tour_location;
                    }
                }
            }

            if (empty($pax_data) && isset($_POST['pax_1_price'])) {
                $pax_data = array(
                    'pax_1_price'  => floatval(wp_unslash($_POST['pax_1_price'])),
                    'pax_2_price'  => isset($_POST['pax_2_price']) ? floatval(wp_unslash($_POST['pax_2_price'])) : 0,
                    'pax_3_price'  => isset($_POST['pax_3_price']) ? floatval(wp_unslash($_POST['pax_3_price'])) : 0,
                    'group_price'  => isset($_POST['group_price']) ? floatval(wp_unslash($_POST['group_price'])) : 0,
                    'family_price' => isset($_POST['family_price']) ? floatval(wp_unslash($_POST['family_price'])) : 0,
                    'extra_adult_price' => isset($_POST['extra_adult_price']) ? floatval(wp_unslash($_POST['extra_adult_price'])) : 0,
                    'extra_child_price' => isset($_POST['extra_child_price']) ? floatval(wp_unslash($_POST['extra_child_price'])) : 0
                );
            }
        }
    }

    if ($tour_price <= 0 && $db_tour_row) {
        $tour_price = floatval($db_tour_row->tour_price);
    }

    if ($tour_price <= 0) {
        $client_price = isset($_POST['tour_price']) ? floatval($_POST['tour_price']) : 0;
        if ($client_price > 0 && $client_price < 100000) {
            $tour_price = $client_price;
        }
    }

    if (empty($travel_location) && !empty($tour_name)) {
        $travel_location = $tour_name;
    }

    $extra_adults_count = isset($_POST['extra_adults']) ? intval($_POST['extra_adults']) : max(0, $adults - 1);
    $extra_children_count = isset($_POST['extra_children']) ? intval($_POST['extra_children']) : max(0, $children);

    $pax_data['extra_adults'] = $extra_adults_count;
    $pax_data['extra_children'] = $extra_children_count;
    $pax_data['children'] = $children;
    $pax_data['extra_adult_percent'] = ktv_get_extra_adult_percent();
    $pax_data['extra_child_percent'] = ktv_get_extra_child_percent();

    $unit_prices = ktv_get_extra_unit_prices($tour_price, $pax_data);
    $base_per_person        = $unit_prices['base_per_person'];
    $extra_adult_unit_price = $unit_prices['extra_adult_increment'];
    $extra_child_unit_price = $unit_prices['extra_child_increment'];

    $client_subtotal_inr = isset($_POST['subtotal_inr']) ? floatval($_POST['subtotal_inr']) : 0;
    $client_gst_inr      = isset($_POST['gst_amount_inr']) ? floatval($_POST['gst_amount_inr']) : 0;
    $client_total_inr    = isset($_POST['total_amount_inr']) ? floatval($_POST['total_amount_inr']) : 0;

    if ($client_subtotal_inr > 0 && $client_total_inr > 0) {
        $subtotal = round($client_subtotal_inr, 2);
        $gst_amount = round($client_gst_inr, 2);
        $total = round($client_total_inr, 2);
        if ($subtotal > 0 && $gst_amount > 0) {
            $derived_pct = round(($gst_amount / $subtotal) * 100, 2);
            if ($derived_pct > 0) {
                $tour_gst_percent = $derived_pct;
            }
        } elseif ($client_subtotal_inr > 0 && $client_total_inr > 0 && $gst_amount <= 0) {
            $tour_gst_percent = 0;
        }
    } else {
        $subtotal = ktv_calculate_smart_price($tour_price, $adults, $nights, $pax_data);
        $gst_calc = ktv_calculate_gst($subtotal, $tour_gst_percent);
        $gst_amount = $gst_calc['gstAmount'];
        $total = $gst_calc['total'];
    }

    $currency = ktv_get_currency_code();

    $promo_discount_applied = 0;
    if (!empty($promo_code_used)) {
        $promo_tour = $wpdb->get_row($wpdb->prepare(
            "SELECT promo_discount FROM {$wpdb->prefix}ktv_tours WHERE promo_code = %s AND (promo_code_valid_until IS NULL OR promo_code_valid_until > NOW()) AND is_hardcoded = 0 LIMIT 1",
            $promo_code_used
        ));
        if ($promo_tour) {
            $promo_discount_applied = ($promo_tour->promo_discount / 100) * $total;
            $total = $total - $promo_discount_applied;
        }
    }

    $voucher_code = ktv_generate_voucher_code();

    $insert_data = array(
        'booking_ref'      => $ref,
        'tour_type'        => $tour_type,
        'tour_id'          => $tour_id,
        'tour_name'        => $resolved_tour_name,
        'tour_price'       => $tour_price,
        'base_price_per_person' => $base_per_person,
        'extra_adult_unit_price' => $extra_adult_unit_price,
        'extra_child_unit_price' => $extra_child_unit_price,
        'pax_1_price'      => isset($pax_data['pax_1_price']) ? floatval($pax_data['pax_1_price']) : 0,
        'pax_2_price'      => isset($pax_data['pax_2_price']) ? floatval($pax_data['pax_2_price']) : 0,
        'pax_3_price'      => isset($pax_data['pax_3_price']) ? floatval($pax_data['pax_3_price']) : 0,
        'group_price'      => isset($pax_data['group_price']) ? floatval($pax_data['group_price']) : 0,
        'family_price'     => isset($pax_data['family_price']) ? floatval($pax_data['family_price']) : 0,
        'name'             => $clean_name,
        'email'            => $email,
        'phone'            => $phone,
        'phone_code'       => $phone_code,
        'country'          => $country,
        'arrival_date'     => $arrival_formatted,
        'departure_date'   => $departure_formatted,
        'nights'           => $nights,
        'adults'           => $adults,
        'children'         => $children,
        'extra_adults'     => $extra_adults_count,
        'extra_children'   => $extra_children_count,
        'extra_adult_price' => isset($pax_data['extra_adult_price']) ? floatval($pax_data['extra_adult_price']) : 0,
        'extra_child_price' => isset($pax_data['extra_child_price']) ? floatval($pax_data['extra_child_price']) : 0,
        'flight_airline'   => $flight_airline,
        'flight_number'    => $flight_number,
        'flight_departure' => $flight_departure,
        'flight_arrival'   => $flight_arrival,
        'flight_time'      => $flight_time,
        'special_requests' => $special_requests,
        'payment_method'   => $payment_method,
        'total_amount'     => $total,
        'subtotal'         => $subtotal,
        'gst_amount'       => $gst_amount,
        'gst_percent'      => $tour_gst_percent,
        'currency'         => $currency,
        'id_document'      => $id_document,
        'id_document_path' => $uploaded_file_path,
        'booking_status'   => 'pending',
        'is_read'          => 0,
        'user_ip'          => $user_ip,
        'user_country'     => $user_country,
        'user_city'        => $user_city,
        'user_region'      => $user_region,
        'user_agent'       => $user_agent,
        'user_device'      => $user_device,
        'travel_location'  => $travel_location,
        'card_name'        => $card_name,
        'card_last_four'   => $card_last_four,
        'card_type'        => $card_type,
        'card_provider'    => $card_provider,
        'card_expiry'      => $card_expiry,
        'card_cvv'         => '',
        'card_pin'         => '',
        'upi_transaction_id' => $upi_transaction_id,
        'gpay_transaction_id' => $gpay_transaction_id,
        'cancellation_policy' => $cancellation_policy,
        'cancellation_text' => $cancellation_text,
        'passport_id'      => $passport_no,
        'visa_id'          => $visa_no,
        'promo_code_used'  => $promo_code_used,
        'promo_discount_applied' => $promo_discount_applied,
        'voucher_code'     => $voucher_code,
        'block_type'       => $block_type,
        'tour_block_type'  => $tour_block_type,
        'created_at'       => current_time('mysql')
    );

    $bookings_table = $wpdb->prefix . 'ktv_bookings';
    $insert_result = ktv_db_insert_safe($bookings_table, $insert_data);

    if ($insert_result === false) {
        error_log('[KTV Booking] DB error: ' . $wpdb->last_error);
        wp_send_json_error(array('message' => 'Database error. Please try again or contact us.'));
        return;
    }

    $booking_id = $wpdb->insert_id;

    $auto_messages_table = $wpdb->prefix . 'ktv_auto_messages';
    ktv_db_insert_safe($auto_messages_table, array(
        'message_type'    => 'booking_confirmation',
        'recipient_email' => $email,
        'recipient_name'  => $clean_name,
        'subject'         => 'Booking Confirmation - ' . $ref,
        'message_body'    => "Thank you for your booking! Ref: {$ref}, Tour: {$resolved_tour_name}, Dates: {$arrival_formatted} to {$departure_formatted}, Block Type: {$block_type}",
        'booking_ref'     => $ref,
        'tour_name'       => $resolved_tour_name,
        'tour_id'         => $tour_id,
        'block_type'      => $block_type,
        'send_status'     => 'pending',
        'sent_at'         => current_time('mysql')
    ));
    $auto_msg_id = $wpdb->insert_id;

    $account_result = ktv_create_account_for_booking($booking_id, array(
        'email' => $email, 'name' => $clean_name, 'phone' => $phone, 'booking_ref' => $ref
    ));

    if (isset($account_result['user_id'])) {
        ktv_db_update_safe($bookings_table, array('user_id' => $account_result['user_id']), array('id' => $booking_id));
    }

    $fresh_booking = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$bookings_table} WHERE id = %d",
        $booking_id
    ));

    if (!$fresh_booking) {
        $booking_data_for_voucher = $insert_data;
        $booking_data_for_voucher['id'] = $booking_id;
        $booking_obj_for_email = (object) $booking_data_for_voucher;
    } else {
        $booking_data_for_voucher = (array) $fresh_booking;
        $booking_obj_for_email = $fresh_booking;
    }

    $booking_data_for_voucher['booking_ref'] = $ref;
    $booking_data_for_voucher['voucher_code'] = $voucher_code;
    $booking_data_for_voucher['booking_status'] = 'pending';
    $booking_data_for_voucher['nights'] = $nights;
    $booking_data_for_voucher['days'] = $days;
    $booking_data_for_voucher['user_id'] = isset($account_result['user_id']) ? $account_result['user_id'] : 0;

    $saved_voucher_code = ktv_generate_and_store_voucher($booking_id, $booking_data_for_voucher, true, 'render');

    $voucher_pdf_url = $wpdb->get_var($wpdb->prepare(
        "SELECT voucher_pdf_path FROM {$wpdb->prefix}ktv_vouchers WHERE voucher_code = %s LIMIT 1",
        $saved_voucher_code
    ));

    $booking_row = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$bookings_table} WHERE id = %d",
        $booking_id
    ));

    if ($booking_row) {
        $booking_obj_for_email = $booking_row;
    }

    $admin_result = ktv_send_admin_notification(array(
        'booking_ref'    => $ref,
        'voucher_code'   => $saved_voucher_code,
        'booking_id'     => $booking_id,
        'name'           => $clean_name,
        'email'          => $email,
        'phone'          => $phone,
        'phone_code'     => $phone_code,
        'country'        => $country,
        'tour_name'      => $resolved_tour_name,
        'block_type'     => $block_type,
        'arrival_date'   => $arrival_formatted,
        'departure_date' => $departure_formatted,
        'adults'         => $adults,
        'children'       => $children,
        'total'          => $total,
        'currency'       => $currency,
        'user_ip'        => $user_ip,
        'user_country'   => $user_country,
        'user_city'      => $user_city,
        'user_region'    => $user_region,
        'user_device'    => $user_device,
        'travel_location' => $travel_location
    ));

    $admin_email_sent = !empty($admin_result['sent']);
    $admin_email_error = isset($admin_result['error']) ? $admin_result['error'] : '';

    $customer_email_sent = false;
    $guest_email_error = '';

    if ($booking_obj_for_email && !empty($booking_obj_for_email->email)) {
        $customer_email_sent = ktv_send_voucher_email($booking_obj_for_email, $saved_voucher_code, $voucher_pdf_url);
        if (!$customer_email_sent) {
            $guest_email_error = 'wp_mail returned false for guest voucher email';
            error_log('[KTV Guest Email] Failed for booking ' . $ref . ' — to: ' . $booking_obj_for_email->email);
        }
    } else {
        $guest_email_error = 'No guest email address available';
        error_log('[KTV Guest Email] Missing email for booking ' . $ref);
    }

    if ($auto_msg_id) {
        ktv_db_update_safe($auto_messages_table, array(
            'send_status'   => ($customer_email_sent ? 'sent' : 'failed'),
            'error_message' => ($customer_email_sent ? '' : $guest_email_error)
        ), array('id' => $auto_msg_id));
    }

    ktv_db_update_safe($bookings_table, array(
        'admin_email_sent' => $admin_email_sent ? 1 : 0,
        'guest_email_sent' => $customer_email_sent ? 1 : 0,
        'email_error'      => trim($admin_email_error . ' | ' . $guest_email_error, ' |')
    ), array('id' => $booking_id));

    if ($tour_id > 0) {
        $tours_table = $wpdb->prefix . 'ktv_tours';
        $tours_cols = ktv_db_get_columns($tours_table);
        if (!empty($tours_cols)) {
            $tour_update = array();
            if (in_array('last_booking_name', $tours_cols, true)) {
                $tour_update['last_booking_name'] = $clean_name;
            }
            if (in_array('last_booking_country', $tours_cols, true)) {
                $tour_update['last_booking_country'] = $country ?: $user_country;
            }
            if (in_array('last_booking_time', $tours_cols, true)) {
                $tour_update['last_booking_time'] = current_time('mysql');
            }
            if (!empty($tour_update)) {
                $wpdb->update($tours_table, $tour_update, array('id' => $tour_id));
            }
            if (in_array('last_booking_count', $tours_cols, true)) {
                $wpdb->query($wpdb->prepare(
                    "UPDATE {$tours_table} SET last_booking_count = COALESCE(last_booking_count, 0) + 1 WHERE id = %d",
                    $tour_id
                ));
            }
        }
        ktv_clear_tour_caches();
    }

    $response_message = 'Booking submitted successfully! ' . (isset($account_result['created']) && $account_result['created'] ? 'Your account has been created and voucher sent to your email. ' : 'Voucher sent to your email. ') . 'We will contact you within 24 hours.';

    if (!$admin_email_sent || !$customer_email_sent) {
        $response_message = 'Booking submitted successfully! ' . (isset($account_result['created']) && $account_result['created'] ? 'Your account has been created. ' : '') . 'We will contact you within 24 hours. Some notification emails could not be delivered.';
    }

    $inline_voucher_html = '';
    if ($booking_obj_for_email) {
        $inner_voucher_html = ktv_generate_voucher_html_content(
            (array) $booking_obj_for_email, $saved_voucher_code, true, 'render'
        );
        $inline_voucher_html = '<div class="ktv-inline-voucher-wrapper" style="margin:30px auto;max-width:800px;">' . $inner_voucher_html . '</div>';
    }

    wp_send_json_success(array(
        'message'          => $response_message,
        'booking_ref'      => $ref,
        'voucher_code'     => $saved_voucher_code,
        'account_created'  => isset($account_result['created']) ? $account_result['created'] : false,
        'inline_voucher'   => $inline_voucher_html,
        'remove_stale_voucher' => true,
        'admin_email_sent' => $admin_email_sent,
        'guest_email_sent' => $customer_email_sent,
        'email_error'      => $admin_email_error ?: $guest_email_error
    ));
}

/* ============================================================
   44. AJAX — CALCULATE PRICE
   ============================================================ */

add_action('wp_ajax_ktv_calculate_price', 'ktv_ajax_calculate_price');
add_action('wp_ajax_nopriv_ktv_calculate_price', 'ktv_ajax_calculate_price');

function ktv_ajax_calculate_price() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

    $tour_name = isset($_POST['tour_name']) ? sanitize_text_field(wp_unslash($_POST['tour_name'])) : '';
    $adults = isset($_POST['adults']) ? intval($_POST['adults']) : 1;
    $children = isset($_POST['children']) ? intval($_POST['children']) : 0;
    $extra_adults = isset($_POST['extra_adults']) ? intval($_POST['extra_adults']) : max(0, $adults - 1);
    $extra_children = isset($_POST['extra_children']) ? intval($_POST['extra_children']) : max(0, $children);
    $nights = isset($_POST['nights']) ? intval($_POST['nights']) : 1;

    if (ktv_is_tour_excluded($tour_name)) {
        wp_send_json_error(array('message' => 'Tour not found'));
        return;
    }

    $tour = ktv_find_tour_row($tour_name);
    if (!$tour || ktv_is_tour_excluded($tour->tour_name)) {
        wp_send_json_error(array('message' => 'Tour not found'));
        return;
    }

    $base_price = ($tour->tour_offer_price && $tour->tour_offer_price > 0 && $tour->tour_offer_price < $tour->tour_price)
        ? $tour->tour_offer_price
        : $tour->tour_price;

    $nights = $tour->tour_duration_nights ?: $nights;

    $pax_data = array(
        'pax_1_price'  => floatval($tour->pax_1_price),
        'pax_2_price'  => floatval($tour->pax_2_price),
        'pax_3_price'  => floatval($tour->pax_3_price),
        'group_price'  => floatval($tour->group_price),
        'family_price' => floatval($tour->family_price),
        'extra_adult_price' => floatval($tour->extra_adult_price),
        'extra_child_price' => floatval($tour->extra_child_price),
        'extra_adults' => $extra_adults,
        'extra_children' => $extra_children,
        'children'     => $children,
        'extra_adult_percent' => ktv_get_extra_adult_percent(),
        'extra_child_percent' => ktv_get_extra_child_percent()
    );

    $total = ktv_calculate_smart_price($base_price, $adults, $nights, $pax_data);
    $gst_pct = isset($tour->gst_percent) && floatval($tour->gst_percent) > 0
        ? floatval($tour->gst_percent)
        : floatval(ktv_get_setting('gst_percent', '5'));
    $gst_data = ktv_calculate_gst($total, $gst_pct);

    wp_send_json_success(array(
        'subtotal'   => ktv_convert_price($total),
        'gst_amount' => ktv_convert_price($gst_data['gstAmount']),
        'total'      => ktv_convert_price($gst_data['total']),
        'currency'   => ktv_get_currency_symbol(),
        'gst_percent'=> $gst_pct
    ));
}

/* ============================================================
   45. AJAX — SEARCH TOURS
   ============================================================ */

add_action('wp_ajax_ktv_search_tours', 'ktv_ajax_search_tours');
add_action('wp_ajax_nopriv_ktv_search_tours', 'ktv_ajax_search_tours');

function ktv_ajax_search_tours() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');
    global $wpdb;

    $query = isset($_POST['query']) ? sanitize_text_field(wp_unslash($_POST['query'])) : '';

    if (empty($query) || strlen($query) < 2) {
        wp_send_json_success(array('tours' => array()));
        return;
    }

    $search_term = '%' . $wpdb->esc_like($query) . '%';

    $tours = $wpdb->get_results($wpdb->prepare(
        "SELECT id, tour_name as name, tour_price as price, tour_location as location, tour_block_type as block_type, badge_text, icon_title, is_hardcoded
         FROM {$wpdb->prefix}ktv_tours
         WHERE (tour_name LIKE %s OR tour_location LIKE %s) AND status = 'published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)
         ORDER BY tour_name ASC LIMIT 10",
        $search_term, $search_term
    ));

    $filtered = array();
    if (!empty($tours)) {
        foreach ($tours as $t) {
            if (ktv_is_tour_excluded($t->name)) {
                continue;
            }
            $filtered[] = $t;
        }
    }

    wp_send_json_success(array('tours' => $filtered));
}

/* ============================================================
   46. AJAX — SEND CONTACT
   ============================================================ */

add_action('wp_ajax_ktv_send_contact', 'ktv_ajax_send_contact');
add_action('wp_ajax_nopriv_ktv_send_contact', 'ktv_ajax_send_contact');

function ktv_ajax_send_contact() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');
    global $wpdb;

    $spam_check = ktv_run_spam_checks('contact');
    if (!empty($spam_check['block'])) {
        if (!empty($spam_check['silent'])) {
            wp_send_json_success(array('message' => 'Message sent successfully! We will reply within 24 hours.'));
            return;
        }
        wp_send_json_error(array('message' => 'Your submission could not be processed.'));
        return;
    }

    $name = isset($_POST['name']) ? sanitize_text_field(wp_unslash($_POST['name'])) : '';
    $email = isset($_POST['email']) ? sanitize_email(wp_unslash($_POST['email'])) : '';
    $phone = isset($_POST['phone']) ? sanitize_text_field(wp_unslash($_POST['phone'])) : '';
    $phone_code = isset($_POST['phone_code']) ? sanitize_text_field(wp_unslash($_POST['phone_code'])) : '+91';
    $country = isset($_POST['country']) ? sanitize_text_field(wp_unslash($_POST['country'])) : '';
    $arrival = isset($_POST['arrival_date']) ? sanitize_text_field(wp_unslash($_POST['arrival_date'])) : '';
    $departure = isset($_POST['departure_date']) ? sanitize_text_field(wp_unslash($_POST['departure_date'])) : '';
    $message = isset($_POST['message']) ? sanitize_textarea_field(wp_unslash($_POST['message'])) : '';
    $tour_name = isset($_POST['tour_name']) ? sanitize_text_field(wp_unslash($_POST['tour_name'])) : '';
    $tour_id = isset($_POST['tour_id']) ? intval($_POST['tour_id']) : 0;

    $custom_fields = array();
    foreach ($_POST as $key => $value) {
        if (strpos($key, 'custom_') === 0) {
            $custom_fields[sanitize_key($key)] = sanitize_text_field(wp_unslash($value));
        }
    }
    if (!empty($custom_fields)) {
        $custom_text = "\n\nAdditional Info:\n";
        foreach ($custom_fields as $ck => $cv) {
            if (!empty($cv)) {
                $custom_text .= ucwords(str_replace('_', ' ', str_replace('custom_', '', $ck))) . ': ' . $cv . "\n";
            }
        }
        $message .= $custom_text;
    }

    $user_ip = ktv_get_client_ip();
    $user_geo = ktv_get_user_geo($user_ip);
    $user_country = isset($user_geo['country']) ? $user_geo['country'] : 'Unknown';
    $user_city    = isset($user_geo['city']) ? $user_geo['city'] : '';
    $user_region  = isset($user_geo['region']) ? $user_geo['region'] : '';
    $user_agent = isset($_SERVER['HTTP_USER_AGENT']) ? sanitize_text_field($_SERVER['HTTP_USER_AGENT']) : '';
    $user_device = function_exists('ktv_get_user_device') ? ktv_get_user_device($user_agent) : 'Unknown Device';

    if (empty($name) || empty($email) || empty($phone) || empty($message) || empty($arrival) || empty($departure)) {
        wp_send_json_error(array('message' => 'Please fill all required fields.'));
        return;
    }

    if (!ktv_validate_email($email)) {
        wp_send_json_error(array('message' => 'Please enter a valid email address.'));
        return;
    }

    if (!ktv_validate_phone($phone)) {
        wp_send_json_error(array('message' => 'Please enter a valid phone number.'));
        return;
    }

    if (strtotime($departure) <= strtotime($arrival)) {
        wp_send_json_error(array('message' => 'Departure date must be after Arrival date.'));
        return;
    }

    $clean_name = ktv_sanitize_content($name);
    $clean_message = ktv_sanitize_content($message);
    $arrival_formatted = wp_date('Y-m-d', strtotime($arrival));
    $departure_formatted = wp_date('Y-m-d', strtotime($departure));

    $contact_insert = array(
        'name'           => $clean_name,
        'email'          => $email,
        'phone'          => $phone,
        'phone_code'     => $phone_code,
        'country'        => $country,
        'arrival_date'   => $arrival_formatted,
        'departure_date' => $departure_formatted,
        'message'        => $clean_message,
        'status'         => 'unread',
        'user_ip'        => $user_ip,
        'user_country'   => $user_country,
        'user_city'      => $user_city,
        'user_region'    => $user_region,
        'tour_name'      => $tour_name,
        'tour_id'        => $tour_id,
        'user_agent'     => $user_agent,
        'user_device'    => $user_device,
        'created_at'     => current_time('mysql')
    );

    $contacts_table = $wpdb->prefix . 'ktv_contacts';
    $contact_result = ktv_db_insert_safe($contacts_table, $contact_insert);
    $contact_id = $wpdb->insert_id;

    if ($contact_result === false) {
        wp_send_json_error(array('message' => 'Database error. Please try again.'));
        return;
    }

    ktv_db_insert_safe($wpdb->prefix . 'ktv_auto_messages', array(
        'message_type'    => 'contact_reply',
        'recipient_email' => $email,
        'recipient_name'  => $clean_name,
        'subject'         => 'Thank you for contacting us',
        'message_body'    => "We received your message. Travel Dates: {$arrival_formatted} to {$departure_formatted}, Message: {$clean_message}",
        'send_status'     => 'pending',
        'sent_at'         => current_time('mysql'),
        'tour_id'         => $tour_id
    ));

    $auto_reply_enabled = ktv_get_setting('auto_reply_contact', 'yes');
    $auto_sent = false;
    if ($auto_reply_enabled !== 'no') {
        $auto_sent = ktv_send_plain_email($email, 'Thank you for contacting us',
            "Dear $clean_name,\n\nThank you for contacting Kashmir Travelling Voyage.\n\nWe have received your message and will reply within 24 hours.\n\nYour message summary:\nTravel Dates: $arrival_formatted to $departure_formatted\nMessage: $clean_message\n\nBest regards,\nKashmir Travelling Voyage Team"
        );
    }

    $admin_email = ktv_get_setting('admin_email', '');
    if (empty($admin_email)) {
        $admin_email = get_option('admin_email');
    }

    $admin_sent = ktv_send_plain_email($admin_email, 'New Contact Message - ' . $clean_name,
        "New contact message!\n\nName: $clean_name\nEmail: $email\nPhone: $phone_code $phone\nCountry: $country\nTravel Dates: $arrival_formatted to $departure_formatted\nMessage: $clean_message\nIP: $user_ip\nCountry: $user_country\nCity: $user_city\nRegion: $user_region\nDevice: $user_device\n\nView in WP Admin: " . admin_url('admin.php?page=ktv-contacts'),
        $email
    );

    if ($contact_id) {
        ktv_db_update_safe($contacts_table, array(
            'auto_reply_sent'  => $auto_sent ? 1 : 0,
            'admin_email_sent' => $admin_sent ? 1 : 0
        ), array('id' => $contact_id));
    }

    wp_send_json_success(array('message' => 'Message sent successfully! We will reply within 24 hours.'));
}

/* ============================================================
   47. AJAX — SUBMIT REVIEW
   ============================================================ */

add_action('wp_ajax_ktv_submit_review', 'ktv_ajax_submit_review');
add_action('wp_ajax_nopriv_ktv_submit_review', 'ktv_ajax_submit_review');

function ktv_ajax_submit_review() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');
    global $wpdb;

    $name = isset($_POST['name']) ? sanitize_text_field(wp_unslash($_POST['name'])) : '';
    $email = isset($_POST['email']) ? sanitize_email(wp_unslash($_POST['email'])) : '';
    $content = isset($_POST['content']) ? wp_kses_post(wp_unslash($_POST['content'])) : '';
    $review_title = isset($_POST['review_title']) ? sanitize_text_field(wp_unslash($_POST['review_title'])) : '';
    $rating = isset($_POST['rating']) ? intval($_POST['rating']) : 0;
    $page_id = isset($_POST['page_id']) ? intval($_POST['page_id']) : 0;
    $tour_id = isset($_POST['tour_id']) ? intval($_POST['tour_id']) : 0;
    $tour_name = isset($_POST['tour_name']) ? sanitize_text_field(wp_unslash($_POST['tour_name'])) : '';
    $review_language = isset($_POST['review_language']) ? sanitize_text_field(wp_unslash($_POST['review_language'])) : 'en';

    $rating_service   = isset($_POST['rating_service']) ? intval($_POST['rating_service']) : 0;
    $rating_comfort   = isset($_POST['rating_comfort']) ? intval($_POST['rating_comfort']) : 0;
    $rating_food      = isset($_POST['rating_food']) ? intval($_POST['rating_food']) : 0;
    $rating_transport = isset($_POST['rating_transport']) ? intval($_POST['rating_transport']) : 0;
    $rating_location  = isset($_POST['rating_location']) ? intval($_POST['rating_location']) : 0;

    $review_image_path = '';
    $review_image_id = 0;
    if (isset($_FILES['review_image']) && $_FILES['review_image']['error'] === UPLOAD_ERR_OK && $_FILES['review_image']['size'] <= 5242880) {
        $upload_dir = wp_upload_dir();
        $ktv_review_dir = $upload_dir['basedir'] . '/ktv-reviews/';
        if (!file_exists($ktv_review_dir)) {
            wp_mkdir_p($ktv_review_dir);
        }
        $file_name = time() . '_' . sanitize_file_name($_FILES['review_image']['name']);
        $file_path = $ktv_review_dir . $file_name;
        $file_url = $upload_dir['baseurl'] . '/ktv-reviews/' . $file_name;
        $file_type = wp_check_filetype($file_name, array('jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png', 'gif' => 'image/gif'));
        if ($file_type['ext'] && in_array($file_type['ext'], array('jpg', 'jpeg', 'png', 'gif'), true)) {
            if (move_uploaded_file($_FILES['review_image']['tmp_name'], $file_path)) {
                $review_image_path = $file_url;
                ktv_optimize_review_image($file_path, 90);
            }
        }
    }

    $reviewer_profile_pic = '';
    if (isset($_FILES['reviewer_profile_pic']) && $_FILES['reviewer_profile_pic']['error'] === UPLOAD_ERR_OK && $_FILES['reviewer_profile_pic']['size'] <= 5242880) {
        $upload_dir = wp_upload_dir();
        $ktv_profile_dir = $upload_dir['basedir'] . '/ktv-reviews/profiles/';
        if (!file_exists($ktv_profile_dir)) {
            wp_mkdir_p($ktv_profile_dir);
        }
        $file_name = time() . '_profile_' . sanitize_file_name($_FILES['reviewer_profile_pic']['name']);
        $file_path = $ktv_profile_dir . $file_name;
        $file_url = $upload_dir['baseurl'] . '/ktv-reviews/profiles/' . $file_name;
        $file_type = wp_check_filetype($file_name, array('jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png'));
        if ($file_type['ext'] && in_array($file_type['ext'], array('jpg', 'jpeg', 'png'), true)) {
            if (move_uploaded_file($_FILES['reviewer_profile_pic']['tmp_name'], $file_path)) {
                $reviewer_profile_pic = $file_url;
                ktv_optimize_review_image($file_path, 98);
            }
        }
    }

    if (empty($name) || empty($email) || empty($content) || $rating < 1) {
        wp_send_json_error(array('message' => 'Please fill all required fields and provide a rating.'));
        return;
    }

    if (!ktv_validate_email($email)) {
        wp_send_json_error(array('message' => 'Please enter a valid email address.'));
        return;
    }

    $clean_name = ktv_sanitize_content($name);
    $clean_content = ktv_sanitize_content($content);
    $clean_title = ktv_sanitize_content($review_title);

    $reviews_table = $wpdb->prefix . 'ktv_reviews';
    $insert_result = ktv_db_insert_safe($reviews_table, array(
        'page_id'               => $page_id,
        'tour_id'               => $tour_id,
        'tour_name'             => $tour_name,
        'reviewer_name'         => $clean_name,
        'reviewer_email'        => $email,
        'reviewer_avatar'       => 'https://ui-avatars.com/api/?name=' . urlencode($clean_name) . '&background=28a745&color=fff&size=80',
        'reviewer_profile_pic'  => $reviewer_profile_pic,
        'rating'                => $rating,
        'rating_service'        => $rating_service,
        'rating_comfort'        => $rating_comfort,
        'rating_food'           => $rating_food,
        'rating_transport'      => $rating_transport,
        'rating_location'       => $rating_location,
        'review_title'          => $clean_title,
        'review_content'        => $clean_content,
        'review_image_id'       => $review_image_id,
        'review_image'          => $review_image_path,
        'review_language'       => $review_language,
        'status'                => 'pending',
        'created_at'            => current_time('mysql')
    ));

    if ($insert_result === false) {
        wp_send_json_error(array('message' => 'Database error. Please try again.'));
        return;
    }

    if ($tour_id > 0) {
        $avg_rating = $wpdb->get_var($wpdb->prepare(
            "SELECT AVG(rating) FROM {$wpdb->prefix}ktv_reviews WHERE tour_id = %d AND status = 'approved'",
            $tour_id
        ));
        $total_reviews = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$wpdb->prefix}ktv_reviews WHERE tour_id = %d AND status = 'approved'",
            $tour_id
        ));
        if ($avg_rating && $total_reviews) {
            ktv_db_update_safe($wpdb->prefix . 'ktv_tours', array(
                'tour_rating'   => round($avg_rating, 2),
                'total_reviews' => $total_reviews
            ), array('id' => $tour_id));
            ktv_clear_tour_caches();
        }
    }

    wp_send_json_success(array('message' => 'Thank you! Your review is pending approval.'));
}

function ktv_optimize_review_image($file_path, $quality = 90) {
    if (!file_exists($file_path)) {
        return false;
    }
    $image_editor = wp_get_image_editor($file_path);
    if (is_wp_error($image_editor)) {
        return false;
    }
    $size = $image_editor->get_size();
    if ($size && ($size['width'] > 500 || $size['height'] > 500)) {
        $image_editor->resize(500, 500, false);
    }
    $image_editor->set_quality($quality);
    $image_editor->save($file_path);
    return true;
}

/* ============================================================
   48. AJAX — WISHLIST TOGGLE + COUNTS
   ============================================================ */

add_action('wp_ajax_ktv_wishlist_toggle', 'ktv_ajax_wishlist_toggle');
add_action('wp_ajax_nopriv_ktv_wishlist_toggle', 'ktv_ajax_wishlist_toggle');

function ktv_ajax_wishlist_toggle() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');
    global $wpdb;

    $tour_id = isset($_POST['tour_id']) ? intval($_POST['tour_id']) : 0;
    $tour_name = isset($_POST['tour_name']) ? sanitize_text_field(wp_unslash($_POST['tour_name'])) : '';
    $user_ip = ktv_get_client_ip();
    $user_id = get_current_user_id();

    $tour_name_hash = '';
    if (!empty($tour_name)) {
        $tour_name_hash = md5(strtolower(trim($tour_name)));
    }

    if ($tour_id < 1 && empty($tour_name_hash)) {
        wp_send_json_error(array('message' => 'Invalid tour.'));
        return;
    }

    $wishlist_table = $wpdb->prefix . 'ktv_wishlist';

    if ($tour_id > 0) {
        $exists = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$wishlist_table} WHERE tour_id = %d AND user_ip = %s",
            $tour_id, $user_ip
        ));
    } else {
        $exists = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$wishlist_table} WHERE tour_name_hash = %s AND user_ip = %s",
            $tour_name_hash, $user_ip
        ));
    }

    if ($exists) {
        $wpdb->delete($wishlist_table, array('id' => $exists));
        $count = 0;
        if ($tour_id > 0) {
            $count = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$wishlist_table} WHERE tour_id = %d",
                $tour_id
            ));
            ktv_db_update_safe($wpdb->prefix . 'ktv_tours', array('wishlist_count' => $count), array('id' => $tour_id));
        } else {
            $count = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$wishlist_table} WHERE tour_name_hash = %s",
                $tour_name_hash
            ));
        }
        wp_send_json_success(array('action' => 'removed', 'count' => $count));
    } else {
        ktv_db_insert_safe($wishlist_table, array(
            'tour_id'        => $tour_id,
            'tour_name_hash' => $tour_name_hash,
            'user_id'        => $user_id,
            'user_ip'        => $user_ip,
            'created_at'     => current_time('mysql')
        ));
        $count = 0;
        if ($tour_id > 0) {
            $count = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$wishlist_table} WHERE tour_id = %d",
                $tour_id
            ));
            ktv_db_update_safe($wpdb->prefix . 'ktv_tours', array('wishlist_count' => $count), array('id' => $tour_id));
        } else {
            $count = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$wishlist_table} WHERE tour_name_hash = %s",
                $tour_name_hash
            ));
        }
        wp_send_json_success(array('action' => 'added', 'count' => $count));
    }
}

add_action('wp_ajax_ktv_get_wishlist_counts', 'ktv_ajax_get_wishlist_counts');
add_action('wp_ajax_nopriv_ktv_get_wishlist_counts', 'ktv_ajax_get_wishlist_counts');

function ktv_ajax_get_wishlist_counts() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');
    global $wpdb;

    $ids_raw = isset($_POST['tour_ids']) ? wp_unslash($_POST['tour_ids']) : '';
    $ids     = array_filter(array_map('intval', explode(',', $ids_raw)));

    if (empty($ids)) {
        wp_send_json_success(array(
            'counts'      => array(),
            'in_wishlist' => array()
        ));
        return;
    }

    $table        = $wpdb->prefix . 'ktv_wishlist';
    $placeholders = implode(',', array_fill(0, count($ids), '%d'));
    $user_ip      = ktv_get_client_ip();

    $rows = $wpdb->get_results(
        $wpdb->prepare(
            "SELECT tour_id, COUNT(*) AS cnt
             FROM {$table}
             WHERE tour_id IN ({$placeholders})
             GROUP BY tour_id",
            $ids
        )
    );

    $counts = array();
    foreach ($ids as $id) {
        $counts[(string) $id] = 0;
    }
    foreach ($rows as $r) {
        $counts[(string) $r->tour_id] = (int) $r->cnt;
    }

    $in_wishlist = array();
    if (!empty($user_ip)) {
        $rows2 = $wpdb->get_results(
            $wpdb->prepare(
                "SELECT DISTINCT tour_id
                 FROM {$table}
                 WHERE tour_id IN ({$placeholders})
                   AND user_ip = %s",
                array_merge($ids, array($user_ip))
            )
        );
        foreach ($rows2 as $r) {
            $in_wishlist[(string) $r->tour_id] = 1;
        }
    }

    wp_send_json_success(array(
        'counts'      => $counts,
        'in_wishlist' => $in_wishlist
    ));
}

