add_action('wp_ajax_ktv_generate_voucher_html', 'ktv_ajax_generate_voucher_html');
add_action('wp_ajax_nopriv_ktv_generate_voucher_html', 'ktv_ajax_generate_voucher_html');

function ktv_ajax_generate_voucher_html() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

    $booking_id = isset($_POST['booking_id']) ? intval($_POST['booking_id']) : 0;
    $voucher_code = isset($_POST['voucher_code']) ? sanitize_text_field(wp_unslash($_POST['voucher_code'])) : '';

    global $wpdb;

    if (!empty($voucher_code)) {
        $booking = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE voucher_code = %s",
            $voucher_code
        ), ARRAY_A);
    } elseif ($booking_id > 0) {
        $booking = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d",
            $booking_id
        ), ARRAY_A);
    } else {
        wp_send_json_error(array('message' => 'Booking not found'));
        return;
    }

    if (!$booking) {
        wp_send_json_error(array('message' => 'Booking not found'));
        return;
    }

    $is_admin = current_user_can('manage_options');
    $is_owner = false;
    if (!$is_admin && !empty($booking['email'])) {
        $current_user = wp_get_current_user();
        if ($current_user && $current_user->ID > 0 && $current_user->user_email === $booking['email']) {
            $is_owner = true;
        }
    }

    $allow_public = !empty($voucher_code) && isset($booking['voucher_code']) && $voucher_code === $booking['voucher_code'];

    if (!$is_admin && !$is_owner && !$allow_public) {
        wp_send_json_error(array('message' => 'You do not have permission to view this voucher.'));
        return;
    }

    $for_guest = !$is_admin;

    if (empty($booking['days']) && !empty($booking['nights'])) {
        $booking['days'] = intval($booking['nights']) + 1;
    }

    $voucher_html = ktv_generate_voucher_html_content($booking, isset($booking['voucher_code']) ? $booking['voucher_code'] : ktv_generate_voucher_code(), $for_guest, 'render');

    wp_send_json_success(array('html' => $voucher_html));
}

add_action('wp_ajax_ktv_mark_notices_read', 'ktv_ajax_mark_notices_read');

function ktv_ajax_mark_notices_read() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

