}

/* ============================================================
   50. AJAX — GUEST VOUCHER ACTIONS
   ============================================================ */

add_action('wp_ajax_ktv_guest_voucher_action', 'ktv_ajax_guest_voucher_action');
add_action('wp_ajax_nopriv_ktv_guest_voucher_action', 'ktv_ajax_guest_voucher_action');

function ktv_ajax_guest_voucher_action() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');
    global $wpdb;

    $voucher_code = isset($_POST['voucher_code']) ? sanitize_text_field(wp_unslash($_POST['voucher_code'])) : '';
    $token        = isset($_POST['token']) ? sanitize_text_field(wp_unslash($_POST['token'])) : '';
    $action       = isset($_POST['guest_action']) ? sanitize_text_field(wp_unslash($_POST['guest_action'])) : '';

    if (empty($voucher_code) || empty($token) || empty($action)) {
        wp_send_json_error(array('message' => 'Missing required parameters.'));
        return;
    }

    if (!in_array($action, array('accept', 'modify', 'decline', 'cancel', 'dynamic'), true)) {
        wp_send_json_error(array('message' => 'Invalid action.'));
        return;
    }

    if (!ktv_validate_voucher_token($voucher_code, $token)) {
        wp_send_json_error(array('message' => 'Invalid or expired token. Please check your email.'));
        return;
    }

    $booking = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE voucher_code = %s LIMIT 1",
        $voucher_code
    ));

    if (!$booking) {
        wp_send_json_error(array('message' => 'Booking not found for this voucher.'));
        return;
    }

    $decline_reason = isset($_POST['decline_reason']) ? sanitize_textarea_field(wp_unslash($_POST['decline_reason'])) : '';

    if ($action === 'dynamic') {
        $booking_array = (array) $booking;
        if (empty($booking_array['days'])) {
            $booking_array['days'] = max(1, intval($booking_array['nights'])) + 1;
        }
        $voucher_html = ktv_generate_voucher_html_content($booking_array, $voucher_code, true, 'render');

        $guest_token = ktv_get_voucher_token($voucher_code);
        $action_buttons = ktv_build_voucher_action_buttons($voucher_code, 'frontend', $guest_token);

        wp_send_json_success(array(
            'message' => 'Dynamic voucher updated.',
            'action'  => 'dynamic',
            'html'    => $voucher_html,
            'actions' => $action_buttons
        ));
        return;
    }

    if ($action === 'accept') {
        $result = ktv_update_booking_status($booking->id, 'confirmed');

        if (!$result['success']) {
            wp_send_json_error(array('message' => 'Could not accept booking. Please try again.'));
            return;
        }

        ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
            'guest_action_status' => 'accepted',
            'guest_action_at'     => current_time('mysql')
        ), array('voucher_code' => $voucher_code));

        $wpdb->insert($wpdb->prefix . 'ktv_auto_messages', array(
            'message_type'    => 'guest_voucher_action',
            'recipient_email' => $booking->email,
            'recipient_name'  => $booking->name,
            'subject'         => 'Guest accepted booking: ' . $booking->booking_ref,
            'message_body'    => 'Guest accepted the booking via voucher token.',
            'booking_ref'     => $booking->booking_ref,
            'tour_name'       => $booking->tour_name,
            'tour_id'         => intval($booking->tour_id),
            'block_type'      => $booking->block_type,
            'send_status'     => 'sent',
            'sent_at'         => current_time('mysql')
        ));

        wp_send_json_success(array(
            'message' => 'Thank you! Your booking has been accepted. A confirmation email has been sent.',
            'action'  => 'accept'
        ));
        return;
    }

    if ($action === 'decline') {
        $result = ktv_update_booking_status($booking->id, 'cancelled', $decline_reason);

        if (!$result['success']) {
            wp_send_json_error(array('message' => 'Could not decline booking. Please try again.'));
            return;
        }

        ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
            'guest_action_status' => 'declined',
            'guest_action_at'     => current_time('mysql')
        ), array('voucher_code' => $voucher_code));

        $wpdb->insert($wpdb->prefix . 'ktv_auto_messages', array(
            'message_type'    => 'guest_voucher_action',
            'recipient_email' => $booking->email,
            'recipient_name'  => $booking->name,
            'subject'         => 'Guest declined booking: ' . $booking->booking_ref,
            'message_body'    => 'Guest declined the booking. Reason: ' . ($decline_reason ?: 'N/A'),
            'booking_ref'     => $booking->booking_ref,
            'tour_name'       => $booking->tour_name,
            'tour_id'         => intval($booking->tour_id),
            'block_type'      => $booking->block_type,
            'send_status'     => 'sent',
            'sent_at'         => current_time('mysql')
        ));

        wp_send_json_success(array(
            'message' => 'Your booking has been declined. We will contact you shortly.',
            'action'  => 'decline'
        ));
        return;
    }

    if ($action === 'cancel') {
        if (in_array($booking->booking_status, array('cancelled', 'cancel_requested'), true)) {
            wp_send_json_error(array('message' => 'This booking is already cancelled or pending cancellation approval.'));
            return;
        }

        $cancel_reason = isset($_POST['cancel_reason']) ? sanitize_textarea_field(wp_unslash($_POST['cancel_reason'])) : '';

        $result = ktv_update_booking_status($booking->id, 'cancel_requested', $cancel_reason);

        if (!$result['success']) {
            wp_send_json_error(array('message' => 'Could not submit cancellation request. Please try again.'));
            return;
        }

        ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
            'guest_action_status' => 'cancel_requested',
            'guest_action_at'     => current_time('mysql')
        ), array('voucher_code' => $voucher_code));

        $wpdb->insert($wpdb->prefix . 'ktv_auto_messages', array(
            'message_type'    => 'guest_voucher_action',
            'recipient_email' => $booking->email,
            'recipient_name'  => $booking->name,
            'subject'         => 'Cancellation request received: ' . $booking->booking_ref,
            'message_body'    => 'Guest submitted a cancellation request. Awaiting admin approval. Reason: ' . ($cancel_reason ?: 'N/A'),
            'booking_ref'     => $booking->booking_ref,
            'tour_name'       => $booking->tour_name,
            'tour_id'         => intval($booking->tour_id),
            'block_type'      => $booking->block_type,
            'send_status'     => 'sent',
            'sent_at'         => current_time('mysql')
        ));

        $admin_email = ktv_get_setting('admin_email', '');
        if (empty($admin_email)) {
            $admin_email = get_option('admin_email');
        }

        ktv_send_plain_email(
            $admin_email,
            'Cancellation Request - ' . $booking->booking_ref,
            "Guest " . $booking->name . " requested cancellation.\n\nBooking: " . $booking->booking_ref . "\nVoucher: " . $voucher_code . "\nReason: " . ($cancel_reason ?: 'N/A') . "\n\nApprove or decline in WP Admin:\n" . admin_url('admin.php?page=ktv-bookings'),
            $booking->email
        );

        wp_send_json_success(array(
            'message' => 'Your cancellation request has been submitted. Our team will review and contact you shortly. The booking is NOT cancelled until we confirm.',
            'action'  => 'cancel'
        ));
        return;
    }

    if ($action === 'modify') {
        $modify_request = isset($_POST['modify_request']) ? sanitize_textarea_field(wp_unslash($_POST['modify_request'])) : '';

        ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
            'guest_action_status' => 'modify_requested',
            'guest_action_at'     => current_time('mysql')
        ), array('voucher_code' => $voucher_code));

        $wpdb->insert($wpdb->prefix . 'ktv_auto_messages', array(
            'message_type'    => 'guest_voucher_action',
            'recipient_email' => $booking->email,
            'recipient_name'  => $booking->name,
            'subject'         => 'Guest requested modification: ' . $booking->booking_ref,
            'message_body'    => 'Guest requested modification. Details: ' . ($modify_request ?: 'N/A'),
            'booking_ref'     => $booking->booking_ref,
            'tour_name'       => $booking->tour_name,
            'tour_id'         => intval($booking->tour_id),
            'block_type'      => $booking->block_type,
            'send_status'     => 'sent',
            'sent_at'         => current_time('mysql')
        ));

        $admin_email = ktv_get_setting('admin_email', '');
        if (empty($admin_email)) {
            $admin_email = get_option('admin_email');
        }

        ktv_send_plain_email(
            $admin_email,
            'Modification Requested - ' . $booking->booking_ref,
            "Guest " . $booking->name . " requested a modification.\n\nBooking: " . $booking->booking_ref . "\nVoucher: " . $voucher_code . "\nRequest: " . ($modify_request ?: 'N/A') . "\n\nManage: " . admin_url('admin.php?page=ktv-bookings'),
            $booking->email
        );

        wp_send_json_success(array(
            'message' => 'Your modification request has been submitted. Our team will contact you shortly.',
            'action'  => 'modify'
        ));
        return;
    }

    wp_send_json_error(array('message' => 'Unhandled action.'));
}

