function ktv_generate_unique_slug($tour_name, $exclude_id = 0) {
    global $wpdb;
    $base_slug = sanitize_title($tour_name);
    if (empty($base_slug)) {
        $base_slug = 'tour-' . time();
    }
    $slug = $base_slug;
    $counter = 1;
    while (true) {
        $existing = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$wpdb->prefix}ktv_tours WHERE tour_slug = %s AND id != %d",
            $slug, $exclude_id
        ));
        if (!$existing) {
            return $slug;
        }
        $slug = $base_slug . '-' . $counter;
        $counter++;
        if ($counter > 100) {
            return $base_slug . '-' . time();
        }
    }
}

function ktv_get_smart_new_tours() {
    $found = array();
    $seen  = array();

    $posts = ktv_get_ktv_blocks_posts_scan();

    if (empty($posts)) {
        return array();
    }

    global $wpdb;
    $existing_names = $wpdb->get_col("SELECT LOWER(TRIM(tour_name)) FROM {$wpdb->prefix}ktv_tours WHERE is_hardcoded = 0");

    foreach ($posts as $post) {
        $blocks = ktv_parse_block_attributes($post->post_content);
        foreach ($blocks as $parsed) {
            $block_name = $parsed['block'];
            $attrs      = $parsed['attrs'];

            if (!in_array($block_name, array('tour-card', 'tour-grid', 'tour-package'), true)) {
                continue;
            }

            $block_type_default = 'grid';
            if ($block_name === 'tour-card') {
                $block_type_default = 'card';
            } elseif ($block_name === 'tour-package') {
                $block_type_default = 'package';
            }

            $name = '';
            if (!empty($attrs['title'])) {
                $name = $attrs['title'];
            } elseif (!empty($attrs['tourName'])) {
                $name = $attrs['tourName'];
            }

            if (!empty($name) && !ktv_is_tour_excluded($name)) {
                $lower = strtolower(trim($name));
                if (!in_array($lower, $existing_names, true) && !in_array($lower, $seen, true)) {
                    $seen[] = $lower;
                    $found[] = array(
                        'title' => $name,
                        'source_post' => intval($post->ID),
                        'block' => $block_name,
                        'block_type' => !empty($attrs['tour_block_type']) ? $attrs['tour_block_type'] : $block_type_default,
                        'price' => isset($attrs['price']) ? floatval($attrs['price']) : 0,
                        'offerPrice' => isset($attrs['offerPrice']) ? floatval($attrs['offerPrice']) : 0,
                        'location' => isset($attrs['location']) ? $attrs['location'] : '',
                        'attrs' => $attrs
                    );
                }
            }

            if (!empty($attrs['customTours']) && is_array($attrs['customTours'])) {
                foreach ($attrs['customTours'] as $ct) {
                    if (!is_array($ct) || empty($ct['title'])) {
                        continue;
                    }
                    $ct_name = $ct['title'];
                    if (ktv_is_tour_excluded($ct_name)) {
                        continue;
                    }
                    $lower = strtolower(trim($ct_name));
                    if (!in_array($lower, $existing_names, true) && !in_array($lower, $seen, true)) {
                        $seen[] = $lower;
                        $found[] = array(
                            'title' => $ct_name,
                            'source_post' => intval($post->ID),
                            'block' => $block_name,
                            'block_type' => !empty($ct['tour_block_type']) ? $ct['tour_block_type'] : $block_type_default,
                            'price' => isset($ct['price']) ? floatval($ct['price']) : 0,
                            'offerPrice' => isset($ct['offerPrice']) ? floatval($ct['offerPrice']) : 0,
                            'location' => isset($ct['location']) ? $ct['location'] : '',
                            'attrs' => $ct
                        );
                    }
                }
            }
        }
    }

    return $found;
}

function ktv_ajax_import_new_tours() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Permission denied'));
        return;
    }

    $found = ktv_get_smart_new_tours();
    if (empty($found)) {
        wp_send_json_success(array('message' => 'No new tours to import.', 'imported' => 0));
        return;
    }

    $imported = 0;
    $failed = 0;
    foreach ($found as $tour) {
        $result = ktv_upsert_block_tour(
            $tour['title'],
            $tour['attrs'],
            $tour['block_type'],
            $tour['source_post']
        );
        if ($result === 'added' || $result === 'updated') {
            $imported++;
        } else {
            $failed++;
        }
    }

    ktv_clear_tour_caches();

    wp_send_json_success(array(
        'message' => 'Imported ' . $imported . ' new tours.' . ($failed ? ' ' . $failed . ' failed.' : ''),
        'imported' => $imported,
        'failed' => $failed
    ));
}

function ktv_ajax_save_tour() {
    if (!check_ajax_referer('ktv_travel_nonce', 'nonce', false)) {
        wp_send_json_error(array('message' => 'Invalid security token'));
        return;
    }

    if (!current_user_can('manage_options') && !current_user_can('edit_posts')) {
        wp_send_json_error(array('message' => 'Permission denied'));
        return;
    }

    $tour_data_raw = isset($_POST['tour_data']) ? wp_unslash($_POST['tour_data']) : '';
    if (empty($tour_data_raw)) {
        wp_send_json_error(array('message' => 'No tour data provided'));
        return;
    }

    $tour_data = json_decode($tour_data_raw, true);
    if (json_last_error() !== JSON_ERROR_NONE || !is_array($tour_data)) {
        wp_send_json_error(array('message' => 'Invalid JSON data'));
        return;
    }

    if (empty($tour_data['tour_name'])) {
        wp_send_json_error(array('message' => 'Tour name is required'));
        return;
    }

    $tour_data['tour_name'] = trim($tour_data['tour_name']);

    global $wpdb;

    $tour_id = isset($tour_data['id']) ? intval($tour_data['id']) : 0;
    if ($tour_id > 0 && $tour_id > 1000000000) {
        $tour_id = 0;
    }

    $existing = $wpdb->get_var($wpdb->prepare(
        "SELECT id FROM {$wpdb->prefix}ktv_tours WHERE tour_name = %s AND id != %d AND is_hardcoded = 0",
        $tour_data['tour_name'],
        $tour_id
    ));

    if ($existing) {
        $tour_id = intval($existing);
    }

    $slug = ktv_generate_unique_slug($tour_data['tour_name'], $tour_id);

    $visible_pax = '';
    if (isset($tour_data['visiblePaxColumns'])) {
        if (is_array($tour_data['visiblePaxColumns'])) {
            $visible_pax = implode(',', array_filter(array_map('sanitize_key', $tour_data['visiblePaxColumns'])));
        } else {
            $visible_pax = sanitize_text_field($tour_data['visiblePaxColumns']);
        }
    }
    if (empty($visible_pax)) {
        $visible_pax = 'pax1';
    }

    $data = array(
        'tour_name'            => sanitize_text_field($tour_data['tour_name']),
        'tour_slug'            => $slug,
        'tour_price'           => floatval(isset($tour_data['tour_price']) ? $tour_data['tour_price'] : 0),
        'tour_offer_price'     => floatval(isset($tour_data['tour_offer_price']) ? $tour_data['tour_offer_price'] : 0),
        'tour_location'        => sanitize_text_field(isset($tour_data['tour_location']) ? $tour_data['tour_location'] : ''),
        'tour_city'            => sanitize_text_field(isset($tour_data['tour_city']) ? $tour_data['tour_city'] : ''),
        'tour_region'          => sanitize_text_field(isset($tour_data['tour_region']) ? $tour_data['tour_region'] : ''),
        'tour_country'         => sanitize_text_field(isset($tour_data['tour_country']) ? $tour_data['tour_country'] : 'India'),
        'tour_block_type'      => sanitize_text_field(isset($tour_data['tour_block_type']) ? $tour_data['tour_block_type'] : 'grid'),
        'tour_duration_nights' => intval(isset($tour_data['tour_duration_nights']) ? $tour_data['tour_duration_nights'] : 0),
        'tour_duration_days'   => intval(isset($tour_data['tour_duration_days']) ? $tour_data['tour_duration_days'] : 0),
        'badge_text'           => sanitize_text_field(isset($tour_data['badge_text']) ? $tour_data['badge_text'] : ''),
        'badge_color'          => sanitize_text_field(isset($tour_data['badge_color']) ? $tour_data['badge_color'] : '#ff5722'),
        'badge_icon'           => sanitize_text_field(isset($tour_data['badge_icon']) ? $tour_data['badge_icon'] : 'fa-star'),
        'badge_position'       => sanitize_text_field(isset($tour_data['badge_position']) ? $tour_data['badge_position'] : 'top-left'),
        'deal_badge_color'     => sanitize_text_field(isset($tour_data['deal_badge_color']) ? $tour_data['deal_badge_color'] : '#ff5722'),
        'deal_badge_text_color' => sanitize_text_field(isset($tour_data['deal_badge_text_color']) ? $tour_data['deal_badge_text_color'] : '#ffffff'),
        'deal_badge_position'  => sanitize_text_field(isset($tour_data['deal_badge_position']) ? $tour_data['deal_badge_position'] : 'bottom-right'),
