        'show_icons'           => isset($tour_data['show_icons']) ? (intval($tour_data['show_icons']) ? 1 : 0) : 1,
        'show_pax'             => isset($tour_data['show_pax']) ? (intval($tour_data['show_pax']) ? 1 : 0) : 1,
        'show_icon_enabled'    => isset($tour_data['show_icon_enabled']) ? (intval($tour_data['show_icon_enabled']) ? 1 : 0) : 1,
        'enable_icon_dropdown' => isset($tour_data['enable_icon_dropdown']) ? (intval($tour_data['enable_icon_dropdown']) ? 1 : 0) : 1,
        'enable_dark_mode'     => isset($tour_data['enable_dark_mode']) ? (intval($tour_data['enable_dark_mode']) ? 1 : 0) : 0,
        'icon_title'           => sanitize_text_field(isset($tour_data['icon_title']) ? $tour_data['icon_title'] : 'fa-map-marker-alt'),
        'icon_title_size'      => sanitize_text_field(isset($tour_data['icon_title_size']) ? $tour_data['icon_title_size'] : '20px'),
        'icon_title_color'     => sanitize_text_field(isset($tour_data['icon_title_color']) ? $tour_data['icon_title_color'] : '#075e54'),
        'is_hardcoded'         => 0,
        'is_ghost'             => 0,
        'is_synced'            => 1
    );

    $tours_table = $wpdb->prefix . 'ktv_tours';

    if ($tour_id > 0) {
        $result = ktv_db_update_safe($tours_table, $data, array('id' => $tour_id));
        if ($result !== false) {
            ktv_clear_tour_caches();
            wp_send_json_success(array(
                'message' => 'Tour updated successfully',
                'id'      => $tour_id
            ));
        } else {
            wp_send_json_error(array('message' => 'Failed to update tour: ' . $wpdb->last_error));
        }
    } else {
        $data['created_at'] = current_time('mysql');
        $result = ktv_db_insert_safe($tours_table, $data);
        if ($result !== false) {
            $insert_id = $wpdb->insert_id;
            ktv_clear_tour_caches();
            wp_send_json_success(array(
                'message' => 'Tour saved successfully',
                'id'      => $insert_id
            ));
        } else {
            wp_send_json_error(array('message' => 'Failed to save tour: ' . $wpdb->last_error));
        }
    }
}

function ktv_ajax_delete_tour() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Permission denied'));
        return;
    }

    $tour_id = isset($_POST['tour_id']) ? intval($_POST['tour_id']) : 0;

    if ($tour_id < 1) {
        wp_send_json_error(array('message' => 'Invalid tour ID'));
        return;
    }

    $result = ktv_delete_tour_completely($tour_id);

    if ($result) {
        wp_send_json_success(array('message' => 'Tour and related display data deleted successfully. Bookings preserved.'));
    } else {
        wp_send_json_error(array('message' => 'Failed to delete tour'));
    }
}

function ktv_ajax_get_tours() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

    $block_type = isset($_POST['block_type']) ? sanitize_text_field(wp_unslash($_POST['block_type'])) : 'all';

    global $wpdb;

    $where = "status = 'published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)";
    $params = array();

    if ($block_type !== 'all' && !empty($block_type)) {
        $where .= " AND tour_block_type = %s";
        $params[] = $block_type;
    }

    $sql = "SELECT * FROM {$wpdb->prefix}ktv_tours WHERE $where ORDER BY featured DESC, id ASC LIMIT 500";

    if (!empty($params)) {
        $sql = $wpdb->prepare($sql, $params);
    }

    $tours = $wpdb->get_results($sql);

    $filtered = array();
    if (!empty($tours)) {
        foreach ($tours as $t) {
            if (ktv_is_tour_excluded($t->tour_name)) {
                continue;
            }
            $block_type_val = $t->tour_block_type ?: 'grid';
            $t->icon_title  = ktv_resolve_tour_icon(isset($t->icon_title) ? $t->icon_title : '', $block_type_val);
            $t->icon_prefix = ktv_icon_to_prefix($t->icon_title);
            $filtered[] = $t;
        }
    }

    wp_send_json_success(array('tours' => $filtered));
}

function ktv_ajax_get_tour_by_id() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

    $tour_id = isset($_POST['tour_id']) ? intval($_POST['tour_id']) : 0;

    if ($tour_id < 1) {
        wp_send_json_error(array('message' => 'Invalid tour ID'));
        return;
    }

    global $wpdb;

    $tour = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_tours WHERE id = %d AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)",
        $tour_id
    ));

    if ($tour && ktv_is_tour_excluded($tour->tour_name)) {
        $tour = null;
    }

    if ($tour) {
        wp_send_json_success(array('tour' => $tour));
    } else {
        wp_send_json_error(array('message' => 'Tour not found'));
    }
}

function ktv_ajax_get_tour_reviews() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

    $tour_id = isset($_POST['tour_id']) ? intval($_POST['tour_id']) : 0;
    $page_id = isset($_POST['page_id']) ? intval($_POST['page_id']) : 0;
    $limit   = isset($_POST['limit'])   ? intval($_POST['limit'])   : 20;

    if ($limit < 1 || $limit > 50) {
        $limit = 20;
    }

    if ($tour_id < 1 && $page_id < 1) {
        wp_send_json_error(array('message' => 'Missing tour_id or page_id'));
        return;
    }

    global $wpdb;
    $reviews_table = $wpdb->prefix . 'ktv_reviews';
    $tours_table   = $wpdb->prefix . 'ktv_tours';

    if ($tour_id > 0) {
        $reviews = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$reviews_table} WHERE tour_id = %d AND status = 'approved' ORDER BY created_at DESC LIMIT %d",
            $tour_id, $limit
        ));
        $tour_name = $wpdb->get_var($wpdb->prepare(
            "SELECT tour_name FROM {$tours_table} WHERE id = %d AND is_hardcoded = 0",
            $tour_id
        ));
    } else {
        $reviews = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$reviews_table} WHERE page_id = %d AND status = 'approved' ORDER BY created_at DESC LIMIT %d",
            $page_id, $limit
        ));
        $tour_name = get_the_title($page_id);
    }

    if (empty($reviews)) {
        wp_send_json_success(array(
            'reviews'   => array(),
            'avg'       => 0,
            'total'     => 0,
            'tour_name' => $tour_name ? $tour_name : '',
            'html'      => '',
            'has_more'  => false
        ));
        return;
    }

    $total = count($reviews);
    $avg   = 0;
    foreach ($reviews as $r) {
        $avg += intval($r->rating);
    }
    $avg = $total > 0 ? round($avg / $total, 1) : 0;

    $star_size  = '16px';
    $star_color = '#FFD700';

    $reviews_html = '';
    foreach ($reviews as $review) {
        $avatar_url = !empty($review->reviewer_profile_pic)
            ? $review->reviewer_profile_pic
            : (!empty($review->reviewer_avatar)
                ? $review->reviewer_avatar
                : 'https://ui-avatars.com/api/?name=' . urlencode($review->reviewer_name) . '&background=28a745&color=fff&size=50');

        $stars = ktv_render_stars_html(floatval($review->rating), $star_size, $star_color);

        $reviews_html .= '<div class="ktv-review-card" data-rating="' . esc_attr($review->rating) . '" data-date="' . esc_attr($review->created_at) . '" data-language="' . esc_attr($review->review_language) . '" style="background:#fff;padding:20px;border-radius:12px;border:1px solid #e0e0e0;box-shadow:0 2px 8px rgba(0,0,0,0.04);margin-bottom:15px;">';
        $reviews_html .= '<div class="ktv-reviewer-info" style="display:flex;align-items:center;gap:12px;margin-bottom:10px;">';
        $reviews_html .= '<img src="' . esc_url($avatar_url) . '" class="ktv-reviewer-avatar" alt="" width="50" height="50" loading="lazy" decoding="async" style="width:50px;height:50px;border-radius:50%;object-fit:cover;">';
        $reviews_html .= '<div>';
        $reviews_html .= '<strong>' . esc_html($review->reviewer_name) . '</strong>';
        if ($review->verified) {
            $reviews_html .= '<span class="ktv-verified-badge" style="color:#28a745;font-size:12px;margin-left:8px;"><i class="fas fa-check-circle"></i> Verified</span>';
        }
        $reviews_html .= '<div class="ktv-review-date" style="font-size:12px;color:#999;">' . esc_html(ktv_time_ago($review->created_at)) . '</div>';
        $reviews_html .= '</div></div>';
        $reviews_html .= '<div class="ktv-stars" style="margin-bottom:8px;">' . $stars . '</div>';
        if (!empty($review->review_title)) {
            $reviews_html .= '<h4 style="font-size:16px;margin:5px 0;color:#333;">' . esc_html($review->review_title) . '</h4>';
        }
        $reviews_html .= '<div class="ktv-review-content" style="font-size:14px;color:#555;line-height:1.6;">' . wp_kses_post(wpautop($review->review_content)) . '</div>';
        if (!empty($review->review_image)) {
            $reviews_html .= '<div style="margin:10px 0;"><img src="' . esc_url($review->review_image) . '" alt="Review Image" width="200" height="200" loading="lazy" decoding="async" style="max-width:200px;border-radius:8px;border:1px solid #e0e0e0;" class="ktv-review-image-thumb" data-full="' . esc_url($review->review_image) . '"></div>';
        }
        $reviews_html .= '<div class="ktv-review-helpful" style="margin-top:10px;display:flex;gap:15px;font-size:12px;color:#999;">';
        $reviews_html .= '<button class="ktv-helpful-btn" data-review-id="' . esc_attr($review->id) . '" style="background:none;border:none;cursor:pointer;color:#666;font-size:12px;"><i class="far fa-thumbs-up"></i> Helpful (<span class="ktv-helpful-count">' . esc_html($review->helpful_count ?: 0) . '</span>)</button>';
        $reviews_html .= '</div>';
        if (!empty($review->reply_content)) {
            $reviews_html .= '<div class="ktv-review-reply" style="margin-top:12px;padding:12px 16px;background:#f0f8f0;border-radius:8px;border-left:3px solid #28a745;">';
            $reviews_html .= '<strong style="color:#075e54;font-size:13px;">Reply from Kashmir Travelling Voyage:</strong>';
            $reviews_html .= '<p style="margin:5px 0 0;font-size:13px;color:#555;">' . esc_html($review->reply_content) . '</p>';
            $reviews_html .= '</div>';
        }
        $reviews_html .= '</div>';
    }

    wp_send_json_success(array(
        'reviews'   => $reviews,
        'avg'       => $avg,
        'total'     => $total,
        'tour_name' => $tour_name ? $tour_name : '',
        'html'      => $reviews_html,
        'has_more'  => $total >= $limit
    ));
}

