function ktv_ajax_save_block_tours() {
    check_ajax_referer('ktv_travel_nonce', 'nonce');

    if (!current_user_can('manage_options')) {
        wp_send_json_error(array('message' => 'Permission denied'));
        return;
    }

    $tours_json = isset($_POST['tours']) ? wp_unslash($_POST['tours']) : '';
    if (empty($tours_json)) {
        wp_send_json_error(array('message' => 'No tours provided'));
        return;
    }

    $tours = json_decode($tours_json, true);
    if (!is_array($tours)) {
        wp_send_json_error(array('message' => 'Invalid data'));
        return;
    }

    global $wpdb;
    $saved_count = 0;
    $failed_count = 0;
    $saved_ids = array();
    $tours_table = $wpdb->prefix . 'ktv_tours';

    foreach ($tours as $tour) {
        if (!is_array($tour) || empty($tour['title'])) {
            $failed_count++;
            continue;
        }

        $title = trim($tour['title']);
        if (empty($title) || ktv_is_ghost_tour_name($title)) {
            $failed_count++;
            continue;
        }

        $existing_id = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$tours_table} WHERE tour_name = %s AND is_hardcoded = 0 LIMIT 1",
            $title
        ));

        $tour_block_type = isset($tour['tour_block_type']) ? $tour['tour_block_type'] : 'grid';
        if (!in_array($tour_block_type, array('grid', 'card', 'package'), true)) {
            $tour_block_type = 'grid';
        }

        $visible_pax = 'pax1';
        if (isset($tour['visiblePaxColumns'])) {
            if (is_array($tour['visiblePaxColumns'])) {
                $visible_pax = implode(',', array_filter(array_map('sanitize_key', $tour['visiblePaxColumns'])));
            } elseif (is_string($tour['visiblePaxColumns']) && $tour['visiblePaxColumns'] !== '') {
                $visible_pax = sanitize_text_field($tour['visiblePaxColumns']);
            }
        }

        $data = array(
            'tour_name'            => sanitize_text_field($title),
            'tour_price'           => floatval(isset($tour['price']) ? $tour['price'] : 0),
            'tour_offer_price'     => floatval(isset($tour['offerPrice']) ? $tour['offerPrice'] : 0),
            'tour_location'        => sanitize_text_field(isset($tour['location']) ? $tour['location'] : ''),
            'tour_block_type'      => $tour_block_type,
            'tour_duration_nights' => intval(isset($tour['durationNights']) ? $tour['durationNights'] : 0),
            'tour_duration_days'   => intval(isset($tour['durationDays']) ? $tour['durationDays'] : 0),
            'badge_text'           => sanitize_text_field(isset($tour['badgeText']) ? $tour['badgeText'] : ''),
            'badge_color'          => sanitize_text_field(isset($tour['badgeColor']) ? $tour['badgeColor'] : '#ff5722'),
            'badge_position'       => sanitize_text_field(isset($tour['badgePosition']) ? $tour['badgePosition'] : 'top-left'),
            'deal_badge_color'     => sanitize_text_field(isset($tour['dealBadgeColor']) ? $tour['dealBadgeColor'] : '#ff5722'),
            'deal_badge_text_color' => sanitize_text_field(isset($tour['dealBadgeTextColor']) ? $tour['dealBadgeTextColor'] : '#ffffff'),
            'deal_badge_position'  => sanitize_text_field(isset($tour['dealBadgePosition']) ? $tour['dealBadgePosition'] : 'bottom-right'),
            'tour_image_id'        => intval(isset($tour['imageId']) ? $tour['imageId'] : 0),
