            'pax_2_icon'           => sanitize_text_field(isset($tour['pax2Icon']) ? $tour['pax2Icon'] : 'fa-user-friends'),
            'pax_3_icon'           => sanitize_text_field(isset($tour['pax3Icon']) ? $tour['pax3Icon'] : 'fa-users'),
            'group_icon'           => sanitize_text_field(isset($tour['groupIcon']) ? $tour['groupIcon'] : 'fa-user-plus'),
            'family_icon'          => sanitize_text_field(isset($tour['familyIcon']) ? $tour['familyIcon'] : 'fa-home'),
            'group_max_persons'    => intval(isset($tour['groupMaxPersons']) ? $tour['groupMaxPersons'] : 0),
            'family_max_persons'   => intval(isset($tour['familyMaxPersons']) ? $tour['familyMaxPersons'] : 0),
            'visible_pax_columns'  => $visible_pax,
            'hotels_label'         => sanitize_text_field(isset($tour['hotelsLabel']) ? $tour['hotelsLabel'] : 'Hotels'),
            'hotels_icon'          => sanitize_text_field(isset($tour['hotelsIcon']) ? $tour['hotelsIcon'] : 'fa-hotel'),
            'meals_label'          => sanitize_text_field(isset($tour['mealsLabel']) ? $tour['mealsLabel'] : 'Meals'),
            'meals_icon'           => sanitize_text_field(isset($tour['mealsIcon']) ? $tour['mealsIcon'] : 'fa-utensils'),
            'transport_label'      => sanitize_text_field(isset($tour['transportLabel']) ? $tour['transportLabel'] : 'Transport'),
            'transport_icon'       => sanitize_text_field(isset($tour['transportIcon']) ? $tour['transportIcon'] : 'fa-car'),
            'sightseeing_label'    => sanitize_text_field(isset($tour['sightseeingLabel']) ? $tour['sightseeingLabel'] : 'Sightseeing'),
            'sightseeing_icon'     => sanitize_text_field(isset($tour['sightseeingIcon']) ? $tour['sightseeingIcon'] : 'fa-eye'),
            'flight_label'         => sanitize_text_field(isset($tour['flightLabel']) ? $tour['flightLabel'] : 'Flight'),
            'flight_icon'          => sanitize_text_field(isset($tour['flightIcon']) ? $tour['flightIcon'] : 'fa-plane'),
            'boat_label'           => sanitize_text_field(isset($tour['boatLabel']) ? $tour['boatLabel'] : 'Boat'),
            'boat_icon'            => sanitize_text_field(isset($tour['boatIcon']) ? $tour['boatIcon'] : 'fa-ship'),
            'horse_riding_label'   => sanitize_text_field(isset($tour['horseRidingLabel']) ? $tour['horseRidingLabel'] : 'Horse Riding'),
            'horse_riding_icon'    => sanitize_text_field(isset($tour['horseRidingIcon']) ? $tour['horseRidingIcon'] : 'fa-horse'),
            'trekking_label'       => sanitize_text_field(isset($tour['trekkingLabel']) ? $tour['trekkingLabel'] : 'Trekking'),
            'trekking_icon'        => sanitize_text_field(isset($tour['trekkingIcon']) ? $tour['trekkingIcon'] : 'fa-hiking'),
            'hiking_label'         => sanitize_text_field(isset($tour['hikingLabel']) ? $tour['hikingLabel'] : 'Hiking'),
            'hiking_icon'          => sanitize_text_field(isset($tour['hikingIcon']) ? $tour['hikingIcon'] : 'fa-mountain'),
            'is_hardcoded'         => 0,
            'is_ghost'             => 0,
            'is_synced'            => 1,
            'status'               => 'published'
        );

        if ($existing_id) {
            $result = ktv_db_update_safe($tours_table, $data, array('id' => $existing_id));
            if ($result !== false) {
                $saved_count++;
                $saved_ids[] = $existing_id;
            } else {
                $failed_count++;
            }
        } else {
            $data['tour_slug'] = ktv_generate_unique_slug($title);
            $data['created_at'] = current_time('mysql');
            $result = ktv_db_insert_safe($tours_table, $data);
            if ($result !== false) {
                $saved_count++;
                $saved_ids[] = $wpdb->insert_id;
            } else {
                $failed_count++;
            }
        }
    }

    ktv_clear_tour_caches();

    wp_send_json_success(array(
        'message' => 'Saved ' . $saved_count . ' tours.' . ($failed_count > 0 ? ' ' . $failed_count . ' failed.' : ''),
        'saved'   => $saved_count,
        'failed'  => $failed_count,
        'ids'     => $saved_ids
    ));
}
/* ============================================================
   53. SYNC ENGINE AND WP-CRON
   ============================================================ */

add_action('save_post', 'ktv_after_save_post_sync', 20, 1);
function ktv_after_save_post_sync($post_id) {
    if (wp_is_post_revision($post_id) || wp_is_post_autosave($post_id)) {
        return;
    }
    if (get_post_status($post_id) !== 'publish') {
        return;
    }

    $debounce_key = 'ktv_sync_debounce_' . intval($post_id);
    if (get_transient($debounce_key)) {
        return;
    }
    set_transient($debounce_key, '1', 15);

    static $syncing = false;
    if ($syncing) {
        return;
    }
    $syncing = true;

    $post = get_post($post_id);
    $has_ktv_block = $post && (
        strpos($post->post_content, 'wp:ktv/tour-card') !== false ||
        strpos($post->post_content, 'wp:ktv/tour-grid') !== false ||
        strpos($post->post_content, 'wp:ktv/tour-package') !== false
    );
    if ($has_ktv_block) {
        ktv_sync_all_block_tours_to_db();
    }

    ktv_clear_tour_caches();

    $syncing = false;
}

add_action('before_delete_post', 'ktv_before_delete_post_cleanup_tours', 10, 1);
function ktv_before_delete_post_cleanup_tours($post_id) {
    global $wpdb;
    $post_id = intval($post_id);
    if ($post_id < 1) {
        return;
    }
    $tours_table = $wpdb->prefix . 'ktv_tours';
    $columns = ktv_db_get_columns($tours_table);
    if (empty($columns) || !in_array('source_block_id', $columns, true)) {
        return;
    }
    $tours = $wpdb->get_col($wpdb->prepare(
        "SELECT id FROM {$tours_table} WHERE source_block_id = %d",
        $post_id
    ));
    if (!empty($tours)) {
        foreach ($tours as $tid) {
            ktv_delete_tour_completely(intval($tid));
        }
    }
    ktv_clear_tour_caches();
}

add_action('after_switch_theme', 'ktv_register_hourly_sync_cron');
function ktv_register_hourly_sync_cron() {
    if (!wp_next_scheduled('ktv_hourly_sync_block_tours')) {
        wp_schedule_event(time() + 60, 'hourly', 'ktv_hourly_sync_block_tours');
    }
}

add_action('ktv_hourly_sync_block_tours', 'ktv_run_hourly_sync');
function ktv_run_hourly_sync() {
    ktv_sync_all_block_tours_to_db();
}

add_action('switch_theme', 'ktv_cleanup_sync_cron');
function ktv_cleanup_sync_cron() {
    $timestamp = wp_next_scheduled('ktv_hourly_sync_block_tours');
    if ($timestamp) {
        wp_unschedule_event($timestamp, 'ktv_hourly_sync_block_tours');
    }
}

function ktv_sync_all_block_tours_to_db() {
    global $wpdb;

    $added   = 0;
    $updated = 0;
    $total   = 0;

    $posts = ktv_get_ktv_blocks_posts_scan();

    if (empty($posts)) {
        return array('added' => 0, 'updated' => 0, 'total' => 0);
    }

    foreach ($posts as $post) {
        $blocks = ktv_parse_block_attributes($post->post_content);
        if (empty($blocks)) {
            continue;
        }

        foreach ($blocks as $parsed) {
            $block_name = $parsed['block'];
            $attrs      = $parsed['attrs'];

            if (!in_array($block_name, array('tour-card', 'tour-grid', 'tour-package'), true)) {
                continue;
            }

            $block_type_default = 'grid';
            if ($block_name === 'tour-card') {
                $block_type_default = 'card';
            } elseif ($block_name === 'tour-package') {
                $block_type_default = 'package';
            }

            $name = '';
            if (!empty($attrs['title'])) {
                $name = $attrs['title'];
            } elseif (!empty($attrs['tourName'])) {
                $name = $attrs['tourName'];
            }

            if (!empty($name) && !ktv_is_tour_excluded($name)) {
                $total++;
                $block_type = !empty($attrs['tour_block_type']) ? $attrs['tour_block_type'] : $block_type_default;

                $insert_result = ktv_upsert_block_tour($name, $attrs, $block_type, $post->ID);
                if ($insert_result === 'added') {
                    $added++;
                } elseif ($insert_result === 'updated') {
                    $updated++;
                }
            }

            if (!empty($attrs['customTours']) && is_array($attrs['customTours'])) {
                foreach ($attrs['customTours'] as $ct) {
                    if (!is_array($ct) || empty($ct['title'])) {
                        continue;
                    }
                    $ct_name = $ct['title'];
                    if (ktv_is_tour_excluded($ct_name)) {
                        continue;
                    }
                    $total++;
                    $ct_block_type = !empty($ct['tour_block_type']) ? $ct['tour_block_type'] : $block_type_default;

                    $insert_result = ktv_upsert_block_tour($ct_name, $ct, $ct_block_type, $post->ID);
                    if ($insert_result === 'added') {
                        $added++;
                    } elseif ($insert_result === 'updated') {
                        $updated++;
                    }
                }
            }
        }
    }

    $all_db_tours = $wpdb->get_results(
        "SELECT id, tour_name, source_block_id FROM {$wpdb->prefix}ktv_tours
         WHERE is_hardcoded = 0 AND is_ghost = 0 AND source_block_id > 0"
    );
    if (!empty($all_db_tours)) {
        foreach ($all_db_tours as $db_tour) {
            $source_post = get_post($db_tour->source_block_id);
            if (!$source_post) {
                ktv_delete_tour_completely($db_tour->id);
                continue;
            }
            $still_present = false;
            $source_blocks = ktv_parse_block_attributes($source_post->post_content);
            if (!empty($source_blocks)) {
                foreach ($source_blocks as $parsed_block) {
                    $block_attrs = $parsed_block['attrs'];
                    $block_title = '';
                    if (!empty($block_attrs['title'])) {
                        $block_title = $block_attrs['title'];
                    } elseif (!empty($block_attrs['tourName'])) {
                        $block_title = $block_attrs['tourName'];
                    }
                    if (!empty($block_title) && strcasecmp(trim($block_title), trim($db_tour->tour_name)) === 0) {
                        $still_present = true;
                        break;
                    }
                    if (!empty($block_attrs['customTours']) && is_array($block_attrs['customTours'])) {
                        foreach ($block_attrs['customTours'] as $ct_item) {
                            if (!is_array($ct_item) || empty($ct_item['title'])) {
                                continue;
                            }
                            if (strcasecmp(trim($ct_item['title']), trim($db_tour->tour_name)) === 0) {
                                $still_present = true;
                                break 2;
                            }
                        }
                    }
                }
            }
            if (!$still_present) {
                ktv_delete_tour_completely($db_tour->id);
            }
        }
    }

    ktv_clear_tour_caches();

    return array('added' => $added, 'updated' => $updated, 'total' => $total);
}

function ktv_upsert_block_tour($name, $attrs, $block_type, $source_block_id) {
    global $wpdb;

    if (!in_array($block_type, array('grid', 'card', 'package'), true)) {
        $block_type = 'grid';
    }

    $existing_id = $wpdb->get_var($wpdb->prepare(
        "SELECT id FROM {$wpdb->prefix}ktv_tours WHERE tour_name = %s AND is_hardcoded = 0 LIMIT 1",
        $name
    ));

    $visible_pax = 'pax1';
    if (isset($attrs['visiblePaxColumns'])) {
        if (is_array($attrs['visiblePaxColumns'])) {
            $visible_pax = implode(',', array_filter(array_map('sanitize_key', $attrs['visiblePaxColumns'])));
        } elseif (is_string($attrs['visiblePaxColumns']) && $attrs['visiblePaxColumns'] !== '') {
            $visible_pax = sanitize_text_field($attrs['visiblePaxColumns']);
        }
    }
    if (empty($visible_pax)) {
        $visible_pax = 'pax1';
    }

    $image_id_value = 0;
    if (isset($attrs['imageId'])) {
        $image_id_value = intval($attrs['imageId']);
    } elseif (isset($attrs['tour_image_id'])) {
        $image_id_value = intval($attrs['tour_image_id']);
    } elseif (isset($attrs['image_id'])) {
        $image_id_value = intval($attrs['image_id']);
    }

    $duration_nights = 0;
    if (isset($attrs['durationNights'])) {
        $duration_nights = intval($attrs['durationNights']);
    } elseif (isset($attrs['nights'])) {
        $duration_nights = intval($attrs['nights']);
    }

    $duration_days = 0;
    if (isset($attrs['durationDays'])) {
        $duration_days = intval($attrs['durationDays']);
    } elseif (isset($attrs['days'])) {
        $duration_days = intval($attrs['days']);
    }

    $icon_title_value = 'fa-map-marker-alt';
    if (isset($attrs['iconTitle']) && !empty($attrs['iconTitle'])) {
        $icon_title_value = sanitize_text_field($attrs['iconTitle']);
    } elseif (isset($attrs['icon_title']) && !empty($attrs['icon_title'])) {
        $icon_title_value = sanitize_text_field($attrs['icon_title']);
    }

    $data = array(
        'tour_name'            => sanitize_text_field($name),
        'tour_price'           => floatval(isset($attrs['price']) ? $attrs['price'] : 0),
        'tour_offer_price'     => floatval(isset($attrs['offerPrice']) ? $attrs['offerPrice'] : 0),
        'tour_location'        => sanitize_text_field(isset($attrs['location']) ? $attrs['location'] : ''),
        'tour_block_type'      => $block_type,
        'tour_duration_nights' => $duration_nights,
        'tour_duration_days'   => $duration_days,
        'badge_text'           => sanitize_text_field(isset($attrs['badgeText']) ? $attrs['badgeText'] : ''),
        'badge_color'          => sanitize_text_field(isset($attrs['badgeColor']) ? $attrs['badgeColor'] : '#ff5722'),
        'badge_position'       => sanitize_text_field(isset($attrs['badgePosition']) ? $attrs['badgePosition'] : 'top-left'),
        'deal_badge_color'     => sanitize_text_field(isset($attrs['dealBadgeColor']) ? $attrs['dealBadgeColor'] : '#ff5722'),
        'deal_badge_text_color' => sanitize_text_field(isset($attrs['dealBadgeTextColor']) ? $attrs['dealBadgeTextColor'] : '#ffffff'),
        'deal_badge_position'  => sanitize_text_field(isset($attrs['dealBadgePosition']) ? $attrs['dealBadgePosition'] : 'bottom-right'),
        'tour_image_id'        => $image_id_value,
        'image_link_url'       => sanitize_text_field(isset($attrs['imageLink']) ? $attrs['imageLink'] : ''),
        'image_display_size'   => sanitize_text_field(isset($attrs['imageDisplaySize']) ? $attrs['imageDisplaySize'] : 'medium'),
        'tour_brief_text'      => sanitize_textarea_field(isset($attrs['briefText']) ? $attrs['briefText'] : ''),
        'tour_after_title_text' => sanitize_text_field(isset($attrs['afterTitleText']) ? $attrs['afterTitleText'] : ''),
        'icon_title'           => $icon_title_value,
        'night_icon'           => sanitize_text_field(isset($attrs['nightIcon']) ? $attrs['nightIcon'] : 'fa-moon'),
        'night_icon_color'     => sanitize_text_field(isset($attrs['nightIconColor']) ? $attrs['nightIconColor'] : '#FFD700'),
        'day_icon'             => sanitize_text_field(isset($attrs['dayIcon']) ? $attrs['dayIcon'] : 'fa-sun'),
        'day_icon_color'       => sanitize_text_field(isset($attrs['dayIconColor']) ? $attrs['dayIconColor'] : '#FFA500'),
        'show_night_day_icons' => isset($attrs['showNightDayIcons']) ? (intval($attrs['showNightDayIcons']) ? 1 : 0) : 1,
        'pax_1_price'          => floatval(isset($attrs['pax1Price']) ? $attrs['pax1Price'] : 0),
        'pax_2_price'          => floatval(isset($attrs['pax2Price']) ? $attrs['pax2Price'] : 0),
        'pax_3_price'          => floatval(isset($attrs['pax3Price']) ? $attrs['pax3Price'] : 0),
        'group_price'          => floatval(isset($attrs['groupPrice']) ? $attrs['groupPrice'] : 0),
        'family_price'         => floatval(isset($attrs['familyPrice']) ? $attrs['familyPrice'] : 0),
        'extra_adult_price'    => floatval(isset($attrs['extraAdultPrice']) ? $attrs['extraAdultPrice'] : 0),
        'extra_child_price'    => floatval(isset($attrs['extraChildPrice']) ? $attrs['extraChildPrice'] : 0),
        'pax_1_label'          => sanitize_text_field(isset($attrs['pax1Label']) ? $attrs['pax1Label'] : '1 Pax'),
        'pax_2_label'          => sanitize_text_field(isset($attrs['pax2Label']) ? $attrs['pax2Label'] : '2 Pax'),
        'pax_3_label'          => sanitize_text_field(isset($attrs['pax3Label']) ? $attrs['pax3Label'] : '3 Pax'),
        'group_label'          => sanitize_text_field(isset($attrs['groupLabel']) ? $attrs['groupLabel'] : 'Group'),
        'family_label'         => sanitize_text_field(isset($attrs['familyLabel']) ? $attrs['familyLabel'] : 'Family'),
        'pax_1_icon'           => sanitize_text_field(isset($attrs['pax1Icon']) ? $attrs['pax1Icon'] : 'fa-user'),
        'pax_2_icon'           => sanitize_text_field(isset($attrs['pax2Icon']) ? $attrs['pax2Icon'] : 'fa-user-friends'),
        'pax_3_icon'           => sanitize_text_field(isset($attrs['pax3Icon']) ? $attrs['pax3Icon'] : 'fa-users'),
        'group_icon'           => sanitize_text_field(isset($attrs['groupIcon']) ? $attrs['groupIcon'] : 'fa-user-plus'),
        'family_icon'          => sanitize_text_field(isset($attrs['familyIcon']) ? $attrs['familyIcon'] : 'fa-home'),
        'group_max_persons'    => intval(isset($attrs['groupMaxPersons']) ? $attrs['groupMaxPersons'] : 0),
        'family_max_persons'   => intval(isset($attrs['familyMaxPersons']) ? $attrs['familyMaxPersons'] : 0),
        'visible_pax_columns'  => $visible_pax,
        'hotels_label'         => sanitize_text_field(isset($attrs['hotelsLabel']) ? $attrs['hotelsLabel'] : 'Hotels'),
        'hotels_icon'          => sanitize_text_field(isset($attrs['hotelsIcon']) ? $attrs['hotelsIcon'] : 'fa-hotel'),
        'meals_label'          => sanitize_text_field(isset($attrs['mealsLabel']) ? $attrs['mealsLabel'] : 'Meals'),
        'meals_icon'           => sanitize_text_field(isset($attrs['mealsIcon']) ? $attrs['mealsIcon'] : 'fa-utensils'),
        'transport_label'      => sanitize_text_field(isset($attrs['transportLabel']) ? $attrs['transportLabel'] : 'Transport'),
        'transport_icon'       => sanitize_text_field(isset($attrs['transportIcon']) ? $attrs['transportIcon'] : 'fa-car'),
        'sightseeing_label'    => sanitize_text_field(isset($attrs['sightseeingLabel']) ? $attrs['sightseeingLabel'] : 'Sightseeing'),
        'sightseeing_icon'     => sanitize_text_field(isset($attrs['sightseeingIcon']) ? $attrs['sightseeingIcon'] : 'fa-eye'),
        'flight_label'         => sanitize_text_field(isset($attrs['flightLabel']) ? $attrs['flightLabel'] : 'Flight'),
        'flight_icon'          => sanitize_text_field(isset($attrs['flightIcon']) ? $attrs['flightIcon'] : 'fa-plane'),
        'boat_label'           => sanitize_text_field(isset($attrs['boatLabel']) ? $attrs['boatLabel'] : 'Boat'),
        'boat_icon'            => sanitize_text_field(isset($attrs['boatIcon']) ? $attrs['boatIcon'] : 'fa-ship'),
        'horse_riding_label'   => sanitize_text_field(isset($attrs['horseRidingLabel']) ? $attrs['horseRidingLabel'] : 'Horse Riding'),
        'horse_riding_icon'    => sanitize_text_field(isset($attrs['horseRidingIcon']) ? $attrs['horseRidingIcon'] : 'fa-horse'),
        'trekking_label'       => sanitize_text_field(isset($attrs['trekkingLabel']) ? $attrs['trekkingLabel'] : 'Trekking'),
        'trekking_icon'        => sanitize_text_field(isset($attrs['trekkingIcon']) ? $attrs['trekkingIcon'] : 'fa-hiking'),
        'hiking_label'         => sanitize_text_field(isset($attrs['hikingLabel']) ? $attrs['hikingLabel'] : 'Hiking'),
        'hiking_icon'          => sanitize_text_field(isset($attrs['hikingIcon']) ? $attrs['hikingIcon'] : 'fa-mountain'),
        'is_hardcoded'         => 0,
        'is_ghost'             => 0,
        'is_synced'            => 1,
        'source_block_id'      => intval($source_block_id),
        'featured'             => (isset($attrs['featured']) && $attrs['featured']) ? 1 : 0,
        'status'               => 'published'
    );

    $tours_table = $wpdb->prefix . 'ktv_tours';

    if ($existing_id) {
        ktv_db_update_safe($tours_table, $data, array('id' => $existing_id));
        return 'updated';
    } else {
        $data['tour_slug']  = ktv_generate_unique_slug($name);
        $data['created_at'] = current_time('mysql');
        ktv_db_insert_safe($tours_table, $data);
        return 'added';
    }
}

