add_action('admin_menu', 'ktv_register_admin_menu');
function ktv_register_admin_menu() {
    $notice_count = ktv_get_booking_notice_count();
    $bookings_label = 'Bookings';
    if ($notice_count > 0) {
        $bookings_label = 'Bookings <span class="awaiting-mod ktv-notice-badge">' . $notice_count . '</span>';
    }

    add_menu_page('KTV Travel', 'KTV Travel', 'manage_options', 'ktv-dashboard', 'ktv_admin_dashboard', 'dashicons-palmtree', 25);
    add_submenu_page('ktv-dashboard', 'KTV Bookings', $bookings_label, 'manage_options', 'ktv-bookings', 'ktv_admin_bookings');
    add_submenu_page('ktv-dashboard', 'KTV Tours', 'Tours', 'manage_options', 'ktv-tours', 'ktv_admin_tours');
    add_submenu_page('ktv-dashboard', 'KTV Flights', 'Flights', 'manage_options', 'ktv-flights', 'ktv_admin_flights');
    add_submenu_page('ktv-dashboard', 'KTV Contacts', 'Contacts', 'manage_options', 'ktv-contacts', 'ktv_admin_contacts');
    add_submenu_page('ktv-dashboard', 'KTV Reviews', 'Reviews', 'manage_options', 'ktv-reviews', 'ktv_admin_reviews');
    add_submenu_page('ktv-dashboard', 'KTV Auto Messages', 'Auto Messages', 'manage_options', 'ktv-auto-messages', 'ktv_admin_auto_messages');
    add_submenu_page('ktv-dashboard', 'KTV Accordion', 'Accordion', 'manage_options', 'ktv-accordion', 'ktv_admin_accordion');
    add_submenu_page('ktv-dashboard', 'KTV Tabs', 'Tabs', 'manage_options', 'ktv-tabs-admin', 'ktv_admin_tabs');
    add_submenu_page('ktv-dashboard', 'KTV Locations', 'Locations', 'manage_options', 'ktv-locations', 'ktv_admin_locations');
    add_submenu_page('ktv-dashboard', 'KTV Voucher', 'Voucher', 'manage_options', 'ktv-voucher', 'ktv_admin_voucher');
    add_submenu_page('ktv-dashboard', 'KTV Spam Protection', 'Honeypot & Spam', 'manage_options', 'ktv-spam-settings', 'ktv_admin_spam_settings');
    add_submenu_page('ktv-dashboard', 'KTV Settings', 'Settings', 'manage_options', 'ktv-settings', 'ktv_admin_settings');
}

add_action('admin_notices', 'ktv_admin_booking_notice');
function ktv_admin_booking_notice() {
    if (!current_user_can('manage_options')) {
        return;
    }
    if (!isset($_GET['page']) || strpos(sanitize_text_field(wp_unslash($_GET['page'])), 'ktv') === false) {
        return;
    }

    $unread_count = ktv_get_booking_notice_count();

    if ($unread_count > 0) {
        echo '<div class="notice notice-info is-dismissible" style="border-left:4px solid #075e54;">';
        echo '<p><strong>🔔 KTV Travel:</strong> You have <strong>' . esc_html($unread_count) . '</strong> new booking' . ($unread_count > 1 ? 's' : '') . '. ';
        echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-bookings')) . '" class="button button-primary button-small">View Bookings</a> ';
        echo '<button type="button" class="button button-small" id="ktv-mark-read-btn">Mark All Read</button></p>';
        echo '</div>';
    }

    $diag = ktv_diagnose_email();
    if (empty($diag['admin_email']) || empty($diag['admin_valid'])) {
        echo '<div class="notice notice-error" style="border-left:4px solid #dc3545;">';
        echo '<p><strong>⚠️ KTV Travel — Email Configuration:</strong> Admin email is missing or invalid. ';
        echo 'Booking confirmation emails will not reach you. ';
        echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-settings')) . '" class="button button-primary button-small">Fix in Settings</a></p>';
        echo '</div>';
    } elseif ($diag['is_local_domain']) {
        echo '<div class="notice notice-warning" style="border-left:4px solid #ffc107;">';
        echo '<p><strong>⚠️ KTV Travel — Email Warning:</strong> Your site URL appears to be a local/test domain (<code>' . esc_html($diag['site_domain']) . '</code>). ';
        echo 'Emails may not deliver. Configure an SMTP plugin or install on a production domain.</p>';
        echo '</div>';
    }

    if (!ktv_is_honeypot_enabled()) {
        echo '<div class="notice notice-warning is-dismissible" style="border-left:4px solid #ffc107;">';
        echo '<p><strong>🍯 KTV Travel — Honeypot Disabled:</strong> Spam protection honeypot is currently OFF. ';
        echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-spam-settings')) . '" class="button button-primary button-small">Enable Honeypot</a></p>';
        echo '</div>';
    }

    if (isset($_GET['page']) && sanitize_text_field(wp_unslash($_GET['page'])) === 'ktv-tours') {
        $new_tours = ktv_get_smart_new_tours();
        if (!empty($new_tours)) {
            echo '<div class="notice notice-warning is-dismissible" style="border-left:4px solid #ff9800;">';
            echo '<p><strong>🆕 KTV Travel — Smart Detection:</strong> Found <strong>' . count($new_tours) . '</strong> tour(s) in your blocks/pages not yet in the database. ';
            echo '<button type="button" class="button button-primary button-small" id="ktv-import-new-tours-btn">Import All Now</button></p>';
            echo '<div id="ktv-import-new-tours-result" style="margin:5px 0;"></div>';
            echo '</div>';
        }
    }
}

/* ============================================================
   55. ADMIN DASHBOARD
   ============================================================ */

function ktv_admin_dashboard() {
    global $wpdb;

    $bookings      = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_bookings");
    $tours         = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_tours WHERE status = 'published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)");
    $flights       = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_flights");
    $contacts      = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_contacts WHERE status = 'unread'");
    $reviews       = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_reviews WHERE status = 'pending'");
    $locations     = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_tour_locations");
    $auto_messages = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_auto_messages");
    $ghost_count   = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_tours WHERE is_hardcoded = 1 OR is_ghost = 1");
    $cancel_requests = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_bookings WHERE booking_status = 'cancel_requested'");
    $blocked_total = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_blocked_log");

    $all_tours = $wpdb->get_results(
        "SELECT id, tour_name, tour_block_type, tour_price, tour_offer_price,
               tour_location, status, total_reviews, tour_rating, featured,
               badge_text, badge_color, badge_position, created_at,
               last_booking_name, last_booking_country, last_booking_time, last_booking_count,
               promo_code, promo_discount, icon_title, tour_image_id, is_hardcoded, is_ghost
        FROM {$wpdb->prefix}ktv_tours
        WHERE is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)
        ORDER BY featured DESC, id DESC
        LIMIT 50"
    );

    $ghost_tours = $wpdb->get_results(
        "SELECT id, tour_name, tour_block_type, tour_price, status
        FROM {$wpdb->prefix}ktv_tours
        WHERE is_hardcoded = 1 OR is_ghost = 1
        ORDER BY id DESC
        LIMIT 50"
    );

    $grid_count    = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_tours WHERE tour_block_type = 'grid' AND status = 'published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)");
    $package_count = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_tours WHERE tour_block_type = 'package' AND status = 'published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)");
    $card_count    = $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_tours WHERE tour_block_type = 'card' AND status = 'published' AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)");

    $recent_bookings = $wpdb->get_results(
        "SELECT id, booking_ref, voucher_code, name, email, tour_type, tour_name,
               total_amount, currency, booking_status, created_at, block_type,
               adults, children, is_read, user_ip, user_country, user_city, user_region, user_device, travel_location
        FROM {$wpdb->prefix}ktv_bookings
        ORDER BY id DESC
        LIMIT 10"
    );

    echo '<div class="wrap">';
    echo '<h1>🏔️ KTV Travel Dashboard</h1>';
    echo '<p style="font-size:14px;color:#666;">All KTV blocks available in WordPress editor under "KTV Travel Blocks" category. Version ' . esc_html(KTV_TRAVEL_VERSION) . '</p>';

    $diag = ktv_diagnose_email();
    if (empty($diag['admin_email']) || empty($diag['admin_valid'])) {
        echo '<div class="notice notice-error" style="border-left:4px solid #dc3545;padding:12px;">';
        echo '<p><strong>⚠️ Email Configuration Issue:</strong> Admin email is missing or invalid. Booking confirmation emails will not reach you. ';
        echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-settings')) . '" class="button button-primary button-small">Fix in Settings</a></p>';
        echo '<p style="font-size:12px;color:#666;margin:5px 0 0;"><strong>Diagnostic:</strong> From: ' . esc_html($diag['from_email']) . ' | Reply-To: ' . esc_html($diag['reply_to']) . ' | Admin: ' . esc_html($diag['admin_email']) . '</p>';
        echo '</div>';
    }

    if ($cancel_requests > 0) {
        echo '<div class="notice notice-warning" style="border-left:4px solid #6c757d;padding:12px;">';
        echo '<p><strong>⚠️ Pending Cancellation Requests:</strong> ' . esc_html($cancel_requests) . ' booking(s) waiting for your approval. ';
        echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-bookings&status=cancel_requested')) . '" class="button button-primary button-small">Review Now</a></p>';
        echo '</div>';
    }

    echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:15px;margin-top:20px;">';
    $stats = array(
        array('value' => $bookings, 'label' => 'Total Bookings', 'color' => '#075e54'),
        array('value' => $tours, 'label' => 'Active Tours', 'color' => '#ff5722'),
        array('value' => $flights, 'label' => 'Flights', 'color' => '#2196F3'),
        array('value' => $contacts, 'label' => 'Unread Messages', 'color' => '#dc3545'),
        array('value' => $reviews, 'label' => 'Pending Reviews', 'color' => '#FFD700'),
        array('value' => $locations, 'label' => 'Locations', 'color' => '#17a2b8'),
        array('value' => $auto_messages, 'label' => 'Auto Messages', 'color' => '#6f42c1'),
        array('value' => $blocked_total, 'label' => 'Blocked (Spam)', 'color' => '#dc3545')
    );

    foreach ($stats as $stat) {
        echo '<div style="background:#fff;padding:20px;border-radius:10px;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><h2 style="color:' . esc_attr($stat['color']) . ';margin:0;font-size:36px;">' . esc_html($stat['value']) . '</h2><p style="margin:5px 0 0;">' . esc_html($stat['label']) . '</p></div>';
    }
    echo '</div>';

    echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:15px;margin-top:20px;">';
    $block_stats = array(
        array('icon' => '📐', 'label' => 'KTV Tour Grid', 'count' => $grid_count, 'color' => '#0d47a1', 'bg' => '#e3f2fd'),
        array('icon' => '📦', 'label' => 'KTV Tour Package', 'count' => $package_count, 'color' => '#e65100', 'bg' => '#fff3e0'),
        array('icon' => '🃏', 'label' => 'KTV Tour Card', 'count' => $card_count, 'color' => '#1b5e20', 'bg' => '#e8f5e9')
    );

    foreach ($block_stats as $bs) {
        echo '<div style="background:' . esc_attr($bs['bg']) . ';padding:15px;border-radius:10px;text-align:center;border-left:4px solid ' . esc_attr($bs['color']) . ';"><h3 style="margin:0;color:' . esc_attr($bs['color']) . ';">' . esc_html($bs['icon']) . ' ' . esc_html($bs['label']) . '</h3><h2 style="margin:5px 0;color:' . esc_attr($bs['color']) . ';">' . esc_html($bs['count']) . '</h2><p style="margin:0;font-size:12px;color:#666;">Tours in ' . esc_html($bs['label']) . ' Layout</p></div>';
    }
    echo '</div>';

    $dark_mode_status = ktv_is_dark_mode_enabled();
    $credit_card_status = ktv_is_credit_card_enabled();
    $honeypot_status = ktv_is_honeypot_enabled();
    $spam_filter_status = ktv_is_spam_filter_enabled();
    $currency_mode = ktv_get_setting('currency_mode', 'auto');
    $currency_code = ktv_get_currency_code();

    echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:15px;margin-top:20px;">';
    echo '<div style="background:' . ($dark_mode_status ? '#1a1a2e' : '#f0f4f8') . ';color:' . ($dark_mode_status ? '#e0e0e0' : '#333') . ';padding:15px;border-radius:10px;">';
    echo '<h3 style="margin-top:0;">🌙 Dark Mode</h3>';
    echo '<p style="margin:0;font-size:13px;">Status: <strong>' . ($dark_mode_status ? 'ENABLED' : 'DISABLED') . '</strong></p>';
    echo '<p style="margin:5px 0 0;font-size:12px;"><a href="' . esc_url(admin_url('admin.php?page=ktv-settings')) . '" style="color:' . ($dark_mode_status ? '#81c784' : '#075e54') . ';">Change in Settings →</a></p>';
    echo '</div>';
    echo '<div style="background:#f0f4f8;padding:15px;border-radius:10px;">';
    echo '<h3 style="margin-top:0;">💳 Credit Card Payments</h3>';
    echo '<p style="margin:0;font-size:13px;">Status: <strong>' . ($credit_card_status ? 'ENABLED' : 'DISABLED') . '</strong></p>';
    echo '<p style="margin:5px 0 0;font-size:12px;"><a href="' . esc_url(admin_url('admin.php?page=ktv-settings')) . '" style="color:#075e54;">Change in Settings →</a></p>';
    echo '</div>';
    echo '<div style="background:' . (($honeypot_status && $spam_filter_status) ? '#e8f5e9' : '#fff3cd') . ';padding:15px;border-radius:10px;">';
    echo '<h3 style="margin-top:0;">🛡️ Honeypot &amp; Spam Filter</h3>';
    echo '<p style="margin:0;font-size:13px;">Honeypot: <strong>' . ($honeypot_status ? 'ENABLED' : 'DISABLED') . '</strong></p>';
    echo '<p style="margin:5px 0 0;font-size:13px;">Spam Filter: <strong>' . ($spam_filter_status ? 'ENABLED' : 'DISABLED') . '</strong></p>';
    echo '<p style="margin:5px 0 0;font-size:12px;"><a href="' . esc_url(admin_url('admin.php?page=ktv-spam-settings')) . '" style="color:#075e54;">Manage Protection →</a></p>';
    echo '</div>';
    echo '<div style="background:#e3f2fd;padding:15px;border-radius:10px;">';
    echo '<h3 style="margin-top:0;">💱 Currency Mode</h3>';
    echo '<p style="margin:0;font-size:13px;">Mode: <strong>' . ($currency_mode === 'auto' ? 'AUTO (IP-based)' : 'MANUAL') . '</strong></p>';
    echo '<p style="margin:5px 0 0;font-size:13px;">Detected: <strong>' . esc_html($currency_code) . ' ' . esc_html(ktv_get_currency_symbol()) . '</strong></p>';
    echo '<p style="margin:5px 0 0;font-size:12px;"><a href="' . esc_url(admin_url('admin.php?page=ktv-settings')) . '" style="color:#075e54;">Change Currency →</a></p>';
    echo '</div>';
    echo '<div style="background:#f0f4f8;padding:15px;border-radius:10px;">';
    echo '<h3 style="margin-top:0;">🎫 Voucher Branding</h3>';
    $voucher_logo = ktv_get_voucher_logo_url();
    $voucher_logo_data = ktv_get_voucher_logo_data_uri();
    $data_len = strlen($voucher_logo_data);
    echo '<p style="margin:0;font-size:12px;">Logo URL: ' . ($voucher_logo ? '✅ Set' : '⚠️ Not set') . '</p>';
    echo '<p style="margin:5px 0 0;font-size:12px;">Inline Data URI: ' . ($data_len > 0 ? '✅ ' . round($data_len / 1024, 1) . ' KB' : '⚠️ Failed — emails may not show logo') . '</p>';
    echo '<p style="margin:5px 0 0;font-size:12px;"><a href="' . esc_url(admin_url('admin.php?page=ktv-voucher')) . '" style="color:#075e54;">Manage Voucher →</a></p>';
    echo '</div>';
    echo '</div>';

    if ($ghost_count > 0) {
        echo '<div style="margin-top:25px;background:#fff3cd;padding:20px;border-radius:12px;border-left:4px solid #ffc107;">';
        echo '<h3 style="margin-top:0;">⚠️ Hardcoded/Ghost Tours Detected: ' . esc_html($ghost_count) . '</h3>';
        echo '<p>These tours are filtered out of Booking Form select dropdown automatically. You can delete them permanently.</p>';
        echo '<button class="button button-primary" id="ktv-purge-ghost-btn">🗑️ Purge All Hardcoded Tours</button>';
        echo '<div id="ktv-purge-result" style="margin-top:10px;"></div>';
        echo '</div>';
    }

    echo '<div style="margin-top:25px;background:#e8f5e9;padding:20px;border-radius:12px;border-left:4px solid #28a745;">';
    echo '<h3 style="margin-top:0;">🔄 Sync Tours From Blocks</h3>';
    echo '<p>Scan all pages/posts for KTV Tour blocks and register them into your database automatically. Runs every hour via WP-Cron.</p>';
    echo '<button class="button button-primary" id="ktv-sync-blocks-btn">🔄 Sync Now</button>';
    echo '<div id="ktv-sync-blocks-result" style="margin-top:10px;"></div>';
    echo '</div>';

    echo '<div style="margin-top:25px;background:#f0f4f8;padding:20px;border-radius:12px;">';
    echo '<h3>📋 Recent Bookings (Ref &amp; Voucher)</h3>';

    if (!empty($recent_bookings)) {
        echo '<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:8px;overflow:hidden;">';
        echo '<thead><tr style="background:#075e54;color:#fff;">';
        echo '<th style="padding:10px 12px;text-align:left;">ID</th>';
        echo '<th style="padding:10px 12px;text-align:left;">Booking Ref</th>';
        echo '<th style="padding:10px 12px;text-align:left;">Voucher Code</th>';
        echo '<th style="padding:10px 12px;text-align:left;">Name</th>';
        echo '<th style="padding:10px 12px;text-align:left;">Tour</th>';
        echo '<th style="padding:10px 12px;text-align:left;">Total</th>';
        echo '<th style="padding:10px 12px;text-align:left;">Block Type</th>';
        echo '<th style="padding:10px 12px;text-align:left;">Status</th>';
        echo '<th style="padding:10px 12px;text-align:left;">Date</th>';
        echo '</tr></thead><tbody>';

        foreach ($recent_bookings as $booking) {
            $block_type_source = '';
            if ($booking->block_type === 'grid') {
                $block_type_source = '📐 KTV Tour Grid';
            } elseif ($booking->block_type === 'package') {
                $block_type_source = '📦 KTV Tour Package';
            } elseif ($booking->block_type === 'card') {
                $block_type_source = '🃏 KTV Tour Card';
            } else {
                $block_type_source = 'Unknown';
            }

            $status_color = '#dc3545';
            if ($booking->booking_status === 'confirmed') {
                $status_color = '#28a745';
            } elseif ($booking->booking_status === 'pending') {
                $status_color = '#ffc107';
            } elseif ($booking->booking_status === 'modified') {
                $status_color = '#17a2b8';
            } elseif ($booking->booking_status === 'cancel_requested' || $booking->booking_status === 'modify_requested') {
                $status_color = '#6c757d';
            }

            $tour_display = !empty($booking->tour_name) ? $booking->tour_name : $booking->tour_type;

            echo '<tr style="border-bottom:1px solid #eee;' . (isset($booking->is_read) && $booking->is_read == 0 ? 'background:#fff8e1;' : '') . '">';
            echo '<td style="padding:10px 12px;"><strong>#' . esc_html($booking->id) . '</strong></td>';
            echo '<td style="padding:10px 12px;"><strong style="color:#075e54;">' . esc_html($booking->booking_ref) . '</strong></td>';
            echo '<td style="padding:10px 12px;"><span style="color:#ff5722;font-weight:600;">' . esc_html($booking->voucher_code ?: '—') . '</span></td>';
            echo '<td style="padding:10px 12px;">' . esc_html($booking->name) . '<br><small style="color:#999;">' . esc_html($booking->email) . '</small></td>';
            echo '<td style="padding:10px 12px;">' . esc_html($tour_display) . '</td>';
            echo '<td style="padding:10px 12px;"><strong style="color:#28a745;">' . esc_html($booking->currency . ' ' . number_format($booking->total_amount, 2)) . '</strong></td>';
            echo '<td style="padding:10px 12px;"><span style="background:#e8f5e9;padding:2px 10px;border-radius:12px;font-size:11px;">' . esc_html($block_type_source) . '</span></td>';
            echo '<td style="padding:10px 12px;"><span style="color:' . esc_attr($status_color) . ';font-weight:600;">' . esc_html(ucfirst(str_replace('_', ' ', $booking->booking_status))) . '</span></td>';
            echo '<td style="padding:10px 12px;font-size:12px;color:#999;">' . esc_html($booking->created_at) . '</td>';
            echo '</tr>';
        }

        echo '</tbody></table>';
        echo '<div style="margin-top:10px;text-align:right;"><a href="' . esc_url(admin_url('admin.php?page=ktv-bookings')) . '" class="button">View All Bookings →</a></div>';
    } else {
        echo '<div style="text-align:center;padding:30px;background:#fff;border-radius:10px;">';
        echo '<i class="fas fa-info-circle" style="font-size:48px;color:#999;"></i>';
        echo '<p style="color:#666;margin-top:10px;">No bookings found yet.</p>';
        echo '</div>';
    }
    echo '</div>';

    echo '<div style="margin-top:25px;background:#f0f4f8;padding:20px;border-radius:12px;">';
    echo '<h3>📋 All Tours from Database</h3>';

    if (!empty($all_tours)) {
        echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:15px;">';
        foreach ($all_tours as $tour) {
            $block_label = $tour->tour_block_type === 'grid' ? 'KTV Tour Grid' : ($tour->tour_block_type === 'package' ? 'KTV Tour Package' : 'KTV Tour Card');
            $block_color = $tour->tour_block_type === 'grid' ? '#0d47a1' : ($tour->tour_block_type === 'package' ? '#e65100' : '#1b5e20');
            $status_color = $tour->status === 'published' ? '#28a745' : '#dc3545';
            $price = ($tour->tour_offer_price && $tour->tour_offer_price > 0 && $tour->tour_offer_price < $tour->tour_price) ? $tour->tour_offer_price : $tour->tour_price;
            $icon_prefix = ktv_icon_to_prefix(ktv_resolve_tour_icon(isset($tour->icon_title) ? $tour->icon_title : '', $tour->tour_block_type));

            $thumb_url = '';
            if (!empty($tour->tour_image_id)) {
                $thumb_url = wp_get_attachment_image_url($tour->tour_image_id, 'thumbnail');
            }

            echo '<div style="background:#fff;padding:15px;border-radius:10px;box-shadow:0 2px 8px rgba(0,0,0,0.06);border-left:4px solid ' . esc_attr($block_color) . ';display:flex;gap:12px;">';
            if ($thumb_url) {
                echo '<img src="' . esc_url($thumb_url) . '" width="50" height="50" loading="lazy" decoding="async" style="width:50px;height:50px;object-fit:cover;border-radius:6px;flex-shrink:0;">';
            }
            echo '<div style="flex:1;min-width:0;">';
            echo '<div style="display:flex;justify-content:space-between;align-items:start;">';
            echo '<div style="min-width:0;">';
            echo '<strong style="color:#075e54;font-size:15px;word-break:break-word;">' . esc_html($icon_prefix . ' ' . $tour->tour_name) . '</strong>';
            echo '<div style="font-size:12px;color:#666;margin-top:4px;">';
            echo '<span style="background:' . esc_attr($block_color) . ';color:#fff;padding:2px 10px;border-radius:12px;font-size:10px;font-weight:600;">' . esc_html($block_label) . '</span>';
            echo ' | ' . ktv_get_currency_symbol() . esc_html($price) . ' | ' . esc_html($tour->tour_location);
            echo '</div>';
            echo '</div>';
            echo '<div style="text-align:right;flex-shrink:0;">';
            echo '<span style="color:' . esc_attr($status_color) . ';font-size:11px;font-weight:600;">' . esc_html($tour->status) . '</span>';
            echo '<div style="font-size:10px;color:#999;margin-top:4px;">ID: #' . esc_html($tour->id) . '</div>';
            echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours&action=edit&id=' . $tour->id)) . '" style="font-size:10px;color:#075e54;">Edit</a>';
            echo '</div>';
            echo '</div>';
            echo '</div>';
            echo '</div>';
        }
        echo '</div>';
    } else {
        echo '<div style="text-align:center;padding:30px;background:#fff;border-radius:10px;">';
        echo '<i class="fas fa-info-circle" style="font-size:48px;color:#999;"></i>';
        echo '<p style="color:#666;margin-top:10px;">No tours found in database.</p>';
        echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours&action=add')) . '" class="button button-primary" style="margin-top:10px;">➕ Add Your First Tour</a>';
        echo '</div>';
    }
    echo '</div>';

    if (!empty($ghost_tours)) {
        echo '<div style="margin-top:25px;background:#f8f9fa;padding:20px;border-radius:12px;border:1px solid #ddd;">';
        echo '<h3>👻 Ghost/Hardcoded Tours (Filtered from Booking Form)</h3>';
        echo '<table class="wp-list-table widefat striped"><thead><tr><th>ID</th><th>Name</th><th>Block Type</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody>';
        foreach ($ghost_tours as $gt) {
            echo '<tr>';
            echo '<td>#' . esc_html($gt->id) . '</td>';
            echo '<td>' . esc_html($gt->tour_name) . '</td>';
            echo '<td>' . esc_html($gt->tour_block_type) . '</td>';
            echo '<td>' . esc_html($gt->tour_price) . '</td>';
            echo '<td>' . esc_html($gt->status) . '</td>';
            echo '<td>';
            echo '<form method="post" style="display:inline;margin-right:5px;">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="tour_id" value="' . esc_attr($gt->id) . '"><button name="delete_tour" class="button button-small" onclick="return confirm(\'Delete permanently?\')">🗑️ Delete</button>';
            echo '</form>';
            echo '</td>';
            echo '</tr>';
        }
        echo '</tbody></table>';
        echo '</div>';
    }

    echo '<div style="margin-top:20px;background:#e8f5e9;padding:15px;border-radius:10px;">';
    echo '<h3>📑 Quick Links</h3>';
    echo '<p>';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-bookings')) . '" class="button">📋 View Bookings</a> ';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours')) . '" class="button">🏷️ Manage Tours</a> ';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-flights')) . '" class="button">✈️ Manage Flights</a> ';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-reviews')) . '" class="button">⭐ Approve Reviews</a> ';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-locations')) . '" class="button">📍 Manage Locations</a> ';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-voucher')) . '" class="button">🎫 Voucher</a> ';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-spam-settings')) . '" class="button">🛡️ Honeypot &amp; Spam</a> ';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-auto-messages')) . '" class="button">💬 Auto Messages</a>';
    echo '</p>';
    echo '</div>';
    echo '</div>';
}

/* ============================================================
   56. ADMIN BOOKINGS
   ============================================================ */

function ktv_admin_bookings() {
    global $wpdb;
    $bookings_per_page = 20;
    $current_page = isset($_GET['paged']) ? max(1, intval($_GET['paged'])) : 1;
    $offset = ($current_page - 1) * $bookings_per_page;

    $search_query = isset($_GET['s']) ? sanitize_text_field(wp_unslash($_GET['s'])) : '';
    $status_filter = isset($_GET['status']) ? sanitize_text_field(wp_unslash($_GET['status'])) : '';
    $block_type_filter = isset($_GET['block_type']) ? sanitize_text_field(wp_unslash($_GET['block_type'])) : '';

    if (isset($_POST['mark_all_read'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            ktv_mark_notices_read();
            echo '<div class="notice notice-success"><p>✅ All bookings marked as read!</p></div>';
        }
    }

    if (isset($_POST['delete_booking']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            $wpdb->delete($wpdb->prefix . 'ktv_bookings', array('id' => $bid));
            $wpdb->delete($wpdb->prefix . 'ktv_vouchers', array('booking_id' => $bid));
            echo '<div class="notice notice-success"><p>✅ Booking #' . intval($bid) . ' deleted!</p></div>';
        }
    }

    if (isset($_POST['accept_booking']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            $result = ktv_update_booking_status($bid, 'confirmed');
            if ($result['success']) {
                $msg = '✅ Booking #' . intval($bid) . ' accepted!';
                if (!empty($result['email_sent'])) {
                    $msg .= ' Voucher sent to customer.';
                } else {
                    $msg .= ' ⚠️ Email could not be sent — ' . esc_html($result['email_error']);
                }
                echo '<div class="notice notice-success"><p>' . $msg . '</p></div>';
            } else {
                echo '<div class="notice notice-error"><p>❌ Error accepting booking.</p></div>';
            }
        }
    }

    if (isset($_POST['decline_booking']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            $decline_reason = isset($_POST['decline_reason']) ? sanitize_textarea_field(wp_unslash($_POST['decline_reason'])) : '';
            $result = ktv_update_booking_status($bid, 'cancelled', $decline_reason);
            if ($result['success']) {
                $msg = '❌ Booking #' . intval($bid) . ' declined!';
                if (!empty($result['email_sent'])) {
                    $msg .= ' ✅ Cancellation email with decline status sent to guest.';
                } else {
                    $msg .= ' ⚠️ Voucher email could not be sent — ' . esc_html($result['email_error']);
                }
                echo '<div class="notice notice-warning"><p>' . $msg . '</p></div>';
            } else {
                echo '<div class="notice notice-error"><p>❌ Error declining booking.</p></div>';
            }
        }
    }

    if (isset($_POST['approve_cancel_request']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            $approve_reason = isset($_POST['approve_reason']) ? sanitize_textarea_field(wp_unslash($_POST['approve_reason'])) : '';
            $result = ktv_update_booking_status($bid, 'cancelled', $approve_reason);
            if ($result['success']) {
                $msg = '✅ Cancellation request for booking #' . intval($bid) . ' approved.';
                if (!empty($result['email_sent'])) {
                    $msg .= ' Voucher sent to guest.';
                }
                echo '<div class="notice notice-success"><p>' . $msg . '</p></div>';
            } else {
                echo '<div class="notice notice-error"><p>❌ Error approving cancellation.</p></div>';
            }
        }
    }

    if (isset($_POST['reject_cancel_request']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            $result = ktv_update_booking_status($bid, 'confirmed');
            if ($result['success']) {
                echo '<div class="notice notice-success"><p>✅ Cancellation request rejected — booking restored to confirmed.</p></div>';
            } else {
                echo '<div class="notice notice-error"><p>❌ Error rejecting cancellation.</p></div>';
            }
        }
    }

    if (isset($_POST['mark_read']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            ktv_db_update_safe($wpdb->prefix . 'ktv_bookings', array('is_read' => 1), array('id' => $bid));
            ktv_get_booking_notice_count(true);
            echo '<div class="notice notice-success"><p>✅ Booking #' . intval($bid) . ' marked as read!</p></div>';
        }
    }

    if (isset($_POST['resend_voucher']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            $booking = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d", $bid));
            if ($booking && !empty($booking->voucher_code)) {
                $booking_array = (array) $booking;
                if (empty($booking_array['days'])) {
                    $booking_array['days'] = max(1, intval($booking_array['nights'])) + 1;
                }
                ktv_generate_and_store_voucher($bid, $booking_array, true, 'render');
                $booking = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d", $bid));
                $voucher_pdf_url = $wpdb->get_var($wpdb->prepare(
                    "SELECT voucher_pdf_path FROM {$wpdb->prefix}ktv_vouchers WHERE voucher_code = %s LIMIT 1",
                    $booking->voucher_code
                ));
                $sent = ktv_send_voucher_email($booking, $booking->voucher_code, $voucher_pdf_url);
                if ($sent) {
                    echo '<div class="notice notice-success"><p>✅ Voucher email resent to ' . esc_html($booking->email) . '!</p></div>';
                } else {
                    echo '<div class="notice notice-error"><p>❌ Failed to resend voucher email. Check error log / email settings.</p></div>';
                }
            } else {
                echo '<div class="notice notice-error"><p>❌ Booking has no voucher code.</p></div>';
            }
        }
    }

    if (isset($_POST['modify_booking']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            $send_voucher_to_guest = isset($_POST['send_voucher_to_guest']) && intval($_POST['send_voucher_to_guest']) === 1;
            $recalc_pricing = isset($_POST['recalc_pricing']) && intval($_POST['recalc_pricing']) === 1;

            $existing_booking = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d", $bid));
            if (!$existing_booking) {
                echo '<div class="notice notice-error"><p>❌ Booking not found.</p></div>';
            } else {
                $modified_data = array(
                    'name'           => sanitize_text_field(wp_unslash(isset($_POST['name']) ? $_POST['name'] : $existing_booking->name)),
                    'email'          => sanitize_email(wp_unslash(isset($_POST['email']) ? $_POST['email'] : $existing_booking->email)),
                    'phone'          => sanitize_text_field(wp_unslash(isset($_POST['phone']) ? $_POST['phone'] : $existing_booking->phone)),
                    'country'        => sanitize_text_field(wp_unslash(isset($_POST['country']) ? $_POST['country'] : $existing_booking->country)),
                    'arrival_date'   => sanitize_text_field(wp_unslash(isset($_POST['arrival_date']) ? $_POST['arrival_date'] : $existing_booking->arrival_date)),
                    'departure_date' => sanitize_text_field(wp_unslash(isset($_POST['departure_date']) ? $_POST['departure_date'] : $existing_booking->departure_date)),
                    'adults'         => intval(isset($_POST['adults']) ? $_POST['adults'] : $existing_booking->adults),
                    'children'       => intval(isset($_POST['children']) ? $_POST['children'] : $existing_booking->children),
                    'tour_type'      => sanitize_text_field(wp_unslash(isset($_POST['tour_type']) ? $_POST['tour_type'] : $existing_booking->tour_type)),
                    'payment_method' => sanitize_text_field(wp_unslash(isset($_POST['payment_method']) ? $_POST['payment_method'] : $existing_booking->payment_method)),
                    'booking_status' => 'modified',
                    'is_read'        => 1
                );

                if (isset($_POST['voucher_content_override'])) {
                    $modified_data['voucher_content_override'] = wp_kses_post(wp_unslash($_POST['voucher_content_override']));
                }

                if (!$recalc_pricing) {
                    $subtotal_in = isset($_POST['subtotal']) ? floatval($_POST['subtotal']) : 0;
                    $gst_in      = isset($_POST['gst_amount']) ? floatval($_POST['gst_amount']) : 0;
                    $total_in    = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
                    if ($subtotal_in <= 0) { $subtotal_in = floatval($existing_booking->subtotal); }
                    if ($gst_in <= 0)      { $gst_in = floatval($existing_booking->gst_amount); }
                    if ($total_in <= 0)    { $total_in = floatval($existing_booking->total_amount); }
                    $modified_data['subtotal']     = $subtotal_in;
                    $modified_data['gst_amount']   = $gst_in;
                    $modified_data['total_amount'] = $total_in;
                }

                ktv_db_update_safe($wpdb->prefix . 'ktv_bookings', $modified_data, array('id' => $bid));

                if ($recalc_pricing) {
                    ktv_recalculate_booking_pricing($bid);
                }

                $booking = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d", $bid));

                if ($booking) {
                    $booking_array = (array) $booking;
                    $voucher_code = !empty($booking->voucher_code) ? $booking->voucher_code : ktv_generate_voucher_code();
                    $booking_array['voucher_code'] = $voucher_code;
                    $booking_array['booking_status'] = 'modified';
                    if (empty($booking_array['days'])) {
                        $booking_array['days'] = intval($booking_array['nights']) + 1;
                    }
                    ktv_generate_and_store_voucher($bid, $booking_array, true, 'render');

                    if ($send_voucher_to_guest) {
                        $booking = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d", $bid));
                        $voucher_pdf_url = $wpdb->get_var($wpdb->prepare(
                            "SELECT voucher_pdf_path FROM {$wpdb->prefix}ktv_vouchers WHERE voucher_code = %s LIMIT 1",
                            $voucher_code
                        ));
                        $sent = ktv_send_voucher_email($booking, $voucher_code, $voucher_pdf_url);
                        $msg = '✅ Booking #' . intval($bid) . ' modified!';
                        if ($sent) {
                            $msg .= ' New edited voucher sent to guest.';
                        } else {
                            $msg .= ' ⚠️ Voucher email could not be sent.';
                        }
                        echo '<div class="notice notice-success"><p>' . $msg . '</p></div>';
                    } else {
                        echo '<div class="notice notice-success"><p>✅ Booking #' . intval($bid) . ' modified! Voucher regenerated but not emailed.</p></div>';
                    }
                }
            }
        }
    }

    if (isset($_POST['send_edited_voucher']) && isset($_POST['bid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $bid = intval($_POST['bid']);
            $booking = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d", $bid));
            if ($booking) {
                $booking_array = (array) $booking;
                if (!empty($booking->voucher_content_override)) {
                    $booking_array['voucher_content_override'] = $booking->voucher_content_override;
                }
                $voucher_code = !empty($booking->voucher_code) ? $booking->voucher_code : ktv_generate_voucher_code();
                $booking_array['voucher_code'] = $voucher_code;
                if (empty($booking_array['days'])) {
                    $booking_array['days'] = intval($booking_array['nights']) + 1;
                }
                ktv_generate_and_store_voucher($bid, $booking_array, true, 'render');

                $booking = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE id = %d", $bid));
                $voucher_pdf_url = $wpdb->get_var($wpdb->prepare(
                    "SELECT voucher_pdf_path FROM {$wpdb->prefix}ktv_vouchers WHERE voucher_code = %s LIMIT 1",
                    $voucher_code
                ));
                $sent = ktv_send_voucher_email($booking, $voucher_code, $voucher_pdf_url);
                if ($sent) {
                    echo '<div class="notice notice-success"><p>✅ New edited voucher sent to ' . esc_html($booking->email) . '!</p></div>';
                } else {
                    echo '<div class="notice notice-error"><p>❌ Failed to send edited voucher.</p></div>';
                }
            }
        }
    }

    $bookings = ktv_get_admin_bookings_all($search_query, $status_filter, $block_type_filter, $bookings_per_page, $offset);
    $total_bookings = ktv_get_admin_bookings_count_all($search_query, $status_filter, $block_type_filter);

    echo '<div class="wrap"><h1>📋 KTV Bookings</h1>';
    echo '<p class="description"><strong>Total Bookings:</strong> ' . esc_html($total_bookings) . ' | <strong>Page:</strong> ' . esc_html($current_page) . '</p>';

    echo '<div class="tablenav"><div class="alignleft actions">';
    echo '<form method="get" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">';
    echo '<input type="hidden" name="page" value="ktv-bookings">';
    echo '<input type="text" name="s" value="' . esc_attr($search_query) . '" placeholder="Search by Ref, Name, Email, Tour..." style="padding:8px 12px;width:300px;border:1px solid #ccc;border-radius:4px;">';
    echo '<select name="status" style="padding:8px 12px;border:1px solid #ccc;border-radius:4px;">';
    echo '<option value="">All Status</option>';
    echo '<option value="pending" ' . ($status_filter === 'pending' ? 'selected' : '') . '>Pending</option>';
    echo '<option value="confirmed" ' . ($status_filter === 'confirmed' ? 'selected' : '') . '>Confirmed</option>';
    echo '<option value="cancelled" ' . ($status_filter === 'cancelled' ? 'selected' : '') . '>Cancelled</option>';
    echo '<option value="modified" ' . ($status_filter === 'modified' ? 'selected' : '') . '>Modified</option>';
    echo '<option value="cancel_requested" ' . ($status_filter === 'cancel_requested' ? 'selected' : '') . '>Cancel Requested</option>';
    echo '<option value="modify_requested" ' . ($status_filter === 'modify_requested' ? 'selected' : '') . '>Modify Requested</option>';
    echo '</select>';
    echo '<select name="block_type" style="padding:8px 12px;border:1px solid #ccc;border-radius:4px;">';
    echo '<option value="">All Block Types</option>';
    echo '<option value="grid" ' . ($block_type_filter === 'grid' ? 'selected' : '') . '>📐 KTV Tour Grid</option>';
    echo '<option value="package" ' . ($block_type_filter === 'package' ? 'selected' : '') . '>📦 KTV Tour Package</option>';
    echo '<option value="card" ' . ($block_type_filter === 'card' ? 'selected' : '') . '>🃏 KTV Tour Card</option>';
    echo '<option value="booking_form" ' . ($block_type_filter === 'booking_form' ? 'selected' : '') . '>📝 KTV Booking Form</option>';
    echo '</select>';
    echo '<button type="submit" class="button">🔍 Search</button>';
    if (!empty($search_query) || !empty($status_filter) || !empty($block_type_filter)) {
        echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-bookings')) . '" class="button">❌ Clear</a>';
    }
    echo '</form></div>';
    echo '<div class="alignright">';
    echo '<form method="post" style="display:inline;">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<button name="mark_all_read" class="button">✅ Mark All as Read</button>';
    echo '</form>';
    echo '</div></div><br>';

    echo '<table class="wp-list-table widefat striped"><thead><tr><th>ID</th><th>Ref / Voucher</th><th>Name / Email</th><th>Tour / Dates</th><th>Total</th><th>Payment</th><th>Block Type</th><th>Location / Device</th><th>Status</th><th>Actions</th></tr></thead><tbody>';

    if (empty($bookings)) {
        echo '<tr><td colspan="10"><strong>❌ No bookings found.</strong></td></tr>';
    } else {
        foreach ($bookings as $b) {
            $block_type_source = '';
            if ($b->block_type === 'grid') {
                $block_type_source = '📐 KTV Tour Grid';
            } elseif ($b->block_type === 'package') {
                $block_type_source = '📦 KTV Tour Package';
            } elseif ($b->block_type === 'card') {
                $block_type_source = '🃏 KTV Tour Card';
            } elseif ($b->block_type === 'booking_form') {
                $block_type_source = '📝 KTV Booking Form';
            } else {
                $block_type_source = '❓ Unknown';
            }

            $status_color = '#dc3545';
            if ($b->booking_status === 'confirmed') {
                $status_color = '#28a745';
            } elseif ($b->booking_status === 'pending') {
                $status_color = '#ffc107';
            } elseif ($b->booking_status === 'modified') {
                $status_color = '#17a2b8';
            } elseif ($b->booking_status === 'cancel_requested' || $b->booking_status === 'modify_requested') {
                $status_color = '#6c757d';
            }

            $is_unread = isset($b->is_read) && $b->is_read == 0;
            $tour_display = !empty($b->tour_name) ? $b->tour_name : $b->tour_type;

            $city = isset($b->user_city) ? $b->user_city : '';
            $region = isset($b->user_region) ? $b->user_region : '';

            $row_style = '';
            if ($is_unread) {
                $row_style = ' style="background:#fff8e1;"';
            } elseif ($b->booking_status === 'cancel_requested') {
                $row_style = ' style="background:#f8d7da;"';
            } elseif ($b->booking_status === 'modify_requested') {
                $row_style = ' style="background:#d1ecf1;"';
            }

            echo '<tr' . $row_style . '>';
            echo '<td><strong>#' . esc_html($b->id) . '</strong>' . ($is_unread ? ' <span style="background:#ff9800;color:#fff;padding:1px 6px;border-radius:8px;font-size:10px;">NEW</span>' : '') . '</td>';
            echo '<td><strong style="color:#075e54;">' . esc_html($b->booking_ref) . '</strong><br><small style="color:#ff5722;">' . esc_html($b->voucher_code ?: 'No voucher') . '</small></td>';
            echo '<td><strong>' . esc_html($b->name) . '</strong><br><small>' . esc_html($b->email) . '</small></td>';
            echo '<td><strong>' . esc_html($tour_display) . '</strong><br><small>📅 ' . esc_html($b->arrival_date) . ' → ' . esc_html($b->departure_date) . '</small><br><small>👤 ' . esc_html($b->adults) . ' Adults, ' . esc_html($b->children) . ' Kids</small></td>';
            echo '<td><strong style="color:#28a745;">' . esc_html($b->currency . ' ' . number_format($b->total_amount, 2)) . '</strong><br><small>Subtotal: ' . esc_html($b->currency . number_format($b->subtotal, 2)) . '</small><br><small>GST: ' . esc_html($b->currency . number_format($b->gst_amount, 2)) . '</small></td>';
            echo '<td>' . esc_html(ucfirst(str_replace('_', ' ', $b->payment_method))) . '</td>';
            echo '<td><span style="background:#e8f5e9;padding:2px 10px;border-radius:12px;font-size:11px;">' . esc_html($block_type_source) . '</span></td>';
            echo '<td><small><strong>IP:</strong> ' . esc_html(isset($b->user_ip) && $b->user_ip ? $b->user_ip : 'N/A') . '<br><strong>Country:</strong> ' . esc_html(isset($b->user_country) && $b->user_country ? $b->user_country : 'N/A') . ($city ? '<br><strong>City:</strong> ' . esc_html($city) : '') . ($region ? '<br><strong>Region:</strong> ' . esc_html($region) : '') . '<br><strong>Device:</strong> ' . esc_html(isset($b->user_device) && $b->user_device ? $b->user_device : 'N/A') . '<br><strong>Travelling To:</strong> ' . esc_html(isset($b->travel_location) && $b->travel_location ? $b->travel_location : 'N/A') . '</small></td>';
            echo '<td><span style="color:' . esc_attr($status_color) . ';font-weight:600;">' . esc_html(ucfirst(str_replace('_', ' ', $b->booking_status))) . '</span></td>';
            echo '<td>';
            echo '<form method="post" style="display:inline;margin-right:5px;">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="bid" value="' . esc_attr($b->id) . '">';
            if ($is_unread) {
                echo '<button name="mark_read" class="button button-small" style="margin-bottom:2px;">👁️ Mark Read</button> ';
            }
            if ($b->booking_status == 'pending' || $b->booking_status == 'modify_requested') {
                echo '<button name="accept_booking" class="button button-primary button-small" style="margin-bottom:2px;">✅ Accept</button> ';
                echo '<button name="decline_booking" class="button button-small" style="margin-bottom:2px;" onclick="return confirm(\'Decline this booking? A declined voucher will be emailed to the guest.\')">❌ Decline</button> ';
            }
            if ($b->booking_status == 'cancel_requested') {
                echo '<button name="approve_cancel_request" class="button button-primary button-small" style="margin-bottom:2px;" onclick="return confirm(\'Approve cancellation? Booking will be cancelled and voucher sent.\')">✅ Approve Cancel</button> ';
                echo '<button name="reject_cancel_request" class="button button-small" style="margin-bottom:2px;">❌ Reject Cancel</button> ';
            }
            if ($b->booking_status != 'cancelled') {
                echo '<button type="button" class="button button-small" style="margin-bottom:2px;" data-toggle-modify="' . esc_attr($b->id) . '">✏️ Modify</button> ';
            }
            if (!empty($b->voucher_code)) {
                echo '<button name="resend_voucher" class="button button-small" style="margin-bottom:2px;">📧 Resend Voucher</button> ';
                echo '<button name="send_edited_voucher" class="button button-small" style="margin-bottom:2px;" onclick="return confirm(\'Regenerate and send the latest voucher to guest?\')">📨 Send New Edited Voucher</button> ';
            }
            echo '<button name="delete_booking" class="button button-small" style="margin-bottom:2px;" onclick="return confirm(\'Delete this booking? This cannot be undone.\')">🗑️</button>';
            echo '</form>';

            echo '<div id="modify-form-' . esc_attr($b->id) . '" style="display:none;margin-top:10px;padding:15px;background:#f8f9fa;border-radius:8px;border:1px solid #ddd;">';
            echo '<form method="post">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="bid" value="' . esc_attr($b->id) . '">';
            echo '<h4>Modify Booking #' . esc_html($b->id) . '</h4>';
            echo '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">';
            echo '<div><label>Name</label><br><input type="text" name="name" value="' . esc_attr($b->name) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Email</label><br><input type="email" name="email" value="' . esc_attr($b->email) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Phone</label><br><input type="text" name="phone" value="' . esc_attr($b->phone) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Country</label><br><input type="text" name="country" value="' . esc_attr(isset($b->country) ? $b->country : '') . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Tour Type</label><br><input type="text" name="tour_type" value="' . esc_attr($b->tour_type) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Arrival Date</label><br><input type="date" name="arrival_date" value="' . esc_attr($b->arrival_date) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Departure Date</label><br><input type="date" name="departure_date" value="' . esc_attr($b->departure_date) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Adults</label><br><input type="number" name="adults" value="' . esc_attr($b->adults) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Children</label><br><input type="number" name="children" value="' . esc_attr($b->children) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>Payment Method</label><br><select name="payment_method" style="width:100%;padding:6px;">';
            $pm_options = array('pay_on_arrival' => 'Pay on Arrival', 'gpay' => 'GPay / UPI', 'credit_card' => 'Credit Card', 'bank_transfer' => 'Bank Transfer');
            foreach ($pm_options as $pm_key => $pm_label) {
                echo '<option value="' . esc_attr($pm_key) . '" ' . selected($b->payment_method, $pm_key, false) . '>' . esc_html($pm_label) . '</option>';
            }
            echo '</select></div>';
            echo '<div><label>Subtotal</label><br><input type="number" name="subtotal" step="0.01" value="' . esc_attr($b->subtotal) . '" style="width:100%;padding:6px;"></div>';
            echo '<div><label>GST Amount</label><br><input type="number" name="gst_amount" step="0.01" value="' . esc_attr($b->gst_amount) . '" style="width:100%;padding:6px;"></div>';
            echo '<div style="grid-column:1/-1;"><label>Total Amount</label><br><input type="number" name="total_amount" step="0.01" value="' . esc_attr($b->total_amount) . '" style="width:100%;padding:6px;"></div>';
            echo '</div>';
            echo '<div style="margin-top:10px;">';
            echo '<label style="display:block;margin-bottom:6px;"><input type="checkbox" name="recalc_pricing" value="1" checked> Recalculate pricing from tour settings (uncheck to keep edited totals)</label>';
            echo '<label style="display:block;margin-bottom:10px;"><input type="checkbox" name="send_voucher_to_guest" value="1"> Send new edited voucher to guest via email</label>';
            echo '<div style="margin-top:10px;"><label style="display:block;margin-bottom:6px;font-weight:600;">Custom Voucher Content Override (optional)</label>';
            echo '<textarea name="voucher_content_override" rows="4" style="width:100%;padding:8px;font-family:monospace;font-size:12px;" placeholder="Leave blank to use auto-generated voucher. HTML allowed.">' . esc_textarea(isset($b->voucher_content_override) ? $b->voucher_content_override : '') . '</textarea></div>';
            echo '<button type="submit" name="modify_booking" class="button button-primary" style="margin-top:10px;">💾 Save Changes</button> ';
            echo '<button type="submit" name="modify_booking" class="button button-primary" style="margin-top:10px;background:#28a745;border-color:#28a745;" onclick="this.form.querySelector(\'input[name=send_voucher_to_guest]\').checked = true;">📨 Save &amp; Send Voucher</button> ';
            echo '<button type="button" class="button" data-close-modify="' . esc_attr($b->id) . '">Cancel</button>';
            echo '</div>';
            echo '</form></div>';
            echo '</td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';

    if ($total_bookings > $bookings_per_page) {
        echo '<div class="tablenav"><div class="tablenav-pages">';
        $total_pages = ceil($total_bookings / $bookings_per_page);
        echo paginate_links(array(
            'base'      => add_query_arg('paged', '%#%'),
            'format'    => '',
            'prev_text' => '&laquo;',
            'next_text' => '&raquo;',
            'total'     => $total_pages,
            'current'   => $current_page
        ));
        echo '</div></div>';
    }
}
