function ktv_admin_tours() {
    global $wpdb;

    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['purge_hardcoded']) && wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
        $deleted = ktv_purge_hardcoded_tours();
        echo '<div class="notice notice-success"><p>✅ Purged ' . esc_html($deleted) . ' hardcoded/ghost tours from database!</p></div>';
    }

    if (isset($_POST['sync_block_tours']) && wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
        $result = ktv_sync_all_block_tours_to_db();
        echo '<div class="notice notice-success"><p>✅ Sync complete. Added: ' . intval($result['added']) . ', Updated: ' . intval($result['updated']) . '</p></div>';
    }

    if (isset($_POST['import_new_tours']) && wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
        $found = ktv_get_smart_new_tours();
        if (empty($found)) {
            echo '<div class="notice notice-info"><p>No new tours to import.</p></div>';
        } else {
            $imported = 0; $failed = 0;
            foreach ($found as $tour) {
                $result = ktv_upsert_block_tour($tour['title'], $tour['attrs'], $tour['block_type'], $tour['source_post']);
                if ($result === 'added' || $result === 'updated') { $imported++; } else { $failed++; }
            }
            ktv_clear_tour_caches();
            echo '<div class="notice notice-success"><p>✅ Imported ' . intval($imported) . ' tours.' . ($failed ? ' ' . intval($failed) . ' failed.' : '') . '</p></div>';
        }
    }

    if (isset($_POST['add_tour']) && isset($_POST['tour_name']) && !empty($_POST['tour_name'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $tour_data = ktv_sanitize_tour_input();

            $tour_data['tour_slug'] = ktv_generate_unique_slug($tour_data['tour_name']);
            if (empty($tour_data['status'])) {
                $tour_data['status'] = 'published';
            }
            if (empty($tour_data['tour_block_type'])) {
                $tour_data['tour_block_type'] = 'grid';
            }

            $tour_data['is_hardcoded'] = 0;
            $tour_data['is_ghost'] = 0;
            $tour_data['is_synced'] = 1;

            $existing = $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM {$wpdb->prefix}ktv_tours WHERE tour_name = %s AND is_hardcoded = 0",
                $tour_data['tour_name']
            ));

            if ($existing) {
                echo '<div class="notice notice-error"><p>❌ A tour with this name already exists (ID #' . esc_html($existing) . '). Please use a different name or edit the existing one.</p></div>';
            } else {
                $tour_data['created_at'] = current_time('mysql');
                $result = ktv_db_insert_safe($wpdb->prefix . 'ktv_tours', $tour_data);
                if ($result !== false) {
                    $inserted_id = $wpdb->insert_id;
                    ktv_clear_tour_caches();
                    echo '<div class="notice notice-success"><p>✅ Tour "' . esc_html($tour_data['tour_name']) . '" added successfully! Block Type: ' . esc_html($tour_data['tour_block_type']) . ' | ID: ' . esc_html($inserted_id) . '</p></div>';
                } else {
                    echo '<div class="notice notice-error"><p>❌ Error adding tour: ' . esc_html($wpdb->last_error) . '</p></div>';
                }
            }
        }
    }

    if (isset($_POST['edit_tour']) && isset($_POST['edit_tour_id'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $edit_id = intval($_POST['edit_tour_id']);
            $tour_data = ktv_sanitize_tour_input();
            $result = ktv_db_update_safe($wpdb->prefix . 'ktv_tours', $tour_data, array('id' => $edit_id));
            if ($result !== false) {
                ktv_clear_tour_caches();
                echo '<div class="notice notice-success"><p>✅ Tour "' . esc_html($tour_data['tour_name']) . '" updated successfully! ID: ' . esc_html($edit_id) . '</p></div>';
            } else {
                echo '<div class="notice notice-error"><p>❌ Error updating tour: ' . esc_html($wpdb->last_error) . '</p></div>';
            }
        }
    }

    if (isset($_POST['delete_tour']) && isset($_POST['tour_id'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $tour_id = intval($_POST['tour_id']);
            $tour_name = $wpdb->get_var($wpdb->prepare("SELECT tour_name FROM {$wpdb->prefix}ktv_tours WHERE id = %d", $tour_id));
            $result = ktv_delete_tour_completely($tour_id);
            if ($result) {
                echo '<div class="notice notice-success"><p>✅ Tour "' . esc_html($tour_name) . '" and related display data deleted successfully! Bookings preserved.</p></div>';
            } else {
                echo '<div class="notice notice-error"><p>❌ Error deleting tour.</p></div>';
            }
        }
    }

    if (isset($_POST['duplicate_tour']) && isset($_POST['tour_id'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $source_id = intval($_POST['tour_id']);
            $source = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_tours WHERE id = %d", $source_id), ARRAY_A);
            if ($source) {
                unset($source['id']);
                unset($source['created_at']);
                unset($source['updated_at']);
                $source['tour_name'] = $source['tour_name'] . ' (Copy)';
                $source['tour_slug'] = ktv_generate_unique_slug($source['tour_name']);
                $source['status'] = 'draft';
                $result = ktv_db_insert_safe($wpdb->prefix . 'ktv_tours', $source);
                if ($result !== false) {
                    ktv_clear_tour_caches();
                    echo '<div class="notice notice-success"><p>✅ Tour duplicated as draft! New ID: ' . intval($wpdb->insert_id) . '</p></div>';
                } else {
                    echo '<div class="notice notice-error"><p>❌ Error duplicating tour.</p></div>';
                }
            }
        }
    }

    echo '<div class="wrap"><h1>🏷️ KTV Tours</h1>';
    echo '<p>';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours&action=add')) . '" class="button button-primary">➕ Add New Tour</a> ';
    echo '<form method="post" style="display:inline;">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<button name="sync_block_tours" class="button">🔄 Sync Block Tours</button>';
    echo '</form> ';
    echo '<form method="post" style="display:inline;" onsubmit="return confirm(\'Purge all hardcoded/ghost tours permanently?\')">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<button name="purge_hardcoded" class="button" style="margin-left:10px;">🗑️ Purge Hardcoded Tours</button>';
    echo '</form> ';
    echo '<button class="button button-primary" id="ktv-import-new-tours-btn-page" style="margin-left:10px;">🆕 Import Smart New Tours</button>';
    echo '</p>';
    echo '<div id="ktv-import-new-tours-result-page" style="margin:10px 0;"></div>';

    if (isset($_GET['action']) && $_GET['action'] === 'add') {
        ktv_admin_tour_form();
        return;
    }

    if (isset($_GET['action']) && $_GET['action'] === 'edit' && isset($_GET['id'])) {
        ktv_admin_tour_form(intval($_GET['id']));
        return;
    }

    $search = isset($_GET['s']) ? sanitize_text_field(wp_unslash($_GET['s'])) : '';
    $block_filter = isset($_GET['block_type']) ? sanitize_text_field(wp_unslash($_GET['block_type'])) : '';
    $source_filter = isset($_GET['source']) ? sanitize_text_field(wp_unslash($_GET['source'])) : 'all';

    if ($source_filter === 'new_from_blocks') {
        $smart_tours = ktv_get_smart_new_tours();
        echo '<h2>🆕 New Tours Detected in Blocks</h2>';
        echo '<p>These tours appear in your KTV Tour Grid / Card / Package blocks but are not yet in the database.</p>';
        if (empty($smart_tours)) {
            echo '<div class="notice notice-info"><p>No new tours detected. All block tours are already in the database.</p></div>';
        } else {
            echo '<form method="post" style="margin-bottom:15px;">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<button name="import_new_tours" class="button button-primary">➕ Import All ' . count($smart_tours) . ' New Tours</button>';
            echo '</form>';
            echo '<table class="wp-list-table widefat striped"><thead><tr><th>Title</th><th>Block</th><th>Type</th><th>Location</th><th>Price</th></tr></thead><tbody>';
            foreach ($smart_tours as $tour) {
                echo '<tr>';
                echo '<td><strong>' . esc_html($tour['title']) . '</strong></td>';
                echo '<td>' . esc_html($tour['block']) . '</td>';
                echo '<td>' . esc_html($tour['block_type']) . '</td>';
                echo '<td>' . esc_html($tour['location']) . '</td>';
                echo '<td>' . ktv_get_currency_symbol() . esc_html($tour['price']) . '</td>';
                echo '</tr>';
            }
            echo '</tbody></table>';
        }
        echo '</div>';
        return;
    }

    $where = "1=1";
    $params = array();

    if ($source_filter === 'active') {
        $where .= " AND is_hardcoded = 0 AND (is_ghost = 0 OR is_ghost IS NULL)";
    } elseif ($source_filter === 'ghost') {
        $where .= " AND (is_hardcoded = 1 OR is_ghost = 1)";
    }

    if (!empty($search)) {
        $where .= " AND (tour_name LIKE %s OR tour_location LIKE %s)";
        $like = '%' . $wpdb->esc_like($search) . '%';
        $params[] = $like;
        $params[] = $like;
    }

    if (!empty($block_filter)) {
        $where .= " AND tour_block_type = %s";
        $params[] = $block_filter;
    }

    $sql = "SELECT * FROM {$wpdb->prefix}ktv_tours WHERE $where ORDER BY is_hardcoded ASC, id DESC";
    if (!empty($params)) {
        $sql = $wpdb->prepare($sql, $params);
    }
    $tours = $wpdb->get_results($sql);

    $block_types = array(
        'grid'    => 'KTV Tour Grid',
        'package' => 'KTV Tour Package',
        'card'    => 'KTV Tour Card'
    );
    $block_colors = array('grid' => '#0d47a1', 'package' => '#e65100', 'card' => '#1b5e20');

    $smart_count = count(ktv_get_smart_new_tours());
    echo '<div style="margin-bottom:20px;display:flex;gap:10px;flex-wrap:wrap;">';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours&source=active')) . '" class="button ' . ($source_filter === 'active' ? 'button-primary' : '') . '">Active Tours</a>';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours&source=ghost')) . '" class="button ' . ($source_filter === 'ghost' ? 'button-primary' : '') . '">Ghost/Hardcoded</a>';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours&source=all')) . '" class="button ' . ($source_filter === 'all' ? 'button-primary' : '') . '">All Tours</a>';
    echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours&source=new_from_blocks')) . '" class="button ' . ($source_filter === 'new_from_blocks' ? 'button-primary' : '') . '">🆕 New from Blocks (' . intval($smart_count) . ')</a>';
    echo '</div>';

    echo '<div style="margin-bottom:20px;">';
    echo '<form method="get" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">';
    echo '<input type="hidden" name="page" value="ktv-tours">';
    echo '<input type="text" name="s" value="' . esc_attr($search) . '" placeholder="Search tours..." style="padding:8px 12px;border:1px solid #ccc;border-radius:4px;width:250px;">';
    echo '<select name="block_type" style="padding:8px 12px;border:1px solid #ccc;border-radius:4px;">';
    echo '<option value="">All Block Types</option>';
    foreach ($block_types as $key => $label) {
        echo '<option value="' . esc_attr($key) . '" ' . selected($block_filter, $key, false) . '>' . esc_html($label) . '</option>';
    }
    echo '</select>';
    echo '<select name="source" style="padding:8px 12px;border:1px solid #ccc;border-radius:4px;">';
    echo '<option value="all" ' . ($source_filter === 'all' ? 'selected' : '') . '>All Tours</option>';
    echo '<option value="active" ' . ($source_filter === 'active' ? 'selected' : '') . '>Active Tours Only</option>';
    echo '<option value="ghost" ' . ($source_filter === 'ghost' ? 'selected' : '') . '>Ghost/Hardcoded Only</option>';
    echo '</select>';
    echo '<button type="submit" class="button">Filter</button>';
    if (!empty($search) || !empty($block_filter) || $source_filter !== 'all') {
        echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours')) . '" class="button">Clear</a>';
    }
    echo '</form></div>';

    echo '<table class="wp-list-table widefat striped"><thead><tr><th>ID</th><th>Image</th><th>Name</th><th>Block Type</th><th>Source</th><th>Price</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody>';

    if (empty($tours)) {
        echo '<tr><td colspan="9">No tours found. <a href="' . esc_url(admin_url('admin.php?page=ktv-tours&action=add')) . '">Add your first tour</a></td></tr>';
    } else {
        foreach ($tours as $t) {
            $block_label = isset($block_types[$t->tour_block_type]) ? $block_types[$t->tour_block_type] : 'Unknown';
            $block_color = isset($block_colors[$t->tour_block_type]) ? $block_colors[$t->tour_block_type] : '#666';
            $block_type_icon = $t->tour_block_type === 'grid' ? '📐' : ($t->tour_block_type === 'package' ? '📦' : '🃏');
            $status_color = $t->status === 'published' ? '#28a745' : '#dc3545';
            $is_ghost = ($t->is_hardcoded == 1 || (isset($t->is_ghost) && $t->is_ghost == 1));
            $icon_prefix = ktv_icon_to_prefix(ktv_resolve_tour_icon(isset($t->icon_title) ? $t->icon_title : '', $t->tour_block_type));

            $thumb = '';
            if (!empty($t->tour_image_id)) {
                $thumb_url = wp_get_attachment_image_url($t->tour_image_id, 'thumbnail');
                if ($thumb_url) {
                    $thumb = '<img src="' . esc_url($thumb_url) . '" width="50" height="50" loading="lazy" decoding="async" style="width:50px;height:50px;object-fit:cover;border-radius:6px;">';
                }
            }
            if (empty($thumb)) {
                $thumb = '<span style="color:#999;font-size:11px;">No image</span>';
            }

            $source_label = $is_ghost ? '<span style="color:#dc3545;">Hardcoded / Ghost</span>' : (!empty($t->is_synced) ? '<span style="color:#075e54;">Synced from Block</span>' : '<span style="color:#28a745;">Manual</span>');

            echo '<tr' . ($is_ghost ? ' style="background:#fff3cd;"' : '') . '>';
            echo '<td><strong>#' . esc_html($t->id) . '</strong></td>';
            echo '<td>' . $thumb . '</td>';
            echo '<td><strong>' . esc_html($block_type_icon) . ' ' . esc_html($icon_prefix . ' ' . $t->tour_name) . '</strong>' . ($is_ghost ? ' <span style="background:#ff9800;color:#fff;padding:1px 6px;border-radius:8px;font-size:10px;">GHOST</span>' : '') . '</td>';
            echo '<td><span style="background:' . esc_attr($block_color) . ';color:#fff;padding:2px 10px;border-radius:12px;font-size:11px;font-weight:600;">' . esc_html($block_label) . '</span></td>';
            echo '<td>' . $source_label . '</td>';
            echo '<td>' . ktv_get_currency_symbol() . esc_html($t->tour_price) . '</td>';
            echo '<td>' . esc_html($t->tour_location) . '</td>';
            echo '<td><span style="color:' . esc_attr($status_color) . ';font-weight:600;">' . esc_html($t->status) . '</span></td>';
            echo '<td>';
            echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-tours&action=edit&id=' . $t->id)) . '" class="button button-small">✏️ Edit</a> ';
            echo '<form method="post" style="display:inline;margin-right:3px;">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="tour_id" value="' . esc_attr($t->id) . '"><button name="duplicate_tour" class="button button-small">📋 Duplicate</button>';
            echo '</form>';
            echo '<form method="post" style="display:inline;" onsubmit="return confirm(\'Delete this tour? Bookings will be preserved.\')">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="tour_id" value="' . esc_attr($t->id) . '"><button name="delete_tour" class="button button-small">🗑️ Delete</button>';
            echo '</form>';
            echo '</td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
}

/* ============================================================
   58. ADMIN TOUR FORM
   ============================================================ */

function ktv_admin_tour_form($id = 0) {
    global $wpdb;
    $tour = null;
    $is_edit = $id > 0;

    if ($is_edit) {
        $tour = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_tours WHERE id = %d", $id));
        if (!$tour) {
            echo '<div class="wrap"><h2>Tour not found</h2></div>';
            return;
        }
    }

    $vals = function($key, $default = '') use ($tour, $is_edit) {
        if ($is_edit && isset($tour->$key) && $tour->$key !== '' && $tour->$key !== null) {
            return $tour->$key;
        }
        return $default;
    };

    $submit_name  = $is_edit ? 'edit_tour' : 'add_tour';
    $submit_label = $is_edit ? '💾 Update Tour' : '✅ Add Tour';
    $title = $is_edit ? '✏️ Edit Tour: ' . esc_html($tour->tour_name) . ' (ID: ' . $tour->id . ')' : '➕ Add New Tour';

    wp_enqueue_media();

    $image_id = $vals('tour_image_id', 0);
    $gallery_ids = $vals('tour_gallery', '');
    $visible_pax_str = $vals('visible_pax_columns', 'pax1');
    $visible_pax_arr = array_filter(array_map('trim', explode(',', $visible_pax_str)));

    echo '<div class="wrap"><h2>' . $title . '</h2>';
    echo '<form method="post" action="' . esc_url(admin_url('admin.php?page=ktv-tours')) . '" id="ktv-tour-form" enctype="multipart/form-data">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    if ($is_edit) {
        echo '<input type="hidden" name="edit_tour_id" value="' . esc_attr($id) . '">';
    }

    echo '<div style="display:grid;grid-template-columns:2fr 1fr;gap:20px;">';
    echo '<div>';

    echo '<h3 style="border-bottom:2px solid #075e54;padding-bottom:8px;">📝 Basic Information</h3>';
    echo '<table class="form-table">';
    echo '<tr><th><label>Tour Name *</label></th><td><input type="text" name="tour_name" value="' . esc_attr($vals('tour_name')) . '" class="regular-text" required></td></tr>';
    echo '<tr><th><label>Tour Location</label></th><td><input type="text" name="tour_location" value="' . esc_attr($vals('tour_location')) . '" class="regular-text"></td></tr>';
    echo '<tr><th><label>Duration</label></th><td><input type="number" name="tour_duration_days" style="width:80px;" value="' . esc_attr($vals('tour_duration_days', 1)) . '"> Days &nbsp; <input type="number" name="tour_duration_nights" style="width:80px;" value="' . esc_attr($vals('tour_duration_nights', 1)) . '"> Nights</td></tr>';
    echo '<tr><th><label>Block Type</label></th><td><select name="tour_block_type"><option value="grid" ' . selected($vals('tour_block_type'), 'grid', false) . '>KTV Tour Grid</option><option value="package" ' . selected($vals('tour_block_type'), 'package', false) . '>KTV Tour Package</option><option value="card" ' . selected($vals('tour_block_type'), 'card', false) . '>KTV Tour Card</option></select></td></tr>';
    echo '<tr><th><label>Status</label></th><td><select name="status"><option value="published" ' . selected($vals('status'), 'published', false) . '>Published</option><option value="draft" ' . selected($vals('status'), 'draft', false) . '>Draft</option></select> &nbsp; <label><input type="checkbox" name="featured" value="1" ' . checked($vals('featured', 0), 1, false) . '> Featured</label></td></tr>';
    echo '<tr><th><label>Brief Text</label></th><td><textarea name="tour_brief_text" rows="2" class="large-text">' . esc_textarea($vals('tour_brief_text')) . '</textarea></td></tr>';
    echo '<tr><th><label>After Title Text</label></th><td><input type="text" name="tour_after_title_text" value="' . esc_attr($vals('tour_after_title_text')) . '" class="regular-text"></td></tr>';
    echo '</table>';

    echo '<h3 style="border-bottom:2px solid #075e54;padding-bottom:8px;">🖼️ Images</h3>';
    echo '<table class="form-table">';
    echo '<tr><th><label>Main Image</label></th><td>';
    echo '<div id="ktv-tour-image-preview" style="margin-bottom:10px;">';
    if ($image_id) {
        $preview_url = wp_get_attachment_image_url($image_id, 'medium');
        if ($preview_url) {
            echo '<img src="' . esc_url($preview_url) . '" width="200" height="150" loading="lazy" decoding="async" style="max-width:200px;border-radius:8px;border:1px solid #ddd;">';
        }
    }
    echo '</div>';
    echo '<input type="hidden" name="tour_image_id" id="ktv-tour-image-id" value="' . esc_attr($image_id) . '">';
    echo '<button type="button" class="button button-primary" id="ktv-upload-tour-image">📷 ' . ($image_id ? 'Change Image' : 'Upload Image') . '</button> ';
    if ($image_id) {
        echo '<button type="button" class="button" id="ktv-remove-tour-image" style="margin-left:8px;">Remove Image</button>';
    }
    echo '<p class="description">Upload main tour image. Recommended 1200x800px or larger.</p>';
    echo '</td></tr>';
    echo '<tr><th><label>Image Link URL</label></th><td><input type="text" name="image_link_url" value="' . esc_attr($vals('image_link_url')) . '" class="regular-text" placeholder="https://example.com/tour-detail"></td></tr>';
    echo '<tr><th><label>Image Display Size</label></th><td><select name="image_display_size"><option value="thumbnail" ' . selected($vals('image_display_size'), 'thumbnail', false) . '>Thumbnail</option><option value="medium" ' . selected($vals('image_display_size'), 'medium', false) . '>Medium</option><option value="large" ' . selected($vals('image_display_size'), 'large', false) . '>Large</option><option value="full" ' . selected($vals('image_display_size'), 'full', false) . '>Full</option></select></td></tr>';
    echo '<tr><th><label>Gallery Images</label></th><td>';
    echo '<div id="ktv-gallery-preview" style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px;">';
    if (!empty($gallery_ids)) {
        $gallery_arr = array_map('trim', explode(',', $gallery_ids));
        foreach ($gallery_arr as $gid) {
            if (empty($gid)) continue;
            $gimg = wp_get_attachment_image_url(intval($gid), 'thumbnail');
            if ($gimg) {
                echo '<div style="position:relative;" data-gid="' . esc_attr($gid) . '">';
                echo '<img src="' . esc_url($gimg) . '" width="60" height="60" loading="lazy" decoding="async" style="width:60px;height:60px;object-fit:cover;border-radius:6px;border:1px solid #ddd;">';
                echo '<button type="button" class="ktv-remove-gallery-img" style="position:absolute;top:-5px;right:-5px;background:#dc3545;color:#fff;border:none;border-radius:50%;width:20px;height:20px;cursor:pointer;font-size:12px;line-height:1;">×</button>';
                echo '</div>';
            }
        }
    }
    echo '</div>';
    echo '<input type="hidden" name="tour_gallery" id="ktv-tour-gallery" value="' . esc_attr($gallery_ids) . '">';
    echo '<button type="button" class="button" id="ktv-upload-gallery">🖼️ Add Gallery Images</button>';
    echo '<p class="description">Upload multiple gallery images (comma-separated IDs).</p>';
    echo '</td></tr>';
    echo '<tr><th><label>Gallery Auto Slide</label></th><td><label><input type="checkbox" name="gallery_auto_slide" value="1" ' . checked($vals('gallery_auto_slide', 0), 1, false) . '> Auto Slide</label> &nbsp; Interval (ms): <input type="number" name="gallery_slide_interval" value="' . esc_attr($vals('gallery_slide_interval', 3000)) . '" style="width:80px;"></td></tr>';
    echo '</table>';

    echo '<h3 style="border-bottom:2px solid #075e54;padding-bottom:8px;">💰 Pricing</h3>';
    echo '<table class="form-table">';
    echo '<tr><th><label>Tour Price</label></th><td><input type="number" name="tour_price" step="0.01" value="' . esc_attr($vals('tour_price', 0)) . '" class="regular-text"></td></tr>';
