    <script>
    (function(){
        var uploadBtn = document.getElementById('ktv-upload-tour-image');
        var removeBtn = document.getElementById('ktv-remove-tour-image');
        var imageIdInput = document.getElementById('ktv-tour-image-id');
        var previewDiv = document.getElementById('ktv-tour-image-preview');
        var mediaFrame = null;
        if (uploadBtn) {
            uploadBtn.addEventListener('click', function(e){
                e.preventDefault();
                if (mediaFrame) { mediaFrame.open(); return; }
                mediaFrame = wp.media({
                    title: 'Select Tour Image',
                    button: { text: 'Use this image' },
                    multiple: false
                });
                mediaFrame.on('select', function(){
                    var attachment = mediaFrame.state().get('selection').first().toJSON();
                    if (imageIdInput) imageIdInput.value = attachment.id;
                    if (previewDiv) previewDiv.innerHTML = '<img src="' + (attachment.sizes && attachment.sizes.medium ? attachment.sizes.medium.url : attachment.url) + '" width="200" height="150" loading="lazy" decoding="async" style="max-width:200px;border-radius:8px;border:1px solid #ddd;">';
                    if (uploadBtn) uploadBtn.innerHTML = '📷 Change Image';
                });
                mediaFrame.open();
            });
        }
        if (removeBtn) {
            removeBtn.addEventListener('click', function(e){
                e.preventDefault();
                if (imageIdInput) imageIdInput.value = '0';
                if (previewDiv) previewDiv.innerHTML = '';
                removeBtn.remove();
                if (uploadBtn) uploadBtn.innerHTML = '📷 Upload Image';
            });
        }

        var galleryBtn = document.getElementById('ktv-upload-gallery');
        var galleryInput = document.getElementById('ktv-tour-gallery');
        var galleryPreview = document.getElementById('ktv-gallery-preview');
        var galleryFrame = null;

        function renderGallery() {
            if (!galleryPreview) return;
            var ids = (galleryInput.value || '').split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s.length > 0; });
            galleryPreview.innerHTML = '';
            ids.forEach(function(gid){
                var html = '<div style="position:relative;" data-gid="' + gid + '">';
                html += '<img src="" width="60" height="60" loading="lazy" decoding="async" style="width:60px;height:60px;object-fit:cover;border-radius:6px;border:1px solid #ddd;">';
                html += '<button type="button" class="ktv-remove-gallery-img" style="position:absolute;top:-5px;right:-5px;background:#dc3545;color:#fff;border:none;border-radius:50%;width:20px;height:20px;cursor:pointer;font-size:12px;line-height:1;">×</button>';
                html += '</div>';
                galleryPreview.insertAdjacentHTML('beforeend', html);
            });
            if (wp.media && wp.media.attachment) {
                galleryPreview.querySelectorAll('div[data-gid]').forEach(function(el){
                    var att = wp.media.attachment(el.getAttribute('data-gid'));
                    att.fetch().then(function(){
                        var url = att.get('sizes') && att.get('sizes').thumbnail ? att.get('sizes').thumbnail.url : att.get('url');
                        var img = el.querySelector('img');
                        if (img && url) img.src = url;
                    });
                });
            }
        }

        if (galleryBtn) {
            galleryBtn.addEventListener('click', function(e){
                e.preventDefault();
                if (galleryFrame) { galleryFrame.open(); return; }
                galleryFrame = wp.media({
                    title: 'Select Gallery Images',
                    button: { text: 'Add to gallery' },
                    multiple: true
                });
                galleryFrame.on('select', function(){
                    var selection = galleryFrame.state().get('selection');
                    var existing = (galleryInput.value || '').split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s.length > 0; });
                    selection.each(function(att){
                        var id = String(att.get('id'));
                        if (existing.indexOf(id) === -1) existing.push(id);
                    });
                    galleryInput.value = existing.join(',');
                    renderGallery();
                });
                galleryFrame.open();
            });
        }

        if (galleryPreview) {
            galleryPreview.addEventListener('click', function(e){
                if (e.target.classList.contains('ktv-remove-gallery-img')) {
                    e.preventDefault();
                    var wrap = e.target.closest('div[data-gid]');
                    if (wrap) {
                        var gid = wrap.getAttribute('data-gid');
                        var ids = (galleryInput.value || '').split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s.length > 0 && s !== gid; });
                        galleryInput.value = ids.join(',');
                        renderGallery();
                    }
                }
            });
        }

        renderGallery();
    })();
    </script>
    <?php
}

/* ============================================================
   59. ADMIN FLIGHTS
   ============================================================ */

function ktv_admin_flights() {
    global $wpdb;
    $table = $wpdb->prefix . 'ktv_flights';

    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['delete_flight']) && isset($_POST['fid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $fid = intval($_POST['fid']);
            $wpdb->delete($table, array('id' => $fid));
            echo '<div class="notice notice-success"><p>Flight deleted!</p></div>';
        }
    }

    if (isset($_POST['add_flight'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            ktv_db_insert_safe($table, array(
                'airline'         => sanitize_text_field(wp_unslash(isset($_POST['airline']) ? $_POST['airline'] : '')),
                'flight_number'   => sanitize_text_field(wp_unslash(isset($_POST['flight_number']) ? $_POST['flight_number'] : '')),
                'departure_city'  => sanitize_text_field(wp_unslash(isset($_POST['departure_city']) ? $_POST['departure_city'] : '')),
                'arrival_city'    => sanitize_text_field(wp_unslash(isset($_POST['arrival_city']) ? $_POST['arrival_city'] : '')),
                'departure_time'  => sanitize_text_field(wp_unslash(isset($_POST['departure_time']) ? $_POST['departure_time'] : '')),
                'arrival_time'    => sanitize_text_field(wp_unslash(isset($_POST['arrival_time']) ? $_POST['arrival_time'] : '')),
                'price'           => floatval(isset($_POST['price']) ? $_POST['price'] : 0),
                'currency'        => sanitize_text_field(wp_unslash(isset($_POST['currency']) ? $_POST['currency'] : 'USD')),
                'days_available'  => sanitize_text_field(wp_unslash(isset($_POST['days_available']) ? $_POST['days_available'] : 'All')),
                'sort_order'      => intval(isset($_POST['sort_order']) ? $_POST['sort_order'] : 0),
                'status'          => 'active'
            ));
            echo '<div class="notice notice-success"><p>Flight added!</p></div>';
        }
    }

    $flights = $wpdb->get_results("SELECT * FROM {$table} ORDER BY sort_order ASC");
    echo '<div class="wrap"><h1>✈️ Manage Flights</h1>';
    echo '<form method="post" style="background:#f8f9fa;padding:15px;margin:20px 0;border-radius:8px;"><h3>Add New Flight</h3>';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:10px;align-items:center;">';
    echo '<input name="airline" placeholder="Airline" required style="padding:8px;">';
    echo '<input name="flight_number" placeholder="Flight No" required style="padding:8px;">';
    echo '<input name="departure_city" placeholder="Departure City" required style="padding:8px;">';
    echo '<input name="arrival_city" placeholder="Arrival City" required style="padding:8px;">';
    echo '</div><div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr 1fr 1fr auto;gap:10px;margin-top:10px;align-items:center;">';
    echo '<input name="departure_time" placeholder="Departure Time" value="06:00 AM" style="padding:8px;">';
    echo '<input name="arrival_time" placeholder="Arrival Time" value="07:30 AM" style="padding:8px;">';
    echo '<input name="price" type="number" step="0.01" placeholder="Price" value="100" style="padding:8px;">';
    echo '<input name="currency" placeholder="Currency" value="USD" style="padding:8px;">';
    echo '<input name="days_available" placeholder="Days" value="All" style="padding:8px;">';
    echo '<input name="sort_order" type="number" placeholder="Order" value="0" style="padding:8px;width:80px;">';
    echo '<button name="add_flight" class="button button-primary">Add Flight</button>';
    echo '</div></form>';

    echo '<table class="wp-list-table widefat striped"><thead><tr><th>Order</th><th>Airline</th><th>Flight No</th><th>Route</th><th>Time</th><th>Price</th><th>Days</th><th>Action</th></tr></thead><tbody>';
    if (empty($flights)) {
        echo '<tr><td colspan="8">No flights found. Add your first flight above.</td></tr>';
    } else {
        foreach ($flights as $f) {
            echo '<tr>';
            echo '<td>' . esc_html($f->sort_order) . '</td>';
            echo '<td><strong>' . esc_html($f->airline) . '</strong></td>';
            echo '<td>' . esc_html($f->flight_number) . '</td>';
            echo '<td>' . esc_html($f->departure_city . ' → ' . $f->arrival_city) . '</td>';
            echo '<td>' . esc_html($f->departure_time . ' - ' . $f->arrival_time) . '</td>';
            echo '<td>' . esc_html($f->currency . ' ' . number_format($f->price, 2)) . '</td>';
            echo '<td>' . esc_html($f->days_available) . '</td>';
            echo '<td><form method="post">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="fid" value="' . esc_attr($f->id) . '"><button name="delete_flight" class="button button-small" onclick="return confirm(\'Delete this flight?\')">Delete</button></form></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
}

/* ============================================================
   60. ADMIN LOCATIONS
   ============================================================ */

function ktv_admin_locations() {
    global $wpdb;
    $table = $wpdb->prefix . 'ktv_tour_locations';

    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['delete_location']) && isset($_POST['lid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $lid = intval($_POST['lid']);
            $wpdb->delete($table, array('id' => $lid));
            echo '<div class="notice notice-success"><p>Location deleted!</p></div>';
        }
    }

    if (isset($_POST['add_location'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $location_name = sanitize_text_field(wp_unslash(isset($_POST['location_name']) ? $_POST['location_name'] : ''));
            ktv_db_insert_safe($table, array(
                'location_name'    => $location_name,
                'location_slug'    => sanitize_title($location_name),
                'location_city'    => sanitize_text_field(wp_unslash(isset($_POST['location_city']) ? $_POST['location_city'] : '')),
                'location_region'  => sanitize_text_field(wp_unslash(isset($_POST['location_region']) ? $_POST['location_region'] : '')),
                'location_country' => sanitize_text_field(wp_unslash(isset($_POST['location_country']) ? $_POST['location_country'] : 'India')),
                'location_icon'    => sanitize_text_field(wp_unslash(isset($_POST['location_icon']) ? $_POST['location_icon'] : 'fa-map-marker-alt')),
                'location_color'   => sanitize_text_field(wp_unslash(isset($_POST['location_color']) ? $_POST['location_color'] : '#075e54')),
                'sort_order'       => intval(isset($_POST['sort_order']) ? $_POST['sort_order'] : 0)
            ));
            echo '<div class="notice notice-success"><p>Location added!</p></div>';
        }
    }

    $locations = $wpdb->get_results("SELECT * FROM {$table} ORDER BY sort_order ASC");
    echo '<div class="wrap"><h1>📍 KTV Tour Locations</h1>';
    echo '<form method="post" style="background:#f8f9fa;padding:15px;margin:20px 0;border-radius:8px;"><h3>Add New Location</h3>';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr auto;gap:10px;align-items:center;">';
    echo '<input name="location_name" placeholder="Location Name" required style="padding:8px;">';
    echo '<input name="location_city" placeholder="City (optional)" style="padding:8px;">';
    echo '<input name="location_region" placeholder="Region (optional)" style="padding:8px;">';
    echo '<input name="location_country" placeholder="Country" value="India" style="padding:8px;">';
    echo '<button name="add_location" class="button button-primary">Add Location</button>';
    echo '</div><div style="display:grid;grid-template-columns:1fr auto auto auto;gap:10px;margin-top:10px;align-items:center;">';
    echo '<input name="location_icon" placeholder="Icon (fa-xxx)" value="fa-map-marker-alt" style="padding:8px;">';
    echo '<input name="location_color" type="color" value="#075e54" style="padding:4px;width:60px;">';
    echo '<input name="sort_order" type="number" placeholder="Order" value="0" style="padding:8px;width:80px;">';
    echo '</div></form>';

    echo '<table class="wp-list-table widefat striped"><thead><tr><th>Order</th><th>Icon</th><th>Location Name</th><th>City</th><th>Region</th><th>Country</th><th>Color</th><th>Action</th></tr></thead><tbody>';
    if (empty($locations)) {
        echo '<tr><td colspan="8">No locations found. Add your first location above.</td></tr>';
    } else {
        foreach ($locations as $loc) {
            echo '<tr>';
            echo '<td>' . esc_html($loc->sort_order) . '</td>';
            echo '<td><i class="fas ' . esc_attr($loc->location_icon) . '" style="color:' . esc_attr($loc->location_color) . ';"></i></td>';
            echo '<td>' . esc_html($loc->location_name) . '</td>';
            echo '<td>' . esc_html(isset($loc->location_city) ? $loc->location_city : '') . '</td>';
            echo '<td>' . esc_html(isset($loc->location_region) ? $loc->location_region : '') . '</td>';
            echo '<td>' . esc_html(isset($loc->location_country) ? $loc->location_country : '') . '</td>';
            echo '<td><span style="background:' . esc_attr($loc->location_color) . ';padding:2px 8px;border-radius:4px;color:#fff;">' . esc_html($loc->location_color) . '</span></td>';
            echo '<td><form method="post">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="lid" value="' . esc_attr($loc->id) . '"><button name="delete_location" class="button button-small" onclick="return confirm(\'Delete this location?\')">Delete</button></form></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
}

/* ============================================================
   61. ADMIN CONTACTS
   ============================================================ */

function ktv_admin_contacts() {
    global $wpdb;

    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['delete_contact']) && isset($_POST['cid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $cid = intval($_POST['cid']);
            $wpdb->delete($wpdb->prefix . 'ktv_contacts', array('id' => $cid));
            echo '<div class="notice notice-success"><p>Contact deleted!</p></div>';
        }
    }

    $contacts = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}ktv_contacts ORDER BY id DESC LIMIT 50");

    $contact_cols = ktv_db_get_columns($wpdb->prefix . 'ktv_contacts');
    $has_device = in_array('user_device', $contact_cols, true);
    $has_city = in_array('user_city', $contact_cols, true);
    $has_region = in_array('user_region', $contact_cols, true);
    $has_honeypot = in_array('honeypot_flagged', $contact_cols, true);

    echo '<div class="wrap"><h1>💬 Contact Messages</h1><table class="wp-list-table widefat striped"><thead><tr><th>Name</th><th>Email</th><th>Country</th><th>Travel Dates</th><th>Message</th><th>IP / Country / City / Region / Device</th><th>Flag</th><th>Actions</th></tr></thead><tbody>';
    if (empty($contacts)) {
        echo '<tr><td colspan="8">No contact messages found.</td></tr>';
    } else {
        foreach ($contacts as $c) {
            $flag_html = '';
            if ($has_honeypot && !empty($c->honeypot_flagged)) {
                $flag_html = '<span style="background:#dc3545;color:#fff;padding:2px 6px;border-radius:4px;font-size:10px;">SPAM</span>';
            }
            echo '<tr>';
            echo '<td>' . esc_html($c->name) . '</td>';
            echo '<td>' . esc_html($c->email) . '</td>';
            echo '<td>' . esc_html($c->country) . '</td>';
            echo '<td>' . esc_html($c->arrival_date . ' → ' . $c->departure_date) . '</td>';
            echo '<td>' . esc_html(substr($c->message, 0, 50)) . '...</td>';
            echo '<td><small>';
            echo esc_html($c->user_ip ?: 'N/A') . '<br>';
            echo esc_html($c->user_country ?: 'N/A');
            if ($has_city && !empty($c->user_city)) {
                echo '<br>' . esc_html($c->user_city);
            }
            if ($has_region && !empty($c->user_region)) {
                echo '<br>' . esc_html($c->user_region);
            }
            if ($has_device) {
                echo '<br>' . esc_html(isset($c->user_device) && $c->user_device ? $c->user_device : 'N/A');
            }
            echo '</small></td>';
            echo '<td>' . $flag_html . '</td>';
            echo '<td><form method="post">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="cid" value="' . esc_attr($c->id) . '"><button name="delete_contact" class="button" onclick="return confirm(\'Delete?\')">Delete</button>';
            echo '</form></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
}

/* ============================================================
   62. ADMIN REVIEWS
   ============================================================ */

function ktv_admin_reviews() {
    global $wpdb;

    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['approve_review']) && isset($_POST['rid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $rid = intval($_POST['rid']);
            ktv_db_update_safe($wpdb->prefix . 'ktv_reviews', array('status' => 'approved'), array('id' => $rid));
            $review = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_reviews WHERE id = %d", $rid));
            if ($review && $review->tour_id > 0) {
                $avg_rating = $wpdb->get_var($wpdb->prepare("SELECT AVG(rating) FROM {$wpdb->prefix}ktv_reviews WHERE tour_id = %d AND status = 'approved'", $review->tour_id));
                $total_reviews = $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_reviews WHERE tour_id = %d AND status = 'approved'", $review->tour_id));
                if ($avg_rating && $total_reviews) {
                    ktv_db_update_safe($wpdb->prefix . 'ktv_tours', array('tour_rating' => round($avg_rating, 2), 'total_reviews' => $total_reviews), array('id' => $review->tour_id));
                    ktv_clear_tour_caches();
                }
            }
            echo '<div class="notice notice-success"><p>Review approved!</p></div>';
        }
    }

    if (isset($_POST['delete_review']) && isset($_POST['rid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $rid = intval($_POST['rid']);
            $wpdb->delete($wpdb->prefix . 'ktv_reviews', array('id' => $rid));
            echo '<div class="notice notice-success"><p>Review deleted!</p></div>';
        }
    }

    if (isset($_POST['edit_review']) && isset($_POST['rid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $rid = intval($_POST['rid']);
            $review_image_action = isset($_POST['review_image_action']) ? sanitize_text_field(wp_unslash($_POST['review_image_action'])) : 'keep';

            $data = array(
                'reviewer_name'   => sanitize_text_field(wp_unslash(isset($_POST['reviewer_name']) ? $_POST['reviewer_name'] : '')),
                'reviewer_email'  => sanitize_email(wp_unslash(isset($_POST['reviewer_email']) ? $_POST['reviewer_email'] : '')),
                'rating'          => intval(isset($_POST['rating']) ? $_POST['rating'] : 5),
                'review_title'    => sanitize_text_field(wp_unslash(isset($_POST['review_title']) ? $_POST['review_title'] : '')),
                'review_content'  => wp_kses_post(wp_unslash(isset($_POST['review_content']) ? $_POST['review_content'] : '')),
                'review_language' => sanitize_text_field(wp_unslash(isset($_POST['review_language']) ? $_POST['review_language'] : 'en')),
                'verified'        => isset($_POST['verified']) ? 1 : 0,
                'status'          => sanitize_text_field(wp_unslash(isset($_POST['status']) ? $_POST['status'] : 'pending'))
            );

            if ($review_image_action === 'remove') {
                $data['review_image'] = '';
                $data['review_image_id'] = 0;
            } else {
                if (isset($_FILES['review_image']) && $_FILES['review_image']['error'] === UPLOAD_ERR_OK) {
                    $upload_dir = wp_upload_dir();
                    $review_dir = $upload_dir['basedir'] . '/ktv-reviews/';
                    if (!file_exists($review_dir)) {
                        wp_mkdir_p($review_dir);
                    }
                    $file_name = time() . '_' . sanitize_file_name($_FILES['review_image']['name']);
                    $file_path = $review_dir . $file_name;
                    $file_url  = $upload_dir['baseurl'] . '/ktv-reviews/' . $file_name;
                    if (move_uploaded_file($_FILES['review_image']['tmp_name'], $file_path)) {
                        $data['review_image'] = $file_url;
                        ktv_optimize_review_image($file_path, 90);
                    }
                }
            }

            if (isset($_FILES['reviewer_profile_pic']) && $_FILES['reviewer_profile_pic']['error'] === UPLOAD_ERR_OK) {
                $upload_dir = wp_upload_dir();
                $profile_dir = $upload_dir['basedir'] . '/ktv-reviews/profiles/';
                if (!file_exists($profile_dir)) {
                    wp_mkdir_p($profile_dir);
                }
                $file_name = time() . '_profile_' . sanitize_file_name($_FILES['reviewer_profile_pic']['name']);
                $file_path = $profile_dir . $file_name;
                $file_url  = $upload_dir['baseurl'] . '/ktv-reviews/profiles/' . $file_name;
                if (move_uploaded_file($_FILES['reviewer_profile_pic']['tmp_name'], $file_path)) {
                    $data['reviewer_profile_pic'] = $file_url;
                    ktv_optimize_review_image($file_path, 98);
                }
            }

            ktv_db_update_safe($wpdb->prefix . 'ktv_reviews', $data, array('id' => $rid));
            echo '<div class="notice notice-success"><p>Review #' . intval($rid) . ' updated successfully!</p></div>';
        }
    }

    if (isset($_GET['action']) && $_GET['action'] === 'edit' && isset($_GET['rid'])) {
        $edit_rid = intval($_GET['rid']);
        $review = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_reviews WHERE id = %d", $edit_rid));
        if ($review) {
            echo '<div class="wrap"><h1>✏️ Edit Review #' . esc_html($review->id) . '</h1>';
            echo '<form method="post" enctype="multipart/form-data">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="rid" value="' . esc_attr($review->id) . '">';
            echo '<table class="form-table">';
            echo '<tr><th>Reviewer Name</th><td><input type="text" name="reviewer_name" value="' . esc_attr($review->reviewer_name) . '" class="regular-text" required></td></tr>';
            echo '<tr><th>Reviewer Email</th><td><input type="email" name="reviewer_email" value="' . esc_attr($review->reviewer_email) . '" class="regular-text" required></td></tr>';
            echo '<tr><th>Rating (1-5)</th><td><input type="number" name="rating" min="1" max="5" value="' . esc_attr($review->rating) . '" style="width:80px;"></td></tr>';
            echo '<tr><th>Review Title</th><td><input type="text" name="review_title" value="' . esc_attr($review->review_title) . '" class="regular-text"></td></tr>';
            echo '<tr><th>Review Content</th><td><textarea name="review_content" rows="6" class="large-text" required>' . esc_textarea($review->review_content) . '</textarea><p class="description">HTML allowed (wp_kses_post filter). Line breaks auto-converted to paragraphs on the frontend.</p></td></tr>';
            echo '<tr><th>Language</th><td><select name="review_language">';
            $langs = array('en' => 'English', 'hi' => 'Hindi', 'ur' => 'Urdu', 'ar' => 'Arabic', 'fr' => 'French', 'es' => 'Spanish', 'de' => 'German');
            foreach ($langs as $code => $label) {
                echo '<option value="' . esc_attr($code) . '" ' . selected($review->review_language, $code, false) . '>' . esc_html($label) . '</option>';
            }
            echo '</select></td></tr>';
            echo '<tr><th>Verified</th><td><input type="checkbox" name="verified" value="1" ' . checked($review->verified, 1, false) . '></td></tr>';
            echo '<tr><th>Status</th><td><select name="status"><option value="pending" ' . selected($review->status, 'pending', false) . '>Pending</option><option value="approved" ' . selected($review->status, 'approved', false) . '>Approved</option><option value="rejected" ' . selected($review->status, 'rejected', false) . '>Rejected</option></select></td></tr>';
            echo '<tr><th>Review Image</th><td>';
            if (!empty($review->review_image)) {
                echo '<img src="' . esc_url($review->review_image) . '" width="150" height="150" loading="lazy" decoding="async" style="max-width:150px;border-radius:6px;display:block;margin-bottom:8px;">';
            }
            echo '<select name="review_image_action"><option value="keep">Keep Current Image</option><option value="remove">Remove Image</option></select><br>';
            echo '<input type="file" name="review_image" accept="image/*" style="margin-top:8px;"></td></tr>';
            echo '<tr><th>Reviewer Profile Pic</th><td>';
            $pic_url = !empty($review->reviewer_profile_pic) ? $review->reviewer_profile_pic : $review->reviewer_avatar;
            if (!empty($pic_url)) {
                echo '<img src="' . esc_url($pic_url) . '" width="60" height="60" loading="lazy" decoding="async" style="width:60px;height:60px;border-radius:50%;object-fit:cover;display:block;margin-bottom:8px;">';
            }
            echo '<input type="file" name="reviewer_profile_pic" accept="image/*"><br><small>Auto-optimized to 98% quality on upload.</small></td></tr>';
            echo '</table>';
            echo '<p><button type="submit" name="edit_review" class="button button-primary">💾 Save Changes</button> ';
            echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-reviews')) . '" class="button">Cancel</a></p>';
            echo '</form></div>';
            return;
        }
    }

    $reviews = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}ktv_reviews ORDER BY id DESC LIMIT 50");
    echo '<div class="wrap"><h1>⭐ KTV Reviews</h1><table class="wp-list-table widefat striped"><thead><tr><th>Rating</th><th>Tour</th><th>Name</th><th>Review</th><th>Image</th><th>Language</th><th>Status</th><th>Action</th></tr></thead><tbody>';
    if (empty($reviews)) {
        echo '<tr><td colspan="8">No reviews found.</td></tr>';
    } else {
        foreach ($reviews as $r) {
            $stars_display = '';
            for ($i = 1; $i <= 5; $i++) {
                $stars_display .= $i <= $r->rating ? '★' : '☆';
            }
            echo '<tr>';
            echo '<td>' . esc_html($stars_display) . '</td>';
            echo '<td>' . esc_html($r->tour_name ?: 'N/A') . '</td>';
            echo '<td>' . esc_html($r->reviewer_name) . '</td>';
            echo '<td>' . esc_html(substr($r->review_content, 0, 40)) . '...</td>';
            echo '<td>' . (!empty($r->review_image) ? '📷' : '') . '</td>';
            echo '<td>' . esc_html($r->review_language ?: 'en') . '</td>';
            echo '<td>' . esc_html($r->status) . '</td>';
            echo '<td>';
            if ($r->status == 'pending') {
                echo '<form method="post" style="display:inline;margin-right:3px;">';
                wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
                echo '<input type="hidden" name="rid" value="' . esc_attr($r->id) . '"><button name="approve_review" class="button button-primary button-small">Approve</button>';
                echo '</form> ';
            }
            echo '<a href="' . esc_url(admin_url('admin.php?page=ktv-reviews&action=edit&rid=' . $r->id)) . '" class="button button-small" style="margin-right:3px;">✏️ Edit</a>';
            echo '<form method="post" style="display:inline;">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="rid" value="' . esc_attr($r->id) . '"><button name="delete_review" class="button button-small" onclick="return confirm(\'Delete?\')">🗑️ Delete</button>';
            echo '</form>';
            echo '</td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
}

/* ============================================================
   63. ADMIN ACCORDION AND TABS
   ============================================================ */

function ktv_admin_accordion() {
    global $wpdb;
    $table = $wpdb->prefix . 'ktv_accordion_items';

    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['add_acc'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            ktv_db_insert_safe($table, array(
                'item_title'       => sanitize_text_field(wp_unslash(isset($_POST['title']) ? $_POST['title'] : '')),
                'item_after_title_text' => sanitize_text_field(wp_unslash(isset($_POST['after_title_text']) ? $_POST['after_title_text'] : '')),
                'item_content'     => wp_kses_post(isset($_POST['content']) ? $_POST['content'] : ''),
                'item_order'       => intval(isset($_POST['order']) ? $_POST['order'] : 0),
                'item_icon'        => sanitize_text_field(wp_unslash(isset($_POST['icon']) ? $_POST['icon'] : 'fa-map-pin')),
                'item_icon_color'  => sanitize_text_field(wp_unslash(isset($_POST['icon_color']) ? $_POST['icon_color'] : '#075e54')),
                'item_icon_size'   => sanitize_text_field(wp_unslash(isset($_POST['icon_size']) ? $_POST['icon_size'] : '16px')),
                'item_title_size'  => sanitize_text_field(wp_unslash(isset($_POST['title_size']) ? $_POST['title_size'] : '16px')),
                'item_title_color' => sanitize_text_field(wp_unslash(isset($_POST['title_color']) ? $_POST['title_color'] : '#333333')),
                'item_title_weight'=> sanitize_text_field(wp_unslash(isset($_POST['title_weight']) ? $_POST['title_weight'] : '600')),
                'after_title_font_size' => sanitize_text_field(wp_unslash(isset($_POST['after_title_font_size']) ? $_POST['after_title_font_size'] : '12px')),
                'after_title_color' => sanitize_text_field(wp_unslash(isset($_POST['after_title_color']) ? $_POST['after_title_color'] : '#666666')),
                'icon_position'    => sanitize_text_field(wp_unslash(isset($_POST['icon_position']) ? $_POST['icon_position'] : 'left')),
                'tour_id'          => intval(isset($_POST['tour_id']) ? $_POST['tour_id'] : 0),
                'page_id'          => intval(isset($_POST['page_id']) ? $_POST['page_id'] : 0),
                'first_open'       => isset($_POST['first_open']) ? 1 : 0
            ));
            echo '<div class="notice notice-success"><p>Accordion item added!</p></div>';
        }
    }

    if (isset($_POST['del_acc']) && isset($_POST['aid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $aid = intval($_POST['aid']);
            $wpdb->delete($table, array('id' => $aid));
            echo '<div class="notice notice-success"><p>Accordion item deleted!</p></div>';
        }
    }

    $items = $wpdb->get_results("SELECT * FROM {$table} ORDER BY item_order ASC");
    echo '<div class="wrap"><h1>📋 KTV Accordion Items</h1>';
    echo '<h3>Add New Item</h3><form method="post"><table class="form-table">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<tr><th>Title</th><td><input name="title" class="regular-text" required></td></tr>';
    echo '<tr><th>After Title Text (shows below title)</th><td><input name="after_title_text" class="regular-text" placeholder="Short description below the title"></td></tr>';
    echo '<tr><th>Content</th><td><textarea name="content" rows="5" class="large-text"></textarea></td></tr>';
    echo '<tr><th>Icon (FontAwesome)</th><td><input name="icon" value="fa-map-pin" class="regular-text"></td></tr>';
    echo '<tr><th>Icon Color</th><td><input name="icon_color" value="#075e54" type="color"></td></tr>';
    echo '<tr><th>Icon Size</th><td><input name="icon_size" value="16px" style="width:80px;"></td></tr>';
    echo '<tr><th>Icon Position</th><td><select name="icon_position"><option value="left">Left</option><option value="right">Right</option></select></td></tr>';
    echo '<tr><th>Title Size</th><td><input name="title_size" value="16px" style="width:80px;"></td></tr>';
    echo '<tr><th>Title Color</th><td><input name="title_color" value="#333333" type="color"></td></tr>';
    echo '<tr><th>Title Font Weight</th><td><select name="title_weight"><option value="400">Normal</option><option value="600" selected>Semi Bold</option><option value="700">Bold</option></select></td></tr>';
    echo '<tr><th>After Title Font Size</th><td><input name="after_title_font_size" value="12px" style="width:80px;"></td></tr>';
    echo '<tr><th>After Title Color</th><td><input name="after_title_color" value="#666666" type="color"></td></tr>';
    echo '<tr><th>Order</th><td><input name="order" type="number" value="1"></td></tr>';
    echo '<tr><th>Tour ID (optional)</th><td><input name="tour_id" type="number" value="0"></td></tr>';
    echo '<tr><th>Page ID (optional)</th><td><input name="page_id" type="number" value="0"></td></tr>';
    echo '<tr><th>First Open</th><td><input name="first_open" type="checkbox" value="1"></td></tr>';
    echo '</table><p><button name="add_acc" class="button button-primary">Add Item</button></p></form>';

    echo '<table class="wp-list-table widefat striped"><thead><tr><th>Order</th><th>Icon</th><th>Title</th><th>After Title Text</th><th>First Open</th><th>Tour ID</th><th>Page ID</th><th>Action</th></tr></thead><tbody>';
    if (empty($items)) {
        echo '<tr><td colspan="8">No accordion items found.</td></tr>';
    } else {
        foreach ($items as $i) {
            echo '<tr>';
            echo '<td>' . esc_html($i->item_order) . '</td>';
            echo '<td><i class="fas ' . esc_attr($i->item_icon) . '" style="color:' . esc_attr($i->item_icon_color) . ';"></i></td>';
            echo '<td>' . esc_html($i->item_title) . '</td>';
            echo '<td><small>' . esc_html(isset($i->item_after_title_text) ? $i->item_after_title_text : '') . '</small></td>';
            echo '<td>' . ($i->first_open ? '✅ Yes' : '❌ No') . '</td>';
            echo '<td>' . esc_html($i->tour_id) . '</td>';
            echo '<td>' . esc_html($i->page_id) . '</td>';
            echo '<td><form method="post" style="display:inline;">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="aid" value="' . esc_attr($i->id) . '"><button name="del_acc" class="button" onclick="return confirm(\'Delete?\')">Delete</button>';
            echo '</form></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
}

function ktv_admin_tabs() {
    global $wpdb;
    $table = $wpdb->prefix . 'ktv_tab_items';

    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['add_tb'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            ktv_db_insert_safe($table, array(
                'tab_title'             => sanitize_text_field(wp_unslash(isset($_POST['title']) ? $_POST['title'] : '')),
                'tab_after_title_text'  => sanitize_text_field(wp_unslash(isset($_POST['after_title_text']) ? $_POST['after_title_text'] : '')),
                'tab_content'           => wp_kses_post(isset($_POST['content']) ? $_POST['content'] : ''),
                'tab_icon'              => sanitize_text_field(wp_unslash(isset($_POST['icon']) ? $_POST['icon'] : 'fa-info-circle')),
                'tab_icon_color'        => sanitize_text_field(wp_unslash(isset($_POST['icon_color']) ? $_POST['icon_color'] : '#075e54')),
                'tab_icon_size'         => sanitize_text_field(wp_unslash(isset($_POST['icon_size']) ? $_POST['icon_size'] : '16px')),
                'tab_title_size'        => sanitize_text_field(wp_unslash(isset($_POST['title_size']) ? $_POST['title_size'] : '14px')),
                'tab_title_color'       => sanitize_text_field(wp_unslash(isset($_POST['title_color']) ? $_POST['title_color'] : '#333333')),
                'tab_title_weight'      => sanitize_text_field(wp_unslash(isset($_POST['title_weight']) ? $_POST['title_weight'] : '600')),
                'tab_after_title_font_size' => sanitize_text_field(wp_unslash(isset($_POST['after_title_font_size']) ? $_POST['after_title_font_size'] : '11px')),
                'tab_after_title_color' => sanitize_text_field(wp_unslash(isset($_POST['after_title_color']) ? $_POST['after_title_color'] : '#666666')),
                'tab_active_color'      => sanitize_text_field(wp_unslash(isset($_POST['active_color']) ? $_POST['active_color'] : '#075e54')),
                'tab_active_text_color' => sanitize_text_field(wp_unslash(isset($_POST['active_text_color']) ? $_POST['active_text_color'] : '#ffffff')),
                'tab_content_bg_color'  => sanitize_text_field(wp_unslash(isset($_POST['content_bg']) ? $_POST['content_bg'] : '#ffffff')),
                'tab_border_radius'     => sanitize_text_field(wp_unslash(isset($_POST['border_radius']) ? $_POST['border_radius'] : '8px')),
                'tab_order'             => intval(isset($_POST['order']) ? $_POST['order'] : 0),
                'tour_id'               => intval(isset($_POST['tour_id']) ? $_POST['tour_id'] : 0),
                'page_id'               => intval(isset($_POST['page_id']) ? $_POST['page_id'] : 0),
                'first_open'            => isset($_POST['first_open']) ? 1 : 0
            ));
            echo '<div class="notice notice-success"><p>Tab added!</p></div>';
        }
    }

    if (isset($_POST['del_tb']) && isset($_POST['tid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $tid = intval($_POST['tid']);
            $wpdb->delete($table, array('id' => $tid));
            echo '<div class="notice notice-success"><p>Tab deleted!</p></div>';
        }
    }

    $items = $wpdb->get_results("SELECT * FROM {$table} ORDER BY tab_order ASC");
    echo '<div class="wrap"><h1>📋 KTV Tab Items</h1>';
    echo '<h3>Add New Tab</h3><form method="post"><table class="form-table">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<tr><th>Title</th><td><input name="title" class="regular-text" required></td></tr>';
    echo '<tr><th>After Title Text</th><td><input name="after_title_text" class="regular-text" placeholder="Short description below the tab title"></td></tr>';
    echo '<tr><th>Content</th><td><textarea name="content" rows="5" class="large-text"></textarea></td></tr>';
    echo '<tr><th>Icon</th><td><input name="icon" value="fa-info-circle" class="regular-text"></td></tr>';
    echo '<tr><th>Icon Color</th><td><input name="icon_color" value="#075e54" type="color"></td></tr>';
    echo '<tr><th>Icon Size</th><td><input name="icon_size" value="16px" style="width:80px;"></td></tr>';
    echo '<tr><th>Title Size</th><td><input name="title_size" value="14px" style="width:80px;"></td></tr>';
    echo '<tr><th>Title Color</th><td><input name="title_color" value="#333333" type="color"></td></tr>';
    echo '<tr><th>Title Font Weight</th><td><select name="title_weight"><option value="400">Normal</option><option value="600" selected>Semi Bold</option><option value="700">Bold</option></select></td></tr>';
    echo '<tr><th>After Title Font Size</th><td><input name="after_title_font_size" value="11px" style="width:80px;"></td></tr>';
    echo '<tr><th>After Title Color</th><td><input name="after_title_color" value="#666666" type="color"></td></tr>';
    echo '<tr><th>Active Tab Color</th><td><input name="active_color" value="#075e54" type="color"></td></tr>';
    echo '<tr><th>Active Tab Text Color</th><td><input name="active_text_color" value="#ffffff" type="color"></td></tr>';
    echo '<tr><th>Content Background</th><td><input name="content_bg" value="#ffffff" type="color"></td></tr>';
    echo '<tr><th>Border Radius</th><td><input name="border_radius" value="8px" style="width:80px;"></td></tr>';
    echo '<tr><th>Order</th><td><input name="order" type="number" value="1"></td></tr>';
    echo '<tr><th>Tour ID (optional)</th><td><input name="tour_id" type="number" value="0"></td></tr>';
    echo '<tr><th>Page ID (optional)</th><td><input name="page_id" type="number" value="0"></td></tr>';
    echo '<tr><th>First Open</th><td><input name="first_open" type="checkbox" value="1"></td></tr>';
    echo '</table><p><button name="add_tb" class="button button-primary">Add Tab</button></p></form>';

    echo '<table class="wp-list-table widefat fixed striped"><thead><tr><th>Order</th><th>Icon</th><th>Title</th><th>After Title Text</th><th>First Open</th><th>Tour ID</th><th>Page ID</th><th>Action</th></tr></thead><tbody>';
    if (empty($items)) {
        echo '<tr><td colspan="8">No tabs found.</td></tr>';
    } else {
        foreach ($items as $i) {
            echo '<tr>';
            echo '<td>' . esc_html($i->tab_order) . '</td>';
            echo '<td><i class="fas ' . esc_attr($i->tab_icon) . '" style="color:' . esc_attr($i->tab_icon_color) . ';"></i></td>';
            echo '<td>' . esc_html($i->tab_title) . '</td>';
            echo '<td><small>' . esc_html(isset($i->tab_after_title_text) ? $i->tab_after_title_text : '') . '</small></td>';
            echo '<td>' . ($i->first_open ? '✅ Yes' : '❌ No') . '</td>';
            echo '<td>' . esc_html($i->tour_id) . '</td>';
            echo '<td>' . esc_html($i->page_id) . '</td>';
            echo '<td><form method="post">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="tid" value="' . esc_attr($i->id) . '"><button name="del_tb" class="button" onclick="return confirm(\'Delete?\')">Delete</button>';
            echo '</form></td>';
            echo '</tr>';
        }
    }
    echo '</tbody></table></div>';
}
