                'voucher_email_show_tour_name'      => isset($_POST['voucher_email_show_tour_name']) ? '1' : '0',
                'voucher_email_show_block_source'   => isset($_POST['voucher_email_show_block_source']) ? '1' : '0',
                'voucher_email_show_travelling_to'  => isset($_POST['voucher_email_show_travelling_to']) ? '1' : '0',
                'voucher_email_show_guest_country'  => isset($_POST['voucher_email_show_guest_country']) ? '1' : '0',
                'voucher_email_show_company_name'   => isset($_POST['voucher_email_show_company_name']) ? '1' : '0',
                'voucher_email_show_logo'           => isset($_POST['voucher_email_show_logo']) ? '1' : '0',
                'voucher_email_logo_size'           => sanitize_text_field(wp_unslash(isset($_POST['voucher_email_logo_size']) ? $_POST['voucher_email_logo_size'] : '120')),
                'voucher_email_footer_text'         => sanitize_text_field(wp_unslash(isset($_POST['voucher_email_footer_text']) ? $_POST['voucher_email_footer_text'] : 'Thank you for choosing Kashmir Travelling Voyage'))
            );
                foreach ($settings as $key => $value) {
                ktv_update_setting($key, $value);
            }

            if (isset($_POST['currency_rates_inr_per']) && is_array($_POST['currency_rates_inr_per'])) {
                $rm = array('INR' => 1.00);
                foreach (wp_unslash($_POST['currency_rates_inr_per']) as $c => $v) {
                    $c = strtoupper(sanitize_key($c));
                    $v = floatval($v);
                    if ($c === '' || $c === 'INR' || $v <= 0) continue;
                    $rm[$c] = round(1 / $v, 7);
                }
                ktv_update_setting('currency_rates_map', wp_json_encode($rm));
            }

            if (isset($_POST['currency_symbols_map']) && is_array($_POST['currency_symbols_map'])) {
                $sm = array();
                foreach (wp_unslash($_POST['currency_symbols_map']) as $c => $v) {
                    $c = strtoupper(sanitize_key($c));
                    $v = sanitize_text_field($v);
                    if ($c !== '' && $v !== '') $sm[$c] = $v;
                }
                ktv_update_setting('currency_symbols_map', wp_json_encode($sm));
            }

            ktv_flush_setting_cache();
            echo '<div class="notice notice-success"><p>✅ Voucher settings saved!</p></div>';
        }
    }

    $header_bg = ktv_get_setting('voucher_header_bg', '#075e54');

    $test_result = null;
    if (isset($_POST['test_voucher_logo']) && wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
        $logo_url_diag = ktv_get_voucher_logo_url();
        $data_uri_diag = ktv_get_voucher_logo_data_uri();

        $test_result = array(
            'url'          => $logo_url_diag,
            'url_set'      => !empty($logo_url_diag),
            'data_uri_len' => strlen($data_uri_diag),
            'data_uri_ok'  => strlen($data_uri_diag) > 0,
            'data_uri_preview' => substr($data_uri_diag, 0, 60) . (strlen($data_uri_diag) > 60 ? '...' : ''),
            'theme_logo_id' => get_theme_mod('custom_logo'),
            'site_icon_id' => get_option('site_icon')
        );
    }

