    echo '<tr><th><label>Icon Color</label></th><td><input type="color" name="voucher_btn_icon_color" value="' . esc_attr(ktv_get_setting('voucher_btn_icon_color', '#ffffff')) . '"></td></tr>';
    echo '<tr><th><label>Gap Between Buttons</label></th><td><input name="voucher_btn_gap" value="' . esc_attr(ktv_get_setting('voucher_btn_gap', '12px')) . '" class="small-text"><p class="description">Vertical/horizontal gap between button rows. Default 12px.</p></td></tr>';
    echo '<tr><th><label>Button Border Radius</label></th><td><input name="voucher_btn_border_radius" value="' . esc_attr(ktv_get_setting('voucher_btn_border_radius', '8px')) . '" class="small-text"></td></tr>';
    echo '</table>';

    echo '<h3>Sections</h3>';
    echo '<table class="form-table">';
    echo '<tr><th><label>Show Logo</label></th><td><label><input type="checkbox" name="voucher_show_logo" value="1" ' . checked(ktv_get_setting('voucher_show_logo', '1'), '1', false) . '> Display logo in voucher header</label></td></tr>';
    echo '<tr><th><label>Show Kids</label></th><td><label><input type="checkbox" name="voucher_show_kids" value="1" ' . checked(ktv_get_setting('voucher_show_kids', '1'), '1', false) . '> Show kids count line and price</label></td></tr>';
    echo '<tr><th><label>Show Booked Via (Host Only)</label></th><td><label><input type="checkbox" name="voucher_show_booked_via" value="1" ' . checked(ktv_get_setting('voucher_show_booked_via', '0'), '1', false) . '> Show "Booked Via" section (never shown to guest)</label></td></tr>';
    echo '<tr><th><label>Show Important Info</label></th><td><label><input type="checkbox" name="voucher_show_important_info" value="1" ' . checked(ktv_get_setting('voucher_show_important_info', '1'), '1', false) . '> Show "Important Information" block</label></td></tr>';
    echo '<tr><th><label>Show Cancellation Policy</label></th><td><label><input type="checkbox" name="voucher_show_cancellation_policy" value="1" ' . checked(ktv_get_setting('voucher_show_cancellation_policy', '1'), '1', false) . '> Show cancellation policy</label></td></tr>';
    echo '<tr><th><label>Show Card Details</label></th><td><label><input type="checkbox" name="voucher_show_card_details" value="1" ' . checked(ktv_get_setting('voucher_show_card_details', '1'), '1', false) . '> Show credit card last-4 details</label></td></tr>';
    echo '<tr><th><label>Show GPay Details</label></th><td><label><input type="checkbox" name="voucher_show_gpay_details" value="1" ' . checked(ktv_get_setting('voucher_show_gpay_details', '1'), '1', false) . '> Show UPI / GPay ID</label></td></tr>';
    echo '<tr><th><label>Show Promo Details</label></th><td><label><input type="checkbox" name="voucher_show_promo_details" value="1" ' . checked(ktv_get_setting('voucher_show_promo_details', '1'), '1', false) . '> Show promo code used</label></td></tr>';
    echo '<tr><th><label>Show Flight Details</label></th><td><label><input type="checkbox" name="voucher_show_flight_details" value="1" ' . checked(ktv_get_setting('voucher_show_flight_details', '1'), '1', false) . '> Show flight details block</label></td></tr>';
