/* ============================================================
   65. ADMIN AUTO MESSAGES
   ============================================================ */

function ktv_admin_auto_messages() {
    global $wpdb;

    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['edit_auto_message']) && isset($_POST['mid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $mid = intval($_POST['mid']);
            $data = array(
                'subject'      => sanitize_text_field(wp_unslash(isset($_POST['subject']) ? $_POST['subject'] : '')),
                'message_body' => wp_kses_post(isset($_POST['message_body']) ? $_POST['message_body'] : ''),
                'send_status'  => sanitize_text_field(wp_unslash(isset($_POST['status']) ? $_POST['status'] : 'sent')),
                'message_type' => sanitize_text_field(wp_unslash(isset($_POST['message_type']) ? $_POST['message_type'] : 'custom')),
                'booking_ref'  => sanitize_text_field(wp_unslash(isset($_POST['booking_ref']) ? $_POST['booking_ref'] : '')),
                'tour_name'    => sanitize_text_field(wp_unslash(isset($_POST['tour_name']) ? $_POST['tour_name'] : '')),
                'tour_id'      => intval(isset($_POST['tour_id']) ? $_POST['tour_id'] : 0),
                'block_type'   => sanitize_text_field(wp_unslash(isset($_POST['block_type']) ? $_POST['block_type'] : 'grid'))
            );
            ktv_db_update_safe($wpdb->prefix . 'ktv_auto_messages', $data, array('id' => $mid));
            echo '<div class="notice notice-success"><p>✅ Auto message #' . intval($mid) . ' updated successfully!</p></div>';
        }
    }

    if (isset($_POST['delete_auto_message']) && isset($_POST['mid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $mid = intval($_POST['mid']);
            $wpdb->delete($wpdb->prefix . 'ktv_auto_messages', array('id' => $mid));
            echo '<div class="notice notice-success"><p>✅ Auto message #' . intval($mid) . ' deleted successfully!</p></div>';
        }
    }

    if (isset($_POST['resend_auto_message']) && isset($_POST['mid'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $mid = intval($_POST['mid']);
            $message = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ktv_auto_messages WHERE id = %d", $mid));

            if ($message) {
                $sent = ktv_send_email($message->recipient_email, $message->subject, wp_kses_post($message->message_body));
                if ($sent) {
                    ktv_db_update_safe($wpdb->prefix . 'ktv_auto_messages', array('sent_at' => current_time('mysql'), 'send_status' => 'sent', 'error_message' => ''), array('id' => $mid));
                    echo '<div class="notice notice-success"><p>✅ Message resent to ' . esc_html($message->recipient_email) . ' successfully!</p></div>';
                } else {
                    echo '<div class="notice notice-error"><p>❌ Failed to resend message. Check error log / email settings.</p></div>';
                }
            }
        }
    }

    if (isset($_POST['add_auto_message'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $recipient_email = sanitize_email(wp_unslash(isset($_POST['recipient_email']) ? $_POST['recipient_email'] : ''));
            $subject = sanitize_text_field(wp_unslash(isset($_POST['subject']) ? $_POST['subject'] : ''));
            $message_body = wp_kses_post(isset($_POST['message_body']) ? $_POST['message_body'] : '');

            if (!empty($recipient_email) && !empty($subject) && !empty($message_body)) {
                ktv_db_insert_safe($wpdb->prefix . 'ktv_auto_messages', array(
                    'message_type'    => sanitize_text_field(wp_unslash(isset($_POST['message_type']) ? $_POST['message_type'] : 'custom')),
                    'recipient_email' => $recipient_email,
                    'recipient_name'  => sanitize_text_field(wp_unslash(isset($_POST['recipient_name']) ? $_POST['recipient_name'] : '')),
                    'subject'         => $subject,
                    'message_body'    => $message_body,
                    'booking_ref'     => sanitize_text_field(wp_unslash(isset($_POST['booking_ref']) ? $_POST['booking_ref'] : '')),
                    'tour_name'       => sanitize_text_field(wp_unslash(isset($_POST['tour_name']) ? $_POST['tour_name'] : '')),
                    'tour_id'         => intval(isset($_POST['tour_id']) ? $_POST['tour_id'] : 0),
                    'block_type'      => sanitize_text_field(wp_unslash(isset($_POST['block_type']) ? $_POST['block_type'] : 'grid')),
                    'sent_at'         => current_time('mysql'),
                    'send_status'     => 'sent'
                ));
                $sent = ktv_send_email($recipient_email, $subject, $message_body);
                if (!$sent) {
                    echo '<div class="notice notice-warning"><p>⚠️ Auto message saved but email could not be sent. Check error log.</p></div>';
                } else {
                    echo '<div class="notice notice-success"><p>✅ Auto message created and sent to ' . esc_html($recipient_email) . '!</p></div>';
                }
            } else {
                echo '<div class="notice notice-error"><p>❌ Please fill all required fields (Email, Subject, Message).</p></div>';
            }
        }
    }

    $auto_messages = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}ktv_auto_messages ORDER BY id DESC LIMIT 50");

    echo '<div class="wrap"><h1>💬 KTV Auto Messages</h1>';
    echo '<p class="description">Auto-reply messages sent to customers. Edit message content and manage all sections.</p>';

    echo '<div style="background:#f0f4f8;padding:20px;border-radius:12px;margin:20px 0;">';
    echo '<h3>➕ Create New Auto Message</h3>';
    echo '<form method="post" style="display:grid;grid-template-columns:1fr 1fr;gap:15px;">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<div><label style="font-weight:600;">Message Type *</label><br><select name="message_type" style="width:100%;padding:8px;border-radius:4px;border:1px solid #ddd;"><option value="booking_confirmation">Booking Confirmation</option><option value="contact_reply">Contact Reply</option><option value="custom" selected>Custom</option></select></div>';
    echo '<div><label style="font-weight:600;">Recipient Email *</label><br><input type="email" name="recipient_email" required style="width:100%;padding:8px;border-radius:4px;border:1px solid #ddd;"></div>';
    echo '<div><label style="font-weight:600;">Recipient Name</label><br><input type="text" name="recipient_name" style="width:100%;padding:8px;border-radius:4px;border:1px solid #ddd;"></div>';
    echo '<div><label style="font-weight:600;">Subject *</label><br><input type="text" name="subject" required style="width:100%;padding:8px;border-radius:4px;border:1px solid #ddd;"></div>';
    echo '<div><label style="font-weight:600;">Booking Ref</label><br><input type="text" name="booking_ref" style="width:100%;padding:8px;border-radius:4px;border:1px solid #ddd;" placeholder="KTV123456"></div>';
    echo '<div><label style="font-weight:600;">Tour Name</label><br><input type="text" name="tour_name" style="width:100%;padding:8px;border-radius:4px;border:1px solid #ddd;"></div>';
    echo '<div><label style="font-weight:600;">Tour ID</label><br><input type="number" name="tour_id" style="width:100%;padding:8px;border-radius:4px;border:1px solid #ddd;" value="0"></div>';
    echo '<div><label style="font-weight:600;">Block Type</label><br><select name="block_type" style="width:100%;padding:8px;border-radius:4px;border:1px solid #ddd;"><option value="grid">KTV Tour Grid</option><option value="package">KTV Tour Package</option><option value="card">KTV Tour Card</option><option value="booking_form">KTV Booking Form</option></select></div>';
    echo '<div style="grid-column:1/-1;"><label style="font-weight:600;">Message Body * (HTML allowed)</label><br><textarea name="message_body" id="message_body_editor" rows="8" style="width:100%;padding:10px;border-radius:4px;border:1px solid #ddd;font-family:monospace;font-size:14px;"></textarea>';
    echo '<div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;">';
    $variables = array('{name}', '{email}', '{booking_ref}', '{tour_type}', '{arrival_date}', '{departure_date}', '{total_amount}', '{voucher_code}');
    foreach ($variables as $var) {
        echo '<button type="button" class="button button-small" data-insert-var="' . esc_attr($var) . '">Insert ' . esc_html($var) . '</button>';
    }
    echo '</div></div>';
    echo '<div style="grid-column:1/-1;"><button name="add_auto_message" class="button button-primary">📨 Create &amp; Send Auto Message</button></div>';
    echo '</form></div>';

    if (!empty($auto_messages)) {
        echo '<h3>📋 Existing Auto Messages</h3>';
        echo '<table class="wp-list-table widefat striped"><thead><tr><th>ID</th><th>Type</th><th>Recipient</th><th>Subject</th><th>Message Body</th><th>Ref/Tour</th><th>Block Type</th><th>Sent At</th><th>Status</th><th>Actions</th></tr></thead><tbody>';

        foreach ($auto_messages as $msg) {
            $status_color = '#28a745';
            if ($msg->send_status === 'failed') {
                $status_color = '#dc3545';
            } elseif ($msg->send_status === 'pending') {
                $status_color = '#ffc107';
            }

            echo '<tr>';
            echo '<td><strong>#' . esc_html($msg->id) . '</strong></td>';
            echo '<td>' . esc_html(str_replace('_', ' ', $msg->message_type)) . '</td>';
            echo '<td><strong>' . esc_html($msg->recipient_name) . '</strong><br><small>' . esc_html($msg->recipient_email) . '</small></td>';
            echo '<form method="post" style="display:contents;">';
            wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
            echo '<input type="hidden" name="mid" value="' . esc_attr($msg->id) . '">';
            echo '<td><input type="text" name="subject" value="' . esc_attr($msg->subject) . '" style="width:100%;font-size:11px;padding:4px;border:1px solid #ddd;border-radius:4px;"></td>';
            echo '<td><textarea name="message_body" rows="3" style="width:100%;font-size:11px;padding:4px;border:1px solid #ddd;border-radius:4px;font-family:monospace;">' . esc_textarea($msg->message_body) . '</textarea></td>';
            echo '<td><small>' . esc_html($msg->booking_ref) . '<br>' . esc_html($msg->tour_name) . '</small></td>';
            echo '<td>' . esc_html(ucfirst($msg->block_type ?: 'Grid')) . '</td>';
            echo '<td><small>' . esc_html($msg->sent_at) . '</small>';
            if (!empty($msg->error_message)) {
                echo '<br><small style="color:#dc3545;" title="' . esc_attr($msg->error_message) . '">⚠️ Error logged</small>';
            }
            echo '</td>';
            echo '<td><span style="color:' . esc_attr($status_color) . ';font-weight:600;font-size:11px;">' . esc_html(ucfirst($msg->send_status)) . '</span>';
            echo '<select name="status" style="font-size:10px;padding:2px 4px;border-radius:4px;border:1px solid #ddd;display:block;margin-top:4px;"><option value="sent" ' . ($msg->send_status === 'sent' ? 'selected' : '') . '>✅ Sent</option><option value="pending" ' . ($msg->send_status === 'pending' ? 'selected' : '') . '>⏳ Pending</option><option value="failed" ' . ($msg->send_status === 'failed' ? 'selected' : '') . '>❌ Failed</option></select></td>';
            echo '<td><button name="edit_auto_message" class="button button-primary button-small" style="margin-bottom:2px;">💾 Save</button> <button name="resend_auto_message" class="button button-small" style="margin-bottom:2px;">📨 Resend</button> <button name="delete_auto_message" class="button button-small" onclick="return confirm(\'Delete this auto message?\')">🗑️</button></td>';
            echo '</form>';
            echo '</tr>';
        }
        echo '</tbody></table>';
    } else {
        echo '<p style="text-align:center;padding:30px;background:#f8f9fa;border-radius:12px;">No auto messages found. Create your first auto message above.</p>';
    }

    echo '</div>';
}

/* ============================================================
   66. ADMIN SETTINGS
   ============================================================ */

function ktv_admin_settings() {
    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['save_settings'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $settings = array(
                'currency'               => sanitize_text_field(wp_unslash(isset($_POST['currency']) ? $_POST['currency'] : 'USD')),
                'currency_mode'          => sanitize_text_field(wp_unslash(isset($_POST['currency_mode']) ? $_POST['currency_mode'] : 'auto')),
                'admin_email'            => sanitize_email(wp_unslash(isset($_POST['admin_email']) ? $_POST['admin_email'] : get_option('admin_email'))),
                'booking_prefix'         => sanitize_text_field(wp_unslash(isset($_POST['prefix']) ? $_POST['prefix'] : 'KTV')),
                'upi_id'                 => sanitize_text_field(wp_unslash(isset($_POST['upi_id']) ? $_POST['upi_id'] : '')),
                'gpay_name'              => sanitize_text_field(wp_unslash(isset($_POST['gpay_name']) ? $_POST['gpay_name'] : '')),
                'company_address'        => sanitize_textarea_field(wp_unslash(isset($_POST['company_address']) ? $_POST['company_address'] : '')),
                'company_phone'          => sanitize_text_field(wp_unslash(isset($_POST['company_phone']) ? $_POST['company_phone'] : '')),
                'company_email'          => sanitize_email(wp_unslash(isset($_POST['company_email']) ? $_POST['company_email'] : '')),
                'gst_percent'            => floatval(isset($_POST['gst_percent']) ? $_POST['gst_percent'] : 5),
                'gst_label'              => sanitize_text_field(wp_unslash(isset($_POST['gst_label']) ? $_POST['gst_label'] : 'GST')),
                'extra_adult_percent'    => floatval(isset($_POST['extra_adult_percent']) ? $_POST['extra_adult_percent'] : 50),
                'extra_child_percent'    => floatval(isset($_POST['extra_child_percent']) ? $_POST['extra_child_percent'] : 40),
                'id_document_mandatory'  => isset($_POST['id_document_mandatory']) ? '1' : '0',
                'upi_gpay_enabled'       => isset($_POST['upi_gpay_enabled']) ? '1' : '0',
                'credit_card_enabled'    => isset($_POST['credit_card_enabled']) ? '1' : '0',
                'dark_mode_enable'       => isset($_POST['dark_mode_enable']) ? '1' : '0',
                'booking_modal_enable'   => isset($_POST['booking_modal_enable']) ? '1' : '0',
                'booking_modal_title'    => sanitize_text_field(wp_unslash(isset($_POST['booking_modal_title']) ? $_POST['booking_modal_title'] : 'Book Your Trip')),
                'booking_modal_subtitle' => sanitize_text_field(wp_unslash(isset($_POST['booking_modal_subtitle']) ? $_POST['booking_modal_subtitle'] : 'Fill the form to reserve your spot')),
                'booking_modal_width'    => sanitize_text_field(wp_unslash(isset($_POST['booking_modal_width']) ? $_POST['booking_modal_width'] : 'large')),
                'booking_modal_animation' => sanitize_text_field(wp_unslash(isset($_POST['booking_modal_animation']) ? $_POST['booking_modal_animation'] : 'slide-down')),
                'booking_modal_close_text' => sanitize_text_field(wp_unslash(isset($_POST['booking_modal_close_text']) ? $_POST['booking_modal_close_text'] : 'Close')),
                'review_modal_title'     => sanitize_text_field(wp_unslash(isset($_POST['review_modal_title']) ? $_POST['review_modal_title'] : 'Write a Review')),
                'review_modal_icon'      => sanitize_text_field(wp_unslash(isset($_POST['review_modal_icon']) ? $_POST['review_modal_icon'] : 'fa-star')),
                'review_modal_logo'      => esc_url_raw(wp_unslash(isset($_POST['review_modal_logo']) ? $_POST['review_modal_logo'] : '')),
                'review_modal_bg_color'  => sanitize_text_field(wp_unslash(isset($_POST['review_modal_bg_color']) ? $_POST['review_modal_bg_color'] : '')),
                'review_modal_bg_image'  => esc_url_raw(wp_unslash(isset($_POST['review_modal_bg_image']) ? $_POST['review_modal_bg_image'] : '')),
                'review_modal_title_bg_color' => sanitize_text_field(wp_unslash(isset($_POST['review_modal_title_bg_color']) ? $_POST['review_modal_title_bg_color'] : '')),
                'review_modal_title_bg_image' => esc_url_raw(wp_unslash(isset($_POST['review_modal_title_bg_image']) ? $_POST['review_modal_title_bg_image'] : '')),
                'review_modal_title_text_color' => sanitize_text_field(wp_unslash(isset($_POST['review_modal_title_text_color']) ? $_POST['review_modal_title_text_color'] : '#ffffff')),
                'review_modal_title_icon_color' => sanitize_text_field(wp_unslash(isset($_POST['review_modal_title_icon_color']) ? $_POST['review_modal_title_icon_color'] : '#FFD700'))
            );

            foreach ($settings as $key => $value) {
                ktv_update_setting($key, $value);
            }
            ktv_flush_setting_cache();

            echo '<div class="notice notice-success"><p>✅ Settings saved successfully!</p></div>';
        }
    }

    if (isset($_POST['purge_hardcoded_settings'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $deleted = ktv_purge_hardcoded_tours();
            echo '<div class="notice notice-success"><p>✅ Purged ' . esc_html($deleted) . ' hardcoded/ghost tours!</p></div>';
        }
    }

    if (isset($_POST['sync_settings'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            $result = ktv_sync_all_block_tours_to_db();
            echo '<div class="notice notice-success"><p>✅ Sync complete. Added: ' . intval($result['added']) . ', Updated: ' . intval($result['updated']) . '</p></div>';
        }
