    $current_currency_mode = ktv_get_setting('currency_mode', 'auto');

    echo '<div class="wrap"><h1>⚙️ KTV Travel Settings</h1>';

    $diag = ktv_diagnose_email();
    echo '<div style="background:' . (($diag['admin_valid'] && !$diag['is_local_domain']) ? '#e8f5e9' : '#fff3cd') . ';padding:20px;border-radius:12px;margin:20px 0;border-left:4px solid ' . (($diag['admin_valid'] && !$diag['is_local_domain']) ? '#28a745' : '#ffc107') . ';">';
    echo '<h3 style="margin-top:0;">📧 Email Diagnostic</h3>';
    echo '<table class="widefat" style="max-width:900px;background:#fff;">';
    echo '<tr><td style="width:200px;"><strong>Admin Email</strong></td><td>' . ($diag['admin_valid'] ? '✅ ' . esc_html($diag['admin_email']) : '❌ ' . esc_html($diag['admin_email'] ?: 'NOT SET')) . '</td></tr>';
    echo '<tr><td><strong>From Email</strong></td><td><code>' . esc_html($diag['from_email']) . '</code></td></tr>';
    echo '<tr><td><strong>Reply-To</strong></td><td><code>' . esc_html($diag['reply_to']) . '</code></td></tr>';
    echo '<tr><td><strong>Site URL</strong></td><td>' . esc_html($diag['site_url']) . '</td></tr>';
    echo '<tr><td><strong>Site Domain</strong></td><td>' . esc_html($diag['site_domain']) . ' ' . ($diag['is_local_domain'] ? '<span style="color:#dc3545;">⚠️ Local/test domain — mail may fail</span>' : '<span style="color:#28a745;">✅ Public domain</span>') . '</td></tr>';
    echo '<tr><td><strong>SMTP Plugin</strong></td><td>' . esc_html($diag['smtp_plugin']) . '</td></tr>';
    echo '</table>';
    if (!$diag['admin_valid']) {
        echo '<p style="color:#dc3545;font-weight:600;margin-top:10px;">⚠️ Admin email is invalid. Booking notifications will not be delivered. Enter a valid admin email below and save.</p>';
    }
    if ($diag['is_local_domain']) {
        echo '<p style="color:#856404;font-weight:600;margin-top:10px;">⚠️ Your site URL is a local/test domain. Install an SMTP plugin (WP Mail SMTP / FluentSMTP) so booking and voucher emails deliver reliably.</p>';
    }
    if ($diag['smtp_plugin'] === 'unknown') {
        echo '<p style="color:#856404;font-weight:600;margin-top:10px;">ℹ️ No SMTP plugin detected. WordPress default <code>mail()</code> often fails. Install an SMTP plugin.</p>';
    }
    echo '</div>';

    echo '<div style="background:#f0f4f8;padding:20px;border-radius:12px;margin:20px 0;">';
    echo '<h3>🧹 Maintenance</h3>';
    echo '<form method="post" style="display:inline-block;margin-right:10px;" onsubmit="return confirm(\'Purge all hardcoded/ghost tours permanently?\')">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
    echo '<button name="purge_hardcoded_settings" class="button button-primary">🗑️ Purge Hardcoded Tours</button>';
