    echo '<tr><th><label>GPay Display Name</label></th><td><input name="gpay_name" value="' . esc_attr(ktv_get_setting('gpay_name', 'Imran Zaindari')) . '" class="regular-text"></td></tr>';
    echo '<tr><th><label>Enable GPay Payment</label></th><td><label><input type="checkbox" name="upi_gpay_enabled" value="1" ' . checked(ktv_get_upi_enabled('gpay'), true, false) . '> Allow GPay as payment method (all other UPI apps are disabled)</label></td></tr>';
    echo '<tr><th><label>Enable Credit Card Payments</label></th><td><label><input type="checkbox" name="credit_card_enabled" value="1" ' . checked($credit_card_enabled, true, false) . '> Show Credit Card option in booking form</label></td></tr>';
    echo '<tr><th><label>Company Address</label></th><td><textarea name="company_address" rows="3" class="large-text">' . esc_textarea(ktv_get_setting('company_address', 'Boulevard Rd, Karapura, Rainawari, Srinagar, Jammu and Kashmir 190003')) . '</textarea></td></tr>';
    echo '<tr><th><label>Company Phone</label></th><td><input name="company_phone" value="' . esc_attr(ktv_get_setting('company_phone', '+917006838859')) . '" class="regular-text"></td></tr>';
    echo '<tr><th><label>Company Email</label></th><td><input name="company_email" value="' . esc_attr(ktv_get_setting('company_email', 'info@kashmiritours.com')) . '" class="regular-text"></td></tr>';
    echo '<tr><th><label>GST Percentage</label></th><td><input name="gst_percent" type="number" step="0.01" value="' . esc_attr($current_gst_percent) . '" class="small-text"> %</td></tr>';
    echo '<tr><th><label>GST Label</label></th><td><input name="gst_label" value="' . esc_attr($current_gst_label) . '" class="regular-text"></td></tr>';
    echo '<tr><th><label>Extra Adult Percentage</label></th><td><input name="extra_adult_percent" type="number" step="0.01" value="' . esc_attr(ktv_get_extra_adult_percent()) . '" class="small-text"> % <p class="description">Applied per extra adult beyond the first adult. Set to 0 for free. Default: 50%.</p></td></tr>';
    echo '<tr><th><label>Extra Child Percentage</label></th><td><input name="extra_child_percent" type="number" step="0.01" value="' . esc_attr(ktv_get_extra_child_percent()) . '" class="small-text"> % <p class="description">Applied per child. Set to 0 for free. Default: 40%.</p></td></tr>';
    echo '<tr><th><label>ID Document Mandatory</label></th><td><label><input type="checkbox" name="id_document_mandatory" value="1" ' . checked($id_document_mandatory, true, false) . '> Make ID Document MANDATORY for all bookings</label></td></tr>';
    echo '</table>';

    echo '<h3>🌙 Dark Mode</h3>';
    echo '<table class="form-table">';
    echo '<tr><th><label>Enable Dark Mode Globally</label></th><td><label><input type="checkbox" name="dark_mode_enable" value="1" ' . checked($dark_mode_enabled, true, false) . '> Apply dark theme to all KTV blocks</label>';
    echo '<p class="description">Can be overridden per-tour in WP Admin → KTV Tours (Dark Mode checkbox).</p></td></tr>';
    echo '</table>';

    echo '<h3>Booking Modal Settings</h3>';
    echo '<table class="form-table">';
    echo '<tr><th><label>Enable Booking Modal by Default</label></th><td><label><input type="checkbox" name="booking_modal_enable" value="1" ' . checked(ktv_get_setting('booking_modal_enable', '0'), '1', false) . '> Open booking form as popup modal</label></td></tr>';
    echo '<tr><th><label>Modal Title</label></th><td><input name="booking_modal_title" value="' . esc_attr(ktv_get_setting('booking_modal_title', 'Book Your Trip')) . '" class="regular-text"></td></tr>';
    echo '<tr><th><label>Modal Subtitle</label></th><td><input name="booking_modal_subtitle" value="' . esc_attr(ktv_get_setting('booking_modal_subtitle', 'Fill the form to reserve your spot')) . '" class="regular-text"></td></tr>';
    echo '<tr><th><label>Modal Width</label></th><td><select name="booking_modal_width"><option value="small" ' . selected(ktv_get_setting('booking_modal_width', 'large'), 'small', false) . '>Narrow</option><option value="medium" ' . selected(ktv_get_setting('booking_modal_width', 'large'), 'medium', false) . '>Normal</option><option value="large" ' . selected(ktv_get_setting('booking_modal_width', 'large'), 'large', false) . '>Wide</option></select></td></tr>';
    echo '<tr><th><label>Modal Animation</label></th><td><select name="booking_modal_animation">';
    $animations = array('slide-down' => 'Slide Down', 'fade' => 'Fade', 'zoom' => 'Zoom');
    foreach ($animations as $key => $label) {
        echo '<option value="' . esc_attr($key) . '" ' . selected(ktv_get_setting('booking_modal_animation', 'slide-down'), $key, false) . '>' . esc_html($label) . '</option>';
    }
    echo '</select></td></tr>';
    echo '<tr><th><label>Close Button Text</label></th><td><input name="booking_modal_close_text" value="' . esc_attr(ktv_get_setting('booking_modal_close_text', 'Close')) . '" class="regular-text"></td></tr>';
    echo '</table>';

    echo '<h3>Review Modal Settings</h3>';
    echo '<table class="form-table">';
    echo '<tr><th><label>Review Modal Title</label></th><td><input name="review_modal_title" value="' . esc_attr(ktv_get_setting('review_modal_title', 'Write a Review')) . '" class="regular-text"></td></tr>';
    echo '<tr><th><label>Review Modal Icon (FontAwesome)</label></th><td><input name="review_modal_icon" value="' . esc_attr(ktv_get_setting('review_modal_icon', 'fa-star')) . '" class="regular-text" placeholder="fa-star"></td></tr>';
    echo '<tr><th><label>Review Modal Logo URL</label></th><td><input name="review_modal_logo" value="' . esc_attr(ktv_get_setting('review_modal_logo', '')) . '" class="large-text" placeholder="https://example.com/logo.png"></td></tr>';
    echo '<tr><th><label>Review Modal Background Color</label></th><td><input type="color" name="review_modal_bg_color" value="' . esc_attr(ktv_get_setting('review_modal_bg_color', '#ffffff')) . '"></td></tr>';
    echo '<tr><th><label>Review Modal Background Image URL</label></th><td><input name="review_modal_bg_image" value="' . esc_attr(ktv_get_setting('review_modal_bg_image', '')) . '" class="large-text" placeholder="https://example.com/bg.jpg"></td></tr>';
    echo '<tr><th><label>Review Modal Title Header BG Color</label></th><td><input type="color" name="review_modal_title_bg_color" value="' . esc_attr(ktv_get_setting('review_modal_title_bg_color', '#075e54')) . '"><p class="description">Background of the top title strip in the review popup.</p></td></tr>';
    echo '<tr><th><label>Review Modal Title Header BG Image</label></th><td><input name="review_modal_title_bg_image" value="' . esc_attr(ktv_get_setting('review_modal_title_bg_image', '')) . '" class="large-text" placeholder="https://example.com/header-bg.jpg"><p class="description">Overrides the header bg color when set.</p></td></tr>';
