    echo '<tr><th><label>Review Modal Title Icon Color</label></th><td><input type="color" name="review_modal_title_icon_color" value="' . esc_attr(ktv_get_setting('review_modal_title_icon_color', '#FFD700')) . '"></td></tr>';
    echo '</table>';

    echo '<p><button name="save_settings" class="button button-primary" style="margin-top:15px;">💾 Save All Settings</button></p>';
    echo '</form></div>';
    ?>
    <script>
    (function(){
        var d={INR:1,USD:0.0120,EUR:0.0111,GBP:0.0095,AUD:0.0183,CAD:0.0164,JPY:1.80,AED:0.0441,SAR:0.0450,SGD:0.0161,MYR:0.0567,KWD:0.0037,QAR:0.0437,OMR:0.0046,BHD:0.0045,TRY:0.39,RUB:1.10,BRL:0.0599,ZAR:0.2236,NZD:0.0199,CHF:0.0106,SEK:0.1253,THB:0.4305,IDR:188.80,PHP:0.6759,KRW:16.09,PKR:3.3491,BDT:1.4130,NPR:1.60,LKR:3.6685,CNY:0.0871};
        var b=document.getElementById('ktv-reset-rates');
        if(b)b.addEventListener('click',function(){
            if(!confirm('Reset all rates to defaults? Save to apply.'))return;
            document.querySelectorAll('.ktv-rate-row').forEach(function(r){
                var c=r.getAttribute('data-code');if(!c||c==='INR')return;
                var i=r.querySelector('.ktv-rate-input');if(!i)return;
                var m=d[c]||1;i.value=m>0?Math.round(10000/m)/10000:1;
                i.dispatchEvent(new Event('input',{bubbles:true}));
            });
        });
        function up(r){
            var i=r.querySelector('.ktv-rate-input'),p=r.querySelector('.ktv-rate-preview');
            if(!i||!p)return;
            var s=parseFloat(r.getAttribute('data-sample'))||5000;
            var v=parseFloat(i.value)||0;
            var si=r.querySelector('input[name^="currency_symbols_map"]');
            var sym=si&&si.value?si.value:'';
            p.textContent=v<=0?'₹'+s.toFixed(0)+' → —':'₹'+s.toFixed(0)+' → '+sym+(Math.round(s/v*100)/100).toFixed(2);
        }
        document.querySelectorAll('.ktv-rate-row').forEach(function(r){
            var i=r.querySelector('.ktv-rate-input');
            if(i)i.addEventListener('input',function(){up(r);});
            var si=r.querySelector('input[name^="currency_symbols_map"]');
            if(si)si.addEventListener('input',function(){up(r);});
            up(r);
        });
    })();
    </script>
    <?php
}

/* ============================================================
   67. ADMIN HONEYPOT AND SPAM SETTINGS
   ============================================================ */

function ktv_admin_spam_settings() {
    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (isset($_POST['clear_blocked_log'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            global $wpdb;
            $wpdb->query("TRUNCATE TABLE {$wpdb->prefix}ktv_blocked_log");
            echo '<div class="notice notice-success"><p>✅ Blocked log cleared.</p></div>';
        }
    }

    if (isset($_POST['save_spam_settings'])) {
        if (!wp_verify_nonce(isset($_POST['ktv_admin_nonce']) ? $_POST['ktv_admin_nonce'] : '', 'ktv_admin_action')) {
            echo '<div class="notice notice-error"><p>Security check failed.</p></div>';
        } else {
            ktv_update_setting('honeypot_enabled', isset($_POST['honeypot_enabled']) ? '1' : '0');
            ktv_update_setting('spam_filter_enabled', isset($_POST['spam_filter_enabled']) ? '1' : '0');
            ktv_update_setting('rate_limit_enabled', isset($_POST['rate_limit_enabled']) ? '1' : '0');
            ktv_update_setting('spam_keywords', sanitize_textarea_field(wp_unslash(isset($_POST['spam_keywords']) ? $_POST['spam_keywords'] : '')));
            ktv_update_setting('blocked_ips', sanitize_textarea_field(wp_unslash(isset($_POST['blocked_ips']) ? $_POST['blocked_ips'] : '')));
            ktv_flush_setting_cache();
            echo '<div class="notice notice-success"><p>✅ Honeypot &amp; Spam settings saved!</p></div>';
        }
    }

    $honeypot_enabled = ktv_is_honeypot_enabled();
    $spam_filter_enabled = ktv_is_spam_filter_enabled();
    $rate_limit_enabled = ktv_is_rate_limit_enabled();
    $spam_keywords_raw = ktv_get_setting('spam_keywords', '');
    if (empty($spam_keywords_raw)) {
        $spam_keywords_raw = "viagra\ncasino\ncrypto\nloan\nporn\nxxx\nbitcoin\nforex\nweight loss\nseo services\nbacklink\nguest post\nfree money\nmake money online\nbinary options";
    }
    $blocked_ips_raw = ktv_get_setting('blocked_ips', '');

    global $wpdb;
    $blocked_log = $wpdb->get_results("SELECT * FROM {$wpdb->prefix}ktv_blocked_log ORDER BY id DESC LIMIT 100");
    $blocked_total = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}ktv_blocked_log");

    echo '<div class="wrap"><h1>🛡️ Honeypot &amp; Spam Protection</h1>';
    echo '<p class="description">Protects the Booking Form and Contact Form against spam bots, disposable emails, malicious links, and flooding.</p>';

    echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:15px;margin:20px 0;">';
    echo '<div style="background:' . ($honeypot_enabled ? '#e8f5e9' : '#fff3cd') . ';padding:15px;border-radius:10px;text-align:center;"><h4 style="margin:0;">Honeypot</h4><strong style="font-size:20px;">' . ($honeypot_enabled ? 'ON' : 'OFF') . '</strong></div>';
    echo '<div style="background:' . ($spam_filter_enabled ? '#e8f5e9' : '#fff3cd') . ';padding:15px;border-radius:10px;text-align:center;"><h4 style="margin:0;">Spam Filter</h4><strong style="font-size:20px;">' . ($spam_filter_enabled ? 'ON' : 'OFF') . '</strong></div>';
    echo '<div style="background:' . ($rate_limit_enabled ? '#e8f5e9' : '#fff3cd') . ';padding:15px;border-radius:10px;text-align:center;"><h4 style="margin:0;">Rate Limit</h4><strong style="font-size:20px;">' . ($rate_limit_enabled ? 'ON' : 'OFF') . '</strong></div>';
    echo '<div style="background:#f0f4f8;padding:15px;border-radius:10px;text-align:center;"><h4 style="margin:0;">Total Blocked</h4><strong style="font-size:20px;">' . esc_html($blocked_total) . '</strong></div>';
    echo '</div>';

    echo '<form method="post">';
    wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');

    echo '<h3>⚙️ Toggles</h3>';
    echo '<table class="form-table">';
    echo '<tr><th><label>Enable Honeypot</label></th><td><label><input type="checkbox" name="honeypot_enabled" value="1" ' . checked($honeypot_enabled, true, false) . '> Add hidden honeypot field to Booking &amp; Contact forms</label><p class="description">Bots fill every field they see; humans never see this field. If filled → submission silently rejected.</p></td></tr>';
    echo '<tr><th><label>Enable Spam Keyword Filter</label></th><td><label><input type="checkbox" name="spam_filter_enabled" value="1" ' . checked($spam_filter_enabled, true, false) . '> Reject submissions containing spam keywords or disposable emails</label></td></tr>';
    echo '<tr><th><label>Enable Rate Limiting</label></th><td><label><input type="checkbox" name="rate_limit_enabled" value="1" ' . checked($rate_limit_enabled, true, false) . '> Limit to 5 submissions per IP per 15 minutes</label></td></tr>';
    echo '</table>';

    echo '<h3>🚫 Spam Keywords (one per line)</h3>';
    echo '<textarea name="spam_keywords" rows="12" class="large-text" style="font-family:monospace;font-size:13px;">' . esc_textarea($spam_keywords_raw) . '</textarea>';
    echo '<p class="description">Case-insensitive. Applied to Name and Message/Special Requests fields.</p>';

    echo '<h3>🚷 Blocked IPs (one per line)</h3>';
    echo '<textarea name="blocked_ips" rows="8" class="large-text" style="font-family:monospace;font-size:13px;">' . esc_textarea($blocked_ips_raw) . '</textarea>';
    echo '<p class="description">Each line must be a valid IPv4 or IPv6 address. These IPs are completely blocked from submissions.</p>';

    echo '<p><button name="save_spam_settings" class="button button-primary" style="margin-top:15px;">💾 Save Honeypot &amp; Spam Settings</button></p>';
    echo '</form>';

    echo '<h3 style="margin-top:30px;">📋 Blocked Log (latest 100)</h3>';
    if (!empty($blocked_log)) {
        echo '<table class="wp-list-table widefat striped"><thead><tr><th>ID</th><th>Form</th><th>Reason</th><th>IP</th><th>Email</th><th>Name</th><th>Detail</th><th>Date</th></tr></thead><tbody>';
        foreach ($blocked_log as $log) {
            echo '<tr>';
            echo '<td>#' . esc_html($log->id) . '</td>';
            echo '<td>' . esc_html($log->form_type) . '</td>';
            echo '<td><strong>' . esc_html($log->block_reason) . '</strong></td>';
            echo '<td>' . esc_html($log->user_ip) . '</td>';
            echo '<td>' . esc_html($log->user_email) . '</td>';
            echo '<td>' . esc_html($log->user_name) . '</td>';
            echo '<td><small>' . esc_html(substr($log->block_detail, 0, 60)) . '</small></td>';
            echo '<td><small>' . esc_html($log->created_at) . '</small></td>';
            echo '</tr>';
        }
        echo '</tbody></table>';
        echo '<form method="post" style="margin-top:15px;" onsubmit="return confirm(\'Clear the entire blocked log?\')">';
        wp_nonce_field('ktv_admin_action', 'ktv_admin_nonce');
        echo '<button name="clear_blocked_log" class="button">🗑️ Clear Log</button>';
        echo '</form>';
    } else {
        echo '<p style="text-align:center;padding:30px;background:#f8f9fa;border-radius:12px;">No blocked submissions logged yet. Good sign — or no bots have visited.</p>';
    }

    echo '</div>';
}

/* ============================================================
   68. VOUCHER DIRECT ACCESS ROUTE
   ============================================================ */

add_action('init', function() {
    add_rewrite_rule('^voucher/([^/]+)/?$', 'index.php?ktv_voucher=$matches[1]', 'top');
}, 1);

add_filter('query_vars', function($vars) {
    $vars[] = 'ktv_voucher';
    return $vars;
});

add_action('template_redirect', function() {
    $voucher_code = get_query_var('ktv_voucher');
    if (empty($voucher_code)) {
        return;
    }

    nocache_headers();
    header('X-Robots-Tag: noindex, nofollow');
    if (is_ssl()) {
        header('Strict-Transport-Security: max-age=31536000');
    }

    global $wpdb;
    $booking = $wpdb->get_row($wpdb->prepare(
        "SELECT * FROM {$wpdb->prefix}ktv_bookings WHERE voucher_code = %s",
        $voucher_code
    ));

    if (!$booking) {
        wp_die('Invalid voucher code. Please check your email and try again.', 'Voucher Not Found');
        return;
    }

    ktv_get_voucher_token($voucher_code);

    $token_from_url = isset($_GET['token']) ? sanitize_text_field(wp_unslash($_GET['token'])) : '';

    if (isset($_GET['admin_action'])) {
        $admin_action = sanitize_text_field(wp_unslash($_GET['admin_action']));
        if (!in_array($admin_action, array('accept', 'decline', 'modify'), true)) {
            wp_die('Invalid admin action.');
        }
        if (empty($token_from_url) || !ktv_validate_voucher_token($voucher_code, $token_from_url)) {
            wp_die('Invalid or expired token. Please request a new email.');
        }

        if ($admin_action === 'accept') {
            $result = ktv_update_booking_status($booking->id, 'confirmed');
            $msg = $result['success']
                ? 'Booking accepted. Voucher sent to guest: ' . esc_html($booking->email)
                : 'Error accepting booking.';
            wp_die($msg, 'Admin Action Complete', array('response' => 200, 'back_link' => true));
        }

        if ($admin_action === 'decline') {
            $result = ktv_update_booking_status($booking->id, 'cancelled', 'Declined by admin');
            $msg = $result['success']
                ? 'Booking declined. Voucher sent to guest: ' . esc_html($booking->email)
                : 'Error declining booking.';
            wp_die($msg, 'Admin Action Complete', array('response' => 200, 'back_link' => true));
        }

        if ($admin_action === 'modify') {
            wp_safe_redirect(admin_url('admin.php?page=ktv-bookings&action=edit&id=' . intval($booking->id)));
            exit;
        }
    }

    if (isset($_POST['guest_action_submit'])) {
        $submit_action = sanitize_text_field(wp_unslash($_POST['guest_action_submit']));
        $post_voucher  = sanitize_text_field(wp_unslash($_POST['voucher_code']));
        $post_token    = sanitize_text_field(wp_unslash($_POST['token']));

        if ($post_voucher !== $voucher_code || !ktv_validate_voucher_token($voucher_code, $post_token)) {
            wp_die('Invalid request.');
        }

        if ($submit_action === 'modify') {
            $modify_request = isset($_POST['modify_request']) ? sanitize_textarea_field(wp_unslash($_POST['modify_request'])) : '';
            ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
                'guest_action_status' => 'modify_requested',
                'guest_action_at'     => current_time('mysql')
            ), array('voucher_code' => $voucher_code));

            ktv_update_booking_status($booking->id, 'modify_requested', $modify_request);

            $wpdb->insert($wpdb->prefix . 'ktv_auto_messages', array(
                'message_type'    => 'guest_voucher_action',
                'recipient_email' => $booking->email,
                'recipient_name'  => $booking->name,
                'subject'         => 'Guest requested modification: ' . $booking->booking_ref,
                'message_body'    => 'Guest requested modification. Details: ' . $modify_request,
                'booking_ref'     => $booking->booking_ref,
                'tour_name'       => $booking->tour_name,
                'tour_id'         => intval($booking->tour_id),
                'block_type'      => $booking->block_type,
                'send_status'     => 'sent',
                'sent_at'         => current_time('mysql')
            ));

            $admin_email = ktv_get_setting('admin_email', '');
            if (empty($admin_email)) {
                $admin_email = get_option('admin_email');
            }
            ktv_send_plain_email(
                $admin_email,
                'Modification Requested - ' . $booking->booking_ref,
                "Guest " . $booking->name . " requested a modification.\n\nBooking: " . $booking->booking_ref . "\nVoucher: " . $voucher_code . "\nRequest: " . $modify_request . "\n\nManage: " . admin_url('admin.php?page=ktv-bookings'),
                $booking->email
            );

            wp_safe_redirect(add_query_arg(
                array('guest_action_done' => 'modify', 'token' => $post_token),
                home_url('/voucher/' . $voucher_code)
            ));
            exit;
        }

        if ($submit_action === 'cancel') {
            $cancel_reason = isset($_POST['cancel_reason']) ? sanitize_textarea_field(wp_unslash($_POST['cancel_reason'])) : '';
            ktv_update_booking_status($booking->id, 'cancel_requested', $cancel_reason);

            ktv_db_update_safe($wpdb->prefix . 'ktv_vouchers', array(
                'guest_action_status' => 'cancel_requested',
                'guest_action_at'     => current_time('mysql')
            ), array('voucher_code' => $voucher_code));

            $admin_email = ktv_get_setting('admin_email', '');
            if (empty($admin_email)) {
                $admin_email = get_option('admin_email');
            }
            ktv_send_plain_email(
                $admin_email,
                'Cancellation Request - ' . $booking->booking_ref,
                "Guest " . $booking->name . " requested cancellation.\n\nBooking: " . $booking->booking_ref . "\nVoucher: " . $voucher_code . "\nReason: " . ($cancel_reason ?: 'N/A') . "\n\nApprove or decline in WP Admin:\n" . admin_url('admin.php?page=ktv-bookings'),
                $booking->email
            );

            wp_safe_redirect(add_query_arg(
                array('guest_action_done' => 'cancel', 'token' => $post_token),
                home_url('/voucher/' . $voucher_code)
            ));
            exit;
        }
    }

    if (isset($_GET['guest_action'])) {
        $guest_action = sanitize_text_field(wp_unslash($_GET['guest_action']));
        if (!in_array($guest_action, array('modify', 'cancel'), true)) {
            wp_die('Invalid guest action.');
        }

        $fontawesome_url = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css';

        if ($guest_action === 'modify') {
            ob_start();
            echo '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Modify Booking</title>';
            echo '<link rel="stylesheet" href="' . esc_url($fontawesome_url) . '">';
            echo '<style>body{font-family:Arial,sans-serif;padding:20px;background:#f5f5f5;margin:0;}';
            echo '.ktv-mg-box{max-width:600px;margin:40px auto;background:#fff;padding:30px;border-radius:12px;box-shadow:0 10px 40px rgba(0,0,0,0.08);}';
            echo 'h2{color:#075e54;margin:0 0 15px;}';
            echo 'textarea{width:100%;padding:12px;border:1px solid #ddd;border-radius:8px;font-size:14px;min-height:120px;}';
            echo 'button{background:#17a2b8;color:#fff;padding:12px 26px;border:none;border-radius:8px;font-size:15px;font-weight:600;cursor:pointer;margin-top:15px;}';
            echo 'button:hover{background:#138496;} .ktv-mg-meta{font-size:12px;color:#666;margin-bottom:15px;}</style></head><body>';
            echo '<div class="ktv-mg-box">';
            echo '<h2><i class="fas fa-edit"></i> Modify Booking</h2>';
            echo '<p class="ktv-mg-meta">Booking Ref: <strong>' . esc_html($booking->booking_ref) . '</strong> | Voucher: <strong>' . esc_html($voucher_code) . '</strong></p>';
            echo '<form method="post" action="">';
            echo '<input type="hidden" name="guest_action_submit" value="modify">';
            echo '<input type="hidden" name="voucher_code" value="' . esc_attr($voucher_code) . '">';
            echo '<input type="hidden" name="token" value="' . esc_attr($token_from_url) . '">';
            echo '<label style="display:block;margin-bottom:8px;font-weight:600;">What would you like to modify?</label>';
            echo '<textarea name="modify_request" required placeholder="E.g. change dates to..., add 2 more adults, change tour package..."></textarea>';
            echo '<button type="submit"><i class="fas fa-paper-plane"></i> Submit Modification Request</button>';
            echo '</form>';
            echo '</div></body></html>';
            ob_end_flush();
            exit;
        }

        if ($guest_action === 'cancel') {
            ob_start();
            echo '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Cancel Reservation</title>';
            echo '<link rel="stylesheet" href="' . esc_url($fontawesome_url) . '">';
            echo '<style>body{font-family:Arial,sans-serif;padding:20px;background:#f5f5f5;margin:0;}';
            echo '.ktv-cn-box{max-width:600px;margin:40px auto;background:#fff;padding:30px;border-radius:12px;box-shadow:0 10px 40px rgba(0,0,0,0.08);}';
            echo 'h2{color:#dc3545;margin:0 0 15px;}';
            echo '.ktv-cn-warn{background:#fff3cd;border-left:4px solid #ffc107;padding:14px 16px;border-radius:8px;margin:15px 0;font-size:14px;color:#856404;}';
            echo 'textarea{width:100%;padding:12px;border:1px solid #ddd;border-radius:8px;font-size:14px;min-height:100px;}';
            echo 'button{background:#6c757d;color:#fff;padding:12px 26px;border:none;border-radius:8px;font-size:15px;font-weight:600;cursor:pointer;margin-top:15px;}';
            echo 'button:hover{background:#5a6268;} .ktv-cn-meta{font-size:12px;color:#666;margin-bottom:15px;}</style></head><body>';
            echo '<div class="ktv-cn-box">';
            echo '<h2><i class="fas fa-ban"></i> Cancel Reservation</h2>';
            echo '<p class="ktv-cn-meta">Booking Ref: <strong>' . esc_html($booking->booking_ref) . '</strong> | Voucher: <strong>' . esc_html($voucher_code) . '</strong></p>';
            echo '<div class="ktv-cn-warn"><strong>Please note:</strong> Your booking is NOT cancelled immediately. Our team will review your request and contact you shortly.</div>';
            echo '<form method="post" action="">';
            echo '<input type="hidden" name="guest_action_submit" value="cancel">';
            echo '<input type="hidden" name="voucher_code" value="' . esc_attr($voucher_code) . '">';
            echo '<input type="hidden" name="token" value="' . esc_attr($token_from_url) . '">';
            echo '<label style="display:block;margin-bottom:8px;font-weight:600;">Reason for cancellation (optional)</label>';
            echo '<textarea name="cancel_reason" placeholder="Tell us why you want to cancel..."></textarea>';
            echo '<button type="submit"><i class="fas fa-paper-plane"></i> Submit Cancellation Request</button>';
            echo '</form>';
            echo '</div></body></html>';
            ob_end_flush();
            exit;
        }
    }

    $download_format = isset($_GET['download']) ? sanitize_text_field(wp_unslash($_GET['download'])) : '';
    $view_format     = isset($_GET['view']) ? sanitize_text_field(wp_unslash($_GET['view'])) : '';

    if (!empty($download_format) || !empty($view_format)) {
        $format = !empty($download_format) ? $download_format : $view_format;
        $is_download = !empty($download_format);
        ktv_serve_voucher_file($booking, $voucher_code, $format, $is_download);
        exit;
    }

    $is_admin_request = current_user_can('manage_options') && isset($_GET['admin']) && sanitize_text_field(wp_unslash($_GET['admin'])) === '1';
    $for_guest = !$is_admin_request;

    $booking_array = (array) $booking;
    if (empty($booking_array['days']) && !empty($booking_array['nights'])) {
        $booking_array['days'] = intval($booking_array['nights']) + 1;
    }

    if (empty($booking->voucher_code)) {
        $booking->voucher_code = ktv_generate_voucher_code();
        ktv_db_update_safe($wpdb->prefix . 'ktv_bookings', array('voucher_code' => $booking->voucher_code), array('id' => $booking->id));
        $booking_array['voucher_code'] = $booking->voucher_code;
    }

    $voucher_html = ktv_generate_voucher_html_content($booking_array, $booking->voucher_code, $for_guest, 'render');

    $settings = ktv_get_voucher_action_settings();
    $guest_token_for_buttons = '';
    if (!empty($token_from_url) && ktv_validate_voucher_token($voucher_code, $token_from_url)) {
        $guest_token_for_buttons = $token_from_url;
    } elseif ($for_guest) {
        $guest_token_for_buttons = ktv_get_voucher_token($voucher_code);
    }
    $action_buttons = ktv_build_voucher_action_buttons($voucher_code, 'frontend', $guest_token_for_buttons);

    $fontawesome_url = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css';

    $button_position_style = 'margin-top:20px;margin-bottom:20px;';

    $body_dark_class = ktv_is_dark_mode_enabled() ? 'ktv-dark-mode ktv-dark-mode-global ktv-dark-mode-active' : '';

    $auto_print = isset($_GET['print']) && sanitize_text_field(wp_unslash($_GET['print'])) === '1';

    $guest_action_done = isset($_GET['guest_action_done']) ? sanitize_text_field(wp_unslash($_GET['guest_action_done'])) : '';

    $print_context_class = $auto_print ? ' ktv-context-print' : '';

    $canonical_url = home_url('/voucher/' . $voucher_code);

    ob_start();
    echo '<!DOCTYPE html>
    <html>
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>Voucher - ' . esc_html($booking->voucher_code) . '</title>
        <link rel="canonical" href="' . esc_url($canonical_url) . '">
        <link rel="stylesheet" href="' . esc_url($fontawesome_url) . '">
        <style>
            body { margin: 0; padding: 20px; background: #f5f5f5; font-family: Arial, sans-serif; }
            body.ktv-dark-mode { background: #12121e; }
            .ktv-voucher-actions { ' . $button_position_style . ' }
            .ktv-guest-action-done-banner {
                max-width: 800px;
                margin: 15px auto;
                padding: 15px;
                border-radius: 12px;
                text-align: center;
                font-size: 14px;
            }
            .ktv-guest-action-done-banner.success {
                background: #d4edda;
                color: #155724;
                border-left: 4px solid #28a745;
            }
            body.ktv-context-print .ktv-voucher-actions,
            body.ktv-context-print .ktv-voucher-guest-actions { display: none !important; }
            @media print { body { background: #fff; padding: 0; } .ktv-voucher-actions, .ktv-voucher-guest-actions, .ktv-guest-action-done-banner { display: none !important; } }
        </style>
    </head>
    <body class="' . esc_attr($body_dark_class . $print_context_class) . '">';
    if ($auto_print) {
        echo '<script>window.addEventListener("load",function(){setTimeout(function(){window.print();},400);});</script>';
    }
    if ($guest_action_done === 'modify') {
        echo '<div class="ktv-guest-action-done-banner success"><strong>✅ Modification request received.</strong> Our team will contact you shortly.</div>';
    } elseif ($guest_action_done === 'cancel') {
        echo '<div class="ktv-guest-action-done-banner success"><strong>✅ Cancellation request received.</strong> Your booking is not cancelled yet — our team will review and confirm.</div>';
    }
    echo $voucher_html . '
        ' . $action_buttons;
    echo '</body></html>';
    ob_end_flush();
    exit;
});

function ktv_serve_voucher_file($booking, $voucher_code, $format, $is_download) {
    $format = strtolower($format);
    $valid_formats = array('pdf', 'docx');
    if (!in_array($format, $valid_formats, true)) {
        wp_die('Invalid format. Supported: pdf, docx.');
    }

    $booking_array = (array) $booking;
    $booking_array['voucher_code'] = $voucher_code;
    if (empty($booking_array['days']) && !empty($booking_array['nights'])) {
        $booking_array['days'] = intval($booking_array['nights']) + 1;
    }
    $upload_dir = wp_upload_dir();
    $voucher_dir = $upload_dir['basedir'] . '/ktv-vouchers/';
    if (!file_exists($voucher_dir)) {
        wp_mkdir_p($voucher_dir);
    }

    $disposition = $is_download ? 'attachment' : 'inline';

    if ($format === 'pdf') {
        $pdf_path = $voucher_dir . 'voucher-' . $booking->id . '-' . $voucher_code . '.pdf';
        if (!file_exists($pdf_path)) {
            $pdf_url = ktv_generate_voucher_pdf($booking_array, $voucher_code, $booking->id, true);
            if (!empty($pdf_url)) {
                $pdf_path = str_replace($upload_dir['baseurl'], $upload_dir['basedir'], $pdf_url);
            }
        }
        if (file_exists($pdf_path)) {
            if (!headers_sent()) {
                header('Content-Type: application/pdf');
                header('Content-Disposition: ' . $disposition . '; filename="voucher-' . $voucher_code . '.pdf"');
                header('Content-Length: ' . filesize($pdf_path));
                header('X-Content-Type-Options: nosniff');
            }
            readfile($pdf_path);
            exit;
        }

        $html = ktv_generate_voucher_html_content($booking_array, $voucher_code, true, 'download');
        if (!headers_sent()) {
            header('Content-Type: text/html; charset=UTF-8');
        }
        echo '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Voucher</title><style>body{font-family:Arial,sans-serif;padding:20px;}@media print{body{padding:0;}}</style></head><body onload="setTimeout(function(){window.print();},400);">' . $html . '</body></html>';
        exit;
    }

    if ($format === 'docx') {
        $docx_path = $voucher_dir . 'voucher-' . $booking->id . '-' . $voucher_code . '.doc';
        if (!file_exists($docx_path)) {
            $docx_html = ktv_generate_voucher_docx_html($booking_array, $voucher_code);
            @file_put_contents($docx_path, $docx_html);
        }
        if (file_exists($docx_path)) {
            $mime = $is_download ? 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' : 'application/msword';
            if (!headers_sent()) {
                header('Content-Type: ' . $mime);
                header('Content-Disposition: ' . $disposition . '; filename="voucher-' . $voucher_code . '.doc"');
                header('Content-Length: ' . filesize($docx_path));
                header('X-Content-Type-Options: nosniff');
            }
            readfile($docx_path);
            exit;
        }

        $docx_html = ktv_generate_voucher_docx_html($booking_array, $voucher_code);
        if (!headers_sent()) {
            header('Content-Type: application/msword');
            header('Content-Disposition: ' . $disposition . '; filename="voucher-' . $voucher_code . '.doc"');
            header('X-Content-Type-Options: nosniff');
        }
        echo $docx_html;
        exit;
    }

    wp_die('Unsupported format.');
}

/* ============================================================
