   ============================================================ */

add_action('admin_footer', function() {
    if (!isset($_GET['page'])) {
        return;
    }
    $page = sanitize_text_field(wp_unslash($_GET['page']));
    if (strpos($page, 'ktv') === false) {
        return;
    }
    $ajax_url = admin_url('admin-ajax.php');
    $ktv_nonce = wp_create_nonce('ktv_travel_nonce');
    ?>
    <script>
    (function(){
        var KTV_AJAX = <?php echo wp_json_encode($ajax_url); ?>;
        var KTV_NONCE = <?php echo wp_json_encode($ktv_nonce); ?>;

        var purgeBtn = document.getElementById('ktv-purge-ghost-btn');
        if (purgeBtn) {
            purgeBtn.addEventListener('click', function(){
                if (!confirm('Purge all hardcoded/ghost tours permanently?')) return;
                var formData = new FormData();
                formData.append('action', 'ktv_purge_hardcoded_tours');
                formData.append('nonce', KTV_NONCE);
                fetch(KTV_AJAX, { method: 'POST', body: formData })
                    .then(function(r){ return r.json(); })
                    .then(function(d){
                        var resultDiv = document.getElementById('ktv-purge-result');
                        if (resultDiv) {
                            resultDiv.innerHTML = d.success
                                ? '<div style="background:#d4edda;color:#155724;padding:10px;border-radius:6px;">' + (d.data.message || 'Purged!') + '</div>'
                                : '<div style="background:#f8d7da;color:#721c24;padding:10px;border-radius:6px;">Error purging tours.</div>';
                        }
                        if (d.success) setTimeout(function(){ location.reload(); }, 1500);
                    });
            });
        }

        var syncBtn = document.getElementById('ktv-sync-blocks-btn');
        if (syncBtn) {
            syncBtn.addEventListener('click', function(){
                syncBtn.disabled = true;
                var originalText = syncBtn.innerHTML;
                syncBtn.innerHTML = '🔄 Syncing...';
                var formData = new FormData();
                formData.append('action', 'ktv_sync_block_tours');
                formData.append('nonce', KTV_NONCE);
                fetch(KTV_AJAX, { method: 'POST', body: formData })
                    .then(function(r){ return r.json(); })
                    .then(function(d){
                        var resultDiv = document.getElementById('ktv-sync-blocks-result');
                        if (resultDiv) {
                            resultDiv.innerHTML = d.success
                                ? '<div style="background:#d4edda;color:#155724;padding:10px;border-radius:6px;">' + (d.data.message || 'Sync complete!') + '</div>'
                                : '<div style="background:#f8d7da;color:#721c24;padding:10px;border-radius:6px;">Error syncing tours.</div>';
                        }
                        syncBtn.disabled = false;
                        syncBtn.innerHTML = originalText;
                        if (d.success) setTimeout(function(){ location.reload(); }, 2000);
                    })
                    .catch(function(){
                        syncBtn.disabled = false;
                        syncBtn.innerHTML = originalText;
                    });
            });
        }

        function handleImportNewTours(btn, resultDivId) {
            if (!btn) return;
            btn.addEventListener('click', function(){
                btn.disabled = true;
                var originalText = btn.innerHTML;
                btn.innerHTML = '🔄 Importing...';
                var formData = new FormData();
                formData.append('action', 'ktv_import_new_tours');
                formData.append('nonce', KTV_NONCE);
                fetch(KTV_AJAX, { method: 'POST', body: formData })
                    .then(function(r){ return r.json(); })
                    .then(function(d){
                        var resultDiv = document.getElementById(resultDivId);
                        if (resultDiv) {
                            resultDiv.innerHTML = d.success
                                ? '<div style="background:#d4edda;color:#155724;padding:10px;border-radius:6px;">' + (d.data.message || 'Imported!') + '</div>'
                                : '<div style="background:#f8d7da;color:#721c24;padding:10px;border-radius:6px;">Error importing tours.</div>';
                        }
                        btn.disabled = false;
                        btn.innerHTML = originalText;
                        if (d.success) setTimeout(function(){ location.reload(); }, 1800);
                    })
                    .catch(function(){
                        btn.disabled = false;
                        btn.innerHTML = originalText;
                    });
            });
        }
        handleImportNewTours(document.getElementById('ktv-import-new-tours-btn'), 'ktv-import-new-tours-result');
        handleImportNewTours(document.getElementById('ktv-import-new-tours-btn-page'), 'ktv-import-new-tours-result-page');

        var markReadBtn = document.getElementById('ktv-mark-read-btn');
        if (markReadBtn) {
            markReadBtn.addEventListener('click', function(){
                var formData = new FormData();
                formData.append('action', 'ktv_mark_notices_read');
                formData.append('nonce', KTV_NONCE);
                fetch(KTV_AJAX, { method: 'POST', body: formData })
                    .then(function(r){ return r.json(); })
                    .then(function(){ location.reload(); });
            });
        }

        document.addEventListener('click', function(e){
            var toggleBtn = e.target.closest('[data-toggle-modify]');
            if (toggleBtn) {
                e.preventDefault();
                var bid = toggleBtn.getAttribute('data-toggle-modify');
                var form = document.getElementById('modify-form-' + bid);
                if (form) form.style.display = form.style.display === 'none' ? 'block' : 'none';
            }
            var closeBtn = e.target.closest('[data-close-modify]');
            if (closeBtn) {
                e.preventDefault();
                var bid2 = closeBtn.getAttribute('data-close-modify');
                var form2 = document.getElementById('modify-form-' + bid2);
                if (form2) form2.style.display = 'none';
            }
            var insertVarBtn = e.target.closest('[data-insert-var]');
            if (insertVarBtn) {
                e.preventDefault();
                var textarea = document.getElementById('message_body_editor');
                if (textarea) {
                    var v = insertVarBtn.getAttribute('data-insert-var');
                    var start = textarea.selectionStart;
                    var end = textarea.selectionEnd;
                    textarea.value = textarea.value.slice(0, start) + v + textarea.value.slice(end);
                    textarea.selectionStart = textarea.selectionEnd = start + v.length;
                    textarea.focus();
                }
            }
        });

        setInterval(function(){
            var badge = document.querySelector('.ktv-notice-badge');
            if (!badge) return;
            var formData = new FormData();
            formData.append('action', 'ktv_booking_notice_count');
            formData.append('nonce', KTV_NONCE);
            fetch(KTV_AJAX, { method: 'POST', body: formData })
                .then(function(r){ return r.json(); })
                .then(function(d){
                    if (d.success && d.data.count > 0) {
                        badge.textContent = d.data.count;
                        badge.style.animation = 'ktvPulseBadge 1s infinite';
                    }
                })
                .catch(function(){});
        }, 60000);
    })();
    </script>
    <style>
    @keyframes ktvPulseBadge {
        0% { transform: scale(1); }
        50% { transform: scale(1.15); }
        100% { transform: scale(1); }
    }
    .ktv-email-warning {
        background: #fff3cd;
        color: #856404;
        padding: 12px;
        border-radius: 8px;
        margin: 15px 0;
        border-left: 4px solid #ffc107;
        font-size: 13px;
    }
    </style>
    <?php
});

