function ktv_run_activation_seeders() {
    if (get_option('ktv_seeders_ran', '') === KTV_TRAVEL_DB_VERSION) {
        return;
    }

    ktv_insert_sample_flights();
    ktv_insert_locations_data();
    ktv_insert_accordion_tabs_data();
    ktv_insert_email_templates();

    if (ktv_get_setting('extra_adult_percent', '') === '') {
        ktv_update_setting('extra_adult_percent', '50');
    }
    if (ktv_get_setting('extra_child_percent', '') === '') {
        ktv_update_setting('extra_child_percent', '40');
    }
    if (ktv_get_setting('honeypot_enabled', '') === '') {
        ktv_update_setting('honeypot_enabled', '1');
    }
    if (ktv_get_setting('spam_filter_enabled', '') === '') {
        ktv_update_setting('spam_filter_enabled', '1');
    }
    if (ktv_get_setting('rate_limit_enabled', '') === '') {
        ktv_update_setting('rate_limit_enabled', '1');
    }
    if (ktv_get_setting('currency_mode', '') === '') {
        ktv_update_setting('currency_mode', 'auto');
    }

    update_option('ktv_seeders_ran', KTV_TRAVEL_DB_VERSION);
}
add_action('after_switch_theme', 'ktv_run_activation_seeders');

/* ============================================================
   72. FLUSH REWRITE RULES
   ============================================================ */

add_action('after_switch_theme', function() {
    flush_rewrite_rules();
}, 99);

add_action('admin_init', function() {
    $current_version = get_option('ktv_rewrite_version', '');
    if ($current_version !== KTV_TRAVEL_VERSION) {
        flush_rewrite_rules(false);
        update_option('ktv_rewrite_version', KTV_TRAVEL_VERSION);
    }
}, 10);

/* ============================================================
   73. ADMIN SMART AUTO-SYNC
   ============================================================ */

add_action('admin_init', function() {
    if (!current_user_can('manage_options')) {
        return;
    }
    $throttle_key = 'ktv_tours_autosync_throttle';
    if (get_transient($throttle_key)) {
        return;
    }
    set_transient($throttle_key, '1', 20);
    ktv_sync_all_block_tours_to_db();
}, 20);

