   74. FRONTEND SYNC ONCE
   ============================================================ */

add_action('init', function() {
    if (is_admin()) {
        return;
    }
    if (get_transient('ktv_frontend_sync_once')) {
        return;
    }
    set_transient('ktv_frontend_sync_once', '1', HOUR_IN_SECONDS);
    ktv_sync_all_block_tours_to_db();
}, 25);

