add_action('admin_init', function() {
    if (!current_user_can('manage_options')) {
        return;
    }
    $stored = get_option('ktv_travel_version_checked', '');
    if ($stored !== KTV_TRAVEL_VERSION) {
        update_option('ktv_travel_version_checked', KTV_TRAVEL_VERSION);
    }
}, 99);

/* ============================================================
   76. EMAIL DIAGNOSTIC TOOL
   ============================================================ */

add_action('admin_notices', function() {
    if (!current_user_can('manage_options')) {
        return;
    }
    if (!isset($_GET['ktv_diag'])) {
        return;
    }

    echo '<div class="notice notice-info" style="padding:0;"><pre style="background:#fff;padding:20px;margin:0;font-size:13px;line-height:1.7;">';
    echo "===== KTV EMAIL DIAGNOSTIC =====\n\n";

    echo "[ FUNCTIONS ]\n";
    echo "ktv_send_plain_email:    " . (function_exists('ktv_send_plain_email') ? 'YES' : 'NO') . "\n";
    echo "ktv_send_email:          " . (function_exists('ktv_send_email') ? 'YES' : 'NO') . "\n\n";

    echo "[ SETTINGS ]\n";
    echo "KTV admin_email setting: '" . ktv_get_setting('admin_email', '(empty)') . "'\n";
    echo "WP admin_email option:   '" . get_option('admin_email') . "'\n";
    echo "Resolved from_email:     '" . ktv_get_from_email() . "'\n";
    echo "Resolved reply_to:       '" . ktv_get_reply_to_email() . "'\n\n";

    echo "[ CURRENCY ]\n";
    echo "Currency Mode:           '" . ktv_get_setting('currency_mode', 'auto') . "'\n";
    echo "Manual Currency:         '" . ktv_get_setting('currency', 'USD') . "'\n";
    echo "Detected Currency:       '" . ktv_get_currency_code() . "'\n";
    echo "Currency Symbol:         '" . ktv_get_currency_symbol() . "'\n";
    echo "Visitor IP:              '" . ktv_get_client_ip() . "'\n";
    echo "Visitor Country:         '" . ktv_get_user_country() . "'\n\n";

    echo "[ SITE ]\n";
    echo "Site URL:                " . get_site_url() . "\n";
    echo "Site host:               " . parse_url(get_site_url(), PHP_URL_HOST) . "\n\n";

    $smtp = defined('WPMS_PLUGIN_VER') ? 'WP Mail SMTP' : (class_exists('FluentSmtpDb') ? 'FluentSMTP' : 'NONE - install SMTP plugin');
    echo "[ SMTP ]\n";
    echo "Detected:                " . $smtp . "\n\n";

    echo "[ TEST SEND ]\n";
    $admin = ktv_get_setting('admin_email', '');
    if (empty($admin) || !ktv_validate_email($admin)) {
        $admin = get_option('admin_email');
    }
    echo "Sending test to:         $admin\n";
    $result = ktv_send_plain_email($admin, 'KTV Test Email', "Test from KTV diagnostic.\nIf you see this, wp_mail works.\nTime: " . current_time('mysql'));
    echo "Result:                  " . var_export($result, true) . "\n\n";

    echo "[ DEBUG LOG - last 30 lines ]\n";
    $log = WP_CONTENT_DIR . '/debug.log';
    if (file_exists($log) && is_readable($log)) {
        $lines = file($log, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
        $lines = array_slice($lines, -30);
        echo esc_html(implode("\n", $lines));
    } else {
        echo "debug.log not found or unreadable.\n";
        echo "Add to wp-config.php:\n";
        echo "  define('WP_DEBUG', true);\n";
        echo "  define('WP_DEBUG_LOG', true);\n";
        echo "  define('WP_DEBUG_DISPLAY', false);\n";
    }
    echo '</pre></div>';
});

/* ============================================================
   77. TOUR FILTER BLOCK
   ============================================================ */

function ktv_get_filter_options() {
    global $wpdb;
    $labels = array('hotels_label', 'boat_label', 'meals_label', 'flight_label');
    $opts = array();
    foreach ($labels as $col) {
        $rows = $wpdb->get_col(
            "SELECT DISTINCT {$col} FROM {$wpdb->prefix}ktv_tours
             WHERE status='published' AND is_hardcoded=0 AND {$col} <> '' AND {$col} IS NOT NULL
             ORDER BY {$col} ASC"
        );
        $opts[$col] = is_array($rows) ? $rows : array();
    }
    return $opts;
}

function ktv_register_tour_filter_block() {
    if (!function_exists('register_block_type')) return;
    register_block_type('ktv/tour-filter', array(
        'editor_script'   => 'ktv-blocks-editor',
        'editor_style'    => 'ktv-blocks-editor-style',
        'style'           => 'ktv-travel-css',
        'render_callback' => 'ktv_render_tour_filter_block',
        'supports'        => array('align' => array('wide', 'full'), 'anchor' => true, 'html' => false)
    ));
}
add_action('init', 'ktv_register_tour_filter_block', 21);

function ktv_render_tour_filter_block($atts) {
    if (ktv_get_setting('tour_filter_enabled', '1') !== '1') return '';
    $opts = ktv_get_filter_options();
    $currency = ktv_get_currency_symbol('INR');

    $duration_options = array(
        ''     => 'Any Duration',
        '1-3'  => '1-3 Days',
        '4-6'  => '4-6 Days',
        '7-10' => '7-10 Days',
        '10+'  => '10+ Days'
    );
    $price_options = array(
        ''          => 'Any Price',
        '0-500'     => 'Under ' . $currency . '500',
        '500-1000'  => $currency . '500 - ' . $currency . '1,000',
        '1000-2000' => $currency . '1,000 - ' . $currency . '2,000',
        '2000-5000' => $currency . '2,000 - ' . $currency . '5,000',
        '5000+'     => 'Above ' . $currency . '5,000'
    );
    $sort_options = array(
        ''           => 'Sort: Recommended',
        'price_low'  => 'Price: Low to High',
        'price_high' => 'Price: High to Low',
        'rating'     => 'Highest Rated',
        'reviews'    => 'Most Reviews',
        'duration'   => 'Duration: Short to Long',
        'newest'     => 'Newest First'
    );
    $review_options = array(
        ''    => 'Any Rating',
        '4.5' => '4.5+ Stars',
        '4'   => '4+ Stars',
        '3'   => '3+ Stars'
    );
    $activities_options = array(
        ''             => 'Any Activity',
        'trekking'     => 'Trekking',
        'hiking'       => 'Hiking',
        'horse_riding' => 'Horse Riding',
        'boat'         => 'Boat / Houseboat',
        'sightseeing'  => 'Sightseeing',
        'transport'    => 'Transport',
        'flights'      => 'Flights'
    );
    $group_options = array(
        ''     => 'Any Group Size',
        '1-2'  => '1-2 People',
        '3-5'  => '3-5 People',
        '6-10' => '6-10 People',
        '10+'  => '10+ People'
    );
    $quick_chips = array(
        'popular' => 'Popular',
        '5days'   => '5+ Days',
        'flights' => 'Flights Included'
    );

    ob_start();
    ?>
    <div class="ktv-tour-filter" data-ktv-filter="1">
        <div class="ktv-quick-chips">
            <?php foreach ($quick_chips as $k => $l): ?>
            <button type="button" class="ktv-quick-chip" data-quick="<?php echo esc_attr($k); ?>"><?php echo esc_html($l); ?></button>
            <?php endforeach; ?>
            <span class="ktv-active-count" hidden><span>0</span> active</span>
        </div>
        <div class="ktv-tour-filter-bar">
            <select class="ktv-filter-duration" aria-label="Duration">
                <?php foreach ($duration_options as $v => $l): ?>
                <option value="<?php echo esc_attr($v); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <select class="ktv-filter-price" aria-label="Price">
                <?php foreach ($price_options as $v => $l): ?>
                <option value="<?php echo esc_attr($v); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <select class="ktv-filter-sort" aria-label="Sort By">
                <?php foreach ($sort_options as $v => $l): ?>
                <option value="<?php echo esc_attr($v); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <select class="ktv-filter-rating" aria-label="Rating">
                <?php foreach ($review_options as $v => $l): ?>
                <option value="<?php echo esc_attr($v); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <select class="ktv-filter-activities" aria-label="Activities">
                <?php foreach ($activities_options as $v => $l): ?>
                <option value="<?php echo esc_attr($v); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <select class="ktv-filter-group" aria-label="Group Size">
                <?php foreach ($group_options as $v => $l): ?>
                <option value="<?php echo esc_attr($v); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <?php if (!empty($opts['hotels_label'])): ?>
            <select class="ktv-filter-hotels" aria-label="Accommodation">
                <option value="">Any Accommodation</option>
                <?php foreach ($opts['hotels_label'] as $l): ?>
                <option value="<?php echo esc_attr($l); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <?php endif; ?>
            <?php if (!empty($opts['boat_label'])): ?>
            <select class="ktv-filter-boat" aria-label="Boat / Houseboat">
                <option value="">Any Boat</option>
                <?php foreach ($opts['boat_label'] as $l): ?>
                <option value="<?php echo esc_attr($l); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <?php endif; ?>
            <?php if (!empty($opts['meals_label'])): ?>
            <select class="ktv-filter-meals" aria-label="Meals">
                <option value="">Any Meals</option>
                <?php foreach ($opts['meals_label'] as $l): ?>
                <option value="<?php echo esc_attr($l); ?>"><?php echo esc_html($l); ?></option>
                <?php endforeach; ?>
            </select>
            <?php endif; ?>
            <?php if (!empty($opts['flight_label'])): ?>
            <select class="ktv-filter-flight" aria-label="Flights">
                <option value="">Any Flight</option>
                <option value="yes">Included</option>
                <option value="no">Not Included</option>
            </select>
            <?php endif; ?>
            <button type="button" class="ktv-filter-reset" hidden><i class="fas fa-times"></i> Reset</button>
        </div>
        <div class="ktv-filter-count"><span>0</span> tours match</div>
    </div>

    <div class="ktv-filter-grid-wrap">
        <div class="ktv-tour-grid ktv-grid-3" data-ktv-filtered-grid="1"></div>
    </div>
    <?php
    return ob_get_clean();
}

add_shortcode('ktv_tour_filter', function($atts) {
    return ktv_render_tour_filter_block((array) $atts);
});

